#[derive(Serialize, Clone)]
pub struct ShellEnvInfo {
    pub path: String,
    pub shell: String,
    #[serde(rename = "claudePath")]
    pub claude_path: Option<String>,
    #[serde(rename = "claudeVersion")]
    pub claude_version: Option<String>,
    #[serde(rename = "codexPath")]
    pub codex_path: Option<String>,
    #[serde(rename = "codexVersion")]
    pub codex_version: Option<String>,
    /// Derived: codex resolved *and* answered `--version`. The tile toolbar
    /// gates its Codex action on this, not on `codexPath` — see
    /// `ShellEnv::codex_healthy`.
    #[serde(rename = "codexHealthy")]
    pub codex_healthy: bool,
    #[serde(rename = "gitPath")]
    pub git_path: Option<String>,
    #[serde(rename = "gitVersion")]
    pub git_version: Option<String>,
    #[serde(rename = "ghPath")]
    pub gh_path: Option<String>,
    #[serde(rename = "ghVersion")]
    pub gh_version: Option<String>,
    #[serde(rename = "supportsStreamJson")]
    pub supports_stream_json: bool,
    #[serde(rename = "probeError")]
    pub probe_error: Option<String>,
}

pub(crate) fn snapshot_env() -> ShellEnvInfo {
    let env = shell_env::get();
    ShellEnvInfo {
        path: env.path.clone(),
        shell: env.shell.clone(),
        claude_path: env.claude_path.clone(),
        claude_version: env.claude_version.clone(),
        codex_path: env.codex_path.clone(),
        codex_version: env.codex_version.clone(),
        codex_healthy: env.codex_healthy(),
        git_path: env.git_path.clone(),
        git_version: env.git_version.clone(),
        gh_path: env.gh_path.clone(),
        gh_version: env.gh_version.clone(),
        supports_stream_json: env.supports_stream_json(),
        probe_error: env.probe_error.clone(),
    }
}

/// The cached shell environment was replaced behind the window's back (a
/// changed PATH override); the payload is the fresh [`ShellEnvInfo`].
pub const SHELL_ENV_CHANGED_EVENT: &str = "shell-env://changed";

#[tauri::command]
pub fn shell_env_info() -> ShellEnvInfo {
    snapshot_env()
}

#[tauri::command]
pub fn shell_env_retry(
    capabilities: State<'_, crate::review_capabilities::ReviewerCapabilityRegistry>,
) -> ShellEnvInfo {
    re_probe_and_forget(Some(&capabilities));
    snapshot_env()
}

/// Re-run the shell probe and forget what Ply thought about the tools: the
/// reviewer capability drift, and the remembered `gh` and `claude` sign-in
/// answers. `shell_env_retry` ("Check again") and OB-3's guided runner after
/// an install or update both go through here.
pub(crate) fn re_probe_and_forget(
    capabilities: Option<&crate::review_capabilities::ReviewerCapabilityRegistry>,
) -> std::sync::Arc<shell_env::ShellEnv> {
    let fresh = shell_env::re_probe();
    if let Some(capabilities) = capabilities {
        if let Err(error) = capabilities.invalidate_drift(&fresh) {
            log::warn!("reviewer capability drift invalidation failed: {error}");
        }
    }
    // Review 2 (N2): re-probing is "forget what you thought". A `gh` resolved at
    // a different path — or the same one, freshly signed in — must not be
    // described by an answer from before the re-probe.
    if let Ok(mut held) = GH_AUTH.lock() {
        *held = None;
    }
    // GH #169: likewise `claude` — a login in another terminal is exactly what
    // `Look again, from scratch` is pressed after.
    if let Ok(mut held) = CLAUDE_AUTH.lock() {
        *held = None;
    }
    fresh
}

/// 1.176.0 R3 review 1: a spawn's own look forgets only what a moved tool
/// makes stale — the reviewer drift always, `gh`'s and Claude's sign-in
/// answers only when that tool's path changed.
pub(crate) fn forget_moved(
    before: &shell_env::ShellEnv,
    after: &shell_env::ShellEnv,
    capabilities: Option<&crate::review_capabilities::ReviewerCapabilityRegistry>,
) {
    if let Some(Err(error)) = capabilities.map(|c| c.invalidate_drift(after)) {
        log::warn!("reviewer capability drift invalidation failed: {error}");
    }
    if before.gh_path != after.gh_path {
        *GH_AUTH.lock().unwrap_or_else(|p| p.into_inner()) = None;
    }
    if before.claude_path != after.claude_path {
        *CLAUDE_AUTH.lock().unwrap_or_else(|p| p.into_inner()) = None;
    }
}

/// v1.32.0: structured dependency-doctor report — required/optional status,
/// versions and install guidance for git / claude / codex / gh. Reads the
/// cached probe; pair with `shell_env_retry` to re-probe before re-fetching.
/// GH #103 review 1: the last answer `gh auth status` gave, and when.
///
/// Module state rather than a field on a store, because it is a cache of
/// something outside Ply, not part of anything Ply owns or persists.
static GH_AUTH: std::sync::Mutex<Option<(std::time::Instant, crate::doctor::ToolAuth)>> =
    std::sync::Mutex::new(None);

/// GH #169: the last answer `claude_auth::read` gave, and when. A read that
/// asks (Diagnostics, its watch) always looks again (review 1); a read that
/// does not ask shows this only while it is under ninety seconds old, like
/// `gh`'s, so app launch and every other doctor read look at nothing.
static CLAUDE_AUTH: std::sync::Mutex<Option<(std::time::Instant, crate::doctor::ToolAuth)>> =
    std::sync::Mutex::new(None);

/// GH #227 review 1: a worker, not the main thread. The report reads the
/// open workspace's skill roots through `git` (and `gh`, when asked), and it
/// is read on launch and on every workspace switch — a slow repository must
/// not freeze the window.
#[tauri::command]
pub async fn dependency_doctor(
    app: AppHandle,
    with_auth: Option<bool>,
    force_auth: Option<bool>,
) -> Result<crate::doctor::DoctorReport, String> {
    tauri::async_runtime::spawn_blocking(move || dependency_doctor_blocking(&app, with_auth, force_auth))
        .await
        .map_err(|e| format!("doctor worker failed: {e}"))
}

fn dependency_doctor_blocking(
    app: &AppHandle,
    // `withAuth` — GH #103 review 1: only a read that shows the sign-in row
    // asks `gh` about it. Absent means no; this command is read on app launch,
    // on every workspace switch and on definition events, and none of those
    // should cost a network round trip.
    with_auth: Option<bool>,
    // `forceAuth` — review 2 (N2): `Look again, from scratch` ignores the
    // remembered answer, because it is the press that means "look properly".
    force_auth: Option<bool>,
) -> crate::doctor::DoctorReport {
    let capabilities = app.state::<crate::review_capabilities::ReviewerCapabilityRegistry>();
    // v1.116.0: read off the local clone, so the team-skills row renders
    // offline and without a membership answer, like Settings → Team's rows.
    let library = team_clone_dir(&app).map(|dir| crate::team_skills::read_library(&dir));
    let team_skills = library.as_ref().map(|library| {
        // Whether a Codex session could actually load them, not just whether
        // the library holds them: the launch path can only log a failure to
        // prepare the overlay, so the doctor is where a member sees it.
        let codex_blocked = library.codex.as_ref().and_then(|marketplace| {
            crate::codex_home::preflight(&crate::codex_home::real_codex_home(), marketplace).err()
        });
        crate::doctor::TeamSkillsInput {
            library,
            codex_blocked,
        }
    });
    // v1.117.0: the open workspace's own skill directories. The CLIs read
    // these out of the repo themselves, so the row is about one workspace —
    // named in the row, because the doctor is otherwise machine-wide.
    let active = active_workspace(&app);
    // OB-2 (C9): read through `git`, so only when git works — on a Mac
    // without the Command Line Tools a bare `git` opens Apple's dialog.
    let git_works = shell_env::get().git_works();
    let project = active
        .as_ref()
        .filter(|_| git_works)
        .map(|(_, cwd)| crate::project_skills::read_project_skills(cwd));
    let project_skills = match (&active, &project) {
        (Some((name, _)), Some(skills)) => Some(crate::doctor::ProjectSkillsInput {
            workspace: name,
            skills,
        }),
        _ => None,
    };
    let env = shell_env::get();
    // OB-2 (D6): the newest releases, read only by a read that asks
    // (Diagnostics and its watch) and cached — never at app launch. Started
    // here on its own thread and joined after the sign-in checks below, so
    // its five-second bound runs beside `gh auth status`'s (review P3-2).
    let latest = {
        let path = env.path.clone();
        let asks = with_auth == Some(true);
        std::thread::spawn(move || crate::doctor_reads::latest_versions(asks, &path))
    };
    // A provider CLI that updated itself since its reviewer proof re-proves
    // in the background; claimed before the report is built, so the row
    // already reads as re-verifying.
    for provider in [
        crate::coordination::Provider::Claude,
        crate::coordination::Provider::Codex,
    ] {
        let view = capabilities.current(provider, &env);
        crate::review_capabilities::schedule_auto_probe(&app, &view);
    }
    // OB-2: Codex's sign-in from its files (no process — `codex login
    // status` runs only in Setup's AI step), the git identity (read only,
    // and only through a git that works), and where each tool really is.
    let real = |p: &Option<String>| {
        p.as_deref()
            .and_then(|p| crate::platform::canonicalize(std::path::Path::new(p)).ok())
            .map(|p| p.to_string_lossy().into_owned())
    };
    let mut facts = crate::doctor::DoctorFacts {
        windows: cfg!(windows),
        codex_auth: env.codex_path.as_ref().map(|_| {
            let (store, file) = crate::doctor_reads::codex_auth();
            crate::doctor::codex_auth_status(store, file)
        }),
        identity: crate::doctor_reads::git_identity(&env),
        // Joined after the sign-in checks; see `apply_latest` below.
        latest: crate::doctor::LatestVersions::default(),
        codex_real_path: real(&env.codex_path),
        gh_real_path: real(&env.gh_path),
        brew: !cfg!(windows) && shell_env::find_in_path(&env.path, "brew").is_some(),
    };
    let mut report = crate::doctor::build_report_with(
        &env,
        Some(&capabilities),
        team_skills,
        project_skills,
        &facts,
    );
    // GH #79: the open workspace's shared definition, from its cache — the
    // doctor never fetches.
    report.shared_definition = {
        let snapshot = app.state::<WorkspaceStore>().snapshot();
        snapshot
            .active_workspace_id
            .as_deref()
            .and_then(|id| snapshot.workspaces.iter().find(|w| w.id == id))
            .and_then(|ws| {
                let cache = crate::workspace_definition::load_cache(
                    &app.state::<ProjectConfigStore>(),
                    &ws.id,
                )?;
                let queue = crate::shared_config::load_queue(
                    &app.state::<ProjectConfigStore>(),
                    &ws.id,
                );
                let local_areas = crate::areas::load(&app.state::<ProjectConfigStore>(), &ws.id);
                crate::doctor::shared_definition_status(&ws.name, &cache, &queue, &local_areas)
            })
    };
    // 1.173.0 (D1): the open workspace's Railway row, only with the Railway
    // program. A read that asks may run `railway status` (bounded, cached ten
    // minutes); every other read looks only at the cache and the link file.
    // On its own thread, joined beside the newest releases below, so its
    // six-second bound runs beside `gh auth status`'s.
    let railway = {
        let snapshot = app.state::<WorkspaceStore>().snapshot();
        let active = snapshot
            .active_workspace_id
            .as_deref()
            .and_then(|id| snapshot.workspaces.iter().find(|w| w.id == id))
            .map(|ws| (ws.id.clone(), ws.name.clone(), std::path::PathBuf::from(&ws.cwd)));
        let asks = with_auth == Some(true);
        std::thread::spawn(move || {
            let (id, name, folder) = active?;
            folder.is_dir().then_some(())?;
            crate::deploy_map::doctor_row(&id, &name, &folder, asks)
        })
    };
    // GH #103 (BOARDS.md §5): `gh` resolving is not `gh` being usable — a
    // signed-out `gh` cannot open a pull request, and the step that fixes it
    // is `gh auth login`, not an install. Asked here rather than in
    // `shell_env::init()`: it validates the token over the network, and app
    // startup must not wait for that.
    //
    // Review 1: and not on every read either. `doctor::auth_probe` decides
    // between saying nothing, reusing what was learnt in the last ninety
    // seconds, and actually running `gh`.
    if let Some(gh) = env.gh_path.clone() {
        let remembered = GH_AUTH
            .lock()
            .ok()
            .and_then(|held| held.clone())
            .map(|(at, auth)| (at.elapsed(), auth));
        let auth = match crate::doctor::auth_probe(
            with_auth == Some(true),
            force_auth == Some(true),
            remembered,
        ) {
            crate::doctor::AuthProbe::Skip => None,
            crate::doctor::AuthProbe::Cached(auth) => Some(auth),
            crate::doctor::AuthProbe::Ask => {
                // GH #189: a failed answer is read beside the login keychain's
                // lock state — `gh` keeps its token there, and a locked keychain
                // fails `gh auth status` like a refused token. Status only
                // (`keychain_lock.rs`): no item is read, nothing can prompt.
                let asked = shell_env::gh_auth_output(&gh, &env.path).map(|(ok, output)| {
                    let keychain = if ok {
                        crate::keychain_lock::KeychainLock::Unknown
                    } else {
                        crate::keychain_lock::default_keychain()
                    };
                    crate::doctor::gh_auth_status(ok, &output, keychain)
                });
                if let (Some(auth), Ok(mut held)) = (asked.clone(), GH_AUTH.lock()) {
                    *held = Some((std::time::Instant::now(), auth));
                }
                asked
            }
        };
        if let Some(auth) = auth {
            if let Some(row) = report.tools.iter_mut().find(|t| t.id == "gh") {
                row.auth = Some(auth);
            }
        }
    }
    // GH #169 (BOARDS.md §5): `claude` signed in or not, from **credential
    // presence only** — the keychain item's attributes and the credentials
    // file's `stat` (`claude_auth.rs`). No network, no process, never a false
    // "signed out". Behind the same `auth_probe` as `gh`, so a read that does
    // not ask (app launch, a workspace switch, the welcome screen, the
    // banner) looks at nothing and shows only an answer from the last ninety
    // seconds.
    //
    // Review 1: a read that asks always looks. The ninety seconds exist to
    // spare `gh`'s network round trip; this is a `stat` and one attributes
    // query, and a login in the tile Diagnostics opened should show on the
    // watch's next read. Reads that do not ask still only reuse the memory.
    if env.claude_path.is_some() {
        let remembered = CLAUDE_AUTH
            .lock()
            .ok()
            .and_then(|held| held.clone())
            .map(|(at, auth)| (at.elapsed(), auth));
        let asks = with_auth == Some(true);
        let auth = match crate::doctor::auth_probe(asks, asks, remembered) {
            crate::doctor::AuthProbe::Skip => None,
            crate::doctor::AuthProbe::Cached(auth) => Some(auth),
            crate::doctor::AuthProbe::Ask => {
                let (keychain, file) = crate::claude_auth::read();
                let auth = crate::doctor::claude_auth_status(keychain, file);
                if let Ok(mut held) = CLAUDE_AUTH.lock() {
                    *held = Some((std::time::Instant::now(), auth.clone()));
                }
                Some(auth)
            }
        };
        if let Some(row) = report.tools.iter_mut().find(|t| t.id == "claude") {
            row.auth = auth;
        }
    }
    // OB-2 (D6): the newest releases, read beside the sign-in checks above.
    facts.latest = latest.join().unwrap_or_default();
    report.railway = railway.join().unwrap_or_default();
    crate::doctor::apply_latest(&mut report, &env, &facts);
    // Microphone: a status read only — it never opens the device or prompts.
    report.microphone = crate::microphone::status().map(crate::doctor::microphone_status);
    // #47: whisper.cpp and the selected dictation model. File checks only;
    // nothing is run.
    let env = shell_env::get();
    let whisper_cli = crate::dictation::resolve_whisper_cli(&env.path);
    // Windows has no one-line whisper.cpp install: without one already on
    // PATH, the whisper and model rows would only offer a step there is none of.
    let dictation_rows = !cfg!(windows) || whisper_cli.is_some();
    if dictation_rows {
        report.tools.push(crate::doctor::whisper_tool_status(whisper_cli));
    }
    if let (Ok(config_dir), Some(settings), true) = (
        app.path().app_config_dir(),
        app.try_state::<SettingsStore>(),
        dictation_rows,
    ) {
        let model = settings.snapshot().behavior.dictation.model;
        let path = crate::dictation::model_path(&config_dir, model);
        report.whisper_model = Some(crate::doctor::whisper_model_status(
            model,
            &path,
            crate::dictation::model_present(&path),
        ));
    }
    // GH #68: whether the shell new tiles run can take dictated text. Only a
    // bash (or sh, which is bash on macOS) is asked its version.
    let tile_shell = app
        .try_state::<SettingsStore>()
        .and_then(|settings| settings.snapshot().shell.tile_shell().map(str::to_string))
        .unwrap_or_else(|| env.shell.clone());
    // Resolved like the PTY spawn does, so `zsh` typed as a bare name is found.
    let resolved = shell_env::resolve_program(&tile_shell, &env.path);
    let shell = resolved.clone().unwrap_or(tile_shell);
    let name = std::path::Path::new(&shell)
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    // Windows: only a bash, zsh or fish (Git Bash, MSYS2) has a line editor
    // this row knows; PowerShell and cmd get no row rather than macOS advice.
    let stem = std::path::Path::new(&shell)
        .file_stem()
        .map(|n| n.to_string_lossy().to_ascii_lowercase())
        .unwrap_or_default();
    // `C:\Windows\System32\bash.exe` is WSL's launcher, not Git Bash.
    let wsl = std::path::Path::new(&shell).parent().is_some_and(|dir| {
        dir.to_string_lossy()
            .to_ascii_lowercase()
            .ends_with(r"\windows\system32")
    });
    if cfg!(windows) && (wsl || !["bash", "sh", "zsh", "fish"].contains(&stem.as_str())) {
        return report;
    }
    // `bash.exe` and `sh.exe` on Windows are asked by their stem.
    let asked = if cfg!(windows) { stem.as_str() } else { name.as_str() };
    let version = resolved
        .as_deref()
        .filter(|_| asked.starts_with("bash") || asked == "sh")
        .and_then(|program| shell_env::shell_version_output(program, &env.path));
    report.dictation_shell = Some(crate::doctor::dictation_shell_status(
        &shell,
        resolved.is_some(),
        version.as_deref(),
    ));
    report
}

// ── #47 dictation (Codex and shell tiles) ───────────────────────────────

fn dictation_config_dir(app: &AppHandle) -> Result<PathBuf, crate::dictation::DictationError> {
    app.path().app_config_dir().map_err(|e| crate::dictation::DictationError {
        kind: crate::dictation::DictationErrorKind::Failed,
        message: format!("app_config_dir: {e}"),
    })
}

/// whisper-cli's resolved path and each model's state, for Settings →
/// Dictation (its model file) and the tile's pre-recording check.
#[tauri::command]
pub fn dictation_status(app: AppHandle) -> Result<crate::dictation::DictationStatus, String> {
    let config_dir = app
        .path()
        .app_config_dir()
        .map_err(|e| format!("app_config_dir: {e}"))?;
    Ok(crate::dictation::status(
        &config_dir,
        &shell_env::get().path,
        &crate::dictation::JOBS,
    ))
}

/// Transcribe a 16 kHz mono WAV recorded in a tile with the model and
/// language Settings selects. The text comes back; the caller inserts it into
/// the prompt and never sends it. `request_id` is what `dictation_cancel`
/// names.
#[tauri::command]
pub async fn dictation_transcribe(
    app: AppHandle,
    settings: State<'_, SettingsStore>,
    wav: Vec<u8>,
    request_id: String,
) -> Result<String, crate::dictation::DictationError> {
    use crate::dictation::{DictationError, DictationErrorKind};
    // Reserved before anything else, so an Esc that arrives while this
    // request is still being set up or queued cancels it (or, if it came
    // first, refuses it here).
    let job = crate::dictation::JOBS.reserve(&request_id)?;
    let config_dir = dictation_config_dir(&app)?;
    let prefs = settings.snapshot().behavior.dictation;
    let env = shell_env::get();
    let whisper_cli = crate::dictation::resolve_whisper_cli(&env.path).ok_or_else(|| {
        DictationError {
            kind: DictationErrorKind::WhisperMissing,
            message: crate::dictation::whisper_missing_message(),
        }
    })?;
    let model = crate::dictation::model_path(&config_dir, prefs.model);
    if !crate::dictation::model_present(&model) {
        return Err(DictationError {
            kind: DictationErrorKind::ModelMissing,
            message: format!(
                "The {} model isn't downloaded. Settings › Look and feel › Dictation › The model file › Download.",
                prefs.model.as_str()
            ),
        });
    }
    let path = env.path.clone();
    tauri::async_runtime::spawn_blocking(move || {
        crate::dictation::transcribe(
            crate::dictation::TranscribeRequest {
                whisper_cli: Path::new(&whisper_cli),
                model: &model,
                language: prefs.language,
                wav: &wav,
                job: &job,
                env_path: &path,
            },
            None,
        )
    })
    .await
    .map_err(|e| DictationError {
        kind: DictationErrorKind::Failed,
        message: format!("join transcription: {e}"),
    })?
}

/// Esc while "Transcribing…": kill that request's whisper-cli, or refuse
/// the request if the cancel arrived before it registered.
#[tauri::command]
pub fn dictation_cancel(request_id: String) -> bool {
    crate::dictation::JOBS.cancel_request(&request_id)
}

#[derive(Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct DictationDownloadProgress {
    model: crate::dictation::DictationModel,
    received: u64,
    total: Option<u64>,
}

/// Download a model into `whisper/models/`, emitting
/// `dictation://download-progress` as it grows. Resolves when the model is
/// installed.
#[tauri::command]
pub async fn dictation_model_download(
    app: AppHandle,
    model: String,
) -> Result<crate::dictation::DictationStatus, crate::dictation::DictationError> {
    use crate::dictation::{DictationError, DictationErrorKind, DictationModel};
    let model = DictationModel::parse(&model).ok_or_else(|| DictationError {
        kind: DictationErrorKind::Failed,
        message: format!("Unknown model '{model}'."),
    })?;
    // Reserved before the worker is queued, so Cancel finds it however soon
    // it arrives, and a second click is refused as Busy.
    let job = crate::dictation::JOBS.reserve(&crate::dictation::download_key(model))?;
    let config_dir = dictation_config_dir(&app)?;
    let emitter = app.clone();
    let dir = config_dir.clone();
    tauri::async_runtime::spawn_blocking(move || {
        crate::dictation::download_model(&job, &dir, model, &|received, total| {
            let _ = emitter.emit(
                "dictation://download-progress",
                DictationDownloadProgress {
                    model,
                    received,
                    total,
                },
            );
        })
    })
    .await
    .map_err(|e| DictationError {
        kind: DictationErrorKind::Failed,
        message: format!("join download: {e}"),
    })??;
    Ok(crate::dictation::status(
        &config_dir,
        &shell_env::get().path,
        &crate::dictation::JOBS,
    ))
}

#[tauri::command]
pub fn dictation_model_download_cancel(model: String) -> bool {
    crate::dictation::DictationModel::parse(&model)
        .map(|model| crate::dictation::JOBS.cancel(&crate::dictation::download_key(model)))
        .unwrap_or(false)
}

/// The doctor's "Request access". Asks macOS for microphone access
/// so its prompt names Ply (the process a PTY child's `/voice` request is
/// attributed to), then returns the row as it now stands. Waits for the
/// user's answer; when access is already decided it returns at once.
#[tauri::command]
pub async fn microphone_request_access() -> Result<crate::doctor::MicrophoneStatus, String> {
    tauri::async_runtime::spawn_blocking(crate::microphone::request_access)
        .await
        .map_err(|error| format!("join microphone request: {error}"))?
        .map(crate::doctor::microphone_status)
        .ok_or_else(|| {
            if cfg!(windows) {
                "Windows did not report a microphone authorization".into()
            } else {
                "macOS did not report a microphone authorization".into()
            }
        })
}

/// Open System Settings → Privacy & Security → Microphone, the only
/// place a denial can be undone. No URL-opener plugin is installed, so this
/// goes through `open` like the attachment commands.
// Async, as every open and reveal command is: the shell hand-off can block
// the thread it runs on (ShellExecute).
#[tauri::command(async)]
pub fn microphone_open_settings() -> Result<(), String> {
    crate::platform::open_url(
        crate::microphone::SETTINGS_URL,
        &[crate::microphone::SETTINGS_SCHEME],
    )
    .map_err(|e| format!("open System Settings failed: {e}"))?;
    Ok(())
}

/// SP-6: the schemes a link in a review's or a comparison's text may open —
/// a web page, nothing else (no `mailto:`, no `file:`, no app scheme).
pub const TEXT_LINK_SCHEMES: &[&str] = &["http", "https"];

/// SP-6 round 2: a character that changes how a link reads without being
/// seen — a control character, or a Unicode format character (category Cf:
/// the bidi controls U+202A–U+202E and U+2066–U+2069, U+200E/F, zero-width
/// marks, the BOM, tags). The frontend draws such a link as words; this
/// refuses it again here.
fn hidden_in_link(c: char) -> bool {
    c.is_control()
        || matches!(
            c as u32,
            0x00AD
                | 0x0600..=0x0605
                | 0x061C
                | 0x06DD
                | 0x070F
                | 0x0890..=0x0891
                | 0x08E2
                | 0x180E
                | 0x200B..=0x200F
                | 0x202A..=0x202E
                | 0x2060..=0x2064
                | 0x2066..=0x206F
                | 0xFEFF
                | 0xFFF9..=0xFFFB
                | 0x110BD
                | 0x110CD
                | 0x13430..=0x1343F
                | 0x1BCA0..=0x1BCA3
                | 0x1D173..=0x1D17A
                | 0xE0001
                | 0xE0020..=0xE007F
        )
}

/// SP-6: open an http(s) link from a finding's or a comparison's text in
/// the default browser. Any other scheme, and any link holding a hidden
/// format or control character, is refused before any spawn.
#[tauri::command(async)]
pub fn open_web_link(url: String) -> Result<(), String> {
    if url.chars().any(hidden_in_link) {
        return Err("open failed: refused a link with a hidden character in it".into());
    }
    crate::platform::open_url(&url, TEXT_LINK_SCHEMES).map_err(|e| format!("open failed: {e}"))
}

/// Getting started TU-8 (TUTORIAL_SPEC §3.3, D23, D28): Get help's
/// *Email support*. The webview does not hand a `mailto:` link to the
/// system (WKWebView loads it itself and fails quietly; WebView2 asks with
/// its own prompt), so the page asks for it here. Only a new email to
/// Plyloft's support address, with the subject and body the page encoded:
/// any other address, scheme or a hidden character is refused before any
/// spawn. The member's mail app opens it; nothing is sent from here.
pub const SUPPORT_MAILTO_PREFIX: &str = "mailto:support@plyloft.com?";

#[tauri::command(async)]
pub fn open_support_mail(url: String) -> Result<(), String> {
    if !url.starts_with(SUPPORT_MAILTO_PREFIX) || url.len() > 8 * 1024 {
        return Err("open failed: only a new email to support@plyloft.com".into());
    }
    if url.chars().any(|c| hidden_in_link(c) || c.is_whitespace()) {
        return Err("open failed: refused a link with a hidden character in it".into());
    }
    // A subject and a body, each at most once: never another recipient
    // (`cc=`, `bcc=`) or an attachment some mail apps honour.
    let query = &url[SUPPORT_MAILTO_PREFIX.len()..];
    let mut seen: Vec<&str> = Vec::new();
    for part in query.split('&') {
        let key = part.split('=').next().unwrap_or("");
        if !matches!(key, "subject" | "body") || !part.contains('=') || seen.contains(&key) {
            return Err("open failed: only a subject and a body".into());
        }
        seen.push(key);
    }
    crate::platform::open_url(&url, &["mailto"]).map_err(|e| format!("open failed: {e}"))
}

#[cfg(test)]
mod open_support_mail_tests {
    use super::*;

    #[test]
    fn only_a_new_email_to_support_is_opened() {
        for refused in [
            "mailto:someone@else.com?subject=x",
            "mailto:support@plyloft.com.evil.com?subject=x",
            "https://plyloft.com",
            "mailto:support@plyloft.com?subject=a b",
            "mailto:support@plyloft.com?subject=a\u{202E}b",
            "mailto:support@plyloft.com?bcc=a@b.c&subject=x",
            "mailto:support@plyloft.com?subject=x&attach=file:///etc/passwd",
            "mailto:support@plyloft.com?subject=x&subject=y",
            "mailto:support@plyloft.com?",
        ] {
            assert!(open_support_mail(refused.to_string()).is_err(), "{refused} refused before any spawn");
        }
        let long = format!("{SUPPORT_MAILTO_PREFIX}body={}", "a".repeat(9000));
        assert!(open_support_mail(long).is_err(), "a link that long is refused");
        // What the page sends passes the checks (only the spawn is left).
        let url = format!("{SUPPORT_MAILTO_PREFIX}subject=Plyloft%3A%20help&body=What%20happened%3A%0A%0A");
        let query = &url[SUPPORT_MAILTO_PREFIX.len()..];
        assert!(query.split('&').all(|p| p.starts_with("subject=") || p.starts_with("body=")));
    }
}

#[cfg(test)]
mod open_web_link_tests {
    use super::*;

    #[test]
    fn a_text_link_opens_only_a_web_page() {
        assert!(crate::platform::url_scheme_allowed("https://github.com/o/r/pull/7", TEXT_LINK_SCHEMES));
        assert!(crate::platform::url_scheme_allowed("http://example.com", TEXT_LINK_SCHEMES));
        for refused in ["javascript:alert(1)", "file:///etc/passwd", "mailto:a@b.c", "ply://x", "data:text/html,x"] {
            assert!(!crate::platform::url_scheme_allowed(refused, TEXT_LINK_SCHEMES), "{refused}");
            assert!(open_web_link(refused.to_string()).is_err(), "{refused} refused before any spawn");
        }
    }

    #[test]
    fn a_text_link_with_a_hidden_character_is_refused() {
        for c in ['\u{202E}', '\u{202A}', '\u{2066}', '\u{2069}', '\u{200E}', '\u{200F}', '\u{200B}', '\u{FEFF}', '\u{E0041}', '\u{7}'] {
            let url = format!("https://github.com/o/r{c}/pull/7");
            assert!(hidden_in_link(c), "{:04X}", c as u32);
            assert!(open_web_link(url).is_err(), "{:04X} refused before any spawn", c as u32);
        }
        // Plain characters, ASCII or not, are not hidden.
        for c in ['a', '/', '例', 'é'] {
            assert!(!hidden_in_link(c), "{c}");
        }
    }
}

/// The workspace the window is on — name and checkout. `None` before the
/// first one is registered, which is the welcome screen.
fn active_workspace(app: &AppHandle) -> Option<(String, PathBuf)> {
    let snapshot = app.state::<WorkspaceStore>().snapshot();
    let id = snapshot.active_workspace_id?;
    snapshot
        .workspaces
        .into_iter()
        .find(|workspace| workspace.id == id)
        .map(|workspace| (workspace.name, PathBuf::from(workspace.cwd)))
}

/// The Doctor's "Build cache" row: the open workspace's shared Cargo target.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct BuildCacheRow {
    pub workspace_id: String,
    pub workspace_name: String,
    /// `ProjectConfig::shared_build_cache`: card sessions build into it.
    pub enabled: bool,
    pub status: crate::worktrees::BuildCacheStatus,
}

/// The open workspace's build-cache row, or `None` with no workspace open.
/// Sized on a worker: the walk over a multi-gigabyte target takes a moment,
/// so it is its own command rather than part of the doctor report.
#[tauri::command]
pub async fn build_cache_status(app: AppHandle) -> Result<Option<BuildCacheRow>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let snapshot = app.state::<WorkspaceStore>().snapshot();
        let Some(active) = snapshot.active_workspace_id else {
            return None;
        };
        let workspace = snapshot.workspaces.into_iter().find(|w| w.id == active)?;
        let enabled = app.state::<ProjectConfigStore>().shared_build_cache(&workspace.id);
        Some(BuildCacheRow {
            status: crate::worktrees::shared_target_status(Path::new(&workspace.cwd)),
            workspace_id: workspace.id,
            workspace_name: workspace.name,
            enabled,
        })
    })
    .await
    .map_err(|e| format!("build cache status worker failed: {e}"))
}

/// The row's "Clear": delete the workspace's shared Cargo target, refused
/// while a Verify uses it. Returns the bytes freed.
#[tauri::command]
pub async fn build_cache_clear(app: AppHandle, workspace_id: String) -> Result<u64, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let cwd = resolve_ws_cwd(&app.state::<WorkspaceStore>(), &workspace_id)?;
        crate::build_cache::clear_shared_target(&cwd)
    })
    .await
    .map_err(|e| format!("build cache clear worker failed: {e}"))?
}

