#[tauri::command]
pub async fn reviewer_capability_probe(
    app: AppHandle,
    provider: String,
) -> Result<crate::review_capabilities::ReviewerCapabilityView, String> {
    let provider = match provider.as_str() {
        "claude" => crate::coordination::Provider::Claude,
        "codex" => crate::coordination::Provider::Codex,
        _ => return Err("reviewer provider must be 'claude' or 'codex'".into()),
    };
    tauri::async_runtime::spawn_blocking(move || {
        let capabilities = app.state::<crate::review_capabilities::ReviewerCapabilityRegistry>();
        let pty = app.state::<crate::pty::PtyRegistry>();
        let env = shell_env::get();
        crate::review_capabilities::run_probe(&capabilities, &pty, provider, &env)
    })
    .await
    .map_err(|error| format!("join reviewer probe: {error}"))?
}

#[tauri::command]
pub async fn reviewer_run(
    app: AppHandle,
    workspace_id: String,
    card_id: String,
    provider: String,
) -> Result<crate::reviewer::ReviewerView, String> {
    let provider = match provider.as_str() {
        "claude" => crate::coordination::Provider::Claude,
        "codex" => crate::coordination::Provider::Codex,
        _ => return Err("reviewer provider must be 'claude' or 'codex'".into()),
    };
    tauri::async_runtime::spawn_blocking(move || {
        crate::reviewer::run_review(
            &app,
            provider,
            &workspace_id,
            &card_id,
            crate::review_passes::PASS_DIFF_BUDGET,
            // The independent review of a card without a Builder keeps its
            // prompt; ADR 0006's sweep is the Builder card's first review.
            crate::review_passes::ReviewKind::Review,
            None,
            &|_| {},
            None,
        )
    })
    .await
    .map_err(|error| format!("join independent reviewer: {error}"))?
}

#[tauri::command]
pub fn reviewer_list(
    reviewers: State<'_, crate::reviewer::ReviewerRegistry>,
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
    card_id: String,
) -> Result<Vec<crate::reviewer::ReviewerView>, String> {
    let cwd = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|workspace| workspace.id == workspace_id)
        .map(|workspace| PathBuf::from(workspace.cwd))
        .ok_or_else(|| format!("workspace '{workspace_id}' not found"))?;
    Ok(crate::reviewer::views_for_card(
        &reviewers,
        &cwd,
        &workspace_id,
        &card_id,
    ))
}

#[derive(Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct DiscussionChangedPayload {
    discussion_id: String,
    error: Option<String>,
}

fn schedule_discussion_worker(
    app: AppHandle,
    discussion_id: String,
    retry_failed_leg: Option<crate::discussion::DiscussionLegKind>,
) -> Result<(), String> {
    let permit = app
        .state::<crate::discussion::DiscussionRegistry>()
        .claim_worker(&discussion_id)?;
    tauri::async_runtime::spawn_blocking(move || {
        let _permit = permit;
        let result =
            crate::discussion::resume_discussion(&app, &discussion_id, retry_failed_leg);
        let payload = DiscussionChangedPayload {
            discussion_id,
            error: result.as_ref().err().cloned(),
        };
        let _ = app.emit("discussion://changed", payload);
        if let Err(error) = result {
            log::warn!("discussion worker failed: {error}");
        }
    });
    Ok(())
}

/// N19: why a discussion (Challenge the plan) may not start on this card —
/// a follow-up whose ask is still bare — or None.
pub(crate) fn discussion_card_refusal(card: Option<&KanbanCard>) -> Option<&'static str> {
    card.filter(|c| crate::kanban::follow_up_ask_empty(c))
        .map(|_| crate::kanban::FOLLOW_UP_ASK_EMPTY)
}

#[tauri::command]
pub async fn discussion_prepare(
    app: AppHandle,
    workspace_id: String,
    card_id: Option<String>,
    problem: String,
    synthesizer: String,
) -> Result<crate::discussion::DiscussionRecord, String> {
    let synthesizer = match synthesizer.as_str() {
        "claude" => crate::coordination::Provider::Claude,
        "codex" => crate::coordination::Provider::Codex,
        _ => return Err("discussion synthesizer must be 'claude' or 'codex'".into()),
    };
    // N19: a follow-up whose brief still asks "What should change now:"
    // with nothing after it starts no session — this one included.
    if let Some(card_id) = card_id.as_deref() {
        let card = app.state::<KanbanStore>().get_card(&workspace_id, card_id).ok();
        if let Some(why) = discussion_card_refusal(card.as_ref()) {
            return Err(why.to_string());
        }
    }
    let worker_app = app.clone();
    let record = tauri::async_runtime::spawn_blocking(move || {
        crate::discussion::prepare_discussion(
            &worker_app,
            &workspace_id,
            card_id.as_deref(),
            &problem,
            synthesizer,
        )
    })
    .await
    .map_err(|error| format!("join discussion preflight: {error}"))??;
    Ok(record)
}

#[tauri::command]
pub fn discussion_launch(app: AppHandle, discussion_id: String) -> Result<(), String> {
    let registry = app.state::<crate::discussion::DiscussionRegistry>();
    let record = registry
        .snapshot()
        .into_iter()
        .find(|record| record.id == discussion_id)
        .ok_or_else(|| format!("discussion '{discussion_id}' not found"))?;
    if record.current_phase != crate::discussion::DiscussionPhase::Preparing {
        return Err("discussion has already been launched".into());
    }
    registry.transition(
        &discussion_id,
        crate::discussion::DiscussionTransition::OpenPipeline,
        chrono::Utc::now().timestamp_millis(),
    )?;
    drop(registry);
    schedule_discussion_worker(app, discussion_id, None)
}

#[tauri::command]
pub fn discussion_list(
    discussions: State<'_, crate::discussion::DiscussionRegistry>,
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
) -> Result<Vec<crate::discussion::DiscussionView>, String> {
    let cwd = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|workspace| workspace.id == workspace_id)
        .map(|workspace| PathBuf::from(workspace.cwd))
        .ok_or_else(|| format!("workspace '{workspace_id}' not found"))?;
    Ok(crate::discussion::views_for_workspace(
        &discussions,
        &cwd,
        &workspace_id,
    ))
}

#[tauri::command]
pub fn discussion_resume(app: AppHandle, discussion_id: String) -> Result<(), String> {
    let record = app
        .state::<crate::discussion::DiscussionRegistry>()
        .snapshot()
        .into_iter()
        .find(|record| record.id == discussion_id)
        .ok_or_else(|| format!("discussion '{discussion_id}' not found"))?;
    if !matches!(
        record.status,
        crate::discussion::DiscussionStatus::PausedProviderUnavailable
            | crate::discussion::DiscussionStatus::Interrupted
    ) {
        return Err("only paused or interrupted discussions can resume".into());
    }
    schedule_discussion_worker(app, discussion_id, None)
}

#[tauri::command]
pub fn discussion_retry(
    app: AppHandle,
    discussion_id: String,
    leg: String,
) -> Result<(), String> {
    let leg = match leg.as_str() {
        "analysis_a" => crate::discussion::DiscussionLegKind::AnalysisA,
        "analysis_b" => crate::discussion::DiscussionLegKind::AnalysisB,
        "cross_review_a" => crate::discussion::DiscussionLegKind::CrossReviewA,
        "cross_review_b" => crate::discussion::DiscussionLegKind::CrossReviewB,
        "synthesis" => crate::discussion::DiscussionLegKind::Synthesis,
        _ => return Err("unknown discussion leg".into()),
    };
    let record = app
        .state::<crate::discussion::DiscussionRegistry>()
        .snapshot()
        .into_iter()
        .find(|record| record.id == discussion_id)
        .ok_or_else(|| format!("discussion '{discussion_id}' not found"))?;
    if crate::discussion::leg_status(&record, leg)
        != crate::discussion::DiscussionLegStatus::Failed
    {
        return Err("only a failed discussion leg can be retried".into());
    }
    schedule_discussion_worker(app, discussion_id, Some(leg))
}

#[tauri::command]
pub fn discussion_abort(app: AppHandle, discussion_id: String) -> Result<(), String> {
    let registry = app.state::<crate::discussion::DiscussionRegistry>();
    let record = registry
        .snapshot()
        .into_iter()
        .find(|record| record.id == discussion_id)
        .ok_or_else(|| format!("discussion '{discussion_id}' not found"))?;
    if matches!(
        record.status,
        crate::discussion::DiscussionStatus::Completed
            | crate::discussion::DiscussionStatus::Failed
            | crate::discussion::DiscussionStatus::Aborted
    ) {
        return Err("only a non-terminal discussion can be aborted".into());
    }
    let active_pty_ids: Vec<String> = app
        .state::<crate::coordination::CoordinationRegistry>()
        .snapshot()
        .sessions
        .into_iter()
        .filter(|session| {
            session.run_id.as_deref() == Some(discussion_id.as_str())
                && session.status.is_active()
        })
        .filter_map(|session| session.pty_id)
        .collect();
    registry.transition(
        &discussion_id,
        crate::discussion::DiscussionTransition::Abort {
            reason: "Aborted by user".into(),
        },
        chrono::Utc::now().timestamp_millis(),
    )?;
    drop(registry);
    let ptys = app.state::<crate::pty::PtyRegistry>();
    for pty_id in active_pty_ids {
        if let Err(error) = ptys.kill(&pty_id) {
            log::warn!("abort discussion collector {pty_id}: {error}");
        }
    }
    let _ = app.emit(
        "discussion://changed",
        DiscussionChangedPayload {
            discussion_id,
            error: None,
        },
    );
    Ok(())
}

// ── Library › Instructions (GH #101, BOARDS.md §5) ────────────────────
//
// The Phase 1C doctor behind a page. Its two old commands
// (`instruction_files_check` / `instruction_files_apply`) are gone with the
// panel that used them: a second way in would have been a way to write the
// checkout of a **shared** workspace, which the card forbids. `set_up` below is
// the one entry point, and it decides where the step writes.

/// Everything the Instructions page draws.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct InstructionsView {
    /// The workspace shares a definition, so the files travel on the channel and
    /// the page is about what the integration branch carries.
    pub shared: bool,
    pub branch: Option<String>,
    pub read_only: bool,
    pub repository: Option<String>,
    /// The checkout, for `Details`.
    pub workspace_root: String,
    /// `In this repository`: one Value row per instruction file the CLIs read.
    pub files: Vec<crate::instruction_files::InstructionFileRow>,
    /// The `Agent instructions` Procedure row.
    pub procedure: crate::instruction_files::InstructionProcedure,
    /// The flow the row's one step opens, already planned — `None` when the
    /// procedure is quiet.
    pub plan: Option<crate::instruction_files::InstructionFlowPlan>,
    /// `On this Mac`: read-only, both CLIs' own files.
    pub personal: Vec<crate::personal_instructions::PersonalInstructionFile>,
    /// What Ply would not read **on this Mac** — a personal instruction file that
    /// is a symlink, a directory or not UTF-8.
    ///
    /// GH #101 review 1 (NIT): this said "on the branch or on this Mac", which it
    /// never carried. What the branch holds and the mirror left out comes with the
    /// library state the page reads beside this (`LibraryState.skipped`), the way
    /// the Skills page reads its own.
    pub errors: Vec<String>,
}

/// GH #101: read the Instructions page. Read-only, on the blocking pool because
/// a shared workspace may have to build its mirror first.
#[tauri::command]
pub async fn library_instructions_view(
    app: AppHandle,
    workspace_id: String,
) -> Result<InstructionsView, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let source = crate::workspace_definition::app_instruction_source(&app, &workspace_id)?;
        let report = crate::instruction_files::inspect(&source.root, &workspace_id);
        // A file the branch keeps as a symlink is missing from the mirror, so the
        // doctor would read it as absent and offer to create one over the link.
        // Ply never replaces a symlinked instruction file, so the row says that
        // and there is no step (Phase 1C's rule, on the branch's side).
        let linked = crate::instruction_files::symlinked_on_branch(&source.skipped);
        let (procedure, plan) = if linked.is_empty() {
            (
                crate::instruction_files::procedure(&report),
                crate::instruction_files::plan(&report, source.shared, source.bases.clone()),
            )
        } else {
            (
                crate::instruction_files::manual_on_branch(
                    &linked,
                    source.branch.as_deref().unwrap_or("the integration branch"),
                ),
                None,
            )
        };
        let mine = crate::personal_instructions::read_personal_instructions(
            &crate::personal_skills::home_dir(),
        );
        Ok(InstructionsView {
            shared: source.shared,
            branch: source.branch,
            read_only: source.read_only,
            repository: source.repository,
            workspace_root: source.cwd.to_string_lossy().into_owned(),
            // GH #161: with the files a queued change laid over the build, so a
            // row about one of them says where the change waits instead of
            // reading the mirror as the branch.
            files: crate::instruction_files::file_rows(
                &source.root,
                &source.cwd,
                &source.queued,
                // …and the branch's own blob per file, which says whether a queued
                // change is laid **over** a copy the branch has (review 1).
                &source.bases,
            ),
            procedure,
            plan,
            personal: mine.files,
            // What Ply would not read on this Mac. What the branch carries and
            // the mirror left out (a symlinked instruction file) comes with the
            // library state the page reads beside this, like the Skills page's.
            errors: mine.errors,
        })
    })
    .await
    .map_err(|e| format!("join instructions view: {e}"))?
}

/// What the flow hands back when `Set up` is pressed: the step it drew, the
/// fingerprints it drew it from, and the blob ids the branch held then.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct InstructionStep {
    pub proposal_id: String,
    pub expected: crate::instruction_files::InstructionFilesExpected,
    #[serde(default)]
    pub bases: std::collections::BTreeMap<String, Option<String>>,
}

/// GH #101: run the Instructions page's one step (BOARDS.md §5 "The flow").
///
/// **Two paths, chosen by the workspace, never by the window.**
///
/// - A **shared** workspace publishes both files in one commit on the
///   integration branch through the library channel, and writes **nothing** to
///   the checkout: the checkout receives them with the normal Sync, like any
///   other shared change. The change carries the blob ids the flow was read
///   with, so a file that moved on the branch meanwhile gets a pull request
///   `Instructions: <file>` instead of being committed over.
/// - A workspace with **no shared definition** writes the checkout as the Phase
///   1C doctor always did, fingerprint-gated, and the flow said `after you
///   commit it`.
///
/// Answers `true` when the change went to the channel (so the page can say
/// "publishing"), `false` when the checkout was written.
#[tauri::command]
pub async fn library_instructions_set_up(
    app: AppHandle,
    workspace_id: String,
    step: InstructionStep,
) -> Result<bool, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let source = crate::workspace_definition::app_instruction_source(&app, &workspace_id)?;
        if !source.shared {
            // The one writer of a checkout in this card, and it is only ever
            // reached when there is no shared definition to publish to.
            let store = app.state::<WorkspaceStore>();
            crate::instruction_files::apply(
                &store,
                &workspace_id,
                &step.proposal_id,
                &step.expected,
            )?;
            return Ok(false);
        }
        // The same refusal the view makes, at the door: the mirror has no copy of
        // a file the branch keeps as a symlink, so both fingerprints would read
        // "absent" and a stale window's plan would otherwise write a regular file
        // over the link.
        let linked = crate::instruction_files::symlinked_on_branch(&source.skipped);
        if !linked.is_empty() {
            return Err(format!(
                "{} on {} {} a symlink, and Plyloft does not replace one. Nothing was changed.",
                linked.join(" and "),
                source.branch.as_deref().unwrap_or("the integration branch"),
                if linked.len() == 1 { "is" } else { "are" },
            ));
        }
        let queued = crate::workspace_definition::app_library_change(&app, &workspace_id, |mirror| {
            // Recomputed from the mirror under the workspace lock: what is
            // written is what this proposal produces from the branch's bytes,
            // never anything the window sent.
            let files = crate::instruction_files::channel_files(
                mirror,
                &step.proposal_id,
                &step.expected,
            )?;
            let title = crate::instruction_files::commit_subject(&step.proposal_id);
            let change = crate::shared_library_sync::LibraryChange::instructions(
                &title,
                files
                    .into_iter()
                    .map(|(path, text)| {
                        crate::shared_library_sync::LibraryFile::new(path, text.as_bytes(), false)
                    })
                    .collect(),
                step.bases.clone(),
            )?;
            Ok((Some(change), ()))
        })?;
        queued
            .map(|()| true)
            .ok_or_else(|| "This workspace's shared definition went away; try again.".to_string())
    })
    .await
    .map_err(|e| format!("join instructions set up: {e}"))?
}

/// GH #101 (BOARDS.md §5, `On this Mac`): show a personal instruction file in
/// Finder.
///
/// The only way Ply reaches those files at all beyond reading them — there is no
/// writable `Open in Code` for one, because Ply must never write there (GH #174's
/// `›` reads one into Code's read-only view, through the same guard).
/// `listed_instruction_file` decides whether the path is one Ply itself listed
/// and refuses every other shape in words; `personal_instructions_tests` walks
/// each refusal. No Tauri plugin is involved: `open` is spawned the way
/// `personal_skill_reveal` and `worktree_reveal` spawn it.
#[tauri::command(async)]
pub fn personal_instruction_reveal(path: String) -> Result<(), String> {
    let file = crate::personal_instructions::listed_instruction_file(
        &crate::personal_skills::home_dir(),
        &path,
    )?;
    crate::platform::reveal_path(&file).map_err(|e| format!("open -R failed: {e}"))?;
    Ok(())
}

