/// Try it (TI-2): the card copy a Try session is started for. The
/// workspace is `pty_spawn`'s own `workspace_id`.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PtyTryArg {
    pub card_id: String,
    #[serde(default)]
    pub lane: Option<String>,
}

/// TI-2: a Try session is a shell tile of a workspace's card.
pub(crate) fn try_target_for(
    try_arg: Option<PtyTryArg>,
    workspace_id: Option<&str>,
    is_provider: bool,
) -> Result<Option<crate::try_session::TryTarget>, String> {
    let Some(arg) = try_arg else { return Ok(None) };
    if is_provider {
        return Err("a Try session runs in a shell, not in Claude or Codex".into());
    }
    let workspace_id = workspace_id
        .filter(|w| !w.trim().is_empty())
        .ok_or_else(|| "a Try session needs its workspace".to_string())?;
    if arg.card_id.trim().is_empty() {
        return Err("a Try session needs its card".into());
    }
    Ok(Some(crate::try_session::TryTarget {
        workspace_id: workspace_id.to_string(),
        card_id: arg.card_id,
        lane: arg.lane.filter(|l| !l.is_empty()),
    }))
}

#[tauri::command]
#[allow(clippy::too_many_arguments)]
pub fn pty_spawn(
    app: tauri::AppHandle,
    registry: State<'_, PtyRegistry>,
    cmd: String,
    args: Vec<String>,
    cwd: Option<String>,
    workspace_id: Option<String>,
    cols: u16,
    rows: u16,
    try_target: Option<PtyTryArg>,
    cli: Option<String>,
    id: Option<String>, // 1.176.0 R7: the id the tile already listens under (`pty_tile_id`)
) -> Result<String, String> {
    // 1.176.0 R3: a Claude/Codex tile is known by its declared kind and runs
    // the backend's path for it, checked on disk now (`cli_fresh`).
    let (cmd, provider) = crate::cli_fresh::tile_program(cli.as_deref(), cmd)?;
    let try_target = try_target_for(try_target, workspace_id.as_deref(), provider.is_some())?;
    crate::pr_review::refuse_terminal(&app, workspace_id.as_deref(), cwd.as_deref())?; // 1.175.0 G7
    let project = match (&workspace_id, &cwd) {
        (Some(workspace_id), Some(cwd)) => crate::coordination::SpawnProject::Project {
            workspace_id: workspace_id.clone(),
            cwd: cwd.into(),
        },
        _ => crate::coordination::SpawnProject::NonProject {
            reason: "terminal launched without both workspace and cwd context".to_string(),
        },
    };
    let coordination_provider = match provider {
        Some(crate::mcp_launch::Provider::Claude) => crate::coordination::Provider::Claude,
        Some(crate::mcp_launch::Provider::Codex) => crate::coordination::Provider::Codex,
        None => crate::coordination::Provider::Shell,
    };
    let enforcement = if matches!(
        &project,
        crate::coordination::SpawnProject::NonProject { .. }
    ) {
        crate::coordination::Enforcement::Exempt
    } else {
        crate::coordination::Enforcement::Advisory
    };
    let intent = crate::coordination::SpawnIntent {
        provider: coordination_provider,
        execution_kind: if provider.is_some() {
            crate::coordination::ExecutionKind::ProviderTile
        } else {
            crate::coordination::ExecutionKind::ShellTile
        },
        attendance: crate::coordination::Attendance::HumanAttended,
        write_intent: crate::coordination::WriteIntent::Unknown,
        enforcement,
        project,
        capability: None,
        card_id: None,
        swarm_id: None,
        role_id: None,
        run_id: None,
        retention_class: crate::coordination::RetentionClass::Interactive,
        objective: None,
    };
    // Terminals block P1: the workspace the tile's row is recorded under.
    let record_ws = workspace_id.clone();
    let knowledge_mcp = match provider {
        Some(provider) => {
            let workspace_id = workspace_id.ok_or_else(|| "provider terminal requires workspaceId".to_string())?;
            let project_cwd = cwd
                .as_deref()
                .ok_or_else(|| "provider terminal requires a project cwd".to_string())?;
            Some(crate::mcp_launch::KnowledgeMcpContext::new(
                &app,
                provider,
                workspace_id,
                project_cwd,
            )?)
        }
        // Shell tiles are free side channels. Even if the frontend supplies
        // workspaceId, they receive no MCP configuration.
        None => None,
    };
    // GH #69: a Claude tile draws for Ply's effective theme at spawn.
    let args = if matches!(provider, Some(crate::mcp_launch::Provider::Claude)) {
        crate::claude_theme::session_args(&app, args)
    } else {
        args
    };
    // Terminals block P1: a Claude tile runs a conversation Plyloft knows the
    // id of (`--session-id`, unless its args already name one), so its name,
    // Resume… and History › Sessions can find it. Codex can't be told an id
    // at spawn: it is looked up after its first turn.
    // P4: a Codex tile opened by Resume… runs `codex resume <id>`.
    let (args, cli_session_id) = match provider {
        Some(crate::mcp_launch::Provider::Claude) => crate::terminal_sessions::claude_args_with_session(args),
        Some(crate::mcp_launch::Provider::Codex) => {
            let id = crate::terminal_sessions::codex_resumed_session(&args);
            (args, id)
        }
        None => (args, None),
    };
    let record = match (provider, record_ws, cwd.clone()) {
        (Some(p), Some(ws), Some(dir)) => Some((
            match p {
                crate::mcp_launch::Provider::Claude => crate::terminal_sessions::SessionKind::Claude,
                crate::mcp_launch::Provider::Codex => crate::terminal_sessions::SessionKind::Codex,
            },
            ws,
            dir,
        )),
        _ => None,
    };
    let id = registry.spawn_tile(app.clone(), &cmd, args, cwd, knowledge_mcp, intent, cols, rows, try_target, id)?;
    if let Some((kind, ws, dir)) = record {
        use tauri::Manager;
        // A row not saved never stops the tile: the tile is the member's.
        match app.path().app_config_dir() {
            Ok(config_dir) => {
                if let Err(error) =
                    crate::terminal_sessions::record_start(&config_dir, &ws, &id, kind, &dir, cli_session_id)
                {
                    log::warn!("terminal sessions: start not saved: {error}");
                }
            }
            Err(error) => log::warn!("terminal sessions: no config dir: {error}"),
        }
    }
    Ok(id)
}

