/// QoL 1.168 (block 4, D11): every workspace's Claude and Codex sessions that
/// were open when Plyloft last quit — the offer to reopen them (never
/// automatic), read once at launch. Only workspaces with something to offer.
#[tauri::command(async)]
pub fn terminal_reopen_offers(
    app: tauri::AppHandle,
    workspaces: State<'_, WorkspaceStore>,
) -> Result<std::collections::HashMap<String, Vec<crate::terminal_sessions::ListedSession>>, String> {
    let config_dir = app.path().app_config_dir().map_err(|e| format!("config dir: {e}"))?;
    let homes = crate::terminal_sessions::CliHomes::real();
    Ok(workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .map(|w| {
            // 1.174.0 walk G3 Windows: only a session with a conversation
            // to resume is offered; none left, no row.
            let offer = crate::terminal_sessions::reopen_offer_resumable(&config_dir, &w.id, &homes);
            (w.id, offer)
        })
        .filter(|(_, offer)| !offer.is_empty())
        .collect())
}

