#[tauri::command]
pub fn workspace_delete(
    store: State<'_, WorkspaceStore>,
    kanban: State<'_, KanbanStore>,
    memory: State<'_, MemoryStore>,
    codex_approvals: State<'_, crate::codex_app::CodexApprovalStore>,
    project_config: State<'_, ProjectConfigStore>,
    chats: State<'_, crate::chat::ChatRegistry>,
    plans: State<'_, crate::plan_exchange::PlanExchanges>,
    rounds: State<'_, crate::next_improvement::round::Rounds>,
    id: String,
) -> Result<(), String> {
    // GH #222 review 4: never while a release of it is committed here but
    // unpublished — its tag would be left on this Mac with nothing in Ply
    // to publish or dismiss it.
    if let Some(refusal) = ship::workspace_delete_refusal(&project_config, &kanban, &id) {
        return Err(refusal);
    }
    store.delete(&id)?;
    // Its plan exchanges: nothing is written for them again.
    plans.forget_workspace(&id);
    // Its Next improvement rounds (E2): stopped, nothing written again.
    rounds.forget_workspace(&id);
    // Its card chats: sessions ended, records, attachments and chat folders
    // removed (on a thread of their own; nothing is stored for it again).
    let _ = chats.forget_workspace(&id);
    // Best-effort kanban cleanup: orphan files would be harmless but we'd
    // rather not leak per-workspace JSON for deleted workspaces.
    if let Err(e) = kanban.delete_workspace(&id) {
        log::warn!("kanban: cleanup for deleted workspace {id} failed: {e}");
    }
    // v1.35.0: same best-effort cleanup for the workspace's memory dir.
    // Failure logs and continues — never blocks the workspace delete.
    if let Err(e) = memory.delete_workspace(&id) {
        log::warn!("memory: cleanup for deleted workspace {id} failed: {e}");
    }
    if let Err(e) = codex_approvals.remove_workspace(&id) {
        log::warn!("codex approvals: cleanup for deleted workspace {id} failed: {e}");
    }
    // Skills hub H8: its links kept on this Mac (and its twin record) go too.
    if let Err(e) = crate::skills_hub_state::forget_workspace(&store.config_dir, &id, chrono::Utc::now().timestamp_millis()) {
        log::warn!("skills hub: cleanup for deleted workspace {id} failed: {e}");
    }
    Ok(())
}

