/// Move to the Trash / Recycle Bin; answers the token Undo hands back.
#[tauri::command(async)]
pub fn fs_trash_entry(
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
    path: String,
) -> Result<String, String> {
    let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
    let original = PathBuf::from(&path);
    let landed = files::trash_entry(&ws_cwd, &original)?;
    Ok(files::remember_trashed(original, landed))
}

/// Undo of `fs_trash_entry`: answers the path the entry is back at.
#[tauri::command(async)]
pub fn fs_undo_trash(token: String) -> Result<String, String> {
    files::undo_trash(&token).map(|p| p.to_string_lossy().into_owned())
}

/// Reveal in Finder / File Explorer from a tree row (a file or a folder).
#[tauri::command(async)]
pub fn fs_reveal_entry(
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
    path: String,
) -> Result<(), String> {
    let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
    let target = files::reveal_entry_target(&ws_cwd, Path::new(&path))?;
    crate::platform::reveal_path(&target).map_err(|e| format!("open -R failed: {e}"))?;
    Ok(())
}

/// QoL 6.4: what a file dropped on the editor opens as — the workspace's own
/// file (`inside`), or a read-only copy kept in the app's cache.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DroppedOpen {
    pub path: String,
    pub inside: bool,
}

/// QoL 6.4: a file dropped from Finder / File Explorer onto the editor. The
/// webview gives its bytes, never its path, so the workspace is searched for
/// the same file (`files::locate_dropped`); when it isn't there, the bytes
/// are kept as a copy the editor opens read-only. `expected_len` is the
/// length the webview read (GH #230): bytes that arrived short are refused.
///
/// D3 (1.172.2): a raw request ([`DroppedRequest`]) — the body is the file's
/// bytes, the workspace, name, length and modification time are headers.
#[tauri::command(async)]
pub fn fs_open_dropped(
    app: tauri::AppHandle,
    workspaces: State<'_, WorkspaceStore>,
    request: tauri::ipc::Request<'_>,
) -> Result<DroppedOpen, String> {
    let drop = DroppedRequest::new(request.headers(), request.body())?;
    let workspace_id = drop.header(crate::chat::HEADER_WORKSPACE)?;
    let name = drop.name()?;
    let bytes = drop.bytes;
    if let Some(expected) = drop.number::<u64>(HEADER_EXPECTED_LEN)? {
        if bytes.len() as u64 != expected {
            return Err(format!(
                "{name}: received {} of {expected} bytes; nothing was opened",
                bytes.len()
            ));
        }
    }
    let modified_ms = drop.number::<i64>(HEADER_MODIFIED_MS)?;
    let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
    if let Some(found) = files::locate_dropped(&ws_cwd, &name, bytes, modified_ms) {
        return Ok(DroppedOpen { path: found.to_string_lossy().into_owned(), inside: true });
    }
    let cache_dir = app.path().app_cache_dir().map_err(|e| format!("app_cache_dir: {e}"))?;
    let copy = files::save_dropped_copy(&cache_dir.join("dropped"), &name, bytes)?;
    Ok(DroppedOpen { path: copy.to_string_lossy().into_owned(), inside: false })
}

/// QoL 6.4: "Copy into the project" on a dropped file's read-only copy. Only
/// a copy `fs_open_dropped` kept is read; it lands in the workspace folder.
#[tauri::command(async)]
pub fn fs_copy_into_workspace(
    app: tauri::AppHandle,
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
    source: String,
    name: String,
) -> Result<String, String> {
    let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
    let dropped = app
        .path()
        .app_cache_dir()
        .map_err(|e| format!("app_cache_dir: {e}"))?
        .join("dropped");
    let source = Path::new(&source);
    let kept = crate::platform::canonicalize(&dropped).ok().zip(crate::platform::canonicalize(source).ok());
    if !kept.is_some_and(|(dir, file)| crate::platform::is_within(&file, &dir) && file.is_file()) {
        return Err("only a dropped file's copy can be copied into the project".into());
    }
    files::copy_into_workspace(&ws_cwd, source, &name).map(|p| p.to_string_lossy().into_owned())
}

/// Save bytes from a drag-dropped external file into the app cache dir and
/// return the resulting absolute path. Used by `Terminal.tsx` to give the
/// PTY a real filesystem path for files dragged from Finder (browsers don't
/// expose `File.path`, so the bytes come through and we materialize them).
///
/// The file lives at `<app_cache>/dropped/<uuid>-<safe_name>` so collisions
/// are impossible; `cache_retention::prune_old` sweeps the directory.
///
/// GH #230: `expected_len` is the length the webview read and checked
/// against `File.size`. Bytes that arrive short (or long) are refused and
/// nothing is written, and the save itself is a same-directory tempfile
/// renamed into place, so the path handed back never names a partial file.
/// The length header is optional, so a caller without it still saves.
///
/// D3 (1.172.2): a raw request ([`DroppedRequest`]) — the body is the file's
/// bytes (a 5 MB screenshot was a ~20 MB JSON number array before), the name
/// and length are headers. Off the main thread.
#[tauri::command(async)]
pub fn fs_save_dropped_file<R: tauri::Runtime>(
    app: tauri::AppHandle<R>,
    request: tauri::ipc::Request<'_>,
) -> Result<String, String> {
    let drop = DroppedRequest::new(request.headers(), request.body())?;
    let name = drop.name()?;
    let expected_len = drop.number::<u64>(HEADER_EXPECTED_LEN)?;
    let cache_dir = app
        .path()
        .app_cache_dir()
        .map_err(|e| format!("app_cache_dir: {e}"))?;
    let target = save_dropped_bytes(&cache_dir.join("dropped"), &name, drop.bytes, expected_len)?;
    Ok(target.to_string_lossy().to_string())
}

/// D3 (1.172.2): the dropped file's length as the webview read it (GH #230).
pub(crate) const HEADER_EXPECTED_LEN: &str = "x-ply-expected-len";
/// D3: the dropped file's modification time, ms since the epoch (QoL 6.4).
pub(crate) const HEADER_MODIFIED_MS: &str = "x-ply-modified-ms";

/// D3 (1.172.2): what a raw dropped-file request carries — the file's bytes
/// as the body (borrowed, never copied) and its other arguments as headers:
/// the name percent-encoded (`chat::HEADER_NAME`, a header value is ASCII),
/// the workspace and card as they are, numbers as decimal text. A JSON body
/// is refused, so an old number-array caller fails loudly, not half-way.
pub(crate) struct DroppedRequest<'a> {
    headers: &'a tauri::http::HeaderMap,
    pub bytes: &'a [u8],
}

impl<'a> DroppedRequest<'a> {
    pub(crate) fn new(
        headers: &'a tauri::http::HeaderMap,
        body: &'a tauri::ipc::InvokeBody,
    ) -> Result<Self, String> {
        match body {
            tauri::ipc::InvokeBody::Raw(bytes) => Ok(Self { headers, bytes: bytes.as_slice() }),
            tauri::ipc::InvokeBody::Json(_) => {
                Err("send the file's bytes as the raw request body (a Uint8Array), not JSON".into())
            }
        }
    }

    fn optional(&self, name: &str) -> Result<Option<&'a str>, String> {
        self.headers
            .get(name)
            .map(|value| value.to_str().map_err(|_| format!("the {name} header is not plain text")))
            .transpose()
    }

    /// A header the request must carry.
    pub(crate) fn header(&self, name: &str) -> Result<String, String> {
        self.optional(name)?
            .map(str::to_string)
            .ok_or_else(|| format!("the file's request has no {name} header"))
    }

    /// The file's name, decoded from its percent-encoded header.
    pub(crate) fn name(&self) -> Result<String, String> {
        crate::chat::percent_decode(&self.header(crate::chat::HEADER_NAME)?)
    }

    /// An optional number header (absent → `None`; present, it must parse).
    pub(crate) fn number<T: std::str::FromStr>(&self, name: &str) -> Result<Option<T>, String> {
        self.optional(name)?
            .map(|raw| raw.trim().parse::<T>().map_err(|_| format!("the {name} header is not a number")))
            .transpose()
    }
}

/// GH #230: the body of `fs_save_dropped_file`, apart from the app handle.
/// Also a card chat attachment's write (`chat_attachments::store`).
pub(crate) fn save_dropped_bytes(
    dropped_dir: &Path,
    name: &str,
    bytes: &[u8],
    expected_len: Option<u64>,
) -> Result<PathBuf, String> {
    use std::io::Write;
    if let Some(expected) = expected_len {
        if bytes.len() as u64 != expected {
            return Err(format!(
                "{name}: received {} of {expected} bytes; nothing was saved",
                bytes.len()
            ));
        }
    }
    std::fs::create_dir_all(dropped_dir).map_err(|e| format!("mkdir: {e}"))?;
    let safe = sanitize_dropped_name(name);
    let target = dropped_dir.join(format!("{}-{}", uuid::Uuid::new_v4(), safe));
    let mut tmp = tempfile::Builder::new()
        .prefix(".drop-")
        .suffix(crate::atomic::TEMP_SUFFIX)
        .tempfile_in(dropped_dir)
        .map_err(|e| format!("create temp in {}: {e}", dropped_dir.display()))?;
    tmp.write_all(bytes)
        .and_then(|()| tmp.as_file().sync_all())
        .map_err(|e| format!("write: {e}"))?;
    let written = tmp
        .as_file()
        .metadata()
        .map_err(|e| format!("stat temp: {e}"))?
        .len();
    if written != bytes.len() as u64 {
        return Err(format!(
            "{name}: wrote {written} of {} bytes; nothing was saved",
            bytes.len()
        ));
    }
    tmp.persist_noclobber(&target)
        .map_err(|e| format!("rename into {}: {}", target.display(), e.error))?;
    crate::platform::mark_from_internet(&target);
    Ok(target)
}

fn sanitize_dropped_name(name: &str) -> String {
    let trimmed = name.trim_matches(|c: char| c.is_whitespace() || c == '/' || c == '\\');
    let safe: String = trimmed
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '.' || c == '-' || c == '_' {
                c
            } else {
                '-'
            }
        })
        .collect();
    // Windows drops trailing dots from a name (spaces are already `-`), so
    // `x.exe.` would land as `x.exe`; the name is cut the same way everywhere.
    let safe = safe.trim_end_matches('.').to_string();
    if safe.is_empty() {
        return "drop".to_string();
    }
    if safe.len() > 100 {
        return safe[safe.len() - 100..].to_string();
    }
    safe
}

#[cfg(test)]
mod dropped_file_tests {
    use super::save_dropped_bytes;

    #[test]
    fn a_trailing_dot_is_cut_as_windows_would() {
        use super::sanitize_dropped_name;
        assert_eq!(sanitize_dropped_name("x.exe."), "x.exe");
        assert_eq!(sanitize_dropped_name("x.exe..."), "x.exe");
        assert_eq!(sanitize_dropped_name("..."), "drop");
        assert_eq!(sanitize_dropped_name("shot.png"), "shot.png");
    }

    /// GH #230: a drop larger than any chunk the path could stop at — 1.5 MiB,
    /// not a multiple of 64 KiB — is saved byte-identical, and nothing but the
    /// saved file is left in the directory.
    #[test]
    fn a_large_drop_is_saved_byte_identical() {
        let dir = tempfile::tempdir().unwrap();
        let bytes: Vec<u8> = (0..1_572_864u32 + 4_321).map(|i| (i * 31 % 251) as u8).collect();
        let saved =
            save_dropped_bytes(dir.path(), "Screenshot 22.13.58.png", &bytes, Some(bytes.len() as u64))
                .unwrap();
        assert_eq!(std::fs::read(&saved).unwrap(), bytes);
        assert!(saved.file_name().unwrap().to_string_lossy().ends_with("-Screenshot-22.13.58.png"));
        let entries: Vec<_> = std::fs::read_dir(dir.path()).unwrap().collect();
        assert_eq!(entries.len(), 1, "a temp was left beside the saved file");
    }

    /// GH #230: bytes shorter than the length the webview read are refused,
    /// and nothing — not even a partial file — is written.
    #[test]
    fn a_short_payload_is_refused_and_nothing_is_written() {
        let dir = tempfile::tempdir().unwrap();
        let bytes = vec![7u8; 262_144];
        let err = save_dropped_bytes(dir.path(), "shot.png", &bytes, Some(454_561)).unwrap_err();
        assert!(err.contains("received 262144 of 454561 bytes"), "{err}");
        assert_eq!(std::fs::read_dir(dir.path()).unwrap().count(), 0);
    }

    /// An older caller that sends no length still saves.
    #[test]
    fn no_expected_length_still_saves() {
        let dir = tempfile::tempdir().unwrap();
        let saved = save_dropped_bytes(dir.path(), "a.txt", b"hello", None).unwrap();
        assert_eq!(std::fs::read(saved).unwrap(), b"hello");
    }

    fn drop_headers(pairs: &[(&'static str, &str)]) -> tauri::http::HeaderMap {
        let mut headers = tauri::http::HeaderMap::new();
        for (name, value) in pairs {
            headers.insert(*name, value.parse().unwrap());
        }
        headers
    }

    /// D3: a raw body is read in place and saved whole, the name decoded from
    /// its percent-encoded header (spaces, an accent, an emoji), the length
    /// and modification time read as numbers.
    #[test]
    fn a_raw_drop_request_is_saved_whole_with_its_unicode_name() {
        use super::{DroppedRequest, HEADER_EXPECTED_LEN, HEADER_MODIFIED_MS};
        use crate::chat::{HEADER_CARD, HEADER_NAME, HEADER_WORKSPACE};
        let bytes: Vec<u8> = (0..1_048_576u32 + 77).map(|i| (i * 7 % 253) as u8).collect();
        let len = bytes.len().to_string();
        // encodeURIComponent("Screenshot 2026-10-28 à 15.35 📸.png")
        let headers = drop_headers(&[
            (HEADER_WORKSPACE, "ws-1"),
            (HEADER_CARD, "card-1"),
            (HEADER_NAME, "Screenshot%202026-10-28%20%C3%A0%2015.35%20%F0%9F%93%B8.png"),
            (HEADER_EXPECTED_LEN, &len),
            (HEADER_MODIFIED_MS, "1761665700123"),
        ]);
        let body = tauri::ipc::InvokeBody::Raw(bytes.clone());
        let drop = DroppedRequest::new(&headers, &body).unwrap();
        assert_eq!(drop.name().unwrap(), "Screenshot 2026-10-28 à 15.35 📸.png");
        assert_eq!(drop.header(HEADER_WORKSPACE).unwrap(), "ws-1");
        assert_eq!(drop.header(HEADER_CARD).unwrap(), "card-1");
        assert_eq!(drop.number::<u64>(HEADER_EXPECTED_LEN).unwrap(), Some(bytes.len() as u64));
        assert_eq!(drop.number::<i64>(HEADER_MODIFIED_MS).unwrap(), Some(1_761_665_700_123));
        let tauri::ipc::InvokeBody::Raw(raw) = &body else { unreachable!() };
        assert_eq!(drop.bytes.as_ptr(), raw.as_ptr(), "the body is borrowed, not copied");
        let dir = tempfile::tempdir().unwrap();
        let saved = save_dropped_bytes(
            dir.path(),
            &drop.name().unwrap(),
            drop.bytes,
            drop.number(HEADER_EXPECTED_LEN).unwrap(),
        )
        .unwrap();
        assert_eq!(std::fs::read(&saved).unwrap(), bytes);
    }

    /// D3: a JSON body (the old number array) is refused; a missing name, a
    /// broken escape or a length that isn't a number is named.
    #[test]
    fn a_json_body_and_broken_headers_are_refused() {
        use super::{DroppedRequest, HEADER_EXPECTED_LEN};
        use crate::chat::{HEADER_NAME, HEADER_WORKSPACE};
        let headers = drop_headers(&[(HEADER_NAME, "a.png")]);
        let json = tauri::ipc::InvokeBody::Json(serde_json::json!({ "bytes": [1, 2, 3] }));
        let err = DroppedRequest::new(&headers, &json).err().unwrap();
        assert!(err.contains("raw request body"), "{err}");

        let body = tauri::ipc::InvokeBody::Raw(b"x".to_vec());
        let drop = DroppedRequest::new(&headers, &body).unwrap();
        assert_eq!(drop.number::<u64>(HEADER_EXPECTED_LEN).unwrap(), None, "the length is optional");
        assert!(drop.header(HEADER_WORKSPACE).unwrap_err().contains(HEADER_WORKSPACE));

        let none = drop_headers(&[]);
        let drop = DroppedRequest::new(&none, &body).unwrap();
        assert!(drop.name().unwrap_err().contains(HEADER_NAME));

        let broken = drop_headers(&[(HEADER_NAME, "a%ZZ.png"), (HEADER_EXPECTED_LEN, "12 bytes")]);
        let drop = DroppedRequest::new(&broken, &body).unwrap();
        assert!(drop.name().is_err());
        assert!(drop.number::<u64>(HEADER_EXPECTED_LEN).unwrap_err().contains("not a number"));
    }

    /// D3 through the registered IPC path: `fs_save_dropped_file` refuses a
    /// JSON body, and a raw body short of its length header (GH #230) —
    /// both before anything is written.
    #[test]
    fn fs_save_dropped_file_takes_only_a_raw_body_of_the_length_read() {
        use super::HEADER_EXPECTED_LEN;
        use crate::chat::HEADER_NAME;
        use tauri::ipc::{CallbackFn, InvokeBody};
        use tauri::test::{get_ipc_response, mock_builder, mock_context, noop_assets};
        use tauri::webview::InvokeRequest;

        let app = mock_builder()
            .invoke_handler(tauri::generate_handler![super::fs_save_dropped_file])
            .build(mock_context(noop_assets()))
            .expect("mock app");
        let webview = tauri::WebviewWindowBuilder::new(&app, "main", Default::default())
            .build()
            .expect("mock webview");
        let call = |body: InvokeBody, headers: tauri::http::HeaderMap| {
            get_ipc_response(
                &webview,
                InvokeRequest {
                    cmd: "fs_save_dropped_file".into(),
                    callback: CallbackFn(0),
                    error: CallbackFn(1),
                    url: "http://tauri.localhost".parse().expect("invoke URL"),
                    body,
                    headers,
                    invoke_key: tauri::test::INVOKE_KEY.to_string(),
                },
            )
        };
        let json = call(
            InvokeBody::Json(serde_json::json!({ "name": "a.png", "bytes": [1, 2, 3], "expectedLen": 3 })),
            Default::default(),
        )
        .expect_err("a JSON body is refused");
        assert!(json.as_str().unwrap().contains("raw request body"), "{json}");

        let short = call(
            InvokeBody::Raw(vec![7u8; 262_144]),
            drop_headers(&[(HEADER_NAME, "shot%20%C3%A9.png"), (HEADER_EXPECTED_LEN, "454561")]),
        )
        .expect_err("a short body is refused");
        assert_eq!(
            short.as_str().unwrap(),
            "shot é.png: received 262144 of 454561 bytes; nothing was saved"
        );
    }
}

#[tauri::command]
pub fn fs_write_text_file(
    watcher: State<'_, WatcherRegistry>,
    path: String,
    content: String,
) -> Result<(), String> {
    let p = Path::new(&path);
    watcher.self_writes().register(p);
    files::write_text_file(p, &content)
}

/// The folder Claude must trust once for Plyloft's read-only Claude sessions
/// (Challenger reviews, discussions, proposals, the capability probe) to run
/// in its interactive TUI — `<config>/claude-sessions`
/// (`claude_session::sessions_root`) — and whether it does (`None`: Claude's state unreadable).
/// Plyloft never answers Claude's trust question: the member does, in a
/// Claude tile opened on `folder`.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ClaudeReviewTrust {
    pub folder: String,
    pub trusted: Option<bool>,
}

#[tauri::command(async)]
pub fn claude_review_trust_status(app: tauri::AppHandle) -> Result<ClaudeReviewTrust, String> {
    let config = app.path().app_config_dir().map_err(|e| e.to_string())?;
    // The session root, not the config dir: the tile the member opens there
    // reaches no settings, workspaces or entitlement. It exists, so the tile
    // can start in it.
    let folder = crate::claude_session::sessions_root(&config);
    std::fs::create_dir_all(&folder).map_err(|e| format!("create {}: {e}", folder.display()))?;
    Ok(ClaudeReviewTrust {
        trusted: crate::claude_session::folder_trusted(&folder),
        folder: folder.to_string_lossy().into_owned(),
    })
}

/// Async: starting a watch scans the workspace tree for the rename cache,
/// which must not hold the main thread (it froze launch with a large repo).
#[tauri::command]
pub async fn fs_watch_workspace(
    app: tauri::AppHandle,
    workspace_id: String,
    cwd: String,
) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        let watcher = app.state::<WatcherRegistry>();
        watcher.watch(app.clone(), workspace_id, PathBuf::from(cwd))
    })
    .await
    .map_err(|e| format!("watch worker failed: {e}"))?
}

/// 1.174.0 E1 (Challenger 1, E1-4 b): which of the watcher's changed `paths`
/// git ignores in `cwd` (the project folder or a copy's) — the "Same folder"
/// chip leaves those out. Async: one `git check-ignore` off the main thread.
#[tauri::command]
pub async fn fs_ignored_paths(cwd: String, paths: Vec<String>) -> Result<Vec<String>, String> {
    tauri::async_runtime::spawn_blocking(move || crate::watcher::ignored_among(Path::new(&cwd), &paths))
        .await
        .map_err(|e| format!("check-ignore worker failed: {e}"))
}

#[tauri::command]
pub fn fs_unwatch_workspace(
    watcher: State<'_, WatcherRegistry>,
    workspace_id: String,
) -> Result<(), String> {
    watcher.unwatch(&workspace_id);
    Ok(())
}

