#[tauri::command]
pub fn settings_set(
    app: tauri::AppHandle,
    store: State<'_, SettingsStore>,
    watcher: State<'_, WatcherRegistry>,
    settings: Settings,
    // 1.176.2 R2: the copy the window's change was based on; only what the
    // window changed against it is applied (`settings_merge`).
    base: Option<Settings>,
) -> Result<Settings, String> {
    let old_cap = store.snapshot().card_swarm_cap();
    let saved = store.replace_from(base, settings)?;
    after_window_save(&app, &watcher, old_cap, &saved);
    Ok(saved)
}

/// What every save from the window does once it is stored: `settings_set`,
/// and since 1.176.3 `settings_reset` (`settings_reset.rs`).
pub(crate) fn after_window_save(app: &tauri::AppHandle, watcher: &WatcherRegistry, old_cap: usize, saved: &Settings) {
    // v1.30.0 (parallel swarms): keep the SwarmRegistry's card-swarm cap in
    // sync with the user's Settings value; if the cap was raised, pump every
    // workspace's queue so the freshly-opened slots fill immediately.
    {
        use tauri::Manager;
        if let Some(reg) = app.try_state::<crate::swarms::SwarmRegistry>() {
            reg.set_card_swarm_cap(saved.card_swarm_cap());
        }
        if saved.card_swarm_cap() > old_cap {
            if let Some(ws_store) = app.try_state::<crate::workspace::WorkspaceStore>() {
                let workspace_ids: Vec<String> = ws_store
                    .snapshot()
                    .workspaces
                    .iter()
                    .map(|w| w.id.clone())
                    .collect();
                for ws_id in workspace_ids {
                    crate::kanban::pump_card_queue(app, &ws_id);
                }
            }
        }
    }
    watcher.set_enabled(saved.behavior.file_watcher_enabled);
    // A changed (or cleared) PATH override is recorded for every later
    // re-probe and applied now, off this thread: clearing it asks the login
    // shell again, which may take seconds. Tiles started afterwards get it,
    // and the window's own copy (the Terminals page's Claude/Codex buttons,
    // Diagnostics) is sent the fresh snapshot instead of waiting for the next
    // Look again.
    if shell_env::configure_path_override(saved.shell.path_override.as_deref()) {
        let app = app.clone();
        std::thread::spawn(move || {
            use tauri::Manager;
            let capabilities =
                app.try_state::<crate::review_capabilities::ReviewerCapabilityRegistry>();
            // 1.176.1: the person's own Program folders: not told back (`cli_seen`).
            let own = crate::cli_seen::OwnChange::new(&[crate::cli_fresh::Cli::Claude, crate::cli_fresh::Cli::Codex]);
            re_probe_and_forget(capabilities.as_ref().map(|state| state.inner()));
            drop(own);
            let _ = app.emit(SHELL_ENV_CHANGED_EVENT, snapshot_env());
        });
    }
    let _ = app.emit("settings://changed", saved.clone());
}

