/// v1.95.0 (P3-1 self-check SC-1): validate a bounded observation draft,
/// stamp it with backend-owned scope/time/version/bundle provenance, and
/// atomically write it to Ply's existing log directory. The expensive native
/// bundle walk runs off the Tauri command thread.
#[tauri::command]
pub async fn installed_self_check_write_report(
    app: AppHandle,
    kanban: State<'_, KanbanStore>,
    draft: crate::installed_self_check::InstalledSelfCheckDraftV1,
) -> Result<crate::installed_self_check::InstalledSelfCheckReportReceipt, String> {
    let card = kanban.get_card(&draft.workspace_id, &draft.card_id)?;
    if card.workspace_id != draft.workspace_id {
        return Err("self-check card/workspace scope mismatch".into());
    }
    let log_dir = app
        .path()
        .app_log_dir()
        .map_err(|error| format!("resolve self-check log directory: {error}"))?;
    let created_at = chrono::Utc::now().timestamp_millis();
    let report_id = uuid::Uuid::new_v4().to_string();
    tauri::async_runtime::spawn_blocking(move || {
        let fingerprint = crate::bundle_fingerprint::current_app_bundle()
            .and_then(|bundle| crate::bundle_fingerprint::fingerprint_bundle(&bundle));
        crate::installed_self_check::write_report(
            &log_dir,
            fingerprint,
            draft,
            created_at,
            report_id,
        )
    })
    .await
    .map_err(|error| format!("join installed self-check report: {error}"))?
}

