#[derive(Serialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum AgentRunRequestResult {
    Started { run: AgentRun },
    Busy {
        conflict: crate::coordination::WriterConflict,
    },
}

/// Phase 3 immediate-run surface. Unlike background triggers, a human click
/// never silently joins the writer queue: the caller receives a typed busy
/// result and may explicitly invoke `agent_run_queue`.
#[tauri::command]
pub fn agent_run_request(
    app: tauri::AppHandle,
    registry: State<'_, AgentRegistry>,
    pty_registry: State<'_, PtyRegistry>,
    drain_coord: State<'_, DrainCoordinator>,
    verify: State<'_, VerifyRegistry>,
    kanban: State<'_, KanbanStore>,
    card_execution: State<'_, crate::card_execution::CardExecutionGate>,
    agent_id: String,
    scope: AgentScope,
    workspace_id: String,
    project_cwd: String,
    prompt_override: Option<String>,
    card_id: Option<String>,
) -> Result<AgentRunRequestResult, String> {
    drain::guard_dispatch(&drain_coord, "agent run")?;
    let start = || {
        registry.start_run(
            app.clone(),
            &pty_registry,
            &agent_id,
            scope,
            &workspace_id,
            PathBuf::from(project_cwd),
            prompt_override,
            AgentTrigger::Manual,
            None,
            None,
            Vec::new(),
            None,
        )
    };
    let result = if let Some(card_id) = card_id.as_deref() {
        card_execution.run_attempt(
            &verify,
            &kanban,
            &workspace_id,
            card_id,
            crate::card_execution::AuthorizationKind::CardAgent,
            || {
                let run = start()?;
                if run.status == crate::agents::AgentStatus::Error {
                    Err(run
                        .error
                        .clone()
                        .unwrap_or_else(|| "agent failed to start".to_string()))
                } else {
                    Ok(run)
                }
            },
            |run| {
                kanban
                    .set_run_state(
                        &workspace_id,
                        card_id,
                        RunStatePatch {
                            linked_run_id: Some(Some(run.id.clone())),
                            linked_swarm_id: Some(None),
                            last_run_status: Some(Some(crate::kanban::LastRunStatus::Running)),
                        },
                    )
                    .map(|_| ())
            },
            |run| {
                if let Err(error) = registry.kill_run(&run.id, &pty_registry) {
                    log::error!(
                        "card Agent {} could not be stopped after link failure: {error}",
                        run.id
                    );
                }
            },
        )
    } else {
        start()
    };
    match result {
        Ok(run) => Ok(AgentRunRequestResult::Started { run }),
        Err(error) => match crate::coordination::decode_writer_busy(&error) {
            Some(conflict) => Ok(AgentRunRequestResult::Busy { conflict }),
            None => Err(error),
        },
    }
}

#[tauri::command]
pub fn agent_run_queue(
    app: tauri::AppHandle,
    drain_coord: State<'_, DrainCoordinator>,
    verify: State<'_, VerifyRegistry>,
    kanban: State<'_, KanbanStore>,
    card_execution: State<'_, crate::card_execution::CardExecutionGate>,
    agent_id: String,
    scope: AgentScope,
    workspace_id: String,
    project_cwd: String,
    prompt_override: Option<String>,
    card_id: Option<String>,
) -> Result<crate::writer_queue::WriterQueueReceipt, String> {
    drain::guard_dispatch(&drain_coord, "agent run")?;
    let enqueue = || {
        crate::agents::enqueue_standalone_run(
            &app,
            agent_id.clone(),
            scope,
            workspace_id.clone(),
            PathBuf::from(project_cwd),
            prompt_override,
            AgentTrigger::Manual,
            format!("manual:{workspace_id}:{agent_id}:{}", uuid::Uuid::new_v4()),
            card_id.clone(),
        )
    };
    let receipt = if let Some(card_id) = card_id.as_deref() {
        card_execution.run_attempt(
            &verify,
            &kanban,
            &workspace_id,
            card_id,
            crate::card_execution::AuthorizationKind::WriterQueue,
            enqueue,
            |_| Ok(()),
            |_| {},
        )?
    } else {
        enqueue()?
    };
    // A queue pump may have raced the initial attempt marker and returned
    // Busy. Wake it once more after run_attempt has dropped that marker.
    if let Some(queue) = app.try_state::<crate::writer_queue::WriterQueue>() {
        queue.request_pump(app.clone());
    }
    Ok(receipt)
}

