// ── Localhost probe (for browser-pane dev-server autodetect) ────

/// Off the main thread, as `probe_ports` is: up to 13 connects (120 ms
/// apiece at most) and the answers' check within [`PROBE_HEAD_BUDGET`].
#[tauri::command]
pub async fn probe_localhost_ports() -> Vec<u16> {
    tauri::async_runtime::spawn_blocking(|| {
        probe_localhost_ports_impl(&[3000, 3001, 4173, 4321, 5173, 5174, 5000, 8000, 8080, 8081, 4200, 1313, 9000])
    })
    .await
    .unwrap_or_default()
}

/// Pure logic split out so it's unit-testable without going through Tauri.
/// A port that answers is kept unless its HTTP answer names macOS's AirPlay
/// receiver (`Server: AirTunes/…`, on 5000 and 7000 since Monterey): it is
/// no dev server, and the preview would stay blank on it. The open ports'
/// answers are read in parallel, all within one [`PROBE_HEAD_BUDGET`].
pub fn probe_localhost_ports_impl(candidates: &[u16]) -> Vec<u16> {
    let open: Vec<(u16, std::net::TcpStream)> = candidates
        .iter()
        .copied()
        .filter_map(|p| {
            let addr = std::net::SocketAddr::from(([127, 0, 0, 1], p));
            std::net::TcpStream::connect_timeout(&addr, std::time::Duration::from_millis(120))
                .ok()
                .map(|stream| (p, stream))
        })
        .collect();
    let deadline = std::time::Instant::now() + PROBE_HEAD_BUDGET;
    std::thread::scope(|scope| {
        let checks: Vec<_> = open
            .into_iter()
            .map(|(p, stream)| scope.spawn(move || (p, !answers_as_airplay(stream, deadline))))
            .collect();
        checks
            .into_iter()
            .filter_map(|h| h.join().ok())
            .filter(|(_, keep)| *keep)
            .map(|(p, _)| p)
            .collect()
    })
}

/// The whole probe's wait for the open ports' answers to `HEAD /`, all
/// together. A dev server answers in milliseconds; a silent one is kept
/// (it may not speak HTTP).
pub const PROBE_HEAD_BUDGET: std::time::Duration = std::time::Duration::from_millis(500);
/// The most of an answer the probe reads: the status line and headers.
const PROBE_HEAD_MAX_BYTES: usize = 2048;

/// Send `HEAD /` on `stream` and read the start of the answer until
/// `deadline` (checked before every read) or [`PROBE_HEAD_MAX_BYTES`]:
/// whether it is the AirPlay receiver's. Any failure reads as "not AirPlay".
fn answers_as_airplay(mut stream: std::net::TcpStream, deadline: std::time::Instant) -> bool {
    use std::io::{Read, Write};
    let left = |now: std::time::Instant| deadline.checked_duration_since(now).filter(|d| !d.is_zero());
    let Some(first) = left(std::time::Instant::now()) else { return false };
    let _ = stream.set_write_timeout(Some(first));
    if stream
        .write_all(b"HEAD / HTTP/1.0\r\nHost: localhost\r\nConnection: close\r\n\r\n")
        .is_err()
    {
        return false;
    }
    let mut buf = Vec::with_capacity(512);
    let mut chunk = [0u8; 512];
    while buf.len() < PROBE_HEAD_MAX_BYTES {
        let Some(wait) = left(std::time::Instant::now()) else { break };
        if stream.set_read_timeout(Some(wait)).is_err() {
            break;
        }
        match stream.read(&mut chunk) {
            Ok(0) | Err(_) => break,
            Ok(n) => {
                buf.extend_from_slice(&chunk[..n]);
                if buf.windows(4).any(|w| w == b"\r\n\r\n") {
                    break;
                }
            }
        }
    }
    is_airplay_answer(&String::from_utf8_lossy(&buf))
}

/// Whether an HTTP answer's `Server` header names AirPlay or AirTunes.
pub fn is_airplay_answer(answer: &str) -> bool {
    answer.lines().skip(1).take_while(|l| !l.trim().is_empty()).any(|line| {
        let Some((name, value)) = line.split_once(':') else { return false };
        let value = value.to_ascii_lowercase();
        name.trim().eq_ignore_ascii_case("server") && (value.contains("airtunes") || value.contains("airplay"))
    })
}

/// Try it TI-3 (docs/try-it/TRY_IT_SPEC.md §4.2): at most this many ports per
/// `probe_ports` call — a card's block is ten.
pub const PROBE_PORTS_MAX: usize = 16;

/// The ports `probe_ports` will try from what the page asked for: no system
/// port (below 1024), no repeat, at most [`PROBE_PORTS_MAX`], in the order
/// asked.
pub fn probe_ports_candidates(ports: &[u16]) -> Vec<u16> {
    let mut out: Vec<u16> = Vec::with_capacity(PROBE_PORTS_MAX);
    for &p in ports {
        if p < 1024 || out.contains(&p) {
            continue;
        }
        if out.len() == PROBE_PORTS_MAX {
            break;
        }
        out.push(p);
    }
    out
}

/// Try it TI-3: a port answers on IPv4 loopback or, failing that, on IPv6
/// `[::1]` — a dev server bound to `localhost` may listen on only one of
/// them (Node 17+ resolves `localhost` to `::1` first on many Macs).
pub fn probe_ports_impl(candidates: &[u16]) -> Vec<u16> {
    let timeout = std::time::Duration::from_millis(120);
    candidates
        .iter()
        .copied()
        .filter(|&p| {
            let v4 = std::net::SocketAddr::from(([127, 0, 0, 1], p));
            let v6 = std::net::SocketAddr::from((std::net::Ipv6Addr::LOCALHOST, p));
            std::net::TcpStream::connect_timeout(&v4, timeout).is_ok()
                || std::net::TcpStream::connect_timeout(&v6, timeout).is_ok()
        })
        .collect()
}

/// Try it TI-3: which of the given localhost ports answer — a card copy's
/// block (`port_base…port_base+9`), never the fixed list above, so a server
/// of the main project is not taken for the card's. Off the main thread: up
/// to 16 ports, each tried on 127.0.0.1 then [::1] (120 ms apiece).
#[tauri::command]
pub async fn probe_ports(ports: Vec<u16>) -> Vec<u16> {
    let candidates = probe_ports_candidates(&ports);
    tauri::async_runtime::spawn_blocking(move || probe_ports_impl(&candidates))
        .await
        .unwrap_or_default()
}

