/// v1.57.0 (Cycle 3 — increment 3a/3b): resolve a workspace's GitHub-Issues
/// sync target. `Some(owner/repo)` only when `kanban_sync_mode` is
/// `GitHubIssues` AND `github_owner_repo` is set — the precondition for every
/// issue-sync hook. `None` means "local-only board, skip GitHub entirely".
pub(crate) fn workspace_github_target(
    workspaces: &WorkspaceStore,
    workspace_id: &str,
) -> Option<String> {
    workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .filter(|w| w.kanban_sync_mode == KanbanSyncMode::GitHubIssues)
        .and_then(|w| w.github_owner_repo)
}

/// The workspace's name as the sidebar shows it, for a message; "This
/// workspace" when it is gone or unnamed.
pub(crate) fn workspace_name(workspaces: &WorkspaceStore, workspace_id: &str) -> String {
    workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .map(|w| w.name)
        .filter(|name| !name.trim().is_empty())
        .unwrap_or_else(|| "This workspace".to_string())
}

/// v1.57.0 (Cycle 3 — increment 3a): reconcile a GitHub-Issues-backed board
/// against the live issues (push-then-pull). The FE drives *when* this runs
/// (workspace-open, Sync button); the backend owns the diff + apply. Errors if
/// the workspace isn't in GitHubIssues mode. Emits `kanban://changed` once.
#[tauri::command]
pub async fn kanban_github_reconcile(
    app: tauri::AppHandle,
    workspace_id: String,
) -> Result<crate::github_sync::ReconcileSummary, String> {
    // `gh` calls plus a bounded `git fetch`: off the main thread, so an
    // unreachable network can't freeze the window.
    tauri::async_runtime::spawn_blocking(move || {
        // GH #79: every Sync reads the shared definition first, so the board
        // and branch below are the repo's.
        crate::workspace_definition::refresh_before(
            &app,
            &workspace_id,
            crate::workspace_definition::RefreshMoment::Sync,
        );
        let store = app.state::<KanbanStore>();
        let workspaces = app.state::<WorkspaceStore>();
        let project_config = app.state::<ProjectConfigStore>();
        let license = app.state::<crate::license::LicenseStore>();
        // v1.85.0: lapse degrade — sync stops (board renders read-only with a
        // flip-to-local escape); local data is never touched.
        team_gate(&license)?;
        let repo = workspace_github_target(&workspaces, &workspace_id).ok_or_else(|| {
            format!("workspace '{workspace_id}' is not in GitHub-Issues sync mode")
        })?;
        let cwd = resolve_ws_cwd(&workspaces, &workspace_id).ok();
        // OB-7b: the issue calls, the fetch and the prune's reads run as the
        // workspace's GitHub account.
        let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
        let labels = crate::github_sync::AreaLabels::for_workspace(&project_config, &workspace_id);
        let mut summary =
            crate::github_sync::reconcile(&store, &workspace_id, &repo, cwd.as_deref(), &labels)?;
        // Cards start from the fetched default branch; a Ship-as-PR card's
        // merge lands on origin, not in this checkout. Every reconcile (board
        // open and Sync) therefore brings the local target branch along when
        // it is clean and strictly behind — never when dirty or diverged
        // (the FE toasts).
        if let Some(cwd) = cwd {
            let branch = resolve_base_branch(&project_config, &workspace_id);
            let outcome = crate::worktrees::mark_repeated_refusal(
                &cwd,
                &branch,
                crate::worktrees::fast_forward_local(&cwd, &branch),
            );
            // G5 (Challenger 2): up to date now → no card asks to be.
            if outcome.fast_forwarded() {
                crate::after_merge::clear_refusals_except(&store, &workspace_id, None);
            }
            // A card shipped as a PR and merged on another Mac keeps its
            // worktree here; the local Ship path is the only other prune.
            let report = prune_merged_card_worktrees(&app, &store, &workspace_id, &cwd, &branch);
            summary.pruned_worktrees = report.pruned.len();
            summary.kept_merged_worktrees = report.kept;
            // F1 (1.172.1): what the folder itself is — its own branch, its
            // date, how far GitHub's target is beyond it, its changes — read
            // after the fetch above. Not when GitHub couldn't be read: the
            // counts would be against an old copy.
            let folder = (!matches!(
                outcome,
                crate::worktrees::LocalBranchSync::Offline { .. } | crate::worktrees::LocalBranchSync::NoRemote
            ))
            .then(|| crate::project_folder::folder_facts(&cwd, &branch));
            let local = crate::worktrees::LocalBranchReport { branch, outcome, folder };
            crate::project_folder::log_outcome(&workspace_id, &local);
            summary.local_branch = Some(local);
            // After the prune, so the worktrees it just trashed are swept
            // too (a no-op for them: the prune stripped them already).
            let gc = crate::build_cache::gc_workspace(
                &app,
                &workspace_id,
                &cwd,
                crate::build_cache::GcTrigger::Sync,
            );
            summary.trash_freed_bytes = gc.freed_bytes;
        }
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        Ok(summary)
    })
    .await
    .map_err(|e| format!("reconcile worker failed: {e}"))?
}

/// QoL 14.1 (C19): the Board's periodic refresh of a GitHub-Issues-backed
/// board: the issue lists, applied locally. No push, definition read, fetch,
/// prune or trash sweep (Sync's). 1.175.0: not purely read-only on a board
/// opened from its last saved copy — its first read is followed by the two
/// one-shot writes kept while it was held (`github_sync::send_held_writes`).
#[tauri::command]
pub async fn kanban_github_refresh(
    app: tauri::AppHandle,
    workspace_id: String,
) -> Result<crate::github_sync::ReconcileSummary, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let store = app.state::<KanbanStore>();
        let workspaces = app.state::<WorkspaceStore>();
        let license = app.state::<crate::license::LicenseStore>();
        team_gate(&license)?;
        let repo = workspace_github_target(&workspaces, &workspace_id).ok_or_else(|| {
            format!("workspace '{workspace_id}' is not in GitHub-Issues sync mode")
        })?;
        let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
        let labels = crate::github_sync::AreaLabels::for_workspace(&app.state::<ProjectConfigStore>(), &workspace_id);
        let summary = crate::github_sync::refresh_then_send_held(&store, &workspace_id, &repo, &labels)?;
        if summary.created + summary.patched > 0 {
            crate::kanban::emit_kanban_changed(&app, &workspace_id);
        }
        Ok(summary)
    })
    .await
    .map_err(|e| format!("refresh worker failed: {e}"))?
}

/// The reconcile's prune pass over this workspace's card worktrees (see
/// `worktrees::prune_merged_card_worktrees`). Serialized with card starts
/// so a start can't pick up a worktree mid-prune; a card with an open
/// Builder session or a running run is never a prune target.
fn prune_merged_card_worktrees(
    app: &tauri::AppHandle,
    store: &KanbanStore,
    workspace_id: &str,
    cwd: &std::path::Path,
    target_branch: &str,
) -> crate::worktrees::MergedPruneReport {
    let _start = CARD_START_LOCK.lock().unwrap_or_else(|p| p.into_inner());
    // A candidate whose directory is already gone has nothing to prune: its
    // handle is cleared rather than skipped and left dangling.
    crate::github_sync::heal_dangling_worktree_handles(store, workspace_id, cwd);
    let cards = match store.load(workspace_id) {
        Ok(cards) => cards,
        Err(e) => {
            log::warn!("reconcile: merged-worktree prune skipped: {e}");
            return Default::default();
        }
    };
    let builders = app.state::<crate::builder::BuilderRegistry>();
    let candidates = merged_prune_candidates(&cards, cwd, &|id| builders.get_pty(id).is_some());
    let cache_paths = app.state::<ProjectConfigStore>().cache_paths(workspace_id);
    let report = crate::worktrees::prune_merged_card_worktrees(
        cwd,
        target_branch,
        &candidates,
        &cache_paths,
    );
    // N18 (owner, Q2): the branch is recorded at the tip proven merged and
    // deleted by the cleanup sweep once the trash entry expires — never here.
    record_merged_branches(store, workspace_id, cwd, &cards, &report);
    for card_id in &report.pruned {
        crate::verify_logs::card_worktree_removed(workspace_id, card_id);
        if let Err(e) = store.clear_worktree_handle(workspace_id, card_id) {
            log::warn!("reconcile: pruned {card_id}'s worktree but couldn't clear the card: {e}");
        }
    }
    for kept in &report.kept {
        log::info!("reconcile: kept merged worktree of {}: {}", kept.card_id, kept.reason);
    }
    report
}

/// The cards Sync's merged prune may consider: a worktree and branch at
/// Plyloft's conventional location, with why a busy one (`live`: its
/// Builder session is open) must stay. Windows walk of #386: never a pull
/// request card — its worktree goes only by its pull request's merged or
/// closed path, as its branch's tip can be on the target while the pull
/// request is open.
pub(crate) fn merged_prune_candidates(
    cards: &[KanbanCard],
    cwd: &std::path::Path,
    live: &dyn Fn(&str) -> bool,
) -> Vec<crate::worktrees::PruneCandidate> {
    cards
        .iter()
        .filter_map(|card| {
            if crate::pr_review::cleaned_only_by_its_pull_request(card) {
                return None;
            }
            let wt = std::path::Path::new(card.worktree_path.as_deref()?);
            let branch = card.branch_name.clone()?;
            // Only the conventional location: prune_worktree_at acts on it.
            let expected = crate::worktrees::card_worktree_path(cwd, &card.id, card.worktree_path.as_deref());
            if crate::platform::canonicalize(wt).ok()? != crate::platform::canonicalize(&expected).ok()? {
                return None;
            }
            let busy = if live(&card.id) {
                Some("its Builder session is open".to_string())
            } else if card.last_run_status == Some(crate::kanban::LastRunStatus::Running) {
                Some("a run is in progress".to_string())
            } else {
                None
            };
            Some(crate::worktrees::PruneCandidate {
                card_id: card.id.clone(),
                path: expected,
                branch,
                recorded_base: card.worktree_base.as_ref().map(|b| b.commit.clone()),
                busy,
            })
        })
        .collect()
}

/// N18: record each branch Sync's merged prune left behind
/// (`CleanupReason::Merged`, at the proven tip, with its trash entry).
fn record_merged_branches(
    store: &KanbanStore,
    workspace_id: &str,
    cwd: &std::path::Path,
    cards: &[KanbanCard],
    report: &crate::worktrees::MergedPruneReport,
) {
    let now = crate::kanban::now_ms();
    for pruned in &report.trash_entries {
        let Some(card) = cards.iter().find(|c| c.id == pruned.card_id) else {
            continue;
        };
        let record = crate::branch_cleanup::record(
            card,
            cwd,
            crate::branch_cleanup::CleanupReason::Merged,
            Some(&pruned.tip),
            Some(&pruned.trash_entry),
            now,
        );
        store.record_branch_cleanup(workspace_id, &card.id, record);
    }
}

/// v1.57.0 (Cycle 3 — increment 3c): one-click Claim. Assigns the authenticated
/// user to the card's backing issue (`gh issue edit --add-assignee @me`) so the
/// subsequent move-to-In-Progress passes the claim gate. Errors if the
/// workspace isn't GitHub-backed or the card has no issue yet.
///
/// GH #66: reads the issue's live assignees first and records them on the
/// card. When someone else already holds it, nothing is assigned unless
/// `confirmed` — co-ownership stays possible, it just is not silent.
#[tauri::command]
pub async fn kanban_card_claim(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    confirmed: Option<bool>,
) -> Result<ClaimOutcome, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let outcome = claim_card(
            &app.state::<KanbanStore>(),
            &app.state::<WorkspaceStore>(),
            &app.state::<crate::license::LicenseStore>(),
            &workspace_id,
            &card_id,
            ClaimMode::Claim {
                confirmed: confirmed.unwrap_or(false),
            },
        )?;
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        Ok(outcome)
    })
    .await
    .map_err(|e| format!("claim worker failed: {e}"))?
}

/// GH #66: re-read who holds the card's issue and record it on the card,
/// assigning nobody (`claimed` = already mine). The check before a start that
/// creates a worktree: the synced `gh_assignees` can be older than a claim
/// made on another Mac since the last Sync.
#[tauri::command]
pub async fn kanban_card_claim_state(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<ClaimOutcome, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let store = app.state::<KanbanStore>();
        let before = store.get_card(&workspace_id, &card_id)?;
        let outcome = claim_card(
            &store,
            &app.state::<WorkspaceStore>(),
            &app.state::<crate::license::LicenseStore>(),
            &workspace_id,
            &card_id,
            ClaimMode::ReadOnly,
        )?;
        // N14 (Challenger P3-1): the author is recorded from the same read.
        if outcome.card.gh_assignees != before.gh_assignees || outcome.card.gh_author != before.gh_author {
            crate::kanban::emit_kanban_changed(&app, &workspace_id);
        }
        Ok(outcome)
    })
    .await
    .map_err(|e| format!("claim state worker failed: {e}"))?
}

/// 1.173.0 (C2): this computer's claim marker on the card's issue, read
/// live. `take_over` (*Take it over here*) writes it over another
/// computer's; without it another computer's stays (*Start here too*).
/// Returns the card with the marker the issue carries afterwards.
#[tauri::command]
pub async fn kanban_card_device_claim(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    take_over: Option<bool>,
) -> Result<KanbanCard, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let store = app.state::<KanbanStore>();
        let how = if take_over.unwrap_or(false) {
            crate::device_claim::ClaimHere::TakeOver
        } else {
            crate::device_claim::ClaimHere::IfFree
        };
        let card = device_claim_card(
            &store,
            &app.state::<WorkspaceStore>(),
            &app.state::<crate::license::LicenseStore>(),
            &workspace_id,
            &card_id,
            how,
        )?;
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        Ok(card)
    })
    .await
    .map_err(|e| format!("device claim worker failed: {e}"))?
}

/// 1.173.0 (C2), 1.175.0 (D2, TM-6): *Close the Builder session* and Stop
/// during the start — this computer's claim marker comes off the issue only
/// when the card's copy isn't on this computer; with the copy here it stays.
/// Best-effort and silent on a local board.
#[tauri::command]
pub async fn kanban_card_device_release(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        let workspaces = app.state::<WorkspaceStore>();
        let Some(repo) = workspace_github_target(&workspaces, &workspace_id) else {
            return Ok(());
        };
        if team_gate(&app.state::<crate::license::LicenseStore>()).is_err() {
            return Ok(());
        }
        let store = app.state::<KanbanStore>();
        let card = store.get_card(&workspace_id, &card_id)?;
        let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
        crate::device_claim::release_unless_copy_here(&store, &repo, &workspace_id, &card);
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        Ok(())
    })
    .await
    .map_err(|e| format!("device release worker failed: {e}"))?
}

/// GH #66: this Mac's GitHub login, for the card's claim chip ("Yours" vs
/// "Claimed by X"). `None` when `gh` can't say. Display only: the claim gate
/// and Claim re-read it themselves. `fresh` (Sync) bypasses the 60-second
/// login cache, so a `gh auth switch` shows at once.
#[tauri::command]
pub async fn github_current_login(fresh: Option<bool>) -> Result<Option<String>, String> {
    tauri::async_runtime::spawn_blocking(move || display_login(fresh.unwrap_or(false)))
        .await
        .map_err(|e| format!("login worker failed: {e}"))
}

fn display_login(fresh: bool) -> Option<String> {
    if fresh {
        crate::github::invalidate_login_cache();
    }
    crate::github::current_login().ok()
}

/// "Use as brief": move the issue text Ply keeps outside the marker blocks
/// (`gh_raw_remainder`) into the card's notes, below any notes already there,
/// then mirror the body so the issue carries it inside the notes block (D3
/// round 2: as the member's edit of the brief, judged by the card as it was).
/// Sync adopts an unmarked body itself when notes are empty; this is the manual path.
#[tauri::command]
pub fn kanban_card_use_issue_remainder<R: tauri::Runtime>(
    app: tauri::AppHandle<R>,
    store: State<'_, KanbanStore>,
    settings: State<'_, SettingsStore>,
    workspaces: State<'_, WorkspaceStore>,
    license: State<'_, crate::license::LicenseStore>,
    workspace_id: String,
    card_id: String,
) -> Result<KanbanCard, String> {
    team_gate_github_card_write(&workspaces, &license, &workspace_id, true)?;
    let email = settings.snapshot().identity.user_email;
    let (before, updated) = (store.get_card(&workspace_id, &card_id)?, store.adopt_gh_remainder(&workspace_id, &card_id, email)?);
    if let Some(repo) = workspace_github_target(&workspaces, &workspace_id) {
        // OB-7b: the workspace's GitHub account for its issue calls.
        let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
        gh_sync_card_edit(&store, &repo, &workspace_id, Some(&before), &updated, true, false);
    }
    crate::kanban::emit_kanban_changed(&app, &workspace_id);
    // Re-read so the FE sees any `sync_pending` flag set by the hook.
    store.get_card(&workspace_id, &card_id)
}

// v1.84.0: the v1.62.0 `github_review_requested` command was removed —
// its only consumer (WorkspaceDetailPane's review widget) died with the
// v1.82.0 sidebar revamp. Review-requested PRs surface through the Inbox
// feed, which calls `github::pr_list_review_requested` directly.

// ── Overlap warning (v1.86.0 — team-tier roadmap cycle 3) ───────────

/// The pre-merge overlap check for one card (`overlap.rs`). ADVISORY —
/// never blocks anything. Local half (free): vs other cards' live
/// worktrees in this workspace. Teammate half (paid, soft-degrades):
/// vs open PRs' changed files in the workspace's repo.
///
/// Onboarding §10 row 8: `teammates: Some(false)` — the frontend in solo
/// mode — leaves the teammate half out, so no pull request is fetched. Absent
/// (an older caller) keeps both halves.
///
/// Off the main thread (1.174.0 B4, CH-1): git per card and `gh pr list`
/// would otherwise freeze the window for as long as GitHub takes. Tests run
/// it on their own thread, the one that holds the thread-local `gh` seam
/// (github.rs), as `inbox_feed`; `the_scan_sees_the_commands_it_guards`
/// (command_threads_tests.rs) keeps the shipping attribute async.
#[cfg_attr(not(test), tauri::command(async))]
#[cfg_attr(test, tauri::command)]
pub fn card_overlap_check(
    store: State<'_, KanbanStore>,
    workspaces: State<'_, WorkspaceStore>,
    project_config: State<'_, ProjectConfigStore>,
    license: State<'_, crate::license::LicenseStore>,
    workspace_id: String,
    card_id: String,
    teammates: Option<bool>,
) -> Result<Vec<crate::overlap::OverlapWarning>, String> {
    use std::collections::BTreeSet;
    let cards = store.load(&workspace_id)?;
    let me = cards
        .iter()
        .find(|c| c.id == card_id)
        .ok_or_else(|| format!("card not found: {card_id}"))?;
    let Some(my_wt) = me.worktree_path.as_deref() else {
        return Ok(Vec::new()); // no worktree yet → nothing to compare
    };
    let my_wt = std::path::Path::new(my_wt);
    if !my_wt.exists() {
        return Ok(Vec::new());
    }
    // 1.173.0 (B3): each card measured from its own area's branch; the
    // stores are read once and each area resolved once (1.174.0 B4).
    let mut reading = crate::card_area::ReadingBranches::new(&project_config, &workspace_id);
    let target = reading.branch(me);
    let my_files = crate::overlap::changed_files(
        my_wt,
        me.worktree_base.as_ref(),
        &target,
    )?;
    if my_files.is_empty() {
        return Ok(Vec::new());
    }

    let mut out = Vec::new();
    for other in cards.iter().filter(|c| c.id != card_id && !c.archived) {
        let Some(wt) = other.worktree_path.as_deref() else {
            continue;
        };
        let p = std::path::Path::new(wt);
        if !p.exists() {
            continue;
        }
        // Best-effort per sibling — one broken worktree shouldn't kill
        // the whole (advisory) report. A sibling already merged into
        // origin contributes only its uncommitted files.
        let Ok(files) = crate::overlap::pending_files(
            p,
            other.branch_name.as_deref(),
            other.worktree_base.as_ref().map(|b| b.commit.as_str()),
            &reading.branch(other),
        ) else {
            continue;
        };
        let common = crate::overlap::intersect(&my_files, &files);
        if !common.is_empty() {
            out.push(crate::overlap::OverlapWarning {
                kind: crate::overlap::OverlapKind::LocalCard,
                other_id: other.id.clone(),
                other_title: other.title.clone(),
                files: common,
            });
        }
    }

    // Teammate half — paid, quiet on any gh failure (advisory), and not
    // fetched in solo mode.
    if teammates.unwrap_or(true) && license.team_allowed() {
        if let Some(repo) = workspace_github_target(&workspaces, &workspace_id) {
            // OB-7b: the workspace's GitHub account for the PR list.
            let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
            if let Ok(prs) = crate::github::pr_list_open_with_files(&repo) {
                for pr in prs {
                    // Skip the card's own PR (post-ship, it IS this diff) —
                    // and the pull request a pull request card reviews, or
                    // one a local card listed above already reviews.
                    if Some(pr.head_ref_name.as_str()) == me.branch_name.as_deref()
                        || crate::pr_review::overlap_skips_pr(me, &cards, &out, pr.number)
                    {
                        continue;
                    }
                    let pr_files: BTreeSet<String> =
                        pr.files.into_iter().map(|f| f.path).collect();
                    let common = crate::overlap::intersect(&my_files, &pr_files);
                    if !common.is_empty() {
                        out.push(crate::overlap::OverlapWarning {
                            kind: crate::overlap::OverlapKind::TeammatePr,
                            other_id: pr.number.to_string(),
                            other_title: format!("PR #{} · {}", pr.number, pr.title),
                            files: common,
                        });
                    }
                }
            }
        }
    }
    Ok(out)
}

// ── Team license (v1.85.0 — team-tier roadmap cycle 2) ──────────────

/// The backend gate on every paid team behavior (GH-Issues backing +
/// claims, review/CODEOWNERS awareness, shared-library writes). Frontend
/// lock chips are UX; THIS is the gate. Checked only at action points —
/// never against running work (a plan lapse must not abort an in-flight
/// swarm). Launch G3: the Team plan, for this Mac's team, as the team's
/// account ([`crate::license::team_access`]); each refusal says which.
pub(crate) fn team_gate(license: &crate::license::LicenseStore) -> Result<(), String> {
    match license.team_access().refusal() {
        None => Ok(()),
        Some(why) => Err(why),
    }
}

/// Launch G3: [`team_gate`] for Create team, where this Mac is on no team
/// yet ([`crate::license::team_create_access`]).
fn team_create_gate(
    license: &crate::license::LicenseStore,
    repo: Option<&str>,
    creator: Option<&str>,
) -> Result<(), String> {
    match license.team_create_access(repo, creator).refusal() {
        None => Ok(()),
        Some(why) => Err(why),
    }
}

/// Onboarding §11.1: the team this Mac is in — `settings.team.teamRepo`.
/// Launch G3: a stored key's `teamRepo` no longer names one. Every reader of
/// "the team repo" goes through this.
pub(crate) fn team_repo_of(settings: &SettingsStore) -> Option<String> {
    crate::team::current_team_repo(&settings.snapshot().team)
}

/// [`team_repo_of`] from the app's managed stores. An app without a settings
/// store (a narrow test app) is on no team.
pub(crate) fn current_team_repo<R: tauri::Runtime>(app: &tauri::AppHandle<R>) -> Option<String> {
    let settings = app.try_state::<SettingsStore>()?;
    team_repo_of(&settings)
}

/// What a team action says on a Mac that is on no team.
fn no_team_message() -> String {
    format!("{THIS_MACHINE_CAP} is not on a team yet. Create or join one in Settings › Team › Members and library.")
}

/// Admit a card mutation before any local write when its workspace is backed
/// by GitHub Issues. The mode is authoritative even if the persisted repo is
/// missing: a corrupt GitHub-mode record must not silently become Local/free.
/// Local-only patch fields pass `touches_github_owned_field = false` and retain
/// their existing behavior in every license state.
pub(crate) fn team_gate_github_card_write(
    workspaces: &WorkspaceStore,
    license: &crate::license::LicenseStore,
    workspace_id: &str,
    touches_github_owned_field: bool,
) -> Result<(), String> {
    let mode = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|workspace| workspace.id == workspace_id)
        .map(|workspace| workspace.kanban_sync_mode)
        .ok_or_else(|| format!("workspace '{workspace_id}' not found"))?;
    if github_card_write_blocked(
        mode,
        license.team_allowed(),
        touches_github_owned_field,
    ) {
        team_gate(license)
    } else {
        Ok(())
    }
}

pub(crate) fn github_card_write_blocked(
    mode: KanbanSyncMode,
    team_allowed: bool,
    touches_github_owned_field: bool,
) -> bool {
    mode == KanbanSyncMode::GitHubIssues
        && !team_allowed
        && touches_github_owned_field
}

// ── Plyloft account (launch A1, account.rs) ─────────────────────────

