/// Onboarding §11.1: **leave the team** — this Mac stops following it. Only
/// the record of which team this Mac is in goes: `settings.team.teamRepo`
/// and the team's account with it. The team repo's clone, the team
/// workspaces and everything in them stay on this Mac; nothing on GitHub
/// changes. Launch G3: a stored key names no team, so it is left alone.
#[tauri::command]
pub async fn team_leave(app: AppHandle) -> Result<crate::license::LicenseInfo, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let license = app.state::<crate::license::LicenseStore>();
        let settings = app.state::<SettingsStore>();
        let saved = leave_team(&settings)?;
        app.state::<crate::team::TeamStore>().forget_membership();
        let _ = app.emit("settings://changed", saved);
        Ok(license.info())
    })
    .await
    .map_err(|error| format!("join team leave: {error}"))?
}

/// [`team_leave`] over the settings. Deletes nothing on disk but the
/// records; the Mac really leaves, so the team's account goes too (launch G3:
/// no key keeps it in a team any more).
pub(crate) fn leave_team(settings: &SettingsStore) -> Result<Settings, String> {
    if team_repo_of(settings).is_none() {
        return Err(no_team_message());
    }
    settings.clear_team()
}

// ── Team (v1.114.0 — team sharing rung 1) ───────────────────────────

/// Everything these three commands do — `git pull`, `gh api`, `gh repo
/// clone` — blocks on a subprocess and a network round trip, so they run
/// on the blocking pool exactly as the ship and reviewer commands do.
/// Cloning a large team workspace must never freeze the window.
pub(crate) fn team_status_blocking(app: &AppHandle, refresh: bool) -> crate::team::TeamStatus {
    team_status_blocking_after_sync(app, refresh, None)
}

/// [`team_status_blocking`], given the clone-or-pull the caller already ran
/// (Skills hub H2's pull, `crate::skills_hub`).
pub(crate) fn team_status_blocking_after_sync(
    app: &AppHandle,
    refresh: bool,
    synced: Option<Result<crate::team::SyncOutcome, String>>,
) -> crate::team::TeamStatus {
    // N14 (OB-7b): the clone, the pull and the membership probe run as the
    // team's account (read only when a call needs it — a local read makes none).
    let _account = team_account_scope(app);
    let status = team_status_with_sync(
        &app.state::<crate::license::LicenseStore>(),
        &app.state::<SettingsStore>(),
        &app.state::<WorkspaceStore>(),
        &app.state::<crate::team::TeamStore>(),
        refresh,
        synced,
    );
    if refresh {
        if let Some(saved) = record_team_account(&app.state::<SettingsStore>(), &status) {
            let _ = app.emit("settings://changed", saved);
        }
    }
    status
}

/// Launch G3 (Challenger P3-5): a read of the team from GitHub that finds the
/// login it ran as a member (now, not a stale verdict) records that login as
/// the team's account, when none is recorded yet (a team joined before
/// accounts were recorded). `Some(settings)` when it wrote.
pub(crate) fn record_team_account(settings: &SettingsStore, status: &crate::team::TeamStatus) -> Option<Settings> {
    // Round 2 (P2-b): only an answer that this login is a member, read now —
    // never a non-member's login, nor a stale verdict carried from before.
    if status.membership != crate::team::Membership::Member || status.membership_stale {
        return None;
    }
    let (Some(repo), Some(login)) = (status.team_repo.as_deref(), status.login.as_deref()) else {
        return None;
    };
    match settings.set_team_account_if_blank(repo, login) {
        Ok(saved) => saved,
        Err(e) => {
            log::warn!("team: couldn't record the team's account: {e}");
            None
        }
    }
}

/// N14 (OB-7b chokepoints, LAUNCH_PLAN T4): every team call site opens this
/// before its first GitHub call, so the team's gh and git run as
/// `settings.team.account` (the account the team was joined with) when it is
/// set — child environment only, never a fall-back to gh's active account
/// when that account can't be used. Unset: gh's active account, as before.
pub(crate) fn team_account_scope<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
) -> crate::github_account::GithubScope {
    let account = app.try_state::<SettingsStore>().and_then(|settings| team_account_of(&settings));
    crate::github_account::enter_for_team(account.as_deref())
}

/// N14 (P2-1): the team's account — `settings.team.account` only while this
/// Mac is in a team. With no team (Create, its defaults) gh's active account
/// is who creates one, whatever a stale setting says.
pub(crate) fn team_account_of(settings: &SettingsStore) -> Option<String> {
    team_repo_of(settings)?;
    settings
        .snapshot()
        .team
        .account
        .map(|a| a.trim().to_string())
        .filter(|a| !a.is_empty())
}

/// [`team_status_blocking`] over the stores themselves.
pub(crate) fn team_status_with(
    license: &crate::license::LicenseStore,
    settings: &SettingsStore,
    workspaces: &WorkspaceStore,
    team: &crate::team::TeamStore,
    refresh: bool,
) -> crate::team::TeamStatus {
    team_status_with_sync(license, settings, workspaces, team, refresh, None)
}

/// [`team_status_with`], given a clone-or-pull already run.
pub(crate) fn team_status_with_sync(
    license: &crate::license::LicenseStore,
    settings: &SettingsStore,
    workspaces: &WorkspaceStore,
    team: &crate::team::TeamStore,
    refresh: bool,
    synced: Option<Result<crate::team::SyncOutcome, String>>,
) -> crate::team::TeamStatus {
    let snapshot = settings.snapshot();
    let team_settings = &snapshot.team;
    let team_repo = crate::team::current_team_repo(team_settings);
    let mut status = crate::team::status_after_sync(
        team_repo.as_deref(),
        None,
        crate::team::clone_root_setting(team_settings, &snapshot.projects),
        &team_settings.ignored_repos,
        workspaces,
        team,
        refresh,
        synced,
    );
    // Promote's gate, from the cached membership only: this read is offline,
    // and a refresh has just asked GitHub and remembered the answer.
    if let Some(slug) = team_repo.as_deref() {
        let (allowed, reason) = promote_permission(
            license.team_access().refusal(),
            status.has_clone,
            team.cached_membership(slug).and_then(|cached| cached.can_write),
            refresh,
            clone_owner_login(&team.clone_dir(slug)).as_deref(),
        );
        status.can_write_library = allowed;
        status.write_library_reason = reason;
    }
    status
}

/// Read-only: the key, the local clone and the last membership answer. No
/// network — the panel renders as soon as Settings → Team opens.
///
/// No gate: reading a team and cloning its workspaces are free, per the
/// team-sharing design — only *writing* into the team library and editing
/// the manifest are paid, and neither ships in rung 1.
#[tauri::command]
pub async fn team_status(app: AppHandle) -> Result<crate::team::TeamStatus, String> {
    tauri::async_runtime::spawn_blocking(move || team_status_blocking(&app, false))
        .await
        .map_err(|error| format!("join team status: {error}"))
}

/// Onboarding §8.3: solo or team for this Mac, explicit or derived by
/// [`crate::team::effective_work_mode`] — the frontend follows this and
/// never re-derives it. Offline: the key, the workspaces and a directory
/// listing of the team clones.
#[tauri::command]
pub fn team_work_mode(
    settings: State<'_, SettingsStore>,
    workspaces: State<'_, WorkspaceStore>,
    team: State<'_, crate::team::TeamStore>,
    account: State<'_, crate::account::AccountStore>,
) -> crate::team::WorkModeView {
    let team_settings = settings.snapshot().team;
    let signals = crate::team::TeamSignals {
        github_issues_workspace: workspaces
            .snapshot()
            .workspaces
            .iter()
            .any(|w| w.kanban_sync_mode == crate::workspace::KanbanSyncMode::GitHubIssues),
        team_clone: team.has_any_clone(),
        plan_owns_team: account.info().owns_team(),
    };
    crate::team::WorkModeView {
        mode: crate::team::effective_work_mode(&team_settings, signals),
        chosen: team_settings.work_mode.is_some(),
    }
}

/// Clone-or-pull the team repo and re-ask GitHub who you are and whether
/// you may read it. Errors are advisory (`status.error`): an offline Mac
/// still shows the team from its local clone.
#[tauri::command]
pub async fn team_refresh(app: AppHandle) -> Result<crate::team::TeamStatus, String> {
    tauri::async_runtime::spawn_blocking(move || {
        crate::github::invalidate_login_cache();
        // Skills hub H2: the same pull the background one is (one at a time,
        // a second press waits for the first's answer), recorded the same
        // way — "Updated …", the toast, access lost, leaving. It also tells
        // the Inbox to read its rows again (H6a: a pull may have brought a
        // script that needs an OK).
        crate::skills_hub::team_pull(&app, crate::skills_hub::Trigger::Refresh)
            .unwrap_or_else(|| team_status_blocking(&app, true))
    })
    .await
    .map_err(|error| format!("join team refresh: {error}"))
}

/// Pick one team workspace: clone it under the clone root and register it
/// through the `import_default` path. Idempotent — a member may press the
/// same row twice.
#[tauri::command]
pub async fn team_workspace_add(
    app: AppHandle,
    repo: String,
) -> Result<crate::team::AddedWorkspace, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let settings = app.state::<SettingsStore>();
        let workspaces = app.state::<WorkspaceStore>();
        let team = app.state::<crate::team::TeamStore>();
        let _account = team_account_scope(&app);
        let slug = team_repo_of(&settings).ok_or_else(no_team_message)?;
        let manifest = crate::team::read_manifest(&team.clone_dir(&slug))?
            .ok_or_else(|| format!("The team repo is not on {THIS_MACHINE} yet — refresh first."))?;
        // The manifest is the truth: a repo it does not list is not a team
        // workspace, whatever the frontend asked for.
        let entry = manifest
            .workspaces
            .iter()
            .find(|w| w.repo.eq_ignore_ascii_case(repo.trim()))
            .ok_or_else(|| format!("{repo} is not a team workspace."))?;
        let snapshot = settings.snapshot();
        let root = crate::team::effective_clone_root(
            crate::team::clone_root_setting(&snapshot.team, &snapshot.projects),
            Some(&manifest),
        );
        // The manifest half of membership has no enforcement other than
        // this check, so it happens here, before any clone.
        // T1 (team walk): nothing to record for the board — a workspace the
        // team's manifest lists runs the team's board for as long as it does
        // (`workspace_adoption::app_team_lists`).
        crate::team::add_workspace_checked(&root, entry, &manifest, &workspaces, &team, &slug)
    })
    .await
    .map_err(|error| format!("join team workspace add: {error}"))?
}

/// GH #226: "Reapply mine on top" — the way out of a team clone that is
/// ahead *and* behind GitHub. Rebases this Mac's unpublished library commits
/// onto GitHub's branch (after recording a backup ref) and pushes; a
/// collision is aborted with the clone left as it was. Never a force-push.
///
/// Gated like every write into the team library: it publishes to it.
///
/// QoL 13.3: `choices` — the member's Keep mine / Keep theirs / Keep both for
/// each file a collision named. With them the rebase is settled on this Mac
/// and **not** pushed (`Resolved`): Publish is the next plain reapply, Undo
/// [`team_library_undo_resolve`].
#[tauri::command]
pub async fn team_library_reapply(
    app: AppHandle,
    choices: Option<std::collections::BTreeMap<String, crate::team::ReapplyChoice>>,
) -> Result<crate::team::ReapplyReport, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let slug = current_team_repo(&app)
            .ok_or_else(no_team_message)?;
        let _account = team_account_scope(&app);
        app.state::<crate::team::TeamStore>().reapply_resolving(&slug, choices.unwrap_or_default())
    })
    .await
    .map_err(|error| format!("join team library reapply: {error}"))?
}

/// QoL 13.3: **Undo** a settled reapply — the team clone goes back to the
/// backup the reapply recorded first. Local only: nothing is pushed or
/// fetched. Gated like the reapply it undoes.
#[tauri::command]
pub async fn team_library_undo_resolve(app: AppHandle) -> Result<String, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let slug = current_team_repo(&app)
            .ok_or_else(no_team_message)?;
        app.state::<crate::team::TeamStore>().undo_resolved(&slug)
    })
    .await
    .map_err(|error| format!("join team library undo: {error}"))?
}

/// QoL 13.3: **Move them aside** — the team clone's uncommitted edits are
/// copied into a dated folder on this Mac, then put back to the clone's last
/// commit, so the reapply can run. Local only. Gated like the reapply.
#[tauri::command]
pub async fn team_library_move_aside(app: AppHandle) -> Result<crate::team::MovedAside, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let slug = current_team_repo(&app)
            .ok_or_else(no_team_message)?;
        app.state::<crate::team::TeamStore>().move_aside(&slug)
    })
    .await
    .map_err(|error| format!("join team library move aside: {error}"))?
}

/// QoL 13.3: show the folder the set-aside copies are in. The path is the
/// backend's own, never one the page sends. A read: not gated.
#[tauri::command(async)]
pub fn team_library_reveal_aside(app: AppHandle) -> Result<(), String> {
    let dir = app.state::<crate::team::TeamStore>().aside_root();
    if !dir.is_dir() {
        return Err(format!("Nothing has been set aside on {THIS_MACHINE} yet."));
    }
    crate::platform::open_path(&dir).map_err(|e| format!("open failed: {e}"))?;
    Ok(())
}

/// GH #226 review 1: show the team clone in Finder — the way to "settle it by
/// hand" after a collision, or to finish a rebase Ply didn't start. The path
/// is the backend's own (the key's team), never one the page sends. A read:
/// not gated.
#[tauri::command(async)]
pub fn team_library_reveal(app: AppHandle) -> Result<(), String> {
    let slug = current_team_repo(&app)
        .ok_or_else(no_team_message)?;
    let dir = app.state::<crate::team::TeamStore>().clone_dir(&slug);
    if !dir.join(".git").exists() {
        return Err(format!("The team repo is not cloned on {THIS_MACHINE} yet."));
    }
    crate::platform::open_path(&dir).map_err(|e| format!("open failed: {e}"))?;
    Ok(())
}

// ── Owner-side team administration (v1.118.0 — team sharing rung 5) ──
//
// Creating the team, inviting people to it, and finding repositories worth
// listing as team workspaces. Every one of these is the owner acting, so
// every one goes through `team_admin::authorize_owner_action` — the key
// *and* being the manifest's owner — before it touches GitHub. Creating is
// the exception that only needs the key: there is no manifest yet to be the
// owner of.
//
// All of them shell out (`gh repo create`, `gh api`, `git push`), so all of
// them run on the blocking pool.

/// How exact the identity behind an owner action has to be.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Identity {
    /// `current_login`'s own 60-second cache is close enough — a read-only
    /// surface that changes nothing.
    Cached,
    /// Re-asked of `gh` right now. **Every mutation uses this.**
    Fresh,
}

/// The manifest's owner, and who this machine is signed in to GitHub as.
///
/// The login comes from `github::current_login` and **never** from the
/// membership cache, however tempting the saved round trip is. That cache is
/// filled by a Settings refresh and has no expiry at all, so after a
/// `gh auth switch` it names the previous account for the life of the
/// process — while the `gh api` calls an invite makes, and the `git push` the
/// manifest rides on, run as the *new* one. v1.105.0 fixed exactly this class
/// for card claims by giving `current_login` a TTL; the owner check is the
/// one place where being wrong is worse, because Ply's own check is the only
/// enforcement of "the owner is the only person who edits members and team
/// workspaces" — GitHub write access is repository-wide.
fn team_owner_facts(
    app: &AppHandle,
    slug: &str,
    identity: Identity,
) -> (Option<String>, Option<String>) {
    let team = app.state::<crate::team::TeamStore>();
    let owner = crate::team::read_manifest(&team.clone_dir(slug))
        .ok()
        .flatten()
        .and_then(|m| m.owner_login().map(str::to_string));
    if identity == Identity::Fresh {
        // One `gh api user` per mutation. These are rare, deliberate acts —
        // creating a team, inviting somebody, editing the workspace list —
        // and each grants somebody access to repositories.
        crate::github::invalidate_login_cache();
    }
    (owner, crate::github::current_login().ok())
}

/// What passing the owner gate established.
struct TeamOwner {
    slug: String,
    manifest: crate::team::TeamManifest,
    /// This machine's GitHub login. Always known — the gate refuses without
    /// it — and carried out so the *re-check* against the pulled manifest
    /// costs no second round trip.
    login: String,
    team_allowed: bool,
}

/// The owner gate in front of every manifest edit and every invite.
///
/// Against the **local** clone, which is what makes it cheap enough to run
/// before anything else. It is a fast refusal, not the last word: a write
/// re-runs `authorize_owner_action` inside its post-pull mutation, because
/// who owns a team is a fact in the very file being edited.
fn team_owner_gate(app: &AppHandle, identity: Identity) -> Result<TeamOwner, String> {
    let slug = current_team_repo(&app)
        .ok_or_else(no_team_message)?;
    // Launch G3: the team gate's own words first (no Team plan, another
    // team, another account); the owner check below is the manifest's.
    team_gate(&app.state::<crate::license::LicenseStore>())?;
    let team_allowed = true;
    // N14 (P3-3): the team's account that can't be used is said as such,
    // not as "could not read your GitHub login".
    if let Some(Err(words)) = crate::github_account::scoped_login() {
        return Err(words);
    }
    let (owner, login) = team_owner_facts(app, &slug, identity);
    crate::team_admin::authorize_owner_action(team_allowed, owner.as_deref(), login.as_deref())?;
    let manifest = crate::team::read_manifest(
        &app.state::<crate::team::TeamStore>().clone_dir(&slug),
    )?
    .ok_or_else(|| format!("The team repo is not on {THIS_MACHINE} yet — refresh first."))?;
    Ok(TeamOwner {
        slug,
        manifest,
        // `authorize_owner_action` refuses a missing login, so passing it
        // means there is one.
        login: login.unwrap_or_default(),
        team_allowed,
    })
}

/// What the Create-team form starts from.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CreateTeamDefaults {
    /// `None` when `gh` could not say; the form then explains that rather
    /// than suggesting a repo under nobody's account.
    pub login: Option<String>,
    /// The GitHub repos this Mac's registered workspaces point at — the
    /// candidates for "team workspaces", pre-checked to none. `team-init.sh`
    /// defaulted to the repo it was run inside; a picker over the workspaces
    /// Ply already knows is the same idea with the guessing removed.
    pub workspaces: Vec<CreateTeamCandidate>,
}

#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CreateTeamCandidate {
    pub repo: String,
    pub name: String,
}

/// Read what the Create-team form needs: who you are, and which of your
/// workspaces are GitHub repositories.
#[tauri::command]
pub async fn team_create_defaults(app: AppHandle) -> Result<CreateTeamDefaults, String> {
    tauri::async_runtime::spawn_blocking(move || {
        // N14 (OB-7b): the account the team would be created as.
        let _account = team_account_scope(&app);
        let login = crate::github::current_login().ok();
        let mut workspaces: Vec<CreateTeamCandidate> = Vec::new();
        for workspace in app.state::<WorkspaceStore>().snapshot().workspaces {
            let cwd = PathBuf::from(&workspace.cwd);
            let Some(repo) = crate::git::capture(&cwd, &["remote", "get-url", "origin"])
                .ok()
                .and_then(|url| crate::team::origin_slug(url.trim()))
            else {
                continue;
            };
            if workspaces
                .iter()
                .any(|c| c.repo.eq_ignore_ascii_case(&repo))
            {
                continue;
            }
            workspaces.push(CreateTeamCandidate {
                repo,
                name: workspace.name,
            });
        }
        Ok(CreateTeamDefaults { login, workspaces })
    })
    .await
    .map_err(|error| format!("join team create defaults: {error}"))?
}

/// **Create team**: the private GitHub repo, the manifest that defines the
/// team, and the empty library rungs 2 and 3 fill.
///
/// Gated on the Team plan (launch G3, [`team_create_gate`]) because adding
/// members and team workspaces are paid and this is where both begin. Not
/// owner-gated: there is no manifest yet to be the owner of, and whoever runs
/// it becomes that owner.
///
/// On success the team is recorded as this Mac's (`settings.team.teamRepo`).
#[tauri::command]
pub async fn team_create(
    app: AppHandle,
    name: String,
    repo: String,
    workspaces: Vec<String>,
) -> Result<crate::team_admin::CreatedTeam, String> {
    tauri::async_runtime::spawn_blocking(move || {
        // P3-10: one Create team at a time in the whole app (a second press,
        // or Setup and Settings at once, would race on the repo and the bind).
        let _creating = crate::commands::CreateTeamRun::begin()?;
        let license = app.state::<crate::license::LicenseStore>();
        // Launch G3: creating a team needs the Team plan; its repository and
        // its creator are checked as soon as they are known (below).
        team_create_gate(&license, None, None)?;
        // D9: one team per account — a seat holder joins, never creates.
        if let Some(account) = app.try_state::<crate::account::AccountStore>() {
            if let Some(why) = crate::team_billing::create_refusal(&account.info()) {
                return Err(why);
            }
        }
        if let Some(existing) = current_team_repo(&app) {
            return Err(format!(
                "{THIS_MACHINE_CAP} is already in the team {existing}. Plyloft follows one team per \
                 {THIS_MACHINE}, so a second one would leave it reading a team you are not on."
            ));
        }
        // N14 (OB-7b): the repository, its clone and its first push run as
        // the team's account when one is set, and that account owns the team.
        let _account = team_account_scope(&app);
        // Whoever runs this becomes the team's owner, so the identity has to
        // be the one GitHub will actually see — not one cached before an
        // account switch.
        crate::github::invalidate_login_cache();
        let login = crate::github::current_login().map_err(|e| {
            format!("Plyloft could not read your GitHub login, so it cannot create a team: {e}")
        })?;
        let plan = crate::team_admin::plan_create_team(&name, &repo, &login, &workspaces)?;
        // D9/D10: the plan's team, created by the plan's own account.
        team_create_gate(&license, Some(plan.repo.as_str()), Some(login.as_str()))?;

        // Does the name already hold something? A repository owned by
        // somebody else answers 404 to this account, so a `false` here is
        // "nothing you can see" and `gh repo create` stays the authority on
        // whether the name is free.
        let start = if crate::github::repo_exists(&plan.repo).unwrap_or(false) {
            // It exists. Two states are this flow's own — private and empty
            // (unfinished: resume it) or private with a manifest this login
            // owns (finished: hand back the command, write nothing). Anything
            // else is somebody's repository (`team_admin::resume_decision`).
            crate::team_admin::resume_decision(
                &plan.repo,
                &login,
                crate::github::repo_resume_state(&plan.repo),
            )?
        } else {
            crate::team_admin::CreateStart::Fresh
        };

        let clone_dir = app
            .state::<crate::team::TeamStore>()
            .clone_dir(&plan.repo);
        let created = crate::team_admin::create_team_with(
            &plan,
            start,
            &clone_dir,
            |slug, description| crate::github::repo_create_private(slug, description),
            |slug, dest| crate::github::library_repo_clone(slug, dest),
            |dir, paths, message| {
                let git = crate::team::RealLibraryGit;
                crate::team::LibraryGit::commit(&git, dir, paths, message)?;
                crate::team::LibraryGit::push(&git, dir).map_err(String::from)
            },
            |dir| {
                crate::git::capture(dir, &["remote", "get-url", "origin"])
                    .ok()
                    .map(|url| url.trim().to_string())
                    .filter(|url| !url.is_empty())
            },
        )?;
        // Onboarding §11.1: the new team is this Mac's team from here on — no
        // key names it, so the setting does.
        let saved = remember_created_team(&app.state::<SettingsStore>(), &created.repo, &login)?;
        // F8: whoever created it is its member, with write access, as `login`
        // — the status read that follows needn't wait for a refresh to say so.
        app.state::<crate::team::TeamStore>().remember_creator(&created.repo, &login);
        // Every window's settings store, and the palette's `hasTeam`, follow.
        let _ = app.emit("settings://changed", saved);
        // Launch T1 (D17): the repository exists and is this Mac's team; bind
        // it to the owner's Team plan, then read the plan again so the gates
        // see the repository. A failure keeps the team and says how to finish.
        let mut created = created;
        match bind_team_repo(&app, &created.repo) {
            crate::team_billing::Bind::Bound => created.bound = true,
            crate::team_billing::Bind::Skipped => {}
            crate::team_billing::Bind::Failed(why) => created.bind_error = Some(why),
        }
        Ok(created)
    })
    .await
    .map_err(|error| format!("join team create: {error}"))?
}

/// P3-10: the in-flight Create team; dropping it lets the next one run.
#[derive(Debug)]
struct CreateTeamRun;

static CREATE_TEAM_RUNNING: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

impl CreateTeamRun {
    fn begin() -> Result<Self, String> {
        CREATE_TEAM_RUNNING
            .compare_exchange(false, true, std::sync::atomic::Ordering::SeqCst, std::sync::atomic::Ordering::SeqCst)
            .map(|_| CreateTeamRun)
            .map_err(|_| "Plyloft is already creating a team. Wait for it to finish.".to_string())
    }
}

impl Drop for CreateTeamRun {
    fn drop(&mut self) {
        CREATE_TEAM_RUNNING.store(false, std::sync::atomic::Ordering::SeqCst);
    }
}

/// Record a team just created as the one this Mac is in. The repository is
/// already on GitHub by now, so a failure says so and how to finish.
///
/// N14 (P2-1): with the account it was created as (`settings.team.account`),
/// so its later calls keep running as the owner after a `gh auth switch`.
fn remember_created_team(settings: &SettingsStore, repo: &str, login: &str) -> Result<Settings, String> {
    settings
        .set_joined_team(repo, Some(login.trim().to_string()).filter(|l| !l.is_empty()))
        .map_err(|e| {
            format!(
                "The team {repo} is on GitHub, but Plyloft could not remember it on {THIS_MACHINE} \
                 ({e}). Create it again with the same name: Plyloft picks up the team it already made."
            )
        })
}

/// **The confirmation screen**: every repository the team owns, the
/// permission Ply would grant on it, and what GitHub already gives this
/// person there. Reads GitHub; writes nothing.
#[tauri::command]
pub async fn team_invite_plan(
    app: AppHandle,
    login: String,
) -> Result<crate::team_admin::InvitePlan, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        // Read-only: this screen grants nothing, and the apply below it
        // re-resolves the identity exactly.
        let TeamOwner { slug, manifest, .. } = team_owner_gate(&app, Identity::Cached)?;
        // Ask GitHub about every repository first, so the screen the owner
        // reads is the one Ply would act on rather than a guess.
        let mut repos: Vec<String> = vec![slug.clone()];
        repos.extend(manifest.workspaces.iter().map(|w| w.repo.clone()));
        let access: Vec<(String, crate::github::CollaboratorAccess)> = repos
            .iter()
            .filter(|repo| crate::team::is_valid_repo_slug(repo))
            .map(|repo| {
                let answer = crate::github::collaborator_access(repo, login.trim())
                    .unwrap_or(crate::github::CollaboratorAccess::Unknown);
                (repo.clone(), answer)
            })
            .collect();
        // N14 (item 1): an invitation already waiting on them is not offered
        // again.
        let invitations = pending_invitations(&repos);
        crate::team_admin::build_invite_plan_with(&login, &slug, &manifest, &access, &invitations)
    })
    .await
    .map_err(|error| format!("join team invite plan: {error}"))?
}

/// **Add member**: apply the plan the owner just confirmed.
///
/// `confirmed` is the digest of the plan they read, and it is the *only*
/// thing the frontend gets to say about what should be granted. Ply pulls the
/// team repo, records the member and pushes, then rebuilds the plan from the
/// manifest that pull produced and grants nothing `confirmed` does not cover
/// — so a team workspace another Mac added in the meantime refuses the press
/// rather than being granted unread, and one it removed is simply not
/// granted.
#[tauri::command]
pub async fn team_invite_apply(
    app: AppHandle,
    login: String,
    confirmed: String,
) -> Result<crate::team_admin::InviteOutcome, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        // A fast refusal against the local clone; the authoritative one runs
        // below, against the manifest the pull produces.
        let owner = team_owner_gate(&app, Identity::Fresh)?;
        let clone_dir = app
            .state::<crate::team::TeamStore>()
            .clone_dir(&owner.slug);
        let request = crate::team_admin::InviteRequest {
            login: login.trim(),
            team_repo: &owner.slug,
            confirmed: &confirmed,
        };
        // GH #226: one git operation on the team clone at a time — held for
        // the manifest's publish only, released once its push returns, never
        // across the GitHub grant calls that follow.
        let team = app.state::<crate::team::TeamStore>();
        // Launch T2: the seat on the team's plan first — every seat taken
        // refuses the add before anything is written or granted on GitHub.
        let account = app.state::<crate::account::AccountStore>();
        crate::team_billing::add_member_with_seat(
            login.trim(),
            crate::github::user_id,
            |sub, member| take_seat(&app, &account, sub, member),
            || {
                let git = team.git_until_pushed();
                crate::team_admin::invite_member_with(
                    &request,
                    &clone_dir,
                    &git,
                    |manifest| {
                        crate::team_admin::authorize_owner_action(
                            owner.team_allowed,
                            manifest.owner_login(),
                            Some(&owner.login),
                        )
                    },
                    |repos| {
                        repos
                            .iter()
                            .map(|repo| {
                                let answer =
                                    crate::github::collaborator_access(repo, login.trim())
                                        .unwrap_or(crate::github::CollaboratorAccess::Unknown);
                                (repo.clone(), answer)
                            })
                            .collect()
                    },
                    |repos| pending_invitations(repos),
                    |repo, login, permission| {
                        crate::github::repo_invite_collaborator(repo, login, permission)
                    },
                )
            },
        )
    })
    .await
    .map_err(|error| format!("join team invite apply: {error}"))?
}

/// N14 (item 1): the pending invitations to `repos`, as the team's account
/// reads them (admins only). A repository GitHub didn't answer for has none
/// here: the plan then offers the grant, whose PUT on a pending invitee only
/// renews the invitation.
fn pending_invitations(repos: &[String]) -> Vec<crate::team_admin::PendingInvitation> {
    repos
        .iter()
        .filter(|repo| crate::team::is_valid_repo_slug(repo))
        .flat_map(|repo| {
            crate::github::repo_invitations(repo)
                .unwrap_or_default()
                .into_iter()
                .map(|invitation| crate::team_admin::PendingInvitation {
                    repo: repo.clone(),
                    invitation,
                })
        })
        .collect()
}

/// **Members** (N14 items 1 and 9): each manifest member as Joined, Invited
/// (with the day the invitation expires) or No access, on the team repo and
/// the team workspaces — two bounded `gh api` reads per repository
/// ([`crate::team_admin::MEMBER_STATE_REPO_LIMIT`] repositories at most),
/// as the team's account. Owner-only: only a repository's admins may read
/// its invitations, and the page shows Members to the owner alone.
#[tauri::command]
pub async fn team_member_states(app: AppHandle) -> Result<crate::team_admin::MemberStates, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        let TeamOwner { slug, manifest, .. } = team_owner_gate(&app, Identity::Cached)?;
        let repos = crate::team_admin::team_repos(&slug, &manifest);
        let asked = repos.len().min(crate::team_admin::MEMBER_STATE_REPO_LIMIT);
        let answers = read_repo_people(&repos[..asked]);
        let mut states = crate::team_admin::member_states(&slug, &manifest, &answers);
        if asked < repos.len() {
            states.problems.push(format!(
                "Plyloft read the first {asked} of the team's {} repositories.",
                repos.len()
            ));
        }
        Ok(states)
    })
    .await
    .map_err(|error| format!("join team member states: {error}"))?
}

/// N14 review (P3-5): [`team_member_states`]' reads, a few repositories at a
/// time ([`crate::github::PROBE_LANES`]), each lane as the caller's account
/// ([`crate::github_account::handoff`]); answers in the repositories' order.
fn read_repo_people(repos: &[String]) -> Vec<crate::team_admin::RepoPeople> {
    let next = std::sync::atomic::AtomicUsize::new(0);
    let out: std::sync::Mutex<Vec<(usize, crate::team_admin::RepoPeople)>> =
        std::sync::Mutex::new(Vec::with_capacity(repos.len()));
    let account = crate::github_account::handoff();
    let (next, out) = (&next, &out);
    std::thread::scope(|scope| {
        for _ in 0..crate::github::PROBE_LANES.min(repos.len()) {
            let account = account.clone();
            scope.spawn(move || {
                let _scope = account.enter();
                loop {
                    let index = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    let Some(repo) = repos.get(index) else { return };
                    let people = crate::team_admin::RepoPeople {
                        repo: repo.clone(),
                        collaborators: crate::github::repo_collaborator_logins(repo),
                        invitations: crate::github::repo_invitations(repo),
                    };
                    out.lock().unwrap_or_else(|e| e.into_inner()).push((index, people));
                }
            });
        }
    });
    let mut answers = std::mem::take(&mut *out.lock().unwrap_or_else(|e| e.into_inner()));
    answers.sort_by_key(|(index, _)| *index);
    answers.into_iter().map(|(_, people)| people).collect()
}

/// **Remove from team** (N14 item 3): take `login`'s access off the team repo
/// and every team workspace (pending invitations withdrawn, collaborator
/// removed, then checked), and only when every repository succeeded, take
/// them out of `team.json` — see [`crate::team_admin::remove_member_with`]
/// for why that order. Owner-only; nobody removes the owner or themselves.
#[tauri::command]
pub async fn team_member_remove(
    app: AppHandle,
    login: String,
) -> Result<crate::team_admin::RemoveOutcome, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        let owner = team_owner_gate(&app, Identity::Fresh)?;
        let team = app.state::<crate::team::TeamStore>();
        let clone_dir = team.clone_dir(&owner.slug);
        let request = crate::team_admin::RemoveRequest {
            login: login.trim(),
            team_repo: &owner.slug,
            acting_login: &owner.login,
        };
        // GH #226: the team clone's git lock is taken by the manifest's
        // publish only, never across the GitHub calls before it.
        let git = team.git_until_pushed();
        let outcome = crate::team_admin::remove_member_with(
            &request,
            &clone_dir,
            &git,
            |manifest| {
                crate::team_admin::authorize_owner_action(
                    owner.team_allowed,
                    manifest.owner_login(),
                    Some(&owner.login),
                )
            },
            revoke_team_access,
        )?;
        // Launch T2: their seat is freed once their GitHub access is gone on
        // every repository; a seat that couldn't be freed is said, and freed
        // again from Members.
        let mut outcome = outcome;
        let account = app.state::<crate::account::AccountStore>();
        let freed = crate::team_billing::free_seat_after_removal(
            &outcome.login,
            outcome.failed.is_empty(),
            crate::github::user_id,
            |sub| {
                // Dev-only: a dev-loaded plan held no seat, so none is claimed freed.
                #[cfg(all(feature = "test-bridge", debug_assertions))]
                if account.dev_plan_has_no_seats_at(chrono::Utc::now().timestamp_millis()) {
                    return Ok(false);
                }
                billing_call(&app, crate::billing_client::seat_delete(&account, sub))
                    .map(|team| team.is_some())
                    .map_err(|e| e.message)
            },
        );
        outcome.seat_freed = freed.freed;
        outcome.seat_error = freed.error;
        Ok(outcome)
    })
    .await
    .map_err(|error| format!("join team member remove: {error}"))?
}

// ── Team with seats and payment (launch T1–T3) ──────────────────────

/// A billing/team server call's result; a call that changed the session
/// (`replaced`: Free here; `unauthorized`: signed out) tells every window the
/// account changed.
fn billing_call<T>(
    app: &AppHandle,
    result: Result<T, crate::account::AccountError>,
) -> Result<T, crate::account::AccountError> {
    if let Err(e) = &result {
        if matches!(e.code, crate::account::ErrorCode::Replaced | crate::account::ErrorCode::Unauthorized) {
            let info = app.state::<crate::account::AccountStore>().info();
            let _ = app.emit(crate::account::EVENT_CHANGED, &info);
        }
    }
    result
}

/// Launch T2: `PUT /team/seats/{sub}`; every seat taken reads the team's
/// seat count for the words ("All N seats are taken").
fn take_seat(
    app: &AppHandle,
    account: &crate::account::AccountStore,
    sub: &str,
    login: &str,
) -> Result<(), crate::team_billing::SeatRefusal> {
    use crate::team_billing::SeatRefusal;
    // Dev-only: a dev-loaded plan has no seats to take, and the rest of Add
    // member runs for real (the team walk's way back).
    #[cfg(all(feature = "test-bridge", debug_assertions))]
    if account.dev_plan_has_no_seats_at(chrono::Utc::now().timestamp_millis()) {
        return Ok(());
    }
    match billing_call(app, crate::billing_client::seat_put(account, sub, login)) {
        Ok(_) => Ok(()),
        Err(e) if e.code == crate::account::ErrorCode::SeatLimit => Err(SeatRefusal::Limit {
            seats: crate::billing_client::team_get(account).ok().flatten().map(|t| t.seats),
            comp: account.info().comp,
        }),
        Err(e) => Err(SeatRefusal::Other(e.message)),
    }
}

/// Launch T1: bind `repo` to the owner's Team plan and read the plan again
/// (the gates then see the repository); emits the account change.
fn bind_team_repo(app: &AppHandle, repo: &str) -> crate::team_billing::Bind {
    let account = app.state::<crate::account::AccountStore>();
    let bind = crate::team_billing::bind_created_team(&account.info(), repo, |repo| {
        billing_call(app, crate::billing_client::team_bind(&account, repo))
    });
    if bind == crate::team_billing::Bind::Bound {
        if let Err(e) = account.refresh() {
            log::info!("team: refresh after binding failed: {}", e.message);
        }
        let _ = app.emit(crate::account::EVENT_CHANGED, &account.info());
    }
    bind
}

/// Launch T1–T3: where Create team stands and the server's view of the
/// team (seats, holders, a lapse). Signed out: no request.
#[tauri::command]
pub async fn team_billing_get(app: AppHandle) -> Result<crate::team_billing::TeamBilling, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let account = app.state::<crate::account::AccountStore>();
        let info = account.info();
        if !info.signed_in {
            return crate::team_billing::TeamBilling {
                stage: crate::team_billing::create_stage(&info, None),
                team: None,
                error: None,
            };
        }
        let (team, error) = match billing_call(&app, crate::billing_client::team_get(&account)) {
            Ok(team) => (team, None),
            Err(e) => (None, Some(e)),
        };
        crate::team_billing::TeamBilling {
            stage: crate::team_billing::create_stage(&account.info(), team.as_ref()),
            team,
            error,
        }
    })
    .await
    .map_err(|error| format!("join team billing: {error}"))
}

/// D16/D17: open Stripe Checkout for the Team plan in the browser, tied to
/// this account, with `seats` (2–50, the owner's included). Team is the only
/// plan sold: any other `plan` is refused (`None` means Team).
#[tauri::command]
pub async fn account_checkout(
    app: AppHandle,
    plan: Option<crate::account::Plan>,
    interval: crate::billing_client::Interval,
    seats: Option<u32>,
) -> Result<(), crate::account::AccountError> {
    if plan.is_some_and(|p| p != crate::account::Plan::Team) {
        return Err(crate::account::AccountError::new(
            crate::account::ErrorCode::BadRequest,
            "Only the Team plan has a checkout.",
        ));
    }
    tauri::async_runtime::spawn_blocking(move || {
        let account = app.state::<crate::account::AccountStore>();
        let url = billing_call(&app, crate::billing_client::checkout(&account, interval, seats))?;
        open_billing_page(&url)
    })
    .await
    .map_err(|e| crate::account::AccountError::new(crate::account::ErrorCode::Internal, e.to_string()))?
}

/// The Stripe Customer Portal in the browser (Add seats, payment, invoices,
/// cancel).
#[tauri::command]
pub async fn account_portal(app: AppHandle) -> Result<(), crate::account::AccountError> {
    tauri::async_runtime::spawn_blocking(move || {
        let account = app.state::<crate::account::AccountStore>();
        let url = billing_call(&app, crate::billing_client::portal(&account))?;
        open_billing_page(&url)
    })
    .await
    .map_err(|e| crate::account::AccountError::new(crate::account::ErrorCode::Internal, e.to_string()))?
}

/// Challenger H1: "Sign out other computers" (Settings › Plan; 1.178.0: Team
/// only, on the frontend). On a Team plan the server also makes this computer
/// the one Team runs on (A5 §3.5), so the plan is read again right after.
#[tauri::command]
pub async fn account_sign_out_others(app: AppHandle) -> Result<u32, crate::account::AccountError> {
    tauri::async_runtime::spawn_blocking(move || {
        let account = app.state::<crate::account::AccountStore>();
        let signed_out = billing_call(&app, account.sign_out_others())?;
        if let Err(e) = crate::account::refresh_and_emit(&app) {
            log::info!("account: refresh after signing out other computers failed: {}", e.message);
        }
        Ok(signed_out)
    })
    .await
    .map_err(|e| crate::account::AccountError::new(crate::account::ErrorCode::Internal, e.to_string()))?
}

fn open_billing_page(url: &str) -> Result<(), crate::account::AccountError> {
    crate::platform::open_url(url, crate::platform::WEB_SCHEMES).map_err(|e| {
        crate::account::AccountError::new(
            crate::account::ErrorCode::Internal,
            format!("Plyloft couldn't open the browser ({e})."),
        )
    })
}

/// The running Checkout wait's cancel, if any (one at a time).
static CHECKOUT_WAIT: std::sync::Mutex<Option<std::sync::Arc<crate::account::Stopper>>> =
    std::sync::Mutex::new(None);

/// LAUNCH_PLAN §5: after Checkout opens, ask the server for the plan every
/// few seconds for up to two minutes. `paid` once the entitlement says Team
/// owner; `pending` after the two minutes; `cancelled` by
/// [`team_checkout_wait_cancel`] (back to the choice) or the app quitting.
#[tauri::command]
pub async fn team_checkout_wait(app: AppHandle) -> Result<crate::team_billing::WaitOutcome, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let cancel = std::sync::Arc::new(crate::account::Stopper::default());
        if let Some(previous) = CHECKOUT_WAIT.lock().unwrap_or_else(|e| e.into_inner()).replace(cancel.clone()) {
            previous.stop();
        }
        let account = app.state::<crate::account::AccountStore>();
        let app_stop = account.stopper();
        let outcome = crate::team_billing::wait_for_team_plan(
            || account.refresh(),
            |d| cancel.wait(d) && !app_stop.is_stopped(),
            crate::team_billing::CHECKOUT_WAIT,
            crate::team_billing::CHECKOUT_POLL,
        );
        let mut slot = CHECKOUT_WAIT.lock().unwrap_or_else(|e| e.into_inner());
        if slot.as_ref().is_some_and(|s| std::sync::Arc::ptr_eq(s, &cancel)) {
            *slot = None;
        }
        drop(slot);
        let _ = app.emit(crate::account::EVENT_CHANGED, &account.info());
        outcome
    })
    .await
    .map_err(|error| format!("join checkout wait: {error}"))
}

#[tauri::command]
pub fn team_checkout_wait_cancel() {
    if let Some(cancel) = CHECKOUT_WAIT.lock().unwrap_or_else(|e| e.into_inner()).take() {
        cancel.stop();
    }
}

/// Launch T1: **Finish creating your team** when the repository is already
/// this Mac's team but not bound to the plan yet (the app closed, or the
/// server couldn't be reached, after Create team).
#[tauri::command]
pub async fn team_bind_current(app: AppHandle) -> Result<crate::account::AccountInfo, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let settings = app.state::<SettingsStore>();
        let repo = team_repo_of(&settings).ok_or_else(no_team_message)?;
        let account = app.state::<crate::account::AccountStore>();
        let info = account.info();
        // P2-1: only the team's owner as `team.json` names them, acting as
        // the team's GitHub account and signed in to Plyloft as it, binds
        // this team to their plan (the owner check without the team gate:
        // the gate can't pass before the bind).
        let _scope = team_account_scope(&app);
        if let Some(Err(words)) = crate::github_account::scoped_login() {
            return Err(words);
        }
        let (owner, login) = team_owner_facts(&app, &repo, Identity::Fresh);
        crate::team_billing::bind_current_check(owner.as_deref(), login.as_deref(), info.login.as_deref())?;
        match bind_team_repo(&app, &repo) {
            crate::team_billing::Bind::Bound => Ok(account.info()),
            crate::team_billing::Bind::Skipped => Err(format!(
                "{} Finish creating the team with the account that paid for it.",
                crate::license::TeamAccess::NoTeamPlan.refusal().unwrap_or_default()
            )),
            crate::team_billing::Bind::Failed(why) => Err(why),
        }
    })
    .await
    .map_err(|error| format!("join team bind: {error}"))?
}

/// Launch T2: free a seat held by somebody who is no longer in the team (a
/// removal whose seat call failed, or an add whose GitHub half never
/// finished). Owner-only; the owner's own seat can't be freed.
#[tauri::command]
pub async fn team_seat_free(app: AppHandle, sub: String) -> Result<Option<crate::billing_client::TeamView>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        let owner = team_owner_gate(&app, Identity::Cached)?;
        let account = app.state::<crate::account::AccountStore>();
        let sub = sub.trim().to_string();
        let listed = member_ids(&owner.manifest);
        if let Some(why) = crate::team_billing::seat_free_refusal(&sub, account.info().sub.as_deref(), &listed) {
            return Err(why);
        }
        billing_call(&app, crate::billing_client::seat_delete(&account, &sub)).map_err(|e| e.message)
    })
    .await
    .map_err(|error| format!("join team seat free: {error}"))?
}

/// P3-5: GitHub numeric ids by login (lowercase), for the life of the
/// process: an account's id never changes, so one `gh api users/<login>` per
/// member is enough.
static MEMBER_IDS: std::sync::Mutex<std::collections::BTreeMap<String, String>> =
    std::sync::Mutex::new(std::collections::BTreeMap::new());

/// `login`'s id, from the cache or GitHub (as the caller's scope).
fn member_id(login: &str) -> Result<String, String> {
    let key = login.trim().to_ascii_lowercase();
    if let Some(id) = MEMBER_IDS.lock().unwrap_or_else(|e| e.into_inner()).get(&key) {
        return Ok(id.clone());
    }
    let id = crate::github::user_id(login)?;
    MEMBER_IDS.lock().unwrap_or_else(|e| e.into_inner()).insert(key, id.clone());
    Ok(id)
}

/// The manifest's members with the ids GitHub gave, and those it couldn't
/// (named, never guessed: a seat is never matched on an incomplete list).
fn member_ids(manifest: &crate::team::TeamManifest) -> crate::team_billing::MemberIds {
    let mut ids = crate::team_billing::MemberIds::default();
    for m in &manifest.members {
        match member_id(&m.login) {
            Ok(sub) => ids.members.push(crate::billing_client::TeamAccount { sub, login: m.login.clone() }),
            Err(e) => {
                log::info!("team: couldn't look up {} on GitHub: {e}", m.login);
                ids.unresolved.push(m.login.clone());
            }
        }
    }
    ids
}

/// Launch T2 (P3-5): the team's members with their GitHub ids, so Members
/// matches seats by id, never by login. Owner-only, like Members.
#[tauri::command]
pub async fn team_member_ids(app: AppHandle) -> Result<crate::team_billing::MemberIds, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        let owner = team_owner_gate(&app, Identity::Cached)?;
        // Round 2 (P3-d): each Members read looks the ids up again.
        MEMBER_IDS.lock().unwrap_or_else(|e| e.into_inner()).clear();
        Ok(member_ids(&owner.manifest))
    })
    .await
    .map_err(|error| format!("join team member ids: {error}"))?
}

/// Launch T2 (P3-5): Give a seat to a listed member who holds none (a member
/// from before seats). Nothing changes on GitHub.
#[tauri::command]
pub async fn team_seat_give(app: AppHandle, login: String) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        let owner = team_owner_gate(&app, Identity::Fresh)?;
        if !owner.manifest.lists(login.trim()) {
            return Err(format!("{} isn't in the team: add them with Add somebody.", login.trim()));
        }
        let account = app.state::<crate::account::AccountStore>();
        crate::team_billing::add_member_with_seat(
            login.trim(),
            member_id,
            |sub, member| take_seat(&app, &account, sub, member),
            || Ok(()),
        )
    })
    .await
    .map_err(|error| format!("join team seat give: {error}"))?
}

/// One repository of Remove from team: withdraw `login`'s pending
/// invitations, take them off the collaborators, then ask GitHub what they
/// still have. Only a confirmed answer is a success (N14 review):
///
/// - a team workspace **they own** is refused before anything — GitHub can't
///   take a repository from its owner;
/// - a repository GitHub no longer shows (deleted, or out of reach) is said
///   as such, with how to drop it from the team's workspaces;
/// - write access that remains is a failure — through an organisation team
///   when an organisation owns the repository, otherwise to check by hand;
/// - an answer Plyloft couldn't read after the removal is a failure too;
/// - read access left on a **private** repository is a success that the
///   result names (an organisation's base permission gives it).
fn revoke_team_access(repo: &str, login: &str) -> Result<crate::team_admin::Revoked, String> {
    use crate::github::CollaboratorAccess;
    if repo
        .split('/')
        .next()
        .is_some_and(|owner| owner.eq_ignore_ascii_case(login.trim()))
    {
        return Err(format!(
            "They own {repo}, so GitHub can't take it from them. Take it off the team's \
             workspaces in team.json first, then Remove again."
        ));
    }
    let mut done = crate::team_admin::Revoked::default();
    let invitations = crate::github::repo_invitations(repo).map_err(|e| {
        let lower = e.to_ascii_lowercase();
        if lower.contains("http 403") || lower.contains("must have admin rights") {
            return format!(
                "You can't manage who has access to {repo} on GitHub — ask its owner, or take it \
                 off the team's workspaces in team.json ({e})"
            );
        }
        match crate::github::classify_gh_error(&e) {
            crate::github::GhErrorKind::Denied => format!(
                "GitHub no longer shows {repo}: it was deleted or renamed. If it's gone, take it \
                 off the team's workspaces in team.json, then Remove again ({e})"
            ),
            _ => format!("Plyloft couldn't read its invitations ({e})"),
        }
    })?;
    for invitation in invitations
        .iter()
        .filter(|i| i.login.eq_ignore_ascii_case(login))
    {
        crate::github::repo_cancel_invitation(repo, invitation.id)
            .map_err(|e| format!("GitHub refused to withdraw the invitation ({e})"))?;
        done.cancelled_invitations += 1;
    }
    // Somebody who was never a collaborator here (a workspace they were never
    // granted) may be answered with a refusal rather than a 204: nothing to
    // take away is a success once GitHub confirms they have no write access.
    let removed = crate::github::repo_remove_collaborator(repo, login);
    let left = match crate::github::collaborator_access(repo, login) {
        Ok(CollaboratorAccess::Unknown) => {
            return Err(match &removed {
                Err(e) => format!("GitHub refused to remove them ({e})"),
                Ok(()) => "Plyloft couldn't confirm what they still have there.".to_string(),
            })
        }
        // Never "no access": an account that was renamed keeps its access under
        // the new login, and this answer can't tell that from one that's gone.
        Ok(CollaboratorAccess::NoSuchAccount) => {
            return Err(format!(
                "GitHub has no account named {} now, so Plyloft can't tell whether they still have \
                 access: an account that was renamed keeps it. Check the repository's collaborators \
                 on GitHub.",
                login.trim()
            ))
        }
        Ok(left) => left,
        Err(e) => {
            return Err(match &removed {
                Err(refused) => format!("GitHub refused to remove them ({refused})"),
                Ok(()) => format!("Plyloft couldn't confirm what they still have there ({e})"),
            })
        }
    };
    let facts = || crate::github::repo_owner_facts(repo);
    if left.can_push() {
        if let Err(e) = removed {
            return Err(format!("GitHub refused to remove them ({e})"));
        }
        return Err(match facts() {
            Ok(f) if f.organisation => format!(
                "GitHub still gives them {} access there through the organization that owns it. \
                 Remove them from that organization's team on GitHub.",
                left.label()
            ),
            _ => format!(
                "GitHub still gives them {} access there. Check the repository's collaborators \
                 on GitHub.",
                left.label()
            ),
        });
    }
    if left == CollaboratorAccess::Read {
        // Unknown ownership: said, neutrally (never a claim about why).
        done.still_reads = facts().map(|f| f.private).unwrap_or(true);
    }
    Ok(done)
}

/// **Assisted discovery**: repositories this account can reach that already
/// carry `.atelier/workspace.json` (ADR 0003) or the older
/// `.atelier/workspace_default.json`.
///
/// It proposes and nothing more. One `gh api` per repository is the only way
/// to ask whether a file exists, so the scan is bounded and says how many it
/// looked at — "nothing found" and "nothing was looked at" are different
/// answers and a member would act differently on each.
#[tauri::command]
pub async fn team_discover(app: AppHandle) -> Result<crate::team_admin::Discovery, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        let TeamOwner { slug, manifest, .. } = team_owner_gate(&app, Identity::Cached)?;
        let ignored = app.state::<SettingsStore>().snapshot().team.ignored_repos;
        let repos = crate::github::repos_accessible(
            crate::team_admin::DISCOVERY_SCAN_LIMIT,
        )?;
        let slugs: Vec<String> = repos
            .iter()
            .map(|repo| repo.name_with_owner.clone())
            .collect();
        // Newest marker first; the older one is asked for only where the
        // newer one was not found, so an adopted repo costs one probe.
        let mut answers: Vec<(String, Vec<Result<bool, String>>)> =
            slugs.iter().map(|slug| (slug.clone(), Vec::new())).collect();
        for marker in crate::team_admin::WORKSPACE_MARKERS {
            let pending: Vec<String> = answers
                .iter()
                .filter(|(_, got)| !got.iter().any(|a| matches!(a, Ok(true))))
                .map(|(slug, _)| slug.clone())
                .collect();
            for (slug, answer) in crate::github::repos_carrying(&pending, marker) {
                if let Some((_, got)) = answers.iter_mut().find(|(s, _)| *s == slug) {
                    got.push(answer);
                }
            }
        }
        let found: Vec<crate::team_admin::DiscoveredRepo> = repos
            .into_iter()
            .map(|repo| {
                let carries_marker = answers
                    .iter()
                    .find(|(slug, _)| *slug == repo.name_with_owner)
                    .and_then(|(_, got)| crate::team_admin::combine_marker_answers(got));
                crate::team_admin::DiscoveredRepo {
                    repo: repo.name_with_owner,
                    description: repo.description,
                    archived: repo.is_archived,
                    private: repo.is_private,
                    carries_marker,
                }
            })
            .collect();
        Ok(crate::team_admin::discovery_proposals(
            &found,
            &slug,
            Some(&manifest),
            &ignored,
        ))
    })
    .await
    .map_err(|error| format!("join team discover: {error}"))?
}

/// Dismiss one discovery proposal on this Mac. Persisted, because a scan
/// re-runs on every press and a dismissal that lasted until the next one
/// would put the same repositories back forever.
///
/// On the blocking pool like its neighbours: the owner gate reads the GitHub
/// login, and a `gh api user` on the UI thread would freeze the window for a
/// round trip.
#[tauri::command]
pub async fn team_discovery_ignore(app: AppHandle, repo: String) -> Result<Vec<String>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        // A local preference, not a team edit — the cached identity is
        // enough, and nothing outward-facing happens either way.
        team_owner_gate(&app, Identity::Cached)?;
        let repo = repo.trim().to_string();
        if !crate::team::is_valid_repo_slug(&repo) {
            return Err(format!("{repo} is not an owner/name repository."));
        }
        let saved = app.state::<SettingsStore>().update(|s| {
            if !s.team.ignored_repos.iter().any(|r| r.eq_ignore_ascii_case(&repo)) {
                s.team.ignored_repos.push(repo);
            }
        })?;
        // The store hears it, so its next whole-settings write (a size
        // save, a preference) carries the ignore instead of undoing it.
        let _ = app.emit("settings://changed", saved.clone());
        Ok(saved.team.ignored_repos)
    })
    .await
    .map_err(|error| format!("join team discovery ignore: {error}"))?
}

/// Put every dismissed repository back in front of the owner. The only undo
/// there is, and there has to be one: an ignore is one click and it is
/// otherwise invisible afterwards.
#[tauri::command]
pub async fn team_discovery_clear_ignored(app: AppHandle) -> Result<Vec<String>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        team_owner_gate(&app, Identity::Cached)?;
        let saved = app.state::<SettingsStore>().update(|s| s.team.ignored_repos.clear())?;
        let _ = app.emit("settings://changed", saved.clone());
        Ok(saved.team.ignored_repos)
    })
    .await
    .map_err(|error| format!("join team discovery clear ignored: {error}"))?
}

/// Add a repository to the team manifest as a team workspace: the other
/// half of assisted discovery, and how a team grows after it is created.
///
/// Existing members do **not** get access to it here. Granting on their
/// behalf without asking is exactly what the confirmation screen exists to
/// prevent — so the panel says to re-run Add member for each of them, which
/// is idempotent and will show only the new repository as a grant.
#[tauri::command]
pub async fn team_workspace_list_add(
    app: AppHandle,
    repo: String,
    name: Option<String>,
) -> Result<bool, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        let owner = team_owner_gate(&app, Identity::Fresh)?;
        let slug = owner.slug.clone();
        let repo = repo.trim().to_string();
        if !crate::team::is_valid_repo_slug(&repo) {
            return Err(format!("{repo} is not an owner/name repository."));
        }
        if repo.eq_ignore_ascii_case(&slug) {
            return Err(
                "The team repo holds the manifest and the library; it is never a workspace."
                    .to_string(),
            );
        }
        let team = app.state::<crate::team::TeamStore>();
        let clone_dir = team.clone_dir(&slug);
        let message = format!("team: add {repo} as a team workspace");
        // GH #226: one git operation on the team clone at a time.
        let _git = team.git_guard();
        let added = crate::team::publish_library_paths(
            &clone_dir,
            &[crate::team::MANIFEST_FILE.to_string()],
            &message,
            |clone| {
                // Re-read inside the mutation: whatever was read before the
                // pull is stale by the time this runs, and for the manifest
                // that means dropping a workspace another Mac just added.
                let current = crate::team::read_manifest(clone)?.ok_or_else(|| {
                    "The team repo has no team.json to add a workspace to.".to_string()
                })?;
                // And re-decide: who owns a team is a fact in the very file
                // being edited, so the gate above is a fast refusal and this
                // is the authoritative one.
                crate::team_admin::authorize_owner_action(
                    owner.team_allowed,
                    current.owner_login(),
                    Some(&owner.login),
                )?;
                match crate::team_admin::manifest_with_workspace(
                    &current,
                    &repo,
                    name.as_deref(),
                ) {
                    None => Ok(()),
                    Some(next) => crate::team_admin::write_manifest(clone, &next),
                }
            },
            &crate::team::RealLibraryGit,
        )
        .map_err(|error| error.message())?;
        Ok(added.committed)
    })
    .await
    .map_err(|error| format!("join team workspace list add: {error}"))?
}

/// QoL 14.4 (G25): take a repository off the team manifest's workspaces —
/// the inverse of [`team_workspace_list_add`], through the same owner gate
/// and the same one-file manifest publish to the team repository. Nothing
/// else changes: members keep their GitHub access to the repository (the
/// owner removes it on GitHub if wanted) and their clones and workspaces.
/// `false` when it wasn't listed.
#[tauri::command]
pub async fn team_workspace_list_remove(app: AppHandle, repo: String) -> Result<bool, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _account = team_account_scope(&app);
        let owner = team_owner_gate(&app, Identity::Fresh)?;
        let slug = owner.slug.clone();
        let repo = repo.trim().to_string();
        if !crate::team::is_valid_repo_slug(&repo) {
            return Err(format!("{repo} is not an owner/name repository."));
        }
        let team = app.state::<crate::team::TeamStore>();
        let clone_dir = team.clone_dir(&slug);
        let message = format!("team: remove {repo} from the team workspaces");
        // GH #226: one git operation on the team clone at a time.
        let _git = team.git_guard();
        let removed = crate::team::publish_library_paths(
            &clone_dir,
            &[crate::team::MANIFEST_FILE.to_string()],
            &message,
            |clone| {
                // Re-read and re-decide inside the mutation, as the add does.
                let current = crate::team::read_manifest(clone)?.ok_or_else(|| {
                    "The team repo has no team.json to remove a workspace from.".to_string()
                })?;
                crate::team_admin::authorize_owner_action(
                    owner.team_allowed,
                    current.owner_login(),
                    Some(&owner.login),
                )?;
                match crate::team_admin::manifest_without_workspace(&current, &repo) {
                    None => Ok(()),
                    Some(next) => crate::team_admin::write_manifest(clone, &next),
                }
            },
            &crate::team::RealLibraryGit,
        )
        .map_err(|error| error.message())?;
        Ok(removed.committed)
    })
    .await
    .map_err(|error| format!("join team workspace list remove: {error}"))?
}

// ── Project skills (v1.117.0 — team sharing rung 4) ─────────────────
//
// The repo's own skill directories, and the two moves between them and the
// team library. Listing and Install are free (reading the library is, per
// `DESIGN.md`'s paid gate); Promote writes into the team repo, so it needs a
// key **and** GitHub write access.
//
// All three shell out — `git pull`, `git push`, `gh api` — so they run on the
// blocking pool like the rest of the team commands.

/// One workspace's name and checkout, from the managed store.
pub(crate) fn workspace_checkout<R: tauri::Runtime>(app: &tauri::AppHandle<R>, workspace_id: &str) -> Result<(String, PathBuf), String> {
    app.state::<WorkspaceStore>()
        .snapshot()
        .workspaces
        .into_iter()
        .find(|workspace| workspace.id == workspace_id)
        .map(|workspace| (workspace.name, PathBuf::from(workspace.cwd)))
        .ok_or_else(|| format!("workspace '{workspace_id}' not found"))
}

/// Whether this Mac may share into the team library, from the three facts
/// that decide it — kept pure so the matrix can be tested without a signed
/// key, a clone and a GitHub account.
///
/// Two separate gates, and the message has to say which one refused: the key
/// is a Ply matter the member can fix by pasting one, while write access is
/// GitHub's and only the team owner can grant it. `DESIGN.md`: "Anyone with
/// GitHub write access to the team repo can share into the library. GitHub is
/// the enforcement; Ply only reads `gh` to know what it may offer."
///
/// `can_write: None` is "GitHub did not say", which is **not** a refusal: Ply
/// offers the button and lets the push be the answer, because the alternative
/// is refusing an owner on the strength of an absent JSON field.
pub(crate) fn promote_permission(
    team_refusal: Option<String>,
    has_clone: bool,
    can_write: Option<bool>,
    asked_github: bool,
    owner: Option<&str>,
) -> (bool, Option<String>) {
    // Launch G3: the team gate's own words (no Team plan, another team,
    // another account), never a key.
    if let Some(why) = team_refusal {
        return (false, Some(why));
    }
    if !has_clone {
        return (
            false,
            Some(
                format!("The team repo is not cloned on {THIS_MACHINE} yet. Open Settings › Team › Members and library and refresh."),
            ),
        );
    }
    match can_write {
        Some(true) => (true, None),
        // Skills hub H4 (R7): GitHub's permissions are the gate, said plainly
        // — in the press-time 403's own words, so the row's hint and the
        // refusal of a press say the same sentence (H4 step 8 c Challenger).
        Some(false) => (false, Some(crate::team_proposal::read_only_words(owner))),
        None if asked_github => (true, None),
        // Nobody has asked GitHub yet this session and the cache is empty.
        None => (
            true,
            Some(
                "Plyloft has not been able to check your write access to the team repo with \
                 GitHub. Sharing may be refused when it reaches GitHub."
                    .to_string(),
            ),
        ),
    }
}

/// Whether [`promote_permission`]'s refusal is GitHub's own answer to this
/// member — read, not write — rather than the team gate (no Team plan,
/// another team, another account) or a missing clone. Only this is said on a
/// row's `⋯` as a disabled Promote (Skills hub H4 step 8 c walk). A missing
/// clone is not: after a switch-off (R16) or leaving (R17) the clone goes
/// while the team stays named, and "refresh" would not bring it back. With
/// no clone, [`promote_permission`] says "not cloned" whatever GitHub said,
/// so a cached read-only answer then is no refusal to show either.
pub(crate) fn promote_refused_by_repo(team_refusal: Option<&str>, has_clone: bool, can_write: Option<bool>) -> bool {
    team_refusal.is_none() && has_clone && can_write == Some(false)
}

/// The owner the team clone's manifest names, for "Ask <owner> for write
/// access" ([`crate::team_proposal::read_only_words`]).
pub(crate) fn clone_owner_login(clone: &Path) -> Option<String> {
    crate::team::read_manifest(clone)
        .ok()
        .flatten()
        .and_then(|manifest| manifest.owner_login().map(str::to_string))
}

/// What [`promote_permission`] decides from.
pub(crate) struct PromoteFacts {
    /// The team gate's refusal.
    pub team_refusal: Option<String>,
    pub has_clone: bool,
    /// GitHub's write answer.
    pub can_write: Option<bool>,
    /// GitHub was asked just now.
    pub asked_github: bool,
    /// The clone manifest's owner.
    pub owner: Option<String>,
    /// H4 Challenger step 13: GitHub couldn't be asked just now because the
    /// team's GitHub account isn't signed in on this machine.
    pub signed_out: bool,
}

/// H4 Challenger step 13: the row's hint when GitHub couldn't be asked about
/// write access because nobody is signed in. Promote stays offered — "GitHub
/// did not say" is never a refusal — and a press says the same in its own
/// words (`team::sign_in_words`), with nothing left behind.
pub(crate) fn promote_signed_out_words() -> String {
    format!(
        "{}{THIS_MACHINE}, so Plyloft has not been able to check your write access to the team \
         repo. Sharing will be refused until you sign in to GitHub in Settings › Team › Members and library.",
        crate::team::SIGN_IN_MARKER
    )
}

/// Whether a membership probe's errors come down to no GitHub sign-in: gh's
/// own words, Plyloft's account words, or git's prompt it may not show.
pub(crate) fn probe_says_signed_out(errors: &[String]) -> bool {
    errors.iter().any(|error| {
        let lower = error.to_lowercase();
        lower.contains("requires authentication")
            || lower.contains("http 401")
            || lower.contains("gh auth login")
            || lower.contains("not logged in")
            || lower.contains("isn't signed in on")
            || crate::platform::is_git_auth_prompt_refused(error)
    })
}

impl PromoteFacts {
    pub(crate) fn decide(self) -> (bool, Option<String>) {
        let signed_out = self.signed_out && self.can_write.is_none();
        let (allowed, reason) =
            promote_permission(self.team_refusal, self.has_clone, self.can_write, self.asked_github, self.owner.as_deref());
        if allowed && signed_out {
            return (true, Some(promote_signed_out_words()));
        }
        (allowed, reason)
    }

    /// [`promote_refused_by_repo`] for these facts.
    pub(crate) fn refused_by_repo(&self) -> bool {
        promote_refused_by_repo(self.team_refusal.as_deref(), self.has_clone, self.can_write)
    }
}

/// The Skills view's Promote gate: whether Promote is offered, what to say
/// about it, and whether that is GitHub's read-only refusal
/// (`ProjectSkillsView::promote_refused`). `None` is a Mac on no team.
pub(crate) fn promote_view_gate(facts: Option<PromoteFacts>) -> (bool, Option<String>, bool) {
    match facts {
        Some(facts) => {
            let refused = facts.refused_by_repo();
            let (allowed, reason) = facts.decide();
            (allowed, reason, refused && !allowed)
        }
        None => (
            false,
            Some(format!("{THIS_MACHINE_CAP} is not on a team yet, so there is no team library to share with.")),
            false,
        ),
    }
}

/// Resolve [`promote_permission`]'s facts, asking GitHub once if the cache has
/// no answer yet.
fn promote_authorization<R: tauri::Runtime>(app: &tauri::AppHandle<R>, slug: &str) -> (bool, Option<String>) {
    promote_facts(app, slug).decide()
}

/// [`promote_authorization`]'s facts, before they are decided.
fn promote_facts<R: tauri::Runtime>(app: &tauri::AppHandle<R>, slug: &str) -> PromoteFacts {
    let team_refusal = app.state::<crate::license::LicenseStore>().team_access().refusal();
    let team_allowed = team_refusal.is_none();
    let team = app.state::<crate::team::TeamStore>();
    let clone_dir = team.clone_dir(slug);
    let has_clone = clone_dir.join(".git").exists();
    // The cached answer first: the panel opens often and this is a network
    // round trip. A cold cache is probed once, which is also what makes the
    // panel's button state right the first time it is rendered.
    let mut asked_github = false;
    let mut signed_out = false;
    let cached = team.cached_membership(slug).or_else(|| {
        if !team_allowed || !has_clone {
            // Refused before GitHub matters; do not spend a round trip on it.
            return None;
        }
        // N14 (OB-7b): asked as the team's account, whatever workspace's
        // account the caller acts for (restored when the probe returns).
        let _account = team_account_scope(app);
        // The manifest is read from the clone so the probe resolves a real
        // membership: `remember_membership` discards an `Unknown`, and a probe
        // that asked GitHub without the manifest would throw away the write
        // answer it did get along with it.
        let manifest = crate::team::read_manifest(&clone_dir).ok().flatten();
        let probe = crate::team::probe_membership(slug, manifest.as_ref());
        // H4 Challenger step 13: "asked" only when GitHub answered. A probe
        // that couldn't reach it (gh signed out, offline) leaves the row's
        // caveat — said as the missing sign-in when that is why.
        asked_github = probe.errors.is_empty();
        signed_out = probe_says_signed_out(&probe.errors);
        team.remember_membership(slug, probe.membership, probe.login, probe.can_write);
        team.cached_membership(slug)
            .or(Some(crate::team::CachedMembership {
                slug: slug.to_string(),
                membership: probe.membership,
                login: None,
                can_write: probe.can_write,
            }))
    });
    PromoteFacts {
        team_refusal,
        has_clone,
        can_write: cached.and_then(|cached| cached.can_write),
        asked_github,
        owner: if has_clone { clone_owner_login(&clone_dir) } else { None },
        signed_out,
    }
}

/// The team clone and its skill library, when this Mac is on a team with a
/// clone. Reading it never fails (rung 2's rule: the team layer is additive).
fn team_library(app: &AppHandle) -> Option<(PathBuf, crate::team_skills::TeamSkillsLibrary)> {
    let slug = current_team_repo(app)?;
    let dir = app.state::<crate::team::TeamStore>().clone_dir(&slug);
    // Skills hub H2 (Windows walk): a library switched off or left lists
    // nothing, even when its clone stayed (no Recycle Bin) — sessions get
    // none of it either (`mcp_launch::team_clone_dir`).
    let delivers = crate::skills_hub::config_dir(app)
        .map(|config_dir| crate::skills_hub::delivers(&config_dir, &slug))
        .unwrap_or(true);
    let library = if delivers {
        crate::team_skills::read_library(&dir)
    } else {
        crate::team_skills::TeamSkillsLibrary::default()
    };
    Some((dir, library))
}

/// Everything Settings → This workspace → Project shows about skills: the
/// repo's own, and the team library's with what installing one would do.
///
/// No gate — a member who cannot share can still see and install.
#[tauri::command]
pub async fn project_skills_view(
    app: AppHandle,
    workspace_id: String,
) -> Result<crate::project_skills::ProjectSkillsView, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let (name, cwd) = workspace_checkout(&app, &workspace_id)?;
        let slug = current_team_repo(&app);
        let (can_promote, reason, promote_refused) =
            promote_view_gate(slug.as_deref().map(|slug| promote_facts(&app, slug)));
        let team = team_library(&app);
        // N14 item 2: what Promote would share is the branch's copy; read
        // only when there is a team to share with (two `ls-tree`s).
        let branch = slug
            .as_ref()
            .map(|_| promote_branch(&app, &workspace_id, &cwd));
        let plumbing = crate::shared_config::Plumbing { cwd: cwd.clone() };
        let trees = branch
            .as_ref()
            .and_then(|branch| branch.tip.as_deref())
            .map(|tip| crate::project_skills::branch_skill_trees(&plumbing, tip))
            .unwrap_or_default();
        let mut view = crate::project_skills::build_view(
            &workspace_id,
            &name,
            &cwd,
            team.as_ref().map(|(dir, library)| (dir.as_path(), library)),
            can_promote,
            reason,
            branch.as_ref().map(|branch| crate::project_skills::BranchView {
                git: &plumbing,
                branch,
                trees: &trees,
            }),
        );
        // Skills hub H6a (R15): a team skill whose scripts have no OK on this
        // Mac says so on its row. Read from the clone's `HEAD` commit, as a
        // launch reads it; a library it cannot read says nothing here (the
        // launch then gives no team skill at all, and logs why).
        if let Some((dir, _)) = team.as_ref() {
            attach_needs_ok(&app, dir, &mut view.team);
        }
        // The team rows' Codex chip is what a session really gets, not what
        // the library holds: the same check `ply_skills_view` runs for Ply's own.
        view.promote_refused = promote_refused;
        view.team_codex = team
            .as_ref()
            .and_then(|(_, library)| library.codex.as_ref())
            .map(|marketplace| {
                crate::branch_codex_skills::delivery_of(
                    &crate::codex_home::real_codex_home(),
                    marketplace,
                )
            });
        Ok(view)
    })
    .await
    .map_err(|error| format!("join project skills view: {error}"))?
}

/// Skills hub H6a: mark each team row whose scripts wait for an OK. A held
/// skill's plugin is its directory in the library, which is the manifest's
/// name in every library Plyloft writes; a row is matched by name and
/// plugin, or by name alone when only one row has it.
fn attach_needs_ok(app: &AppHandle, clone: &Path, rows: &mut [crate::project_skills::TeamSkillRow]) {
    let Ok(config_dir) = crate::skills_hub::config_dir(app) else {
        return;
    };
    let state = crate::skills_hub_state::load(&config_dir);
    let items = match crate::skill_scripts::needs_ok(clone, &state) {
        Ok(items) => items,
        Err(error) => {
            log::debug!("skills hub: which skills need an OK is unknown ({error})");
            return;
        }
    };
    for item in items {
        let named = rows.iter().filter(|row| row.skill.name == item.skill).count();
        if let Some(row) = rows.iter_mut().find(|row| {
            row.skill.name == item.skill && (row.skill.plugin == item.plugin || named == 1)
        }) {
            row.needs_ok = Some(item);
        }
    }
}

/// Skills hub H10: the clone the *Needs your OK* sheet reads — My library's
/// for `library: "mine"`, the team library's otherwise.
fn scripts_clone(app: &AppHandle, library: Option<&str>) -> Result<PathBuf, String> {
    if library == Some("mine") {
        return crate::my_library::delivered_clone(app)
            .ok_or_else(|| format!("My library is not on {THIS_MACHINE} yet."));
    }
    crate::mcp_launch::team_clone_dir(app).ok_or_else(|| format!("The team library is not on {THIS_MACHINE} yet."))
}

/// Skills hub H6a (R15): what the *Needs your OK* sheet shows for a team
/// skill — every file, scripts first, with what changed since the version new
/// sessions keep. `None` when it needs no OK. Free on every plan: safety is
/// never gated (§9).
#[tauri::command]
pub async fn skills_hub_scripts_review(
    app: AppHandle,
    plugin: String,
    skill: String,
    library: Option<String>,
) -> Result<Option<crate::skill_scripts::ScriptsReview>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let clone = scripts_clone(&app, library.as_deref())?;
        let config_dir = crate::skills_hub::config_dir(&app)?;
        let state = crate::skills_hub_state::load(&config_dir);
        crate::skill_scripts::review(&clone, &plugin, &skill, &state)
    })
    .await
    .map_err(|error| format!("join scripts review: {error}"))?
}

/// Skills hub H6a (R15): the member's OK for what the sheet showed — the
/// skill's scripts at `commit`, for this Mac only. Refused when the library
/// moved under the sheet to a version with other scripts. The next session
/// gets the approved version; running ones keep what they have (D13).
#[tauri::command]
pub async fn skills_hub_approve(
    app: AppHandle,
    plugin: String,
    skill: String,
    commit: String,
    scripts_ids: Vec<String>,
    library: Option<String>,
) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        let clone = scripts_clone(&app, library.as_deref())?;
        let config_dir = crate::skills_hub::config_dir(&app)?;
        crate::skill_scripts::approve(
            &config_dir,
            &clone,
            &plugin,
            &skill,
            &commit,
            &scripts_ids,
            chrono::Utc::now().timestamp_millis(),
        )?;
        // The Inbox row and the Library row resolve on their next read.
        let _ = app.emit("skills-hub://decision", ());
        Ok(())
    })
    .await
    .map_err(|error| format!("join scripts approval: {error}"))?
}

/// Skills hub H6b (R15 AC 1): the **Install-time sheet** — what Install
/// (`verb: "install"`, the team skill `plugin:skill`) or Update / Take
/// upstream (`"update"`, the linked copy `skill` of this repository) would
/// write into the repository that is not text, with every file listed. `None`
/// when nothing asks: the action goes ahead without a sheet. Read from the
/// clone as this Mac has it (no pull); the action pulls first and refuses
/// when what it would write is not what the sheet's OK named. Free on every
/// plan (§9).
#[tauri::command]
pub async fn skills_hub_install_review(
    app: AppHandle,
    workspace_id: String,
    plugin: String,
    skill: String,
    verb: String,
    library: Option<String>,
) -> Result<Option<crate::skill_scripts::ScriptsReview>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let skill = crate::project_skills::safe_name(&skill)?;
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        let (clone, plugin, name, copies) = match verb.as_str() {
            "install" => {
                // Skills hub H10: Install from My library reads its clone.
                let clone = scripts_clone(&app, library.as_deref())?;
                (clone, plugin, skill.clone(), Vec::new())
            }
            "update" => {
                let read = skills_hub_copy::app_links_here(&app, &workspace_id, &cwd);
                let link = read
                    .links
                    .get(&skill)
                    .ok_or_else(|| format!("{skill} isn't linked to a library here."))?;
                // H8: a copy of another workspace's skill (or this Mac's).
                if crate::skill_copy::is_copy_origin(&link.origin) {
                    return skills_hub_copy::update_review(&app, &workspace_id, &cwd, &skill, link);
                }
                let clone = team_origin_clone(&app, &link.origin).ok_or_else(|| {
                    format!(
                        "{skill} is linked to {}, which isn't available on {THIS_MACHINE}.",
                        crate::skill_links::origin_words(&link.origin)
                    )
                })?;
                let here = crate::skill_card::checkout_twin_ids(&cwd, &skill);
                let effective =
                    skills_hub_decisions::effective_link(Some(&clone), link, &here, Some((&cwd, skill.as_str())));
                let plugin = effective.origin.plugin.clone().unwrap_or_default();
                let target = resolve_base_branch(&app.state::<ProjectConfigStore>(), &workspace_id);
                (clone, plugin, effective.origin.name.clone(), checkout_copies(&cwd, &target, &skill))
            }
            other => return Err(format!("unknown action `{other}`")),
        };
        let (_, path) = team_source_path(&clone, &plugin, &name)?;
        let config_dir = crate::skills_hub::config_dir(&app)?;
        let state = crate::skills_hub_state::load(&config_dir);
        crate::skill_scripts::repo::repo_review(&clone, &plugin, &name, &path, &copies, &state)
    })
    .await
    .map_err(|error| format!("join install review: {error}"))?
}

/// Decision §6 (group B): the whole-tree digest of each copy of a duplicated
/// skill, so the Library can tell two byte-identical copies (the state a Promote
/// or an Install leaves behind) from two that differ. Each group is one copy's
/// directories; `None` where one cannot be read or its directories disagree
/// ([`crate::project_skills::tree_digest`]), and — GH #216 review 1 (L9) — where
/// a directory is outside the places the Library lists skills from
/// ([`crate::project_skills::tree_digests_within`]). Read-only, and no gate.
#[tauri::command]
pub async fn skill_tree_digests(
    app: AppHandle,
    workspace_id: String,
    groups: Vec<Vec<String>>,
) -> Result<Vec<Option<String>>, String> {
    let mut allowed: Vec<PathBuf> = Vec::new();
    if let Ok((_, cwd)) = workspace_checkout(&app, &workspace_id) {
        allowed.extend(
            crate::project_skills::SKILL_ROOTS
                .iter()
                .map(|root| crate::project_skills::under(&cwd, root.rel)),
        );
    }
    if let Ok(config) = app.path().app_config_dir() {
        // The branch mirror, and the builds its link points at (a row may
        // name either) — not the rest of the workspace's Plyloft directory.
        let mirror = config
            .join("projects")
            .join(&workspace_id)
            .join(ply_memory::SHARED_LIBRARY_MIRROR_DIR);
        allowed.extend(ply_memory::resolve_mirror(&mirror));
        allowed.push(crate::shared_library_sync::versions_dir(&mirror));
        allowed.push(mirror);
    }
    let home = crate::personal_skills::home_dir();
    allowed.extend(
        crate::personal_skills::PERSONAL_ROOTS
            .iter()
            .map(|root| crate::project_skills::under(&home, root.rel)),
    );
    allowed.extend(crate::mcp_launch::team_clone_dir(&app));
    allowed.extend(crate::ply_skills::bundle_dir(&app));
    tauri::async_runtime::spawn_blocking(move || {
        let groups: Vec<Vec<PathBuf>> = groups
            .iter()
            .map(|dirs| dirs.iter().map(PathBuf::from).collect())
            .collect();
        crate::project_skills::tree_digests_within(&groups, &allowed)
    })
    .await
    .map_err(|error| format!("join skill tree digests: {error}"))
}

/// GH #96 (ADR 0005): the member's own skills, for the Library's `On this Mac`
/// section. **Read-only** — the reader opens nothing for writing, and
/// `personal_skills_tests` asserts the whole home is byte-identical after a
/// call. No workspace: these skills reach every session on this Mac.
#[tauri::command]
pub async fn personal_skills_view() -> Result<crate::personal_skills::PersonalSkills, String> {
    tauri::async_runtime::spawn_blocking(|| {
        crate::personal_skills::read_personal_skills(&crate::personal_skills::home_dir())
    })
    .await
    .map_err(|error| format!("join personal skills view: {error}"))
}

/// GH #106 (ADR 0005, BOARDS.md §3 `Comes with Ply`): the skills that ship
/// inside the app, for the Library's `Comes with Ply` section and for each one's
/// page.
///
/// The bundle is the app's own read-only directory, so this reads and never
/// writes it; which of them are switched on is the member's `settings.json`,
/// read where every other setting is read. No workspace: these are per Mac.
///
/// **The chips are what a launch would really deliver** (review 1). This builds
/// the very library the next session gets — the same content-named directory, so
/// nothing extra is left on disk, and without stamping it, because a read is not a
/// launch (review 2). A skill is listed only when
/// [`crate::team_skills::read_skill_dir`] accepts it, the one reader that answers
/// "would a CLI load this at all" at every scope.
///
/// **A build that cannot be made lights no chips at all**, on any row, and the
/// section says why once (review 2). The previous rule lit a switched-*off* row
/// and darkened a switched-*on* one, which reads as exactly backwards; a state
/// where nothing is delivered is one state, and drawing it as one is what a member
/// can make sense of.
///
/// **Codex is asked separately**, because reaching it needs more than a build:
/// Codex has no session-scoped flag, so the skills arrive through a `CODEX_HOME`
/// overlay, and a member who already has a `ply-app` marketplace of their own gets
/// no overlay for them. [`crate::codex_home::preflight`] is the same check the
/// doctor runs for the team library, run here for Ply's own — without it the chip
/// stayed lit while no Codex session ever saw them. A Mac with **no** Codex home
/// is not a fault and is not said: the chip is simply dark, the rule the team layer
/// already follows for an absent layer.
#[tauri::command]
pub async fn ply_skills_view(app: tauri::AppHandle, workspace_id: Option<String>) -> Result<PlySkillsView, String> {
    let bundle = crate::ply_skills::bundle_dir(&app);
    let config_dir = app
        .path()
        .app_config_dir()
        .map_err(|error| format!("resolve Plyloft config directory: {error}"))?;
    let mac_off = app.state::<SettingsStore>().snapshot().library.ply_skills_off;
    tauri::async_runtime::spawn_blocking(move || {
        let Some(bundle) = bundle else {
            return PlySkillsView::default();
        };
        // Skills hub H9 (R9): the switch as this workspace's next session
        // reads it — the same inputs the launch reads (`mcp_launch`).
        let (place, inputs) = ply_skill_ipc::place_and_inputs(&app, workspace_id.as_deref(), mac_off.clone());
        let names = crate::ply_skills::read_bundle(&bundle);
        let off = inputs.off(names.iter().map(|skill| skill.name.as_str()).collect::<Vec<_>>());
        // `stamp: false` — the Library reads this on every open, and a read must
        // not keep a build alive that no session gets.
        let delivery = crate::ply_skills::deliver(
            &config_dir.join(crate::ply_skills::BUILDS_DIR),
            &bundle,
            &off,
            false,
        );
        let real_codex_home = crate::codex_home::real_codex_home();
        // Only when there is a marketplace to check: with no build there is
        // nothing to ask about, and `problem` already says so.
        let codex_refusal = delivery.library.codex.as_ref().and_then(|marketplace| {
            crate::codex_home::preflight(&real_codex_home, marketplace).err()
        });
        // A member who does not use Codex has nothing wrong with their Mac. Their
        // chip is dark and the section stays quiet.
        let no_codex_here = !real_codex_home.is_dir();
        let reaches = delivery.problem.is_none();
        // …and there has to *be* a marketplace: a build whose Codex half no reader
        // accepted would otherwise light the chip with nothing behind it.
        let reaches_codex =
            reaches && delivery.library.codex.is_some() && codex_refusal.is_none();
        PlySkillsView {
            skills: delivery
                .bundle
                .into_iter()
                .map(|skill| PlySkillRow {
                    // Walk follow-ups 2026-10-19: no `\\?\` in the page's Details.
                    dir: crate::platform::display_path(&bundle.join(&skill.name)),
                    claude: reaches,
                    codex: reaches_codex,
                    on: !mac_off.iter().any(|name| name == &skill.name),
                    version: skill.version().map(str::to_string),
                    switch: place.as_ref().map(|_| ply_skill_ipc::PlySwitchView::of(&inputs, &skill.name)),
                    changes: skill.changes,
                    name: skill.name,
                    title: skill.title,
                    description: skill.description,
                })
                .collect(),
            problem: delivery
                .problem
                .or_else(|| codex_refusal.filter(|_| !no_codex_here)),
            place,
        }
    })
    .await
    .map_err(|error| format!("join Plyloft skills view: {error}"))
}

/// The `Comes with Ply` section: its rows, and why they reach nothing when they
/// reach nothing.
#[derive(Debug, Clone, Default, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PlySkillsView {
    pub skills: Vec<PlySkillRow>,
    /// Said once under the section heading. `None` in the ordinary case, and also
    /// when every skill is switched off — that is a choice, not a fault.
    pub problem: Option<String>,
    /// Skills hub H9: the workspace this was read for, and its team.
    pub place: Option<ply_skill_ipc::PlyPlace>,
}

/// One row of the `Comes with Ply` section.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PlySkillRow {
    /// Its directory name, which is its identity in both CLIs (`ply:card-brief`).
    pub name: String,
    /// The `SKILL.md`'s own first heading — the row's plain name (BOARDS.md §3).
    pub title: String,
    pub description: String,
    /// The bundled directory, so the skill's page can read its text.
    pub dir: String,
    pub claude: bool,
    pub codex: bool,
    /// Switched on on this Mac (`settings.library.plySkillsOff`).
    pub on: bool,
    /// Skills hub H9 (R9): the Plyloft version that last changed it.
    pub version: Option<String>,
    /// …and every version, newest first (`CHANGES.json`).
    pub changes: Vec<crate::ply_skills::SkillChange>,
    /// The switch at every level in the workspace this was read for.
    pub switch: Option<ply_skill_ipc::PlySwitchView>,
}

/// GH #100 (BOARDS.md §4, state D): show a personal skill's directory in
/// Finder.
///
/// The board's `Details` on a personal skill's page holds the path and
/// `Reveal in Finder`, and this is the only way Ply reaches that folder — it
/// still never writes there. `listed_skill_dir` decides whether the path is one
/// Ply itself listed (a visible, real, direct child of one of the three personal
/// roots under this Mac's home) and refuses every other shape in words;
/// `personal_skills_tests` walks each refusal. No Tauri plugin is involved, so
/// the capability list needs nothing new: `open` is spawned the way
/// `worktree_reveal` and `kanban_attachment_reveal` spawn it.
#[tauri::command(async)]
pub fn personal_skill_reveal(path: String) -> Result<(), String> {
    let dir = crate::personal_skills::listed_skill_dir(
        &crate::personal_skills::home_dir(),
        &path,
    )?;
    crate::platform::reveal_path(&dir).map_err(|e| format!("open -R failed: {e}"))?;
    Ok(())
}

/// GH #100 (BOARDS.md §4): who last changed a skill, and when.
///
/// The fact line's `Last changed by MatteoB-adv 7 weeks ago` and the `Details`
/// line's `staging · a3f9c21 · MatteoB-adv · 2026-07-30 14:12`. Read with
/// `git log`, which writes nothing: a repository skill from
/// `refs/remotes/origin/<integration branch>` when the workspace shares one and
/// from the checkout's own `HEAD` otherwise, a team skill from the clone Ply
/// keeps in step. A window names the scope and the skill only — the revision and
/// the paths are built here (see [`crate::skill_history`]).
///
/// Never an error the page has to show: a scope with no history to read (this
/// Mac's own folders are not a repository; Ply's own skills have no files yet)
/// answers with every field empty, and the page leaves that part of the line out.
#[tauri::command]
pub async fn skill_history(
    app: AppHandle,
    workspace_id: String,
    scope: String,
    skill: String,
    plugin: Option<String>,
) -> Result<crate::skill_history::SkillHistory, String> {
    tauri::async_runtime::spawn_blocking(move || {
        crate::shared_library_sync::check_name(&skill)?;
        match scope.as_str() {
            "repository" => {
                let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
                // The branch the mirror is built from, when this workspace has
                // one. `app_library_state` is the one place that knows, and it
                // is what the page already read to draw the row.
                let branch = crate::workspace_definition::app_library_state(&app, &workspace_id)
                    .ok()
                    .filter(|state| state.shared)
                    .and_then(|state| state.branch);
                Ok(crate::skill_history::repository_history(
                    &cwd,
                    branch.as_deref(),
                    &skill,
                ))
            }
            "team" => {
                let Some((dir, _)) = team_library(&app) else {
                    return Ok(crate::skill_history::SkillHistory::default());
                };
                let plugin = plugin.unwrap_or_else(|| {
                    crate::team_skills::PLY_PLUGIN.to_string()
                });
                Ok(crate::skill_history::team_history(&dir, &plugin, &skill))
            }
            // `this-mac` and `ply` are not repositories: nothing to read, and
            // nothing invented in its place.
            _ => Ok(crate::skill_history::SkillHistory::default()),
        }
    })
    .await
    .map_err(|error| format!("join skill history: {error}"))?
}

/// What a Promote did, for the toast.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PromotedSkill {
    pub skill: String,
    pub plugin: String,
    pub copied: crate::project_skills::CopyOutcome,
    /// False when the library already held these exact bytes.
    pub committed: bool,
    /// The team repo on GitHub now has it. False only for a local-only team
    /// repo — reported rather than swallowed, because nothing reached a
    /// teammate.
    pub pushed: bool,
    /// N14 item 2: the branch the shared copy was read from.
    pub branch: String,
    /// N14 item 2: "Your local changes … aren't included", when this
    /// checkout's copy differed from the branch's.
    pub left_out: Option<String>,
    /// Skills hub H4 (R7): the pull request opened instead of a push — the
    /// skill changed in the team library since this Mac's last pull, or the
    /// library takes changes by pull request.
    pub pull_request: Option<PromotePullRequest>,
}

/// H4 (R7): a Promote that became a pull request in the team repository.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PromotePullRequest {
    pub url: String,
    pub number: Option<u64>,
    /// "Ana changed it meanwhile — opened pull request #31 instead."
    pub why: String,
}

/// What a Promote's library write did (H4, R7).
pub(crate) enum LibraryWrite {
    /// Committed (and pushed) to the team library's default branch.
    Pushed(crate::team::LibraryOutcome, crate::project_skills::CopyOutcome),
    /// Opened as a pull request instead.
    PullRequest(PromotePullRequest),
}

/// R7's per-path base: the tree ids the skill's two halves have at the
/// clone's `HEAD` (absent: not there).
fn half_ids(clone: &Path, halves: &[String]) -> Vec<Option<String>> {
    halves
        .iter()
        .map(|half| crate::library_snapshot::entry_tree(clone, "HEAD", half).ok().flatten())
        .collect()
}

/// R7 (never override), as Promote judges it: the skill's halves at `dir`
/// moved since `base`. Only a Promote that **replaces** can override a
/// teammate's change, so only it is judged; one that doesn't replace keeps
/// its own collision refusal (`write_promoted_skill`), which asks about a
/// same-named skill a teammate published meanwhile instead of overwriting it
/// in a pull request (H4 Challenger).
fn moved_since_base(replace: bool, dir: &Path, halves: &[String], base: &[Option<String>]) -> bool {
    replace && half_ids(dir, halves) != base
}

/// Who last changed `halves` at the clone's `HEAD`, for R7's toast.
fn last_author(clone: &Path, halves: &[String]) -> Option<String> {
    let mut args = vec!["log", "-1", "--format=%an", "HEAD", "--"];
    args.extend(halves.iter().map(String::as_str));
    crate::team::library_git_capture(clone, &args)
        .ok()
        .map(|out| out.trim().to_string())
        .filter(|name| !name.is_empty())
}

/// What a write's apply step returns when R7 finds the skill moved since
/// this Mac's base: nothing is written, and the Promote becomes a pull
/// request.
const MOVED_SINCE_BASE: &str = "the skill changed in the team library since the base this write started from";

/// H4 (R7): Promote as a pull request in the team repository — the skill
/// written exactly as Promote writes it (`write_promoted_skill`, manifests
/// included), on GitHub's tip of the default branch, in a scratch worktree
/// (the clone's checkout untouched). This Mac's pull request still open for
/// the skill takes the commit instead (one pull request per skill).
fn promote_pull_request<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    slug: &str,
    plugin: &str,
    skill: &str,
    source: &std::path::Path,
    paths: &[String],
) -> Result<crate::team_proposal::Opened, crate::project_skills::CopyError> {
    let team = app.state::<crate::team::TeamStore>();
    let clone = team.clone_dir(slug);
    let gh = crate::doctor::require("gh")
        .map(crate::shared_config::Gh::new)
        .map_err(|_| "Opening a pull request needs the GitHub CLI (gh). Settings › Setup and account › Setup installs it.".to_string())?;
    let config_dir = app.state::<WorkspaceStore>().config_dir.clone();
    let key = crate::skills_hub_state::proposal_key(&crate::skills_hub_state::team_key(slug), plugin, skill);
    let previous = crate::skills_hub_state::load(&config_dir).proposals.get(&key).cloned();
    let open = previous.filter(|p| {
        !p.branch.is_empty()
            && !p.commit.is_empty()
            && gh
                .pr_for_branch(&clone, slug, &p.branch)
                .ok()
                .flatten()
                .is_some_and(|found| found.state == crate::shared_config::PrState::Open)
    });
    let base_branch = crate::team_proposal::default_branch(&clone)?;
    let parent = match open.as_ref() {
        Some(p) => p.commit.clone(),
        None => crate::team_proposal::upstream_commit(&clone)?,
    };
    let branch = open
        .as_ref()
        .map(|p| p.branch.clone())
        .unwrap_or_else(|| crate::team_proposal::branch_name(skill, chrono::Local::now()));
    let message = format!("skills: share \"{skill}\" with the team");
    let title = crate::team_proposal::title(skill);
    let body = format!(
        "Shared from Plyloft as a pull request: {skill}. Nothing changes for anyone until it merges; \
         then every member's sessions get it."
    );
    let request = crate::team_proposal::Request {
        clone: &clone,
        slug,
        base_branch: &base_branch,
        branch: &branch,
        parent: &parent,
        paths,
        message: &message,
        title: &title,
        body: &body,
        reuse: open.is_some(),
    };
    let owner = crate::team::read_manifest(&clone)
        .ok()
        .flatten()
        .and_then(|manifest| manifest.owner_login().map(str::to_string));
    let opened = {
        let _git = team.git_guard();
        crate::team_proposal::open(&request, &gh, |root| {
            crate::project_skills::write_promoted_skill(root, plugin, skill, source, true)
                .map(|_| ())
                .map_err(String::from)
        })
    }
    .map_err(|error| error.words(owner.as_deref()))?;
    let now = chrono::Utc::now().timestamp_millis();
    crate::skills_hub_state::update(&config_dir, now, |state| {
        state.proposals.insert(
            key.clone(),
            crate::skills_hub_state::Proposal {
                branch: opened.branch.clone(),
                url: opened.url.clone(),
                number: opened.number,
                content_id: String::new(),
                commit: opened.commit.clone(),
                at: now,
                extra: Default::default(),
            },
        );
    })?;
    crate::skills_hub::nudge(crate::skills_hub::Trigger::AfterWrite);
    Ok(opened)
}

fn pull_request_words(number: Option<u64>) -> String {
    number.map(|n| format!("pull request #{n}")).unwrap_or_else(|| "a pull request".to_string())
}

/// N14 item 2: the branch `Promote to Team` reads a project skill from — the
/// shared definition's branch when the workspace has one, else the project's
/// integration branch (`main` when none is set), as SP-5's approvals use.
fn promote_branch(app: &AppHandle, workspace_id: &str, cwd: &Path) -> crate::project_skills::PromoteBranch {
    let git = crate::shared_config::Plumbing { cwd: cwd.to_path_buf() };
    let (branch, shared) = promote_branch_name(app, workspace_id);
    crate::project_skills::PromoteBranch::resolve(&git, &branch, shared)
}

/// The branch's name, and whether it is the shared definition's.
fn promote_branch_name(app: &AppHandle, workspace_id: &str) -> (String, bool) {
    let shared = crate::workspace_definition::app_library_state(app, workspace_id)
        .ok()
        .filter(|state| state.shared)
        .and_then(|state| state.branch);
    if let Some(branch) = shared {
        return (branch, true);
    }
    let branch = app
        .state::<ProjectConfigStore>()
        .get(workspace_id)
        .map(|config| config.target_branch)
        .filter(|branch| !branch.trim().is_empty())
        .unwrap_or_else(|| "main".to_string());
    (branch, false)
}

/// N14 review (P3-3): before a Promote reads GitHub's copy, fetch it —
/// bounded, as the workspace's GitHub account. A fetch that fails (offline,
/// sign-in) leaves the last fetched copy, which is still a committed one.
fn fetch_promote_branch(app: &AppHandle, workspace_id: &str, cwd: &Path) {
    let git = crate::shared_config::Plumbing { cwd: cwd.to_path_buf() };
    if !git.has_origin() {
        return;
    }
    let (branch, _) = promote_branch_name(app, workspace_id);
    let _account = crate::github_account::enter_for_app(app, workspace_id);
    if let Err(failure) = git.fetch(&branch) {
        log::info!("promote: couldn't fetch {branch} first; reading the last fetched copy: {failure:?}");
    }
}

/// **Promote**'s library write: `skill`'s copy at `source` into both halves
/// of the team library, committed and pushed as one change.
///
/// The mutation's own error is a sentence (the library write rolls back on
/// it), so the different-bytes refusal is carried out beside it and returned
/// as the value the window asks Replace about — but only when the rollback
/// provably left the library as it was; otherwise the library write's own
/// words say what may be left behind.
fn promote_into_library(
    app: &AppHandle,
    slug: &str,
    plugin: &str,
    skill: &str,
    source: &std::path::Path,
    replace: bool,
) -> Result<LibraryWrite, crate::project_skills::CopyError>
{
    let paths = crate::team_skills::promote_paths(plugin, skill)?;
    let message = format!("skills: share \"{skill}\" with the team");
    // N14 review (Q1): the team library's pull and push run as the team's account.
    let _account = team_account_scope(app);
    let copied: std::cell::RefCell<Option<crate::project_skills::CopyOutcome>> =
        std::cell::RefCell::new(None);
    let refused: std::cell::RefCell<Option<crate::project_skills::NotTheSameSkill>> =
        std::cell::RefCell::new(None);
    // Skills hub H4 (R7, never override): this Mac's base for the skill —
    // its two halves as the last pull left them. The write's own pull may
    // bring a teammate's change to them; then nothing is pushed and the
    // Promote becomes a pull request. A change to another skill is not a
    // divergence for this one (per path).
    let halves = paths[..2].to_vec();
    let clone = app.state::<crate::team::TeamStore>().clone_dir(slug);
    let base_ids = half_ids(&clone, &halves);
    let moved_by: std::cell::RefCell<Option<String>> = std::cell::RefCell::new(None);
    let published = app.state::<crate::team::TeamStore>().publish_paths(
        slug,
        &paths,
        &message,
        |clone_dir| {
            if moved_since_base(replace, clone_dir, &halves, &base_ids) {
                *moved_by.borrow_mut() = Some(last_author(clone_dir, &halves).unwrap_or_else(|| "A teammate".to_string()));
                return Err(MOVED_SINCE_BASE.to_string());
            }
            let outcome =
                crate::project_skills::write_promoted_skill(clone_dir, plugin, skill, source, replace)
                    .map_err(|error| {
                        *refused.borrow_mut() = error.refusal().cloned();
                        String::from(error)
                    })?;
            *copied.borrow_mut() = Some(outcome);
            Ok(())
        },
    );
    if let Some(author) = moved_by.into_inner() {
        let opened = promote_pull_request(app, slug, plugin, skill, source, &paths)?;
        let why = format!("{author} changed it meanwhile — opened {} instead.", pull_request_words(opened.number));
        return Ok(LibraryWrite::PullRequest(PromotePullRequest { url: opened.url, number: opened.number, why }));
    }
    // R7: GitHub refused the push. A branch that takes changes by pull
    // request gets one; a member who can't write hears so plainly. The write
    // took its own commit back; one an earlier push that may have landed left
    // goes too (GitHub refuses it just the same), so nothing waits half
    // published and no retry loop starts.
    if let Err(crate::team::LibraryError::Conflict { stage: crate::team::ConflictStage::Push, detail, .. }) = &published {
        let refusal = crate::team_proposal::push_refusal(detail);
        // A sign-in never arrives here: it's `LibraryError::SignIn`, or `Abandoned`.
        if refusal.is_some() {
            let head = crate::team::library_git_capture(&clone, &["rev-parse", "HEAD"]).map(|out| out.trim().to_string());
            let owner = crate::team::read_manifest(&clone)
                .ok()
                .flatten()
                .and_then(|manifest| manifest.owner_login().map(str::to_string));
            let drop_it = |head: &Result<String, String>| {
                let team = app.state::<crate::team::TeamStore>();
                let _git = team.git_guard();
                if let Ok(head) = head {
                    if let Err(error) = crate::team_proposal::drop_refused_commit(&clone, head) {
                        log::warn!("skills: couldn't put the team clone back after a refused push ({error})");
                    }
                }
            };
            if refusal == Some(crate::team_proposal::PushRefusal::ReadOnly) {
                drop_it(&head);
                // H4 step 8 c (Challenger): GitHub's answer, kept for the rows.
                app.state::<crate::team::TeamStore>().remember_read_only(slug);
                return Err(crate::team_proposal::read_only_words(owner.as_deref()).into());
            }
            // Whether or not the pull request opens, nothing refused stays: the
            // change is on the pull request's branch, or nowhere but in the
            // repository it came from (H4 Challenger). The pull request is cut
            // from `source`, never from the clone's commit.
            let opened = promote_pull_request(app, slug, plugin, skill, source, &paths);
            drop_it(&head);
            let opened = opened?;
            let why = format!(
                "{} Opened {}.",
                crate::team_proposal::TAKES_PULL_REQUESTS_WORDS,
                pull_request_words(opened.number)
            );
            return Ok(LibraryWrite::PullRequest(PromotePullRequest { url: opened.url, number: opened.number, why }));
        }
    }
    // H4 Challenger step 13: git couldn't sign in to GitHub. The library
    // write took its commit back, so the clone is as it was; the sentence
    // names the skill, not its path.
    if let Err(crate::team::LibraryError::SignIn { stage, ssh, .. }) = &published {
        return Err(crate::team::sign_in_words(&format!("share {skill}"), *stage, *ssh).into());
    }
    let outcome = crate::project_skills::promote_published(published, refused.into_inner())?;
    Ok(LibraryWrite::Pushed(outcome, copied.into_inner().unwrap_or_default()))
}

/// **Promote**: copy one project skill into both halves of the team library,
/// committed and pushed as one change.
#[tauri::command]
pub async fn project_skill_promote(
    app: AppHandle,
    workspace_id: String,
    skill: String,
    replace: bool,
    shown: Option<String>,
) -> Result<PromotedSkill, crate::project_skills::CopyError> {
    tauri::async_runtime::spawn_blocking(move || -> Result<PromotedSkill, crate::project_skills::CopyError> {
        // The gate first, before anything is read: this is the paid,
        // outward-facing half of the rung.
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let slug = current_team_repo(&app).ok_or_else(no_team_message)?;
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        let (allowed, reason) = promote_authorization(&app, &slug);
        if !allowed {
            return Err(reason
                .unwrap_or_else(|| {
                    format!("Plyloft cannot share into this team's library from {THIS_MACHINE}.")
                })
                .into());
        }

        // N14 item 2 (owner decision (b)): the branch's committed copy is what
        // is shared — never the checkout's, which is only read to say whether
        // local changes were left out, and never written. Read before the
        // library write because nothing in the team repo can change it; the
        // scratch copy lives until the write returns.
        fetch_promote_branch(&app, &workspace_id, &cwd);
        let branch = promote_branch(&app, &workspace_id, &cwd);
        let git = crate::shared_config::Plumbing { cwd: cwd.clone() };
        let source = crate::project_skills::branch_source(&git, &cwd, &branch, &skill)?;
        // The copy that would go, before anything is written (owner, 2026-11-03).
        crate::project_skills::refuse_private_files_on_branch(&skill, &source.dir, &branch)?;

        let plugin = crate::team_skills::PLY_PLUGIN;
        // The whole move happens inside the post-pull mutation (rung 2's lesson): the collision
        // check must be decided against what teammates have published, not against a stale clone.
        let written = promote_into_library(&app, &slug, plugin, &skill, &source.dir, replace)?;
        let left_out = [
            source.local_changes_left_out.then(|| {
                if source.checkout_behind {
                    crate::project_skills::newer_shared_line(&skill, &branch)
                } else {
                    crate::project_skills::left_out_line(&skill, &branch.branch)
                }
            }),
            branch.ahead_note.clone(),
        ]
        .into_iter()
        .flatten()
        .collect::<Vec<_>>();
        let (copied, committed, pushed, pull_request) = match written {
            LibraryWrite::Pushed(outcome, copied) => (copied, outcome.committed, outcome.pushed, None),
            LibraryWrite::PullRequest(pr) => (Default::default(), false, false, Some(pr)),
        };
        if committed && pushed { crate::skill_scripts::own_promote_needs_no_ok(&app, &app.state::<crate::team::TeamStore>().clone_dir(&slug), plugin, &skill, &source.dir, shown.as_deref()); }
        Ok(PromotedSkill {
            left_out: (!left_out.is_empty()).then(|| left_out.join(" ")),
            branch: branch.branch,
            skill,
            plugin: plugin.to_string(),
            copied,
            committed,
            pushed,
            pull_request,
        })
    })
    .await
    .map_err(|error| format!("join project skill promote: {error}"))?
}

/// Where a personal skill is promoted to (GH #96, BOARDS.md §6 "Promote").
#[derive(serde::Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum PromoteTarget {
    /// This repository's native roots. Commits nothing; the card ships it.
    Repository,
    /// The team library, committed and pushed as one change.
    Team,
}

/// What promoting a personal skill did.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PromotedPersonalSkill {
    pub skill: String,
    /// The team plugin, when it went to the team library.
    pub plugin: Option<String>,
    pub copied: crate::project_skills::CopyOutcome,
    /// The team library was changed. Always false for a repository promote,
    /// which commits nothing by design.
    pub committed: bool,
    /// The team repo on GitHub has it now.
    pub pushed: bool,
    /// Skills hub H4 (R7): opened as a pull request instead of a push.
    pub pull_request: Option<PromotePullRequest>,
}

/// **Promote a personal skill** into this repository or into the team library
/// (GH #96, ADR 0005: "Personal skills … are shown read-only with Promote").
///
/// The member's own copy is never touched — the flow says so, and this command
/// only ever reads the personal directory. Which is also why the source is
/// resolved through [`crate::personal_skills::read_personal_skills`] rather
/// than from a path the window sent: a name is all the frontend gets to choose,
/// and the reader decides which directory that name means.
#[tauri::command]
pub async fn personal_skill_promote(
    app: AppHandle,
    workspace_id: String,
    skill: String,
    target: PromoteTarget,
    replace: bool,
) -> Result<PromotedPersonalSkill, crate::project_skills::CopyError> {
    tauri::async_runtime::spawn_blocking(move || -> Result<PromotedPersonalSkill, crate::project_skills::CopyError> {
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        let mine = crate::personal_skills::read_personal_skills(
            &crate::personal_skills::home_dir(),
        );
        let entry = mine
            .skills
            .iter()
            .find(|candidate| candidate.name == skill)
            .ok_or_else(|| crate::project_skills::not_in_own_folders(&skill))?;
        let source = std::path::PathBuf::from(&entry.dir);
        // Before anything is written, to the repository or to the team.
        crate::project_skills::refuse_private_files(&skill, &source)?;

        if target == PromoteTarget::Repository {
            let copied =
                crate::project_skills::install_into_repo(&cwd, &skill, &source, replace)?;
            return Ok(PromotedPersonalSkill {
                skill,
                plugin: None,
                copied,
                committed: false,
                pushed: false,
                pull_request: None,
            });
        }

        // The team half is the paid, outward-facing one: the gate first, before
        // anything is read out of the library.
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let slug = current_team_repo(&app)
            .ok_or_else(no_team_message)?;
        let (allowed, reason) = promote_authorization(&app, &slug);
        if !allowed {
            return Err(reason
                .unwrap_or_else(|| {
                    format!("Plyloft cannot share into this team's library from {THIS_MACHINE}.")
                })
                .into());
        }
        let plugin = crate::team_skills::PLY_PLUGIN;
        // The whole move inside the post-pull mutation, as rung 2 learned: the
        // collision is decided against what teammates have published.
        let written = promote_into_library(&app, &slug, plugin, &skill, &source, replace)?;
        let (copied, committed, pushed, pull_request) = match written {
            LibraryWrite::Pushed(outcome, copied) => (copied, outcome.committed, outcome.pushed, None),
            LibraryWrite::PullRequest(pr) => (Default::default(), false, false, Some(pr)),
        };
        if committed && pushed {
            crate::skill_scripts::own_share_needs_no_ok(&app, &app.state::<crate::team::TeamStore>().clone_dir(&slug), plugin, &skill, &source);
        }
        Ok(PromotedPersonalSkill {
            skill,
            plugin: Some(plugin.to_string()),
            copied,
            committed,
            pushed,
            pull_request,
        })
    })
    .await
    .map_err(|error| format!("join personal skill promote: {error}"))?
}

/// What a Share with Team… of one of this Mac's skills would send, for its page
/// to name: the same folder [`personal_skill_promote`] resolves and reads.
#[tauri::command]
pub async fn personal_skill_share_preview(
    app: AppHandle,
    skill: String,
) -> Result<crate::project_skills::SharePreview, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let mine = crate::personal_skills::read_personal_skills(&crate::personal_skills::home_dir());
        let dir = mine.skills.iter().find(|candidate| candidate.name == skill).map(|entry| entry.dir.clone());
        Ok(crate::project_skills::share_preview(current_team_repo(&app), &skill, dir.as_deref().map(Path::new)))
    })
    .await
    .map_err(|error| format!("join personal skill share preview: {error}"))?
}

/// Group B decision §3: **New skill…** in Library › Skills. Writes
/// `.claude/skills/<name>/SKILL.md` and `.agents/skills/<name>/SKILL.md` in
/// this workspace's checkout, with the same text
/// ([`crate::project_skills::create_new_skill`]). Commits and publishes
/// nothing — "Publish to <branch>" stays the way out — so, like Install, no
/// gate: it writes only into the member's own repository.
#[tauri::command]
pub async fn project_skill_create(
    app: AppHandle,
    workspace_id: String,
    name: String,
    description: String,
) -> Result<crate::project_skills::CreatedSkill, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        // The integration branch's skills, from the mirror: a name it
        // already carries is refused too (GH #216 review 1, L6).
        let on_branch = app
            .path()
            .app_config_dir()
            .ok()
            .and_then(|config| {
                ply_memory::resolve_mirror(
                    &config
                        .join("projects")
                        .join(&workspace_id)
                        .join(ply_memory::SHARED_LIBRARY_MIRROR_DIR),
                )
            })
            .map(|build| crate::skill_reach::names_in(&build))
            .unwrap_or_default();
        crate::project_skills::create_new_skill(&cwd, &name, &description, &on_branch)
    })
    .await
    .map_err(|error| format!("join new skill: {error}"))?
}

// ── Skills hub H3a: linked copies and the skill card ────────────────
//
// `docs/plans/SKILLS_HUB.md` R2, §4.2. Install and Update make a skill card
// (`skill_card.rs`); the untracked Install is retired (§14 Q1). Reading the
// team library, installing out of it and Update are on every plan.

/// What an Install did.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase", tag = "kind")]
pub enum SkillInstalled {
    /// The skill card, at its Ship step.
    Card { card: KanbanCard },
    /// A workspace folder that is not a git repository has no card to carry
    /// it (R2 edge): the copies were written straight into the folder.
    Written { copied: crate::project_skills::CopyOutcome },
}

/// The team library's copy of one skill, read for a skill card.
struct TeamSkillSource {
    /// Skills hub H10: `team`, or `library` for My library (the link's
    /// `origin.kind`).
    kind: &'static str,
    slug: String,
    plugin: String,
    source: crate::skill_card::Source,
    /// The CLIs the team skill reaches: only those get a copy (R2 edge).
    reach: crate::skill_card::Reach,
    /// Skills hub H6b: the member OK'd this scripts id on the Install-time
    /// sheet; recorded as this Mac's OK once the card is made.
    confirmed: Option<String>,
    clone: PathBuf,
    /// Skills hub H9 (R9): the source is a skill that comes with Plyloft, at
    /// this Plyloft version — the bundle, not a library clone. Its card links
    /// the copy to Plyloft (`origin.kind = plyloft`), and no script waits for
    /// an OK (the bundle is the app's own, reviewed like code).
    plyloft: Option<String>,
}

impl TeamSkillSource {
    /// H6b: the sheet's OK is this Mac's OK for sessions too (same key).
    fn record_ok<R: tauri::Runtime>(&self, app: &tauri::AppHandle<R>, skill: &str) {
        let Some(id) = self.confirmed.as_deref() else {
            return;
        };
        let recorded = crate::skills_hub::config_dir(app).and_then(|config_dir| {
            crate::skill_scripts::repo::record(
                &config_dir,
                &self.clone,
                &self.plugin,
                skill,
                &self.source.path,
                &self.source.commit,
                id,
                chrono::Utc::now().timestamp_millis(),
            )
        });
        match recorded {
            Ok(()) => {
                let _ = app.emit("skills-hub://decision", ());
            }
            Err(error) => log::warn!("skills hub: couldn't record the OK for {skill} ({error})"),
        }
    }
}

/// The team clone, pulled first (advisory: an offline member installs from
/// the clone they have), and the source of `plugin:skill` in it. Skills hub
/// H6b (R15): refused, with `SCRIPTS_WAIT_MARKER`, while it would put a
/// script or an extra file into the repository — whose copies are `here` —
/// that the member hasn't OK'd on the Install-time sheet (`confirmed`, the
/// scripts ids the sheet's OK sent).
fn team_skill_source<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    plugin: &str,
    skill: &str,
    here: &[crate::skill_scripts::repo::CopyFiles],
    confirmed: Option<&[String]>,
    mine: bool,
) -> Result<TeamSkillSource, String> {
    let (kind, slug, clone) = if mine {
        // Skills hub H10: My library, pulled first as its own account
        // (advisory, like the team's), on a plan that pulls it.
        let (slug, clone) = my_library_for_card(app)?;
        ("library", slug, clone)
    } else {
        let slug = current_team_repo(app).ok_or_else(no_team_message)?;
        // N14 review (Q1): the team library's pull runs as the team's account.
        let _account = team_account_scope(app);
        let team = app.state::<crate::team::TeamStore>();
        if let Err(error) = team.sync(&slug) {
            log::warn!("skills: could not refresh the team clone before a skill card ({error})");
        }
        let clone = team.clone_dir(&slug);
        (crate::skill_links::KIND_TEAM, slug, clone)
    };
    let (entry, path) = team_source_path(&clone, plugin, skill)?;
    let commit = crate::library_snapshot::head_commit(&clone)?;
    let confirmed = match crate::skill_scripts::repo::repo_answer(&clone, &commit, &path, skill, here, confirmed)? {
        crate::skill_scripts::repo::RepoAnswer::Clear => None,
        crate::skill_scripts::repo::RepoAnswer::Confirmed { scripts_id } => Some(scripts_id),
        crate::skill_scripts::repo::RepoAnswer::Refused(why) => return Err(why),
    };
    let source = crate::skill_card::read_source(&clone, &commit, &path)?;
    let reach = crate::skill_card::Reach { claude: entry.claude, codex: entry.codex };
    Ok(TeamSkillSource { kind, slug, plugin: plugin.to_string(), source, reach, confirmed, clone, plyloft: None })
}

fn capitalised(words: &str) -> String {
    let mut out = words.to_string();
    if let Some(first) = out.get_mut(..1) {
        first.make_ascii_uppercase();
    }
    out
}

/// Skills hub H10: My library's repository and clone for a skill card,
/// pulled first (best effort: a failed pull installs from the copy this Mac
/// has).
fn my_library_for_card<R: tauri::Runtime>(app: &tauri::AppHandle<R>) -> Result<(String, PathBuf), String> {
    let mine = crate::my_library::setting(app)
        .ok_or_else(|| format!("My library isn't set up on {THIS_MACHINE}."))?;
    let clone = crate::my_library::delivered_clone(app)
        .ok_or_else(|| format!("My library isn't on {THIS_MACHINE} yet."))?;
    let _ = crate::my_library::pull(app);
    Ok((mine.repo, clone))
}

/// The library entry of `plugin:skill` in `clone` and the directory Install
/// copies from (`project_skills::install_source`), as git names it.
fn team_source_path(clone: &Path, plugin: &str, skill: &str) -> Result<(crate::team_skills::TeamSkill, String), String> {
    let library = crate::team_skills::read_library(clone);
    // Skills hub H10: My library's words for My library's clone.
    let place = crate::skill_scripts::place_words(clone);
    let entry = library
        .skills
        .iter()
        .find(|candidate| candidate.name == skill && candidate.plugin == plugin)
        .cloned()
        .ok_or_else(|| format!("`{plugin}:{skill}` is not in {place} any more — refresh."))?;
    let dir = crate::project_skills::install_source(clone, &entry)
        .ok_or_else(|| format!("{} lists `{plugin}:{skill}` but has no files for it.", capitalised(place)))?;
    let path = crate::skill_card::repo_path_of(clone, &dir)
        .ok_or_else(|| format!("{} lists `{plugin}:{skill}` but has no files for it.", capitalised(place)))?;
    Ok((entry, path))
}

/// Skills hub H6b: the copies of `skill` this repository's `rev` holds (its
/// Claude and Codex directories), for what the Install-time sheet asks.
/// A rev without the skill counts as one empty copy (every file is new there).
fn repo_copies(repo: &Path, rev: &str, prefix: &str, skill: &str) -> Vec<crate::skill_scripts::repo::CopyFiles> {
    crate::skill_scripts::repo::copies_at(repo, &[rev], &skill_copy_dirs(prefix, skill))
}

fn skill_copy_dirs(prefix: &str, skill: &str) -> Vec<String> {
    [crate::skill_links::CLAUDE_ROOT, crate::skill_links::CODEX_ROOT]
        .into_iter()
        .map(|root| format!("{prefix}{root}/{skill}"))
        .collect()
}

/// The copies an Update compares with: those at the commit its card would be
/// cut from (`worktrees::skill_base_as_known`, the card's own rule without
/// the fetch — a local target holding commits origin lacks, ahead or
/// diverged, where the ship lands; origin otherwise), else
/// `HEAD`, because the card is not cut from the checkout's `HEAD`
/// (Challenger, H6b); `make_skill_card` checks again at the very commit it
/// is cut from. None in a folder that is not a git repository.
pub(crate) fn checkout_copies(cwd: &Path, target: &str, skill: &str) -> Vec<crate::skill_scripts::repo::CopyFiles> {
    match crate::skill_card::workspace_prefix(cwd) {
        Ok(prefix) => {
            let base = crate::worktrees::skill_base_as_known(cwd, target);
            let revs: Vec<&str> = base.as_deref().into_iter().chain(["HEAD"]).collect();
            crate::skill_scripts::repo::copies_at(cwd, &revs, &skill_copy_dirs(&prefix, skill))
        }
        Err(_) => Vec::new(),
    }
}

/// The team clone a link's origin is read from on this Mac, when it is
/// this Mac's team.
fn team_origin_clone<R: tauri::Runtime>(app: &tauri::AppHandle<R>, origin: &crate::skill_links::LinkOrigin) -> Option<PathBuf> {
    // Skills hub H10 (R6 AC): a copy linked to My library reads it from this
    // Mac's clone when this Mac uses that repository; on a teammate's Mac (or
    // one that uses another) it is *not available on this Mac*.
    if origin.kind == crate::skill_links::KIND_LIBRARY {
        let mine = crate::my_library::setting(app)?;
        if !mine.repo.eq_ignore_ascii_case(&origin.source) {
            return None;
        }
        return crate::my_library::delivered_clone(app);
    }
    if origin.kind != crate::skill_links::KIND_TEAM {
        return None;
    }
    let slug = current_team_repo(app)?;
    if !slug.eq_ignore_ascii_case(&origin.source) {
        return None;
    }
    // Skills hub H4 (R2/R8 edge): a library switched off or left on this Mac
    // is "not available" — never read as removed.
    let delivers = crate::skills_hub::config_dir(app)
        .map(|config_dir| crate::skills_hub::delivers(&config_dir, &slug))
        .unwrap_or(true);
    if !delivers {
        return None;
    }
    let clone = app.state::<crate::team::TeamStore>().clone_dir(&slug);
    clone.join(".git").exists().then_some(clone)
}

/// Skills hub H4: the decisions about a linked copy (3-way Compare, Keep
/// mine, Propose mine upstream, removals and renames upstream).
#[path = "skills_hub_decisions.rs"]
pub(crate) mod skills_hub_decisions;
// Skills hub H5 (R12): the twins on the Library's rows, and Align by card.
#[path = "skills_hub_twins.rs"]
pub(crate) mod skills_hub_twins;
