/// v1.10.x Cycle A: reveal a card's worktree directory in Finder.
/// Path-injection guarded — refuses any path that's not under one of the
/// workspace's worktree roots (`.plyloft-worktrees/`, or the legacy
/// `.atelier-worktrees/`), `..` included (`worktrees::is_under_worktree_root`).
#[tauri::command(async)]
pub fn worktree_reveal(
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
    path: String,
) -> Result<(), String> {
    let ws_cwd = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .map(|w| PathBuf::from(w.cwd))
        .ok_or_else(|| format!("workspace '{workspace_id}' not found"))?;
    let target = Path::new(&path);
    if !crate::worktrees::is_under_worktree_root(&ws_cwd, target) {
        return Err("path is not under the workspace's worktrees folder".into());
    }
    if !target.exists() {
        return Err("worktree path does not exist on disk".into());
    }
    crate::platform::reveal_path(target).map_err(|e| format!("open -R failed: {e}"))?;
    Ok(())
}

/// UX-8.5: `Reveal in Finder` on the page Code shows for a file it cannot
/// open (binary, over 5 MB, not UTF-8). Only a file inside the workspace's
/// own directory is revealed (`files::reveal_target`).
#[tauri::command(async)]
pub fn fs_reveal_in_workspace(
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
    path: String,
) -> Result<(), String> {
    let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
    let target = files::reveal_target(&ws_cwd, Path::new(&path))?;
    crate::platform::reveal_path(&target).map_err(|e| format!("open -R failed: {e}"))?;
    Ok(())
}

