/// 1.173.0 A2 (Challenger 1): where a new copy would start, read without
/// fetching — the branch, whether origin is on GitHub, when it was last read.
#[tauri::command]
pub async fn copy_start_point(
    app: tauri::AppHandle,
    workspace_id: String,
    target: Option<String>,
    skip_changed: Option<bool>,
) -> Result<crate::copies::StartPoint, String> {
    // 1.174.0 E1 round 2: the "Same folder" popover skips the folder's
    // `git status` (`skipChanged`); the sheet, and an older caller, read it.
    let count_changed = !skip_changed.unwrap_or(false);
    tauri::async_runtime::spawn_blocking(move || {
        crate::copies::start_point_for_app(&app, &workspace_id, target.as_deref(), count_changed)
    })
    .await
    .map_err(|e| format!("copy start point worker failed: {e}"))?
}

/// 1.173.0 A2: the Undo of *Throw away*.
#[tauri::command]
pub async fn copy_restore(
    app: tauri::AppHandle,
    workspace_id: String,
    copy_id: String,
) -> Result<crate::copies::CopyEntry, String> {
    tauri::async_runtime::spawn_blocking(move || crate::copies::restore_for_app(&app, &workspace_id, &copy_id))
        .await
        .map_err(|e| format!("copy restore worker failed: {e}"))?
}

// ── 1.173.0 A3: Make it a card, Open a pull request (`copies.rs`) ─────

/// What *Make it a card* made.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CopyMadeCard {
    pub card: KanbanCard,
    /// The card is in Working on the copy. `false` on a GitHub Issues board
    /// (claim it first) or when the start was refused (`note` says why):
    /// the card waits in Not started, and Start build continues in the copy.
    pub started: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

/// 1.173.0 A3: *Make it a card*, under `CARD_START_LOCK` (the caller's). The
/// card is made in Not started; Start build takes it on. The copy's
/// work not yet committed is saved on its branch as "chore: work from the
/// copy <name>" (`copies::save_changes`, bounded); then the copy is recorded
/// as the new card's (it leaves the list) and the card is made in **Not
/// started** with the copy's folder, branch and base as its worktree, its
/// origin (`from_copy`), its port block and the area whose branch the copy
/// started from (none when no single area has it: the card asks).
///
/// 1.174.0 C4 (P17): the card is called after the copy's own last commit
/// (`copies::last_commit_subject`, read before the work is saved; the copy's
/// name when there is none), and its brief is empty: Start build waits for
/// it (`kanban::copy_brief_empty`). Where it came from is its `from_copy`,
/// which Activity shows.
///
/// Walk fix (b): no session works on it yet, so it is not in Working.
/// Start build is the cards' own advance (`kanban_card_advance_to_in_progress`),
/// whose reuse path (`worktrees::reuse_card_worktree`) keeps the folder and
/// the branch as they are: the open terminals carry on, and the card's
/// Builder starts on the work, then the Challenger and Verify check it.
/// The branch keeps its name (`worktrees::is_card_owned_branch`).
#[allow(clippy::too_many_arguments)]
pub(crate) fn make_card_from_copy<R: tauri::Runtime>(
    app: Option<&tauri::AppHandle<R>>,
    store: &KanbanStore,
    workspaces: &WorkspaceStore,
    project_config: &ProjectConfigStore,
    license: &crate::license::LicenseStore,
    settings: &crate::settings::Settings,
    workspace_id: &str,
    copy_id: &str,
    title: Option<&str>,
    setup_running: bool,
) -> Result<CopyMade, String> {
    let ws_cwd = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .map(|w| PathBuf::from(w.cwd))
        .ok_or_else(|| format!("workspace '{workspace_id}' not found"))?;
    let dir = project_config.workspace_dir(workspace_id);
    let place = crate::copies::Place { registry_dir: &dir, workspace_cwd: &ws_cwd };
    // Challenger 6: never while it is being sent to GitHub.
    crate::copies::refuse_while_sending(workspace_id, copy_id)?;
    // Challenger 4: a copy whose card isn't on the board is a copy again
    // (the caller holds CARD_START_LOCK, so no card is half made now).
    crate::copies::release_stranded_on(&dir, store.load_whole(workspace_id))?;
    let copy = crate::copies::ready_to_hand_on(place, copy_id, setup_running)?;
    // Re-walk (orchestrator, 2026-10-30): the card waits in Not started, and
    // Start build takes it on, as for every card
    // (`advance_card_to_in_progress_staged`).
    let _ = app;
    team_gate_github_card_write(workspaces, license, workspace_id, true)?;
    // Walk fix (c): the work is saved in a commit that says where it came
    // from — before anything else reads the card's copy (the review's read
    // would otherwise save it as a "review checkpoint").
    // C4: the copy's own last commit names the card — read first, so the
    // commit below is never it.
    let subject = crate::copies::last_commit_subject(Path::new(&copy.path), &copy.base_commit);
    crate::copies::save_changes(Path::new(&copy.path), &crate::copies::work_from_copy_message(&copy.name))?;
    let card_id = uuid::Uuid::new_v4().to_string();
    let title = title
        .map(str::trim)
        .filter(|t| !t.is_empty())
        .map(str::to_string)
        .or(subject)
        .unwrap_or_else(|| copy.name.clone());
    // The copy is the card's first, so it can't be thrown away under it.
    crate::copies::give_to_card(place, copy_id, &card_id)?;
    let mut card = KanbanCard::new(
        card_id.clone(),
        workspace_id.to_string(),
        title,
        None,
        KanbanColumnId::Todo,
    );
    stamp_new_card(&mut card, settings);
    card.worktree_path = Some(copy.path.clone());
    card.branch_name = Some(copy.branch.clone());
    card.from_copy = Some(crate::kanban::CardFromCopy { id: copy.id.clone(), name: copy.name.clone() });
    // B3 (Windows walk): the area of the copy's changed files when they all
    // fall in one whose branch is the copy's start; else the area whose
    // branch the copy started from; none when neither is single (the card
    // then asks "Which area is this?").
    let paths = crate::card_area::changed_paths(Path::new(&copy.path), &copy.base_commit).unwrap_or_default();
    card.area = area_for_copy(project_config, workspace_id, &copy.base_branch, &paths);
    // Challenger 2: the copy's port block goes with it (its dev server keeps
    // its ports); `ensure_port_base` keeps a block nobody else holds.
    card.port_base = copy.port_base.filter(|b| crate::worktree_ports::is_block_base(*b));
    let source = copy.base_source.unwrap_or(crate::worktrees::BaseSource::Origin);
    let (origin_slug, origin_url) = crate::review_base::origin_record_of(&ws_cwd);
    card.worktree_base = (!copy.base_commit.is_empty()).then(|| crate::worktrees::WorktreeBase {
        commit: copy.base_commit.clone(),
        ref_name: match source {
            crate::worktrees::BaseSource::Origin => format!("origin/{}", copy.base_branch),
            _ => copy.base_branch.clone(),
        },
        source,
        note: copy.base_note.clone(),
        origin_slug,
        origin_url,
        merged_target: None,
    });
    let created = match store.create_card(workspace_id, card) {
        Ok(card) => card,
        Err(e) => {
            // Nothing holds the copy: it goes back to the list.
            let _ = crate::copies::update(&dir, |file| {
                if let Some(c) = file.copies.iter_mut().find(|c| c.id == copy_id) {
                    c.card_id = None;
                }
                Ok(((), true))
            });
            return Err(e);
        }
    };
    // Challenger 8: on a GitHub Issues board the issue is made by the caller
    // once CARD_START_LOCK is released (`CopyMade::mirror_to`).
    if let Some(repo) = workspace_github_target(workspaces, workspace_id) {
        let note = Some("Claim it and say what the Builder should do, then Start build.".to_string());
        return Ok(CopyMade { made: CopyMadeCard { card: created, started: false, note }, pending: None, mirror_to: Some(repo) });
    }
    // Its port block (the copy's, kept when nobody else holds it).
    let card = match store.ensure_port_base(workspace_id, &card_id, None) {
        Ok(_) => store.get_card(workspace_id, &card_id).unwrap_or(created),
        Err(e) => {
            log::warn!("worktree ports {workspace_id}/{card_id}: {e}");
            created
        }
    };
    Ok(CopyMade { made: CopyMadeCard { card, started: false, note: None }, pending: None, mirror_to: None })
}

/// B3: the one area of the workspace whose branch is `branch`; `None` with
/// no areas, none or several (the card asks).
pub(crate) fn area_for_branch(store: &ProjectConfigStore, workspace_id: &str, branch: &str) -> Option<String> {
    area_for_copy(store, workspace_id, branch, &[])
}

/// B3 (Windows walk): a card made from a copy takes the area every one of
/// `paths` (the copy's changed files) falls in — `areas::area_of_path` —
/// when that area's branch is the copy's start `branch`, and none (the card
/// asks) when it is another branch. With no files, or files spread over
/// areas: the one area on `branch`; otherwise none.
pub(crate) fn area_for_copy(store: &ProjectConfigStore, workspace_id: &str, branch: &str, paths: &[String]) -> Option<String> {
    let config = store.get(workspace_id)?;
    let areas = crate::areas::for_workspace(store, workspace_id);
    let branch_of = |id: &str| match crate::areas::resolve_config(&config, &areas, Some(id)) {
        crate::areas::AreaConfig::Area { area, .. } => Some(area.branch),
        _ => None,
    };
    let of_files: std::collections::BTreeSet<Option<String>> =
        paths.iter().map(|p| crate::areas::area_of_path(&areas, p)).collect();
    if let [Some(id)] = of_files.iter().collect::<Vec<_>>().as_slice() {
        // The files point at one area: that one, or — on another branch — the
        // card asks; never the other area.
        return (branch_of(id).as_deref() == Some(branch.trim())).then(|| id.clone());
    }
    let matching: Vec<String> = areas
        .iter()
        .filter(|def| branch_of(def.id.trim()).as_deref() == Some(branch.trim()))
        .map(|def| def.id.trim().to_string())
        .collect();
    match matching.as_slice() {
        [only] => Some(only.clone()),
        _ => None,
    }
}

/// What [`make_card_from_copy`] leaves for its caller to finish with
/// `CARD_START_LOCK` released: a setup to run, an issue to make.
pub(crate) struct CopyMade {
    pub made: CopyMadeCard,
    pub pending: Option<PendingSetup>,
    /// The GitHub Issues board to mirror the new card to (`gh_sync_card_create`).
    pub mirror_to: Option<String>,
}

/// 1.173.0 A3: *Make it a card* — see [`make_card_from_copy`].
#[tauri::command]
pub async fn copy_make_card(
    app: tauri::AppHandle,
    workspace_id: String,
    copy_id: String,
    title: Option<String>,
) -> Result<CopyMadeCard, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let CopyMade { made, pending, mirror_to } = {
            let _start = CARD_START_LOCK.lock().unwrap_or_else(|p| p.into_inner());
            make_card_from_copy(
                Some(&app),
                &app.state::<KanbanStore>(),
                &app.state::<WorkspaceStore>(),
                &app.state::<ProjectConfigStore>(),
                &app.state::<crate::license::LicenseStore>(),
                &app.state::<SettingsStore>().snapshot(),
                &workspace_id,
                &copy_id,
                title.as_deref(),
                crate::worktree_setup::is_in_flight(&workspace_id, &copy_id),
            )?
        };
        crate::copies::emit_changed(&app, &workspace_id);
        // Challenger 8: the issue, with the lock released.
        let made = match mirror_to {
            None => made,
            Some(repo) => {
                let store = app.state::<KanbanStore>();
                let workspaces = app.state::<WorkspaceStore>();
                let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
                gh_sync_card_create(&store, &repo, &workspace_id, &made.card);
                gh_push_area_label_soon(&app, &workspace_id, &made.card.id);
                let card = store.get_card(&workspace_id, &made.card.id).unwrap_or_else(|_| made.card.clone());
                CopyMadeCard { card, ..made }
            }
        };
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        // The copy's folder was there: no setup is staged; one that is runs
        // as a card start's does, with the lock released.
        let made = match pending {
            None => made,
            Some(pending) => {
                let card = finish_card_setup(
                    Some(&app),
                    &app.state::<KanbanStore>(),
                    &app.state::<ProjectConfigStore>(),
                    pending,
                    true,
                )?;
                CopyMadeCard { card, ..made }
            }
        };
        Ok(made)
    })
    .await
    .map_err(|e| format!("make card worker failed: {e}"))?
}

/// 1.173.0 A3 (walk fix a): what a card made from a copy holds that its base
/// doesn't — the copy's own changes, committed or not (`copies::changed_files`
/// on the card's copy since its recorded base). `None` for a card that wasn't
/// made from a copy or has no copy here.
#[tauri::command]
pub async fn card_copy_changes(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<Option<crate::copies::ChangedFiles>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let card = app.state::<KanbanStore>().get_card(&workspace_id, &card_id)?;
        Ok(card_copy_changes_of(&card))
    })
    .await
    .map_err(|e| format!("card copy changes worker failed: {e}"))?
}

pub(crate) fn card_copy_changes_of(card: &KanbanCard) -> Option<crate::copies::ChangedFiles> {
    card.from_copy.as_ref()?;
    let path = PathBuf::from(card.worktree_path.as_deref()?);
    if !path.is_dir() {
        return None;
    }
    let base = card.worktree_base.as_ref().map(|b| b.commit.as_str()).unwrap_or("");
    Some(crate::copies::changed_files(&path, base))
}

/// 1.173.0 A3: *Open a pull request* for a copy, on the person's press
/// (AGENTS.md › Product boundaries, "Copies, areas and claims"): Ship's own
/// checks first — origin on GitHub (`pr_origin`), gh and the sign-in
/// (`pr_github_preflight`) — then `copies::open_pr_with`: the copy's changes
/// committed, its branch pushed by an explicit refspec to the same name,
/// never forced, and Ship's `gh pr create --base <the copy's base>` with
/// Ship's body rule, as the workspace's GitHub account.
#[tauri::command]
pub async fn copy_open_pr(
    app: tauri::AppHandle,
    workspace_id: String,
    copy_id: String,
    title: String,
) -> Result<crate::copies::CopyEntry, String> {
    tauri::async_runtime::spawn_blocking(move || {
        // A second press waits for the first; Make it a card and Throw away
        // wait too (`copies::refuse_while_sending`, Challenger 6).
        let Some(sending) = crate::copies::begin_sending(&workspace_id, &copy_id) else {
            return Err(crate::copies::SENDING_REFUSAL.to_string());
        };
        let out = copy_open_pr_blocking(&app, &workspace_id, &copy_id, &title);
        drop(sending);
        crate::copies::emit_changed(&app, &workspace_id);
        out
    })
    .await
    .map_err(|e| format!("open pull request worker failed: {e}"))?
}

/// 1.173.0 A3 (Challenger 7): read the copies' open pull requests now — the
/// Copies view asks as it opens, on a worker.
#[tauri::command]
pub async fn copy_refresh_prs(app: tauri::AppHandle, workspace_id: String) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || crate::copies::refresh_prs_now(&app, &workspace_id))
        .await
        .map_err(|e| format!("copy pull request worker failed: {e}"))?
}

fn copy_open_pr_blocking(
    app: &tauri::AppHandle,
    workspace_id: &str,
    copy_id: &str,
    title: &str,
) -> Result<crate::copies::CopyEntry, String> {
    let workspaces = app.state::<WorkspaceStore>();
    let configs = app.state::<ProjectConfigStore>();
    let ws_cwd = resolve_ws_cwd(&workspaces, workspace_id)?;
    let dir = configs.workspace_dir(workspace_id);
    let place = crate::copies::Place { registry_dir: &dir, workspace_cwd: &ws_cwd };
    if let Some(_start) = crate::copies::try_card_start_lock() {
        crate::copies::release_stranded_for_app(app, workspace_id, &dir);
    }
    let setup_running = crate::worktree_setup::is_in_flight(workspace_id, copy_id);
    let entry = crate::copies::ready_to_hand_on(place, copy_id, setup_running)?;
    let wt = PathBuf::from(&entry.path);
    let origin = pr_origin(&wt);
    if !origin.offers_pr() {
        let words = origin_refused_words(&origin)
            .unwrap_or_else(|| "Pull requests need a project on GitHub; this project isn't on GitHub.".to_string());
        return Err(format!("{words} Nothing was sent."));
    }
    pr_github_preflight(&workspaces, workspace_id, &wt, "pr")?;
    let gh = crate::doctor::require("gh")?;
    let origin_repo = match origin {
        PrOrigin::GitHub { repo } => repo,
        _ => None,
    };
    let _github = crate::github_account::enter_for_workspace(&workspaces, workspace_id);
    crate::copies::open_pr_with(
        place,
        copy_id,
        title,
        &gh,
        origin_repo.as_deref(),
        setup_running,
        crate::kanban::now_ms(),
    )
}

// ── v1.31.0 (Cycle 1 — Review surface) ────────────────────────────────

/// Resolve a workspace's cwd, or a friendly error.
pub(crate) fn resolve_ws_cwd(
    workspaces: &State<'_, WorkspaceStore>,
    workspace_id: &str,
) -> Result<PathBuf, String> {
    workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .map(|w| PathBuf::from(w.cwd))
        .ok_or_else(|| format!("workspace '{workspace_id}' not found"))
}

fn target_dirty_state_from_paths(dirty: crate::pinned_read::DirtyPaths) -> TargetDirtyState {
    TargetDirtyState {
        total_count: dirty.total_count,
        paths: dirty.paths,
        truncated: dirty.truncated,
    }
}

#[cfg(test)]
fn capture_target_dirty_state_with_git(
    git: &str,
    target: &Path,
) -> Result<TargetDirtyState, String> {
    crate::pinned_read::tracked_dirty_paths_with_git(git, target)
        .map(target_dirty_state_from_paths)
}

/// The target checkout's uncommitted changes to **tracked** files — what
/// Land's rollback (`git reset --hard HEAD`) would destroy. Untracked files
/// are not counted (GH #190): the reset never touches them, a merge that
/// would overwrite one is refused by git before it writes anything, and the
/// ones the land's fast-forward would overwrite are GH #88's to classify —
/// counting them here hid #151's refusal behind this one.
fn capture_target_dirty_state(target: &Path) -> Result<TargetDirtyState, String> {
    crate::pinned_read::tracked_dirty_paths(target).map(target_dirty_state_from_paths)
}

fn require_clean_target_state(state: TargetDirtyState) -> Result<(), String> {
    if state.total_count == 0 {
        Ok(())
    } else {
        Err(crate::review::encode_target_dirty_error(&state))
    }
}

/// R6: also Ship's (`ship::ship_card` / `ship_batch`), before anything is
/// merged — its rollback is the same `git reset --hard`.
pub(crate) fn require_clean_target(target: &Path) -> Result<(), String> {
    require_clean_target_state(capture_target_dirty_state(target)?)
}

/// The branch a workspace's card worktrees fork from: the project_config
/// `target_branch`, or `main` when the workspace has no config.
fn resolve_base_branch(
    project_config: &State<'_, ProjectConfigStore>,
    workspace_id: &str,
) -> String {
    project_config
        .get(workspace_id)
        .map(|c| c.target_branch)
        .unwrap_or_else(|| "main".to_string())
}

/// Subject of the commit that flushes a swarm's uncommitted edits onto its
/// card branch (review diff, local land, a Ship of verified edits).
const REVIEW_CHECKPOINT_MSG: &str = crate::commit_message::REVIEW_CHECKPOINT;

/// Subject of the commit Ship makes from uncommitted edits Verify has not
/// passed on, on a card with no Builder (an interrupted or crashed run).
/// Nothing is published until Verify passes on exactly that commit.
/// R8: read back in either form (`commit_message::is_ship_recovery`).
const SHIP_RECOVERY_COMMIT_MSG: &str = crate::commit_message::SHIP_RECOVERY;

/// v1.31.0 (Cycle 1): the git diff a card's worktree branch introduced
/// since it forked from the target branch, parsed into per-file hunks.
/// Commits the swarm's uncommitted edits + new files onto the branch first
/// so the diff is complete and stable while the user reviews. An empty
/// `files` vec is the legitimate "swarm changed nothing" state. A Builder
/// card is never flushed: its diff is the committed branch, which is what
/// Ship would publish once it is a build snapshot.
///
/// CL-6 round 2: async, the git work on a blocking worker — with the
/// findings' anchors it is up to a few dozen git calls, never on the main
/// thread.
#[tauri::command]
pub async fn card_review_diff(
    app: AppHandle,
    kanban: State<'_, KanbanStore>,
    project_config: State<'_, ProjectConfigStore>,
    reviewers: State<'_, crate::reviewer::ReviewerRegistry>,
    workspace_id: String,
    card_id: String,
) -> Result<ReviewDiff, String> {
    let card = kanban.get_card(&workspace_id, &card_id)?;
    let worktree = card.worktree_path.clone().ok_or_else(|| {
        "This card has no copy of the repository yet. Move it to In Progress and run a swarm first."
            .to_string()
    })?;
    let branch = card
        .branch_name
        .clone()
        .ok_or_else(|| "This card has its own copy but no branch on record.".to_string())?;
    let worktree_path = PathBuf::from(&worktree);
    if !worktree_path.exists() {
        return Err(format!(
            "The card's copy of the repository is gone ({worktree}), so its \
             changes can't be read."
        ));
    }
    // 1.173.0 (B3): measured from the card's area's branch.
    let base = crate::pr_review::review_target(&card, &crate::card_area::reading_branch(&project_config, &workspace_id, &card));
    let ledger = reviewers.ledger(&workspace_id, &card_id);
    tauri::async_runtime::spawn_blocking(move || {
        // The base is checked against origin as the workspace's GitHub account.
        let _github = crate::github_account::enter_for_app(&app, &workspace_id);
        review_diff_blocking(card, card_id, worktree_path, branch, base, ledger)
    })
    .await
    .map_err(|e| format!("the diff worker failed: {e}"))?
}

/// `card_review_diff`'s git work, off the main thread.
fn review_diff_blocking(
    card: crate::kanban::KanbanCard,
    card_id: String,
    worktree_path: PathBuf,
    branch: String,
    base: String,
    ledger: Option<crate::review_ledger::CardLedger>,
) -> Result<ReviewDiff, String> {
    if card.builder.is_none() {
        crate::worktrees::commit_pending_in_worktree(&worktree_path, REVIEW_CHECKPOINT_MSG)?;
    }
    // GH #191: diffed from the card's own base, so a stale local target
    // can't pad the review with upstream files; checked against origin's
    // real tip like the Challenger's range, so moved refs can't empty it.
    let fork = crate::review_base::verified(
        &worktree_path,
        &branch,
        card.worktree_base.as_ref(),
        &base,
    )
    .map(|b| b.commit)
    .unwrap_or_else(|| base.clone());
    let files = crate::git::diff_hunks(&worktree_path, &fork, &branch)?;
    // CL-6: the Challenger's findings on the lines they name, mapped from
    // the revision each review read to the branch the diff shows.
    let anchors = crate::review_anchors::anchors(&worktree_path, &branch, ledger.as_ref());
    Ok(ReviewDiff {
        card_id,
        base_branch: base,
        card_branch: branch,
        files,
        generated_at: now_millis_i64(),
        anchors,
    })
}

/// The branch the workspace checkout is on (`HEAD` detached reads `HEAD`).
fn land_checkout_branch(ws_cwd: &Path) -> Result<String, crate::worktrees::ShipError> {
    let output = crate::platform::git_command()
        .args(["rev-parse", "--abbrev-ref", "HEAD"])
        .current_dir(ws_cwd)
        .output()
        .map_err(|e| format!("Nothing was merged: couldn't read the checkout's branch ({e})."))?;
    if !output.status.success() {
        return Err(format!(
            "Nothing was merged: couldn't read the checkout's branch ({}).",
            String::from_utf8_lossy(&output.stderr).trim()
        )
        .into());
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

/// Land's fast-forward before the merge (`land_card_local`), taken out so the
/// fixture repos can drive it (GH #151). A shared-settings publish moves
/// origin's branch, never this one: land on origin's tip when the (clean)
/// checkout can simply be fast-forwarded, so the land doesn't fork the branch.
/// Anything else lands as before. Call holding the integration lock, then
/// the fast-forward lock (`held`, GH #203), which Land keeps to its commit.
/// GH #183: `Ok(true)` only when the checkout is now at origin's tip.
pub(crate) fn land_sync_gate(
    held: &crate::worktrees::FastForwardHeld,
    ws_cwd: &Path,
    target_branch: &str,
) -> Result<bool, crate::worktrees::ShipError> {
    use crate::worktrees::LocalBranchSync as Sync;
    // Skills hub H3a walk: Land squash-merges into the checkout's own branch,
    // so a checkout on another branch than the target took the card (and
    // everything between the two branches) onto that branch. Ship has
    // refused this from the start (`ship::ship_card`'s branch check).
    let on = land_checkout_branch(ws_cwd)?;
    if on != target_branch {
        return Err(format!(
            "Nothing was merged: your project folder is on `{on}` and this card lands on `{target_branch}`. Switch your project folder to `{target_branch}` first, then try again."
        )
        .into());
    }
    match crate::worktrees::fast_forward_local_locked(held, ws_cwd, target_branch) {
        // GH #151: GH #88's untracked-files refusal is a value, not a sentence:
        // the card's Ship step draws Sync's block from it, with its two ways
        // out. Nothing has been merged.
        outcome @ Sync::UntrackedDiffers { .. } => {
            Err(crate::worktrees::ShipError::local_branch_refused(
                crate::worktrees::RefusedOperation::Land,
                target_branch,
                outcome,
            ))
        }
        // Unsafe to go on: the checkout changed while this waited, or the
        // sync itself broke off. Nothing has been merged.
        // P-D2 (Challenger): the outcome in words, not its Debug form.
        Sync::Dirty { behind } => Err(format!(
            "Nothing was merged: Plyloft couldn't bring {target_branch} up to date with the online copy first. The online copy has {behind} commit(s) your project folder doesn't, and your project folder has changes that aren't in a commit. Commit or undo them, then try again."
        )
        .into()),
        Sync::Failed { reason } => Err(format!(
            "Nothing was merged: Plyloft couldn't bring {target_branch} up to date with the online copy first: {reason}. Try again."
        )
        .into()),
        outcome => {
            log::info!("land_card_local: {target_branch} before the merge: {outcome:?}");
            Ok(outcome.fast_forwarded())
        }
    }
}

/// Skills hub H6b (Windows walk): the base a skill card's own change is
/// taken from when it lands — its worktree's base — so the land applies
/// that change alone. `None` for any other card (it squash-merges as ever).
pub(crate) fn own_skill_base(card: &KanbanCard) -> Option<&str> {
    card.skill_card()?;
    card.worktree_base.as_ref().map(|base| base.commit.as_str())
}

/// 1.169.1 (R2): the commits a pull request from `card` would carry that
/// aren't the card's own and aren't on GitHub's `target` — those `origin/
/// <target>` lacks of: the card's start (`worktree_base.commit`: a local
/// target ahead of origin, an offline start, a skill card cut from a
/// diverged one); the target commit Plyloft merged into it to resolve a
/// conflict (`merged_target`), while the card's branch still holds it (an
/// *Undo the merge* leaves the record behind); and what the card's branch
/// shares with the local target (`git merge-base --all <tip> <target>`), so
/// a local target merged into the card's copy any other way counts too. The
/// card's own commits come after all of those, so they are never counted.
/// `None` when there are none, the card has no recorded start, or GitHub
/// has no `target` branch (the pull request is refused there anyway).
pub(crate) fn pr_carries_local_commits(ws_cwd: &Path, card: &KanbanCard, target: &str) -> Option<crate::review::LocalCommits> {
    let start = card.worktree_base.as_ref()?;
    let remote = crate::worktrees::resolve_commit(ws_cwd, &format!("refs/remotes/origin/{target}"))?;
    let tip = card
        .branch_name
        .as_deref()
        .and_then(|branch| crate::worktrees::resolve_commit(ws_cwd, &format!("refs/heads/{branch}")));
    let mut range: Vec<String> = vec![start.commit.clone()];
    if let (Some(merged), Some(tip)) = (start.merged_target.as_deref(), tip.as_deref()) {
        if crate::worktrees::is_ancestor(ws_cwd, merged, tip) {
            range.push(merged.to_string());
        }
    }
    if let (Some(tip), Some(local)) = (tip.as_deref(), crate::worktrees::resolve_commit(ws_cwd, &format!("refs/heads/{target}"))) {
        if let Ok(bases) = crate::git::capture(ws_cwd, &["merge-base", "--all", tip, &local]) {
            range.extend(bases.lines().map(str::trim).filter(|b| !b.is_empty()).map(str::to_string));
        }
    }
    range.push(format!("^{remote}"));
    let range: Vec<&str> = range.iter().map(String::as_str).collect();
    let count: u32 = crate::git::capture(ws_cwd, &[&["rev-list", "--count"][..], &range].concat())
        .ok()?
        .trim()
        .parse()
        .ok()?;
    if count == 0 {
        return None;
    }
    let max = format!("--max-count={LOCAL_COMMITS_LISTED}");
    let subjects = crate::git::capture(ws_cwd, &[&["log", "--format=%s", &max][..], &range].concat())
        .ok()?
        .lines()
        .map(|line| line.trim().to_string())
        .collect();
    Some(crate::review::LocalCommits { target: target.to_string(), count, subjects })
}

/// R2: at most this many subjects are listed; `count` says how many there are.
const LOCAL_COMMITS_LISTED: usize = 20;

/// Challenger (H6b Windows walk): why a skill card can't ship as a pull
/// request, if it can't — it starts from a local target holding commits
/// GitHub's lacks (`resolve_skill_base`, where a local ship lands), and a
/// pull request from its branch would carry those commits too, unasked.
/// `None` for any other card, a base GitHub's branch already holds, or a
/// target GitHub has no branch of (the pull request is refused there anyway).
/// R2: the commits are found as every card's are ([`pr_carries_local_commits`]).
pub(crate) fn skill_pr_carries_local_commits(ws_cwd: &Path, card: &KanbanCard, target: &str) -> Option<String> {
    card.skill_card()?;
    let lacks = pr_carries_local_commits(ws_cwd, card, target)?.count;
    let commits = if lacks == 1 { "1 commit".to_string() } else { format!("{lacks} commits") };
    Some(format!(
        "This skill card starts from your local {target}, which has {commits} GitHub's {target} doesn't. \
         A pull request from it would carry them too, so nothing was shipped. Publish {target}, then ship again."
    ))
}

/// R2: Ship as a PR on a card that isn't a skill card stops before anything
/// is pushed when the pull request would carry commits not on GitHub yet
/// ([`pr_carries_local_commits`]), and says which — unless the person chose
/// *Include them and ship as a PR* (`carry_local_commits`). A skill card keeps its own
/// refusal; a repository without a GitHub `origin` (R10) lands locally or is
/// refused, and pushes nothing.
fn pr_carry_stop(
    workspaces: &State<'_, WorkspaceStore>,
    project_config: &State<'_, ProjectConfigStore>,
    workspace_id: &str,
    card: &KanbanCard,
    wt: &Path,
    mode: &str,
    carry_local_commits: bool,
) -> Result<Option<ShipOutcome>, String> {
    if mode != "pr" || carry_local_commits || card.skill_card().is_some() || !origin_offers_pr(wt) {
        return Ok(None);
    }
    let ws_cwd = resolve_ws_cwd(workspaces, workspace_id)?;
    // 1.173.0 (B3): the card's area's branch.
    let target = crate::card_area::branch_for_card(project_config, workspace_id, card)?;
    // Ship as a PR goes online anyway: read GitHub's target as it is now
    // (bounded; offline, the last fetched copy stands), as the workspace's
    // GitHub account.
    {
        let _github = crate::github_account::enter_for_workspace(workspaces, workspace_id);
        if let Err(e) = crate::worktrees::fetch_origin_branch(&ws_cwd, &target) {
            log::info!("ship: {}: origin/{target} not refreshed before the carry check: {e}", card.id);
        }
    }
    Ok(pr_carries_local_commits(&ws_cwd, card, &target).map(|local| ShipOutcome {
        kind: "carries_local_commits".into(),
        local_commits: Some(local),
        ..Default::default()
    }))
}

/// v1.31.0 (Cycle 1): land a card locally — squash-merge its worktree
/// branch into the workspace's target branch. On a real git conflict the
/// merge is rolled back (the worktree is untouched) and the card is marked
/// `ConflictBlocked` — it never half-merges. Shared by `card_review_merge`
/// and the local path of `card_ship`.
///
/// v1.34.x: on a successful merge, also stamps the card with
/// `ship_status = Shipped` + `commit_sha` + `shipped_version` + one fresh
/// `ShipEntry`, clears the worktree handle, and best-effort prunes the
/// worktree directory to its root's `.trash/`. Without that
/// writeback the Outcome-screen Ship-it path left cards as
/// `Unshipped` forever, which over-counted the toolbar Ship-batch badge
/// and kept the `cardLifecyclePill` stuck on `✓ verified` for already-
/// landed work. Mirrors the same kanban update legacy `ship::ship_card`
/// performs.
pub(crate) fn land_card_local<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    workspaces: &State<'_, WorkspaceStore>,
    kanban: &State<'_, KanbanStore>,
    project_config: &State<'_, ProjectConfigStore>,
    workspace_id: &str,
    card_id: &str,
    // The commit Ship's gate already verified (`card_ship`); None for the
    // developer-panel Merge, which runs its own checks here.
    verified_rev: Option<&str>,
) -> Result<ReviewMergeResult, crate::worktrees::ShipError> {
    let card = kanban.get_card(workspace_id, card_id)?;
    // SL-6: two builds and no pick yet — nothing to land.
    if crate::build_both::is_undecided(&card) {
        return Err(crate::build_both::UNDECIDED_REFUSAL.to_string().into());
    }
    let branch = card
        .branch_name
        .clone()
        .ok_or_else(|| "this card has no branch to merge".to_string())?;
    let worktree = card
        .worktree_path
        .clone()
        .ok_or_else(|| "This card has no copy of the repository.".to_string())?;
    let ws_cwd = resolve_ws_cwd(workspaces, workspace_id)?;

    // The main checkout's tracked files must be clean: rolling back a failed
    // squash-merge needs `git reset --hard`, which would otherwise destroy the
    // user's own uncommitted work in the workspace checkout. Untracked files
    // are not in its reach, and GH #88's refusal of the ones in the
    // fast-forward's way must be reached (GH #190), so they don't count here.
    require_clean_target(&ws_cwd)?;

    let worktree_path = PathBuf::from(&worktree);
    // What gets merged is one immutable commit, fixed here. After this
    // point nothing is committed into the worktree, so an edit arriving
    // later cannot ride along with the merge.
    let publish = match verified_rev {
        Some(rev) => rev.to_string(),
        None if card.builder.is_some() => {
            // A Builder card lands only as its verified build snapshot.
            let in_flight = app
                .state::<VerifyRegistry>()
                .is_inflight(workspace_id, card_id);
            crate::builder::require_verified_snapshot(&card, &worktree_path, in_flight)?;
            crate::builder::publish_rev(&card, &branch)
        }
        None => {
            crate::worktrees::commit_pending_in_worktree(&worktree_path, REVIEW_CHECKPOINT_MSG)?;
            crate::worktrees::head_sha(&worktree_path)?
        }
    };
    // 1.173.0 (B3): the card lands on its area's branch (refused on Held,
    // an unlisted area or none chosen).
    let target_branch = crate::card_area::branch_for_card(project_config, workspace_id, &card)?;
    // GH #80: serialized with shared-config publishes onto the same branch.
    let integration = crate::shared_config::integration_lock(&ws_cwd, &target_branch);
    let _integration = integration.lock().unwrap_or_else(|p| p.into_inner());
    // GH #222 review 4: again under the integration lock, which a Ship holds
    // from its record check through its pushes — a release recorded while
    // this Land waited for the lock still holds it back.
    refuse_land_while_recorded(app, workspace_id)?;
    // GH #203 review 1: Ply's own fast-forwards (a reconcile, a Trash) wait
    // from here to the commit or the rollback, so none of them meets this
    // merge's index or reads its staged squash as "dirty".
    let fast_forward = crate::worktrees::hold_fast_forward(&ws_cwd);
    // Land on origin's tip when the checkout can simply be fast-forwarded
    // (`land_sync_gate`); GH #88's refusal stops it as a value (GH #151).
    // OB-7b: the fetch runs as the workspace's GitHub account.
    let github = crate::github_account::enter_for_app(app, workspace_id);
    let fast_forwarded = land_sync_gate(&fast_forward, &ws_cwd, &target_branch)?;
    drop(github);
    // G5 (Challenger 2): this computer has GitHub's target now.
    crate::after_merge::up_to_date_now(app, workspace_id, fast_forwarded);
    // The wait for the lock and the fetch took time: the rollback below runs
    // `git reset --hard`, so the checkout must still be clean right now.
    require_clean_target(&ws_cwd)?;
    // H6b (Windows walk): a skill card lands its own change only, never
    // the commits between its base and this target (`own_skill_base`).
    match crate::worktrees::squash_merge_into_workspace(&ws_cwd, &publish, own_skill_base(&card)) {
        Ok(()) => {
            // R8: bounded, and its own words when a hook refuses it; the
            // squash is never left staged. Challenger M3: put back with
            // `reset --merge`, which keeps a file edited while the hook ran
            // (the folder was clean before the squash, so only the squash is
            // undone); when git refuses that, the folder is left as it is
            // and said so — never `reset --hard` over someone's edit.
            let subject = crate::commit_message::land_subject(&card.title, &card.id);
            if let Err(failure) = crate::git::commit(&ws_cwd, &["-m", &subject]) {
                let words = match crate::git::run(&ws_cwd, &["reset", "--merge", "--quiet", "HEAD"]) {
                    Ok(()) => failure.text(),
                    Err(e) => format!(
                        "{}\n\nPlyloft couldn't take the card's merge back out of the project folder \
                         ({e}), so it left the folder as it is: the merge is staged there. Look at \
                         `git status` before you change anything.",
                        failure.text()
                    ),
                };
                drop(fast_forward);
                return Err(words.into());
            }
            drop(fast_forward);

            // v1.34.x: stamp ship-state. The commit lives on the target
            // branch; the worktree is now garbage; the toolbar badge and
            // the lifecycle pill both key off these fields. Failures
            // logged but not surfaced — the user's land already
            // succeeded, and the next startup `reconcile_ship_backfill`
            // pass can recover any card we couldn't stamp now.
            let commit_sha = crate::git::capture(&ws_cwd, &["rev-parse", "HEAD"])
                .map(|s| s.trim().to_string())
                .unwrap_or_default();
            let shipped_version = project_config
                .get(workspace_id)
                .and_then(|cfg| crate::ship::read_project_version(&ws_cwd, &cfg))
                .unwrap_or_else(|| "unknown".to_string());

            // N18: the card's branch at the commit that landed, recorded
            // before the ship-state stamp clears the card's branch handle.
            let landed_tip = crate::worktrees::resolve_commit(&ws_cwd, &publish);
            let mut branch_record = crate::branch_cleanup::record(
                &card,
                &ws_cwd,
                crate::branch_cleanup::CleanupReason::Landed,
                landed_tip.as_deref(),
                None,
                crate::kanban::now_ms(),
            );
            kanban.set_card_review(
                workspace_id,
                card_id,
                Some(crate::kanban::ReviewStatus::Merged),
                None,
            )?;
            if !commit_sha.is_empty() {
                let sha = commit_sha.clone();
                let ver = shipped_version.clone();
                if let Err(e) =
                    kanban.with_card(workspace_id, card_id, move |c| {
                        crate::ship::mark_card_shipped_local(c, &sha, &ver);
                        Ok(())
                    })
                {
                    log::warn!(
                        "land_card_local: mark_card_shipped_local for {card_id}: {e}"
                    );
                }
            } else {
                log::warn!(
                    "land_card_local: could not capture HEAD sha for {card_id}; \
                     leaving ship-state unstamped (next startup will reconcile)"
                );
            }
            let cache_paths = project_config.cache_paths(workspace_id);
            let path = crate::worktrees::card_worktree_path(&ws_cwd, card_id, card.worktree_path.as_deref());
            // Try it (TI-2): its preview stops before its copy goes; the
            // card says so (`try_session::STOPPED_FOR_SHIP_WORDS`).
            crate::try_session::stop_card_try_sessions(workspace_id, card_id, None, crate::try_session::TryStopReason::Ship);
            // Windows walk 2026-10-20: a copy a program still has open (the
            // card's Builder session, until the person closes it) is kept,
            // and the card says so and why (`kept_copy`); it is tried again
            // when that session closes and at launch.
            match crate::kept_copy::prune_or_keep(kanban, workspace_id, card_id, &ws_cwd, &path, &cache_paths) {
                Ok(entry) => {
                    if let (Some(rec), Some(entry)) = (branch_record.as_mut(), entry) {
                        rec.trash_entry = Some(entry.to_string_lossy().to_string());
                    }
                }
                Err(e) => log::warn!("land_card_local: worktree prune for {card_id}: {e}"),
            }
            kanban.record_branch_cleanup(workspace_id, card_id, branch_record);
            crate::verify_logs::card_worktree_removed(workspace_id, card_id);

            Ok(ReviewMergeResult {
                merged: true,
                conflicting_paths: Vec::new(),
                fast_forwarded,
                review_override: None,
            })
        }
        Err(merge_err) => {
            // Capture the conflicting paths before unwinding. P-E
            // (Challenger): `-z`, so a name with an accent or a space is
            // recorded as the path it is, not git's quoted form — "Ask the
            // Builder" reads those files back for their marks.
            let unmerged = crate::git::capture(
                &ws_cwd,
                &["diff", "--name-only", "-z", "--diff-filter=U"],
            )
            .unwrap_or_default();
            let conflicting: Vec<String> = unmerged
                .split('\0')
                .filter(|s| !s.is_empty())
                .map(str::to_string)
                .collect();
            // UX P1 point 7 (P-E): the target commit the card's work met —
            // the checkout's HEAD, which the failed merge never moved —
            // kept with the paths for "Ask the Builder to resolve it".
            let met_target = crate::worktrees::resolve_commit(&ws_cwd, "HEAD");
            // Restore the clean checkout. Safe: tracked files were verified
            // clean above, and `reset --hard` leaves untracked files alone —
            // a merge that would have overwritten one was refused by git
            // before it wrote anything (GH #190).
            let _ = crate::git::run(&ws_cwd, &["reset", "--hard", "HEAD"]);
            drop(fast_forward);
            if conflicting.is_empty() {
                // UX P-A (Windows walk 2): git refused the merge over
                // untracked files the card's commit adds — with the target
                // Diverged the sync gate never looked at them. The same typed
                // refusal as the gate's, its ways out on the card's Ship step,
                // not a generic "couldn't finish". Nothing was merged (git
                // wrote nothing), and the card keeps its review status.
                if let Some(head) = crate::worktrees::resolve_commit(&ws_cwd, "HEAD") {
                    let toplevel = crate::git::capture(&ws_cwd, &["rev-parse", "--show-toplevel"])
                        .map(|s| PathBuf::from(s.trim()))
                        .unwrap_or_else(|_| ws_cwd.clone());
                    let in_the_way =
                        crate::worktrees::untracked_in_the_merges_way(&toplevel, &head, &publish)
                            .unwrap_or_default();
                    if !in_the_way.is_empty() {
                        log::info!(
                            "land_card_local: {card_id}'s merge refused over untracked files: {merge_err}"
                        );
                        let output = merge_err
                            .split_once("failed: ")
                            .map(|(_, git_said)| git_said.to_string())
                            .unwrap_or_else(|| merge_err.clone());
                        return Err(crate::worktrees::ShipError::merge_untracked_refused(
                            &target_branch,
                            &head,
                            &publish,
                            &in_the_way,
                            output,
                        ));
                    }
                }
                // Not a conflict — a genuine failure (bad branch, etc.).
                return Err(merge_err.into());
            }
            let record = met_target.map(|target_sha| crate::kanban::ShipConflict {
                paths: conflicting.clone(),
                target_sha,
                at: crate::kanban::now_ms(),
                branch: target_branch.clone(),
                merge_started_at: None,
                sync: false,
                review_before: None,
            });
            kanban.with_card(workspace_id, card_id, |c| {
                c.review_status = Some(crate::kanban::ReviewStatus::ConflictBlocked);
                c.ship_conflict = record;
                Ok(())
            })?;
            Ok(ReviewMergeResult {
                merged: false,
                conflicting_paths: conflicting,
                fast_forwarded,
                review_override: None,
            })
        }
    }
}

/// v1.31.0 (Cycle 1): land an accepted card via local squash-merge — the
/// per-hunk developer panel's "Merge" action.
///
/// GH #80: a worker, not the main thread — the merge waits on the integration
/// lock a shared-settings publish may hold across network calls.
#[tauri::command]
pub async fn card_review_merge(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    // PR #375 review (P2-b): the member chose "Merge anyway" — land a
    // Builder snapshot the Challenger has not approved. Absent: false.
    unreviewed_ok: Option<bool>,
) -> Result<ReviewMergeResult, crate::worktrees::ShipError> {
    tauri::async_runtime::spawn_blocking(move || {
        card_review_merge_blocking(&app, workspace_id, card_id, unreviewed_ok.unwrap_or(false))
    })
    .await
    .map_err(|e| format!("merge worker failed: {e}"))?
}

fn card_review_merge_blocking<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    workspace_id: String,
    card_id: String,
    unreviewed_ok: bool,
) -> Result<ReviewMergeResult, crate::worktrees::ShipError> {
    let app = app.clone();
    // GH #222 review 1: as `card_ship`.
    let _ship = hold_ship_lock(&app, &workspace_id)?;
    refuse_land_while_recorded(&app, &workspace_id)?;
    let workspaces = app.state::<WorkspaceStore>();
    let kanban = app.state::<KanbanStore>();
    let project_config = app.state::<ProjectConfigStore>();
    // v1.154.1 round 3 (Challenger): the review panel's "Merge to base" never
    // lands a card whose work is in an open pull request.
    let card = kanban.get_card(&workspace_id, &card_id)?;
    if let Some(words) = crate::pr_status::review_merge_refusal(&card) {
        return Err(words.into());
    }
    // PR #375 review (P2-b): a Builder card lands as its verified last
    // snapshot (as before) and, like Ship, never past the Challenger
    // silently: an unapproved snapshot needs the member's "Merge anyway",
    // and the receipt keeps the line Ship would write. The snapshot, its
    // checks and the review are all read from this one card.
    let builder_land = match (&card.builder, &card.worktree_path, &card.branch_name) {
        (Some(_), Some(worktree), Some(branch)) if !crate::build_both::is_undecided(&card) => {
            let in_flight = app
                .try_state::<VerifyRegistry>()
                .is_some_and(|r| r.is_inflight(&workspace_id, &card_id));
            crate::builder::require_verified_snapshot(&card, Path::new(worktree), in_flight)?;
            let publish = crate::builder::publish_rev(&card, branch);
            let gap = crate::builder::merge_review_gap(&card, &publish);
            if gap.is_some() && !unreviewed_ok {
                return Err(crate::builder::MERGE_UNREVIEWED_REFUSAL.to_string().into());
            }
            let lines = crate::builder::ship_review_record(&card, &publish, false);
            Some((publish, lines))
        }
        _ => None,
    };
    let mut res = land_card_local(
        &app,
        &workspaces,
        &kanban,
        &project_config,
        &workspace_id,
        &card_id,
        builder_land.as_ref().map(|(publish, _)| publish.as_str()),
    )?;
    if res.merged {
        // PR #375 review: "Card landed" says the human's decision on the
        // review, as Ship's receipt does.
        if card.builder.is_some() {
            res.review_override = review_override_line(&card);
        }
        if let Some((_, lines)) = &builder_land {
            crate::builder::record_shipped_unreviewed(&kanban, &workspace_id, &card_id, lines.as_deref());
        }
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
    }
    Ok(res)
}

/// Read-only advisory check for the target checkout used by `card_ship`.
/// `Some(clean)` is distinct from `None`: the latter means Git status was
/// unavailable, so the UI must show no modifier and the mutation-time guard
/// remains authoritative.
///
/// H4 Windows walk: off the main thread. A `git status` of a large checkout
/// on Windows takes seconds, and as a plain command it ran on the main
/// thread, so the page stopped answering while a skill card opened at Ship.
#[tauri::command(async)]
pub fn card_ship_preflight(
    workspaces: State<'_, WorkspaceStore>,
    kanban: State<'_, KanbanStore>,
    workspace_id: String,
    card_id: String,
) -> Result<Option<TargetDirtyState>, String> {
    kanban.get_card(&workspace_id, &card_id)?;
    let target = resolve_ws_cwd(&workspaces, &workspace_id)?;
    match capture_target_dirty_state(&target) {
        Ok(state) => Ok(Some(state)),
        Err(error) => {
            log::warn!(
                "card_ship_preflight: target status unavailable for {workspace_id}/{card_id}: {error}"
            );
            Ok(None)
        }
    }
}

/// F1 (1.172.1): the changes sheet — the project folder's changes not in a
/// commit, each file's lines as the review draws them. Read-only; logged
/// (count and paths). `None` when Git couldn't read them.
#[tauri::command(async)]
pub fn project_folder_changes_detail(
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
) -> Result<Option<crate::project_folder::FolderChanges>, String> {
    let cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
    match crate::project_folder::folder_changes(&cwd) {
        Ok(changes) => Ok(Some(changes)),
        Err(error) => {
            log::warn!("project_folder_changes_detail: unavailable for {workspace_id}: {error}");
            Ok(None)
        }
    }
}

/// F1 (1.172.1): *Bring it up to date* — moves only the branch the project
/// folder already has, only forward, from its own GitHub copy (the Sync's
/// `fast_forward_local`). Never switches the folder's branch, rewrites,
/// stashes or pushes: no write to GitHub. Off the main thread (it fetches).
#[tauri::command]
pub async fn project_folder_bring_up_to_date(
    app: tauri::AppHandle,
    workspace_id: String,
) -> Result<crate::project_folder::FolderUpdate, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let workspaces = app.state::<WorkspaceStore>();
        let project_config = app.state::<ProjectConfigStore>();
        let cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
        let target = resolve_base_branch(&project_config, &workspace_id);
        let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
        let update = crate::project_folder::bring_up_to_date(&cwd, &target);
        log::info!("project folder bring up to date: workspace={workspace_id} target={target} result={update:?}");
        Ok(update)
    })
    .await
    .map_err(|e| format!("bring up to date worker failed: {e}"))?
}

/// v1.31.0 (Outcome screen): ship a card. `mode = "merge_live"` (the vibe
/// default) squash-merges the card into the build branch and runs the
/// project's go-live step (`install_script`) so the change is live
/// immediately; `mode = "pr"` pushes the branch and opens a GitHub PR for
/// team review. `pr` with no git remote falls back to `merge_live`, flagged.
/// G1 (1.170.0): `ship_it` is the card's Ship it — a pull request that
/// merges when its checks pass on a project that can take one, unless the
/// workspace ships on this Mac ([`resolve_ship_press`]); `pr_only` is a
/// pull request without auto-merge.
///
/// GH #80: runs on a worker — it pushes, calls `gh`, and waits on the
/// integration lock a shared-settings publish may hold.
#[tauri::command]
pub async fn card_ship(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    mode: String,
    // R2: *Include them and ship as a PR* — push the commits `carries_local_commits` listed.
    carry_local_commits: Option<bool>,
    // G4 Challenger 1: this press's draft request (`card_pr_draft_prepare`).
    pr_draft_request: Option<String>,
) -> Result<ShipOutcome, crate::worktrees::ShipError> {
    tauri::async_runtime::spawn_blocking(move || {
        let carry = carry_local_commits.unwrap_or(false);
        let draft = pr_draft_request.as_deref();
        let outcome = card_ship_blocking(app.clone(), workspace_id.clone(), card_id.clone(), mode, carry, draft)?;
        close_landed_skill_card_issues(&app, &workspace_id, std::slice::from_ref(&card_id));
        // SL-3: the ship lock is released; read a PR auto-merge may have merged.
        crate::pr_merge::kick_read_after_ship(&app, &workspace_id, &card_id, &outcome.kind);
        Ok(outcome)
    })
    .await
    .map_err(|e| format!("ship worker failed: {e}"))?
}

// 1.174.0 X1 (CH-8): the card's ship and pull request commands live in
// `card_pr_commands.rs` (`commands::card_pr_commands`).
#[path = "card_pr_commands.rs"]
pub(crate) mod card_pr_commands;

// ── Challenger on a pull request (`pr_review.rs`) ─────────────────────

/// Board › Review a pull request: the repository's open pull requests, as
/// the workspace's GitHub account. Read-only.
#[tauri::command]
pub async fn pr_review_list(app: tauri::AppHandle, workspace_id: String) -> Result<crate::pr_review::PrList, String> {
    tauri::async_runtime::spawn_blocking(move || crate::pr_review::list(&app, &workspace_id))
        .await
        .map_err(|e| format!("pull request list worker failed: {e}"))?
}

/// The sheet's Review: the card "Review: <title>" on pull request `input`
/// (a link or a number of this repository), its worktree at the pull
/// request's head, and the review by `challenger`.
#[tauri::command]
pub async fn pr_review_create(
    app: tauri::AppHandle,
    workspace_id: String,
    input: String,
    challenger: String,
) -> Result<crate::pr_review::PrReviewCreated, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let kanban = app.state::<KanbanStore>();
        crate::pr_review::create(&app, &workspace_id, &input, &challenger, |card_id, head| {
            crate::builder::review_pr_head(&app, &kanban, &workspace_id, card_id, head).map(|_| ())
        })
    })
        .await
        .map_err(|e| format!("pull request review worker failed: {e}"))?
}

/// The card page's open and its Check GitHub: read the pull request again.
#[tauri::command]
pub async fn pr_review_refresh(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<KanbanCard, String> {
    tauri::async_runtime::spawn_blocking(move || crate::pr_review::refresh_card(&app, &workspace_id, &card_id))
        .await
        .map_err(|e| format!("pull request refresh worker failed: {e}"))?
}

/// Review / Review again: the pull request's current head, on the card's
/// branch brought there.
#[tauri::command]
pub async fn pr_review_start(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<KanbanCard, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let kanban = app.state::<KanbanStore>();
        let live = app.state::<crate::builder::BuilderRegistry>().get_pty(&card_id).is_some();
        crate::pr_review::start(&app, &workspace_id, &card_id, live, |head| {
            crate::builder::review_pr_head(&app, &kanban, &workspace_id, &card_id, head).map(|_| ())
        })
    })
        .await
        .map_err(|e| format!("pull request review worker failed: {e}"))?
}

/// Challenger on a pull request (P2-2): **Bring in the new commits** — the
/// member's own pull request has commits on top of the head an unpushed fix
/// is built on; they are merged into the card's branch.
#[tauri::command]
pub async fn pr_review_merge_head(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<KanbanCard, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let live = || app.state::<crate::builder::BuilderRegistry>().get_pty(&card_id).is_some();
        let card = crate::pr_review::merge_new_commits(&app, &workspace_id, &card_id, live)?;
        // Round 2 (P2-A): the merge is snapshotted as Build done would, so
        // the Challenger reviews it and its Verify runs now (round 3: here,
        // not from the page). Round 3: not while a Builder session opened
        // meanwhile — it presses its own Build done. A Build done that fails
        // or is skipped leaves "merged, not built yet".
        if card.pr_review.as_ref().is_some_and(|p| p.merged) && !live() {
            let by = app.state::<SettingsStore>().snapshot().identity.user_email;
            let kanban = app.state::<KanbanStore>();
            match crate::builder::done(app.clone(), &kanban, &workspace_id, &card_id, false, by.as_deref(), None) {
                Ok(done) if done.new_snapshot || done.reselected => {
                    if let Err(e) = app.state::<crate::card_execution::CardExecutionGate>().enqueue_verify(
                        app.clone(),
                        &app.state::<VerifyRegistry>(),
                        &kanban,
                        &app.state::<WorkspaceStore>(),
                        &app.state::<AgentRegistry>(),
                        &app.state::<SwarmRegistry>(),
                        VerifyRequest { workspace_id: workspace_id.clone(), card_id: card_id.clone(), post_outcome_issue: false },
                    ) {
                        log::warn!("pr_review: {card_id}: merged and built; Verify didn't start: {e}");
                    }
                }
                Ok(_) => {}
                Err(e) => log::warn!("pr_review: {card_id}: merged; Finish and check didn't run: {e}"),
            }
        }
        app.state::<KanbanStore>().get_card(&workspace_id, &card_id)
    })
    .await
    .map_err(|e| format!("pull request merge worker failed: {e}"))?
}

/// GH #222 review 1: the per-workspace ship lock, for a Land (`card_ship`,
/// the review panel's Merge) — refused with `ship::SHIP_BUSY` while a release
/// or another Land of this workspace runs, and a release started meanwhile is
/// refused the same way. An app without the registry (a test's) takes none.
pub(crate) fn hold_ship_lock<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    workspace_id: &str,
) -> Result<Option<ship::ShipLockGuard>, String> {
    let guard = match app.try_state::<ShipRegistry>() {
        Some(registry) => Some(
            registry
                .try_acquire(workspace_id)
                .ok_or_else(|| ship::SHIP_BUSY.to_string())?,
        ),
        None => None,
    };
    Ok(guard)
}

/// GH #222 review 2–3: nothing lands on the target branch while a release of
/// it is recorded but unpublished — the tag would never leave this Mac. The
/// refusal is the value (`ShipError::Unpublished` / `RecordUnreadable`), so
/// the window leads to the Ship step's Publish and Dismiss. A PR-mode
/// `card_ship` lands nothing on the target branch and doesn't ask.
fn refuse_land_while_recorded<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    workspace_id: &str,
) -> Result<(), crate::worktrees::ShipError> {
    let (Some(workspaces), Some(config), Some(kanban)) = (
        app.try_state::<WorkspaceStore>(),
        app.try_state::<ProjectConfigStore>(),
        app.try_state::<KanbanStore>(),
    ) else {
        return Ok(());
    };
    ship::refuse_land_while_recorded(&workspaces, &config, &kanban, workspace_id)
}

/// Findings filter: a dismissal is a human decision on the review too,
/// said beside an accepted pushback in the receipt and the PR body (Ship),
/// and in the review panel's "Card landed" (PR #375 review).
fn review_override_line(card: &crate::kanban::KanbanCard) -> Option<String> {
    match (
        crate::builder::review_override_summary(card),
        crate::builder::dismissal_summary(card),
    ) {
        (Some(overridden), Some(dismissed)) => Some(format!("{overridden} {dismissed}")),
        (overridden, dismissed) => overridden.or(dismissed),
    }
}

fn card_ship_blocking(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    mode: String,
    carry_local_commits: bool,
    pr_draft_request: Option<&str>,
) -> Result<ShipOutcome, crate::worktrees::ShipError> {
    card_ship_blocking_with(app, workspace_id, card_id, mode, carry_local_commits, None, pr_draft_request, &|_| {})
}

/// `card_ship`, with one more line for the PR body (ADR 0006: `Shipped
/// with N open findings: #140`). `on_landed` hears what shipped ("the PR
/// URL", "merged locally as <sha>") as soon as it has landed and the card is
/// marked shipped — before the go-live step and any optional network work,
/// which may fail or relaunch Ply.
fn card_ship_blocking_with(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    mode: String,
    // R2: the person chose *Include them and ship as a PR* over `carries_local_commits`.
    carry_local_commits: bool,
    pr_line: Option<String>,
    // G4 Challenger 1: the draft request this press made, if any.
    pr_draft_request: Option<&str>,
    on_landed: &dyn Fn(&str),
) -> Result<ShipOutcome, crate::worktrees::ShipError> {
    // GH #222 review 1: never beside a release (or another Land) of this
    // workspace — a card mid-batch would be squashed onto a released commit.
    let _ship = hold_ship_lock(&app, &workspace_id)?;
    let workspaces = app.state::<WorkspaceStore>();
    let kanban = app.state::<KanbanStore>();
    let project_config = app.state::<ProjectConfigStore>();
    let card = kanban.get_card(&workspace_id, &card_id)?;
    // SL-6: two builds and no pick yet — nothing to ship.
    if crate::build_both::is_undecided(&card) {
        return Err(crate::build_both::UNDECIDED_REFUSAL.to_string().into());
    }
    // Challenger on a pull request: its fixes go to that pull request.
    if let Some(why) = crate::pr_review::ship_refusal(&card) {
        return Err(why.into());
    }
    // 1.173.0 (B3): where the card goes — its area's branch. Held, an
    // unlisted area and a card with none chosen ship nothing.
    let ship_branch = crate::card_area::branch_for_card(&project_config, &workspace_id, &card)?;
    let branch = card
        .branch_name
        .clone()
        .ok_or_else(|| "this card has no branch to ship".to_string())?;
    let worktree = card
        .worktree_path
        .clone()
        .ok_or_else(|| "This card has no copy of the repository.".to_string())?;
    let wt = PathBuf::from(&worktree);
    if !wt.is_dir() {
        return Err(format!("The card's copy of the repository is gone ({worktree}).").into());
    }
    // G1: Ship it ships as the workspace says (a pull request that merges
    // when its checks pass, or a land here); Open the pull request only is
    // a pull request without auto-merge.
    // G1 Challenger (8): Ship it from a GitHub address Plyloft can't read
    // stops with its way on, never answered by landing here instead (said
    // after a skill card's own preflight, whose answer comes first).
    let unreadable_refusal = ship_it_origin_refusal(&workspaces, &workspace_id, &wt, &mode);
    let (mode, auto_merge) = ship_press_for(&workspaces, &workspace_id, &wt, &mode);
    let mut auto_merge = auto_merge;

    // Skills hub H3a (§4.2 "Preflight at Ship"): a skill card already shipped
    // by someone else, overtaken by its origin, or whose target copy changed
    // since it was made. The last never overrides that change: it ships as a
    // pull request, with the reason.
    let mut mode = mode;
    let mut skill_note: Option<String> = None;
    if let Some(skill) = card.skill_card() {
        match skill_card_preflight(&app, &workspaces, &ship_branch, &workspace_id, skill) {
            crate::skill_card::Preflight::UpToDate => {
                return Ok(ShipOutcome {
                    kind: "skill_up_to_date".into(),
                    skill_note: Some(crate::skill_card::UP_TO_DATE_WORDS.into()),
                    ..Default::default()
                })
            }
            crate::skill_card::Preflight::RefreshNeeded => {
                return Ok(ShipOutcome {
                    kind: "skill_refresh".into(),
                    skill_note: Some(crate::skill_card::REFRESH_WORDS.into()),
                    ..Default::default()
                })
            }
            crate::skill_card::Preflight::HereMoved(why) => {
                let origin = pr_origin(&wt);
                if origin == PrOrigin::None {
                    return Err(format!(
                        "{why} This repository has no remote to open one on, so nothing was shipped. \
                         Delete this card and install it again from the Library."
                    )
                    .into());
                }
                // R10 (Challenger): an origin that can't take a pull request
                // — Ship it would land the old copy, so the way on is the
                // Library, not a land here.
                if let Some(words) = origin_refused_words(&origin) {
                    return Err(format!(
                        "{why} {words} Nothing was shipped. Delete this card and install it again from the Library."
                    )
                    .into());
                }
                mode = "pr".to_string();
                // G1 Challenger (3): forced to a pull request, it never
                // merges by itself — the person reads why first.
                auto_merge = ShipAutoMerge::Off;
                skill_note = Some(why);
            }
            crate::skill_card::Preflight::Go => {}
        }
    }
    if skill_note.is_none() {
        if let Some(why) = unreadable_refusal {
            return Err(why.into());
        }
    }

    // G8 fixes (1.170.0, Challenger major 3): a card in a release pull
    // request on its way isn't shipped as a pull request of its own too
    // (Merge is held back by the release's record already).
    if mode == "pr" {
        if let Some(why) = ship::in_release_pr_refusal(&project_config, &kanban, &workspace_id, &card) {
            return Err(why.into());
        }
    }

    // 1.169.1 (R10): a pull request is opened only on a GitHub `origin`;
    // one elsewhere is refused before anything is gated or pushed.
    if let Some(why) = pr_origin_refusal(&wt, &mode) {
        return Err(match &skill_note {
            Some(moved) => format!("{moved} {why}"),
            None => why,
        }
        .into());
    }
    // G1: nor without the GitHub CLI and a sign-in — said with its ways on,
    // never answered by landing here instead.
    if let Err(why) = pr_github_preflight(&workspaces, &workspace_id, &wt, &mode) {
        return Err(match &skill_note {
            Some(moved) => format!("{moved} {why}"),
            None => why,
        }
        .into());
    }

    // Challenger (H6b Windows walk): a skill card cut from a local target
    // GitHub's lacks commits of never opens a pull request carrying them.
    if mode == "pr" && card.skill_card().is_some() && origin_offers_pr(&wt) {
        let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
        if let Some(why) = skill_pr_carries_local_commits(&ws_cwd, &card, &ship_branch) {
            return Err(match &skill_note {
                Some(moved) => format!("{moved} {why}"),
                None => why,
            }
            .into());
        }
    }

    // 1.169.1 (R2): nor does any other card's carry commits that aren't its
    // own and aren't on GitHub yet, unless the person chose to — said before
    // anything is gated or pushed.
    if let Some(stop) = pr_carry_stop(&workspaces, &project_config, &workspace_id, &card, &wt, &mode, carry_local_commits)? {
        return Ok(stop);
    }

    // Ship never publishes edits nobody verified (see `ship_decision`). The
    // gate names one immutable commit; the merge and the push use it.
    let (publish, skill_only) = match ship_tree_gate(&app, &workspaces, &kanban, &card, &wt)? {
        ShipGate::Publish(rev) => (rev, false),
        ShipGate::PublishSkillOnly(rev) => (rev, true),
        ShipGate::Pending(pending) => {
            crate::kanban::emit_kanban_changed(&app, &workspace_id);
            return Ok(pending);
        }
    };
    // R13 (Challenger): where it shipped, and whether the project is on
    // GitHub, said by the backend — the toast and the receipt agree.
    let ship_target = ship_branch.clone();
    let on_github = resolve_ws_cwd(&workspaces, &workspace_id)
        .is_ok_and(|cwd| crate::project_setup_config::local_origin(&cwd).github_repo.is_some());
    // Skills hub H3a: what the Ship step says about a skill card's ship.
    let finish = |mut outcome: ShipOutcome| {
        outcome.skill_only = skill_only;
        outcome.skill_note = skill_note.clone();
        outcome.target = Some(ship_target.clone());
        outcome.on_github = on_github;
        outcome
    };
    let shipped_snapshot = card.builder.as_ref().and_then(|b| b.snapshots.last().cloned());
    let review_override = review_override_line(&card);
    // GH #99 + #129: the unreviewed-commit and handed-over lines; else the
    // review gap (#378), except beside Ship with follow-up's own line.
    let unreviewed = crate::builder::ship_review_record(&card, &publish, pr_line.is_some());
    // G1 Challenger (1, 4): nothing unreviewed, shipped over a request for
    // changes nobody resolved, or shipped with its findings in a follow-up
    // merges by itself; a human's decision (`review_override`) does.
    let press_auto_merge = auto_merge;
    let auto_merge = ship_auto_merge_guarded(auto_merge, unreviewed.as_deref(), pr_line.is_some());
    // G1–G3 Challenger (1, 3): the guard held auto-merge off — Some(whether
    // the press wanted it, so it is turned on once reviewed).
    let review_hold = (unreviewed.is_some() || pr_line.is_some())
        .then(|| ship_wants_auto_merge(press_auto_merge, &workspaces, &workspace_id));

    // merge_live: land the card into the build branch, then run the
    // project's go-live step so the change is immediately live. A
    // configured `install_script` runs detached (the rebuild); no
    // install_script → the merge is the whole ship.
    let merge_and_go_live = |fell_back: bool| -> Result<ShipOutcome, crate::worktrees::ShipError> {
        // GH #222 review 2–3: only the merge is held back by a recorded
        // release; PR mode (which pushes the card's own branch) is not.
        refuse_land_while_recorded(&app, &workspace_id)?;
        // Skills hub H3a (§14 Q23): a skill-only merge needs no rebuild —
        // skills reach new sessions directly — so no install script runs.
        let install_script = if skill_only {
            None
        } else {
            project_config.get(&workspace_id).and_then(|c| c.install_script)
        };
        // Windows: Ply's own go-live is refused before the merge, not after.
        #[cfg(windows)]
        if let Some(script) = install_script.clone() {
            crate::ship::refuse_self_install(&resolve_ws_cwd(&workspaces, &workspace_id)?, Some(&script))?;
        }
        let res = land_card_local(
            &app,
            &workspaces,
            &kanban,
            &project_config,
            &workspace_id,
            &card_id,
            Some(&*publish),
        )?;
        if !res.merged {
            // Conflict — land_card_local marked the card ConflictBlocked.
            return Ok(ShipOutcome {
                kind: "local_merge".to_string(),
                pr_url: None,
                merged: false,
                conflicting_paths: res.conflicting_paths,
                fell_back,
                fast_forwarded: res.fast_forwarded,
                shipped_snapshot: shipped_snapshot.clone(),
                review_override: review_override.clone(),
                unreviewed: unreviewed.clone(),
                ..Default::default()
            });
        }
        crate::builder::record_shipped_unreviewed(&kanban, &workspace_id, &card_id, unreviewed.as_deref());
        on_landed(&format!("merged locally as {}", short_sha(&publish)));
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        // Phase 6B: new ship events no longer write the legacy run-keyed
        // SuggestionsFile format. The evidence-backed proposal was persisted
        // inside land_card_local and remains pending until the 6C generator.
        // Historical legacy files stay readable/actionable.
        let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
        match install_script.filter(|script| !crate::checks_consent::hold_install_of(&project_config, &workspace_id, None, Some(script))) {
            Some(script) => {
                crate::ship::spawn_install_script(&ws_cwd, &script)?;
                // 1.171.0 A3 (DL-30): only Plyloft's own install relaunches.
                let relaunches = crate::ship::is_self_install(&ws_cwd, &script);
                Ok(ShipOutcome {
                    kind: "merged_live".to_string(),
                    relaunches,
                    pr_url: None,
                    merged: true,
                    conflicting_paths: Vec::new(),
                    fell_back,
                    fast_forwarded: res.fast_forwarded,
                    shipped_snapshot: shipped_snapshot.clone(),
                    review_override: review_override.clone(),
                    unreviewed: unreviewed.clone(),
                    ..Default::default()
                })
            }
            None => Ok(ShipOutcome {
                kind: "local_merge".to_string(),
                pr_url: None,
                merged: true,
                conflicting_paths: Vec::new(),
                fell_back,
                fast_forwarded: res.fast_forwarded,
                shipped_snapshot: shipped_snapshot.clone(),
                review_override: review_override.clone(),
                unreviewed: unreviewed.clone(),
                ..Default::default()
            }),
        }
    };

    if mode != "pr" {
        return merge_and_go_live(false).map(finish);
    }

    // PR mode — needs a GitHub `origin` (or one it can't tell isn't). None
    // → merge + go live, flagged (one elsewhere was refused above, R10).
    let origin = pr_origin(&wt);
    if !origin.offers_pr() {
        return merge_and_go_live(true).map(finish);
    }
    // R10 (Challenger): `gh pr create` opens it on origin's repository,
    // never on another remote gh may pick (`upstream`).
    let origin_repo = match origin {
        PrOrigin::GitHub { repo } => repo,
        _ => None,
    };

    // v1.32.0: resolve `gh` up front via the dependency doctor — a friendly,
    // install-pointing message, and checked *before* the branch is pushed so
    // a missing CLI doesn't leave a half-shipped branch behind.
    let gh = crate::doctor::require("gh")?;
    // OB-7b: the push and every `gh` below run as the workspace's GitHub
    // account (one token read for the whole PR flow).
    let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);

    // Push exactly the commit the gate verified to the card's branch, so a
    // commit made after the gate (an open Builder session, anything) is
    // never published.
    // 1.173.0 (B3): the pull request goes to the card's area's branch.
    let base = ship_branch.clone();
    // 1.175.0 (D1): a teammate's pull request for the same issue stops Ship
    // before anything is sent; a push the branch refuses names who pushed.
    if let Some(repo) = workspace_github_target(&workspaces, &workspace_id) {
        crate::second_claim::ship_refusal(&repo, &card, &branch, &base)?;
    }
    push_branch_for_pr(
        &wt,
        &publish,
        &branch,
        "no PR was opened and the card is not marked shipped. Ship again to push the same commit and open the PR.",
    )
    .map_err(|e| crate::second_claim::name_who_pushed(origin_repo.as_deref(), &branch, &card, e))?;

    // v1.58.0 (Cycle 3 / Phase 4): when the card is backed by a GitHub issue,
    // open the PR body with `Closes #N` so merging auto-closes the issue (which
    // moves the card to Done on the next reconcile). Detailed run outcome lives
    // in the issue's comments (Phase 4a/4b), so the body stays terse.
    let mut body = match card.gh_issue_number {
        Some(n) => format!(
            "Closes #{n}\n\nShipped from Plyloft — see the card for the task and review."
        ),
        None => "Shipped from Plyloft — see the card for the task and review.".to_string(),
    };
    // The reviewer on the other Mac sees that the last Challenger verdict
    // was overridden rather than addressed.
    if let Some(line) = &review_override {
        body.push_str(&format!("\n\n**{}**", crate::builder::line_for_github(line, &wt)));
    }
    // Skills hub H3a: why a skill card came as a pull request.
    if let Some(line) = &skill_note {
        body.push_str(&format!("\n\n**{line}**"));
    }
    // GH #99 + #129: so whoever reviews the PR knows without opening Ply.
    if unreviewed.is_some() {
        body = crate::builder::pr_body_with_unreviewed(&body, unreviewed.as_deref());
    }
    // ADR 0006: shipped with follow-up — the open findings' new card.
    if let Some(line) = &pr_line {
        body.push_str(&format!("\n\n**{line}**"));
    }
    // G4: the Builder's title and description when this press asked it for
    // them (its request id), for the snapshot being shipped, and they are
    // usable (the file is deleted either way); Plyloft's lines follow under
    // "From Plyloft".
    let drafted = crate::pr_draft::take_for_ship(
        &workspace_id,
        &card_id,
        &wt,
        chrono::Utc::now().timestamp_millis(),
        pr_draft_request,
        shipped_snapshot.as_ref().map(|s| s.sha.as_str()),
        card.builder.as_ref().and_then(|b| b.pr_draft.as_ref()),
    );
    let (title, body) = match drafted {
        Some(draft) => (draft.title.clone(), crate::pr_draft::body_with_plyloft(&draft.body, &body)),
        // R12: the repository's pull-request template comes first, as
        // GitHub would have filled it in.
        None => (card.title.clone(), pr_body_with_template(pr_template_at(&wt, &publish).as_deref(), &body)),
    };
    // A pull request that already exists for this branch is linked instead
    // of failing (`open_branch_pr`), and told what this push changed.
    let (pr_url, existed) = match open_branch_pr(&gh, &wt, &base, &branch, &title, &body, origin_repo.as_deref())? {
        PrOpened::New(url) => (url, false),
        PrOpened::Existing(url) => (url, true),
    };
    kanban.mark_card_pr_shipped(&workspace_id, &card_id, &pr_url, Some(&*publish))?;
    crate::builder::record_shipped_unreviewed(&kanban, &workspace_id, &card_id, unreviewed.as_deref());
    on_landed(&pr_url);
    if existed {
        // GH #99 (review 1): the push may have added an
        // unreviewed commit (or a reviewed one) to this PR.
        refresh_unreviewed_pr_line(&gh, &wt, &pr_url, unreviewed.as_deref());
        // ADR 0006: a PR that already existed says it shipped
        // with follow-up too.
        if let Some(line) = &pr_line {
            refresh_pr_body(&gh, &wt, &pr_url, |body| crate::review_ledger::pr_body_with_follow_up(body, line));
        }
    }
    post_challenger_verdict_comment(&gh, &wt, &pr_url, &card);
    auto_merge_after_ship(
        &workspaces,
        &kanban,
        &workspace_id,
        &card_id,
        auto_merge,
        review_hold,
        existed,
        &gh,
        &wt,
        &pr_url,
        &publish,
    );
    crate::kanban::emit_kanban_changed(&app, &workspace_id);
    Ok(finish(ShipOutcome {
        kind: "pr".to_string(),
        pr_url: Some(pr_url),
        merged: false,
        conflicting_paths: Vec::new(),
        fell_back: false,
        shipped_snapshot: shipped_snapshot.clone(),
        review_override: review_override.clone(),
        unreviewed: unreviewed.clone(),
        ..Default::default()
    }))
}

/// What [`open_branch_pr`] got: a pull request it opened, or the one that
/// was already open for the branch.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum PrOpened {
    New(String),
    Existing(String),
}

/// Ship's push for a pull request: exactly `publish` to `refs/heads/<branch>`
/// on origin — an explicit refspec to the same branch name, never forced —
/// bounded and exit-registered like Ship's release push (GH #222).
/// `timed_out_tail` says, after a push stopped at its bound, what wasn't
/// done and how to try again. Shared by Ship as a PR and a copy's *Open a
/// pull request* (1.173.0 A3).
pub(crate) fn push_branch_for_pr(wt: &Path, publish: &str, branch: &str, timed_out_tail: &str) -> Result<(), String> {
    let refspec = format!("{publish}:refs/heads/{branch}");
    let push_timeout = crate::ship::ship_push_timeout();
    crate::worktrees::release_push(wt, &refspec, push_timeout).map_err(|e| match e {
        crate::worktrees::ReleasePushFailure::Failed(e) => {
            format!("couldn't push the branch to the remote: {e}")
        }
        crate::worktrees::ReleasePushFailure::TimedOut => format!(
            "couldn't push the branch to the remote: `git push origin {branch}` did not finish \
             within {} and was stopped. It may have reached origin before that; {timed_out_tail}",
            crate::ship::describe_bound(push_timeout)
        ),
    })
}

/// Ship's `gh pr create --base <base> --head <branch>` on origin's
/// repository (`origin_repo`, R10), the body on stdin (`--body-file -`,
/// R12); a pull request that already exists for the branch is linked
/// instead (`gh pr view`). Shared by Ship as a PR and a copy's *Open a pull
/// request* (1.173.0 A3). Errors start with [`PR_OPEN_FAILED`].
pub(crate) fn open_branch_pr(
    gh: &str,
    wt: &Path,
    base: &str,
    branch: &str,
    title: &str,
    body: &str,
    origin_repo: Option<&str>,
) -> Result<PrOpened, String> {
    // R12 (Challenger): the body goes in on stdin (`--body-file -`), never
    // as an argument — a long template would pass Windows' command-line cap.
    let mut create: Vec<&str> = vec!["pr", "create", "--base", base, "--head", branch, "--title", title, "--body-file", "-"];
    if let Some(repo) = origin_repo {
        create.extend(["--repo", repo]);
    }
    // 1.171.0 B3: the branch is on GitHub now — a `gh` that didn't finish
    // (the network dropped, its bound ran out) is said as the pull request
    // not opening, as gh's own refusal is below; the card offers the same
    // ship again (`cardPage.ts::prOpenFailure`).
    let out = ship_gh_with_body(gh, wt, &create, body).map_err(|e| format!("{PR_OPEN_FAILED} {}", e.trim()))?;
    if out.status.success() {
        return Ok(PrOpened::New(String::from_utf8_lossy(&out.stdout).trim().to_string()));
    }
    let err = String::from_utf8_lossy(&out.stderr);
    if err.to_lowercase().contains("already exists") {
        // R10 (Challenger): on origin's repository, as `gh pr create` was.
        let mut view_args: Vec<&str> = vec!["pr", "view", branch, "--json", "url", "--jq", ".url"];
        if let Some(repo) = origin_repo {
            view_args.extend(["--repo", repo]);
        }
        if let Ok(view) = ship_gh(gh, wt, &view_args) {
            let url = String::from_utf8_lossy(&view.stdout).trim().to_string();
            if view.status.success() && !url.is_empty() {
                return Ok(PrOpened::Existing(url));
            }
        }
    }
    Err(format!("{PR_OPEN_FAILED} {}", err.trim()))
}

/// The words a ship's error starts its pull request part with once the
/// branch was pushed (`cardPage.ts::PR_OPEN_FAILED_WORDS`).
pub(crate) const PR_OPEN_FAILED: &str = "opening the pull request failed:";

/// ADR 0006: `Ship with follow-up`. From the fourth changes-requested
/// verdict on a card, with findings open and no P1 among them, the card
/// ships and its open findings become one new card whose brief lists them
/// by id and links the PR; the PR body says `Shipped with N open findings:
/// #<new card>`. The offer is checked again here, whatever the UI showed.
/// The new card is made once: a ship that fails and is tried again reuses
/// it.
#[tauri::command]
pub async fn card_ship_with_follow_up(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    mode: String,
    // R2: *Include them and ship as a PR*, as `card_ship`'s.
    carry_local_commits: Option<bool>,
    // G4 Challenger 1: as `card_ship`'s.
    pr_draft_request: Option<String>,
) -> Result<ShipOutcome, crate::worktrees::ShipError> {
    tauri::async_runtime::spawn_blocking(move || {
        let carry = carry_local_commits.unwrap_or(false);
        let outcome = card_ship_with_follow_up_blocking(
            app.clone(),
            workspace_id.clone(),
            card_id.clone(),
            mode,
            carry,
            pr_draft_request.as_deref(),
        )?;
        // SL-3: the ship lock is released; read a PR auto-merge may have merged.
        crate::pr_merge::kick_read_after_ship(&app, &workspace_id, &card_id, &outcome.kind);
        Ok(outcome)
    })
    .await
    .map_err(|e| format!("ship worker failed: {e}"))?
}

/// Why `Ship with follow-up` is not available for this card, or None.
pub(crate) fn follow_up_refusal(
    card: &KanbanCard,
    ledger: &[crate::review_ledger::LedgerFinding],
) -> Option<String> {
    let count = card.builder.as_ref().map_or(0, |b| b.changes_requested_count);
    if !crate::builder::changes_requested_on_current(card) {
        return Some("Ship with follow-up is for a card whose Reviewer requests changes on its last round.".into());
    }
    if count < crate::review_ledger::SHIP_WITH_FOLLOW_UP_FROM {
        return Some(format!(
            "Ship with follow-up is offered from the fourth changes-requested verdict; this card has had {count}."
        ));
    }
    if ledger.iter().any(|f| f.is_open() && !f.pre_existing && f.severity.as_deref() == Some("P1")) {
        return Some("A P1 finding is open: it has to be fixed before this card ships.".into());
    }
    if !crate::review_ledger::ship_with_follow_up_offered(count, ledger) {
        return Some("No finding is open to carry into a follow-up card.".into());
    }
    None
}

/// What `card_ship_blocking_with` would refuse before merging or pushing a
/// Builder card, checked without side effects: a branch, a worktree, and
/// the worktree exactly at its last snapshot with Verify passed on it. A
/// merge conflict or a failed push can still stop the ship later; the new
/// card then says it has not landed, and the next attempt reuses it.
pub(crate) fn follow_up_ship_preflight(card: &KanbanCard, verify_in_flight: bool) -> Result<(), String> {
    if card.branch_name.is_none() {
        return Err("this card has no branch to ship".into());
    }
    let worktree = card
        .worktree_path
        .as_deref()
        .ok_or_else(|| "This card has no copy of the repository.".to_string())?;
    let wt = Path::new(worktree);
    if !wt.is_dir() {
        return Err(format!("The card's copy of the repository is gone ({worktree}).").into());
    }
    crate::builder::require_verified_snapshot(card, wt, verify_in_flight)
}

/// Push the follow-up card's brief to its issue now instead of at the next
/// Sync, as Sync would: under the board-pass lock (a Sync or migration that
/// holds it pushes the card itself — it is marked pending), and
/// acknowledged with `github_sync::stamp_pushed`, which clears
/// `sync_pending` only when the card still holds what went up. An edit made
/// meanwhile stays pending and is never overwritten by the next pull.
fn push_follow_up_brief(store: &KanbanStore, repo: &str, workspace_id: &str, card_id: &str) {
    let lock = crate::github_sync::board_pass_lock(workspace_id);
    let _pass = match lock.try_lock() {
        Ok(guard) => guard,
        Err(std::sync::TryLockError::Poisoned(p)) => p.into_inner(),
        Err(std::sync::TryLockError::WouldBlock) => return,
    };
    let Ok(uploaded) = store.get_card(workspace_id, card_id) else {
        return;
    };
    let Some(number) = uploaded.gh_issue_number else {
        return;
    };
    // 1.173.0 (C2, Challenger 1): the claim marker GitHub has now.
    let (body, claim) = match crate::device_claim::rebuilt_body(repo, number, &uploaded) {
        Ok(rebuilt) => rebuilt,
        Err(e) => {
            log::warn!("ship: the follow-up card's issue was not read ({e}); Sync retries it");
            let _ = store.set_github_sync(workspace_id, card_id, None, Some(true), None);
            return;
        }
    };
    match crate::github::issue_edit_body(repo, number, &body) { // D3: the brief alone
        Ok(_) => {
            let mine = crate::device_claim::this_id_for(repo);
            let _ = store.set_gh_claim(workspace_id, card_id, claim, mine.as_deref());
            if let Err(e) = crate::github_sync::stamp_pushed(store, workspace_id, &uploaded, number) {
                log::warn!("ship: could not acknowledge the follow-up card's issue update: {e}");
            }
        }
        Err(e) => log::warn!("ship: the follow-up card's issue was not updated ({e}); Sync retries it"),
    }
}

/// How the PR body and the receipt name the follow-up card: its issue,
/// or its title in quotes on a board without issues.
fn follow_up_card_ref(card: &KanbanCard) -> String {
    match card.gh_issue_number {
        Some(number) => format!("#{number}"),
        None => format!("\"{}\"", card.title),
    }
}

/// The follow-up card's identity for this attempt: an earlier attempt's
/// card id is kept (never a second card), a new one is chosen otherwise;
/// the findings it carries are always the ledger's open ones now.
pub(crate) fn follow_up_identity(
    known: Option<crate::kanban::FollowUpCard>,
    carried: &[&crate::review_ledger::LedgerFinding],
    title: &str,
) -> crate::kanban::FollowUpCard {
    let mut follow = known.unwrap_or_else(|| crate::kanban::FollowUpCard {
        card_id: uuid::Uuid::new_v4().to_string(),
        card_ref: format!("\"{title}\""),
        finding_ids: Vec::new(),
        shipped: false,
    });
    follow.finding_ids = carried.iter().map(|finding| finding.id.clone()).collect();
    follow
}

type CardLocks = std::collections::HashMap<(String, String), std::sync::Arc<std::sync::Mutex<()>>>;

/// GH #209: one guard per card around making its follow-up card, so a
/// double press or a second window cannot make two cards (or two issues).
fn follow_up_lock(workspace_id: &str, card_id: &str) -> std::sync::Arc<std::sync::Mutex<()>> {
    static LOCKS: std::sync::LazyLock<std::sync::Mutex<CardLocks>> =
        std::sync::LazyLock::new(Default::default);
    LOCKS
        .lock()
        .unwrap_or_else(|p| p.into_inner())
        .entry((workspace_id.to_string(), card_id.to_string()))
        .or_default()
        .clone()
}

/// GH #209 review 1: the refusal a second `Ship with follow-up` of a card
/// gets while the first is still running (a second window, a double press).
pub(crate) const FOLLOW_UP_SHIP_IN_FLIGHT: &str =
    "This card is already shipping with a follow-up — in this window or another. Wait for that to finish; it makes the follow-up card.";

/// GH #209 review 1: one `Ship with follow-up` of a card at a time. Held for
/// the whole command — making the follow-up card, the ship, and the receipt
/// `on_landed` writes — so a second call can never write its stale view of
/// the follow-up (`shipped: false`, the pre-ship brief) over the first
/// call's receipt. Released on drop.
pub(crate) struct FollowUpShipClaim {
    key: (String, String),
}

fn follow_up_ships_in_flight() -> &'static std::sync::Mutex<std::collections::HashSet<(String, String)>> {
    static IN_FLIGHT: std::sync::LazyLock<std::sync::Mutex<std::collections::HashSet<(String, String)>>> =
        std::sync::LazyLock::new(Default::default);
    &IN_FLIGHT
}

impl FollowUpShipClaim {
    /// The claim, or the refusal when a ship with follow-up of this card is
    /// already running. Never waits.
    pub(crate) fn take(workspace_id: &str, card_id: &str) -> Result<Self, String> {
        let key = (workspace_id.to_string(), card_id.to_string());
        let mut in_flight = follow_up_ships_in_flight().lock().unwrap_or_else(|p| p.into_inner());
        if !in_flight.insert(key.clone()) {
            return Err(FOLLOW_UP_SHIP_IN_FLIGHT.to_string());
        }
        Ok(Self { key })
    }
}

impl Drop for FollowUpShipClaim {
    fn drop(&mut self) {
        follow_up_ships_in_flight()
            .lock()
            .unwrap_or_else(|p| p.into_inner())
            .remove(&self.key);
    }
}

/// The receipt of a landed ship with follow-up: the follow-up card's brief
/// becomes `receipt` (marked for Sync on a GitHub board) and the shipped card
/// records its follow-up as shipped. Runs inside the ship's
/// [`FollowUpShipClaim`], so no second call can write over it.
pub(crate) fn record_follow_up_landed(
    kanban: &KanbanStore,
    workspace_id: &str,
    card_id: &str,
    follow: &crate::kanban::FollowUpCard,
    receipt: &str,
    github: bool,
) {
    let _ = kanban.with_card(workspace_id, &follow.card_id, |c| {
        c.notes = Some(receipt.to_string());
        if github {
            c.sync_pending = true;
        }
        Ok(())
    });
    let mut shipped = follow.clone();
    shipped.shipped = true;
    let _ = kanban.with_card(workspace_id, card_id, |c| {
        if let Some(b) = c.builder.as_mut() {
            b.follow_up = Some(shipped.clone());
        }
        Ok(())
    });
}

/// How the follow-up card reaches its GitHub issue: the live path calls
/// `gh_sync_card_create` / `gh_sync_card_edit`; tests pass stubs.
pub(crate) struct FollowUpIssue<'a> {
    pub create: &'a dyn Fn(&KanbanCard),
    pub edit: &'a dyn Fn(&KanbanCard),
}

/// Make (or reuse) the follow-up card of `card_id` and record it on the
/// card, under the card's follow-up guard (GH #209). The card's recorded
/// follow-up is read again under the guard, so a second concurrent call
/// finds the first call's card and reuses it: exactly one card and one
/// issue create, and both calls return the same follow-up. `issue` is None
/// on a board without GitHub.
#[allow(clippy::too_many_arguments)]
pub(crate) fn ensure_follow_up_card(
    kanban: &KanbanStore,
    workspace_id: &str,
    card_id: &str,
    carried: &[&crate::review_ledger::LedgerFinding],
    title: &str,
    brief: &str,
    // 1.174.0 (DS4 round 1): who makes it and the Builder a new card starts
    // with — stamped like every other new card (`stamp_new_card`).
    settings: Option<&crate::settings::Settings>,
    issue: Option<&FollowUpIssue<'_>>,
) -> Result<crate::kanban::FollowUpCard, String> {
    let lock = follow_up_lock(workspace_id, card_id);
    let _guard = lock.lock().unwrap_or_else(|p| p.into_inner());
    // Re-read under the guard: what an earlier (or concurrent) call
    // recorded decides the identity, never the copy read before it.
    let card = kanban.get_card(workspace_id, card_id)?;
    // The new card's identity is saved on this card before the new card
    // exists, so no crash can leave a card the next attempt does not
    // recognise: an attempt that finds the id and no card creates it under
    // that id; one that finds both reuses it.
    let known = card.builder.as_ref().and_then(|b| b.follow_up.clone());
    // A retry after the card landed (the go-live step failed, say) keeps the
    // receipt already on the new card: its brief links what shipped.
    let already_landed = known.as_ref().is_some_and(|f| f.shipped);
    let mut follow = follow_up_identity(known, carried, title);
    kanban.with_card(workspace_id, card_id, |c| {
        if let Some(b) = c.builder.as_mut() {
            b.follow_up = Some(follow.clone());
        }
        Ok(())
    })?;
    let existing = kanban.get_card(workspace_id, &follow.card_id).ok();
    let created = match existing {
        Some(_) => {
            // Reused: its brief follows the current ledger, unless the card
            // already landed and the brief is the receipt.
            let mut updated: Option<KanbanCard> = None;
            kanban.with_card(workspace_id, &follow.card_id, |c| {
                if !already_landed {
                    c.notes = Some(brief.to_string());
                }
                updated = Some(c.clone());
                Ok(())
            })?;
            let updated = updated.ok_or_else(|| "the follow-up card vanished".to_string())?;
            if let Some(issue) = issue {
                if updated.gh_issue_number.is_some() {
                    if !already_landed {
                        (issue.edit)(&updated);
                    }
                } else {
                    (issue.create)(&updated);
                }
            }
            updated
        }
        None => {
            let mut new_card = KanbanCard::new(
                follow.card_id.clone(),
                workspace_id.to_string(),
                title.to_string(),
                Some(brief.to_string()),
                KanbanColumnId::Todo,
            );
            if let Some(settings) = settings {
                stamp_new_card(&mut new_card, settings);
            }
            // 1.173.0 (B3 Challenger 1): the follow-up stays in the card's area.
            new_card.area = crate::card_area::inherited_area(&card);
            let created = kanban.create_card(workspace_id, new_card)?;
            if let Some(issue) = issue {
                (issue.create)(&created);
            }
            created
        }
    };
    // N19: the follow-up link, both ways, as `Follow up` records it.
    // Idempotent; a failure only loses the link, never the ship.
    if let Err(e) = kanban.link_follow_up(workspace_id, card_id, &created.id) {
        log::warn!("ship: could not link the follow-up card: {e}");
    }
    let created = kanban.get_card(workspace_id, &created.id)?;
    // On a GitHub board the PR must name the issue: nothing ships until the
    // new card has one (Sync may hold the board, or GitHub may have failed).
    // The card and its id are kept, so the next attempt reuses them.
    if issue.is_some() && created.gh_issue_number.is_none() {
        return Err(format!(
            "The follow-up card \"{}\" was made, but its GitHub issue isn't yet — Sync may be running, or GitHub failed. Nothing was shipped. Try Ship with follow-up again; it reuses that card.",
            created.title
        ));
    }
    follow.card_ref = follow_up_card_ref(&created);
    kanban.with_card(workspace_id, card_id, |c| {
        if let Some(b) = c.builder.as_mut() {
            b.follow_up = Some(follow.clone());
        }
        Ok(())
    })?;
    Ok(follow)
}

fn card_ship_with_follow_up_blocking(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    mode: String,
    carry_local_commits: bool,
    pr_draft_request: Option<&str>,
) -> Result<ShipOutcome, crate::worktrees::ShipError> {
    // GH #209 review 1: first, before anything is read — held to the end.
    let _claim = FollowUpShipClaim::take(&workspace_id, &card_id)?;
    let kanban = app.state::<KanbanStore>();
    let workspaces = app.state::<WorkspaceStore>();
    let reviewers = app.state::<crate::reviewer::ReviewerRegistry>();
    let card = kanban.get_card(&workspace_id, &card_id)?;
    let ledger = reviewers
        .ledger(&workspace_id, &card_id)
        .map(|ledger| ledger.findings)
        .unwrap_or_default();
    if let Some(refusal) = follow_up_refusal(&card, &ledger) {
        return Err(refusal.into());
    }
    // 1.173.0 (B3 Challenger 1): the card's area, before the follow-up card
    // or its issue exist — Held, an unlisted area or none chosen ship
    // nothing and make nothing.
    crate::card_area::config_for_card(&app.state::<ProjectConfigStore>(), &workspace_id, &card)?;
    // Ship's own gate, checked before the new card and its issue exist: a
    // ship it would refuse must not leave a follow-up card behind.
    {
        let verify = app.state::<VerifyRegistry>();
        follow_up_ship_preflight(&card, verify.is_inflight(&workspace_id, &card_id))?;
    }
    // R2: so is Ship as a PR's stop over commits not on GitHub yet, and
    // R10's refusal of an origin that isn't on GitHub.
    if let Some(wt) = card.worktree_path.as_deref().map(PathBuf::from).filter(|wt| wt.is_dir()) {
        // G1: the press as `card_ship_blocking_with` resolves it (it is
        // handed the press itself, to know what to ask GitHub for).
        if let Some(why) = ship_it_origin_refusal(&workspaces, &workspace_id, &wt, &mode) {
            return Err(why.into());
        }
        let (mode, _) = ship_press_for(&workspaces, &workspace_id, &wt, &mode);
        if let Some(why) = pr_origin_refusal(&wt, &mode) {
            return Err(why.into());
        }
        pr_github_preflight(&workspaces, &workspace_id, &wt, &mode)?;
        let project_config = app.state::<ProjectConfigStore>();
        if let Some(stop) = pr_carry_stop(&workspaces, &project_config, &workspace_id, &card, &wt, &mode, carry_local_commits)? {
            return Ok(stop);
        }
    }
    // What the new card carries is read from the ledger now, on every
    // attempt: a review between a failed ship and its retry may have closed
    // some findings and raised others.
    let carried = crate::review_ledger::follow_up_findings(&ledger);
    let repo = workspace_github_target(&workspaces, &workspace_id);
    // OB-7b: the follow-up's issue calls and the ship's PR flow (which
    // reuses this scope) run as the workspace's GitHub account.
    let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
    let mut title = format!("Follow-up: {}", card.title.trim());
    if title.chars().count() > 120 {
        title = format!("{}…", title.chars().take(119).collect::<String>());
    }
    let brief = crate::review_ledger::follow_up_brief(&card.title, &carried, None);
    // The Team gate on every attempt: access may have lapsed, or the board
    // become GitHub-backed, since an earlier one.
    {
        let license = app.state::<crate::license::LicenseStore>();
        team_gate_github_card_write(&workspaces, &license, &workspace_id, true)?;
    }
    let settings_now = app.state::<SettingsStore>().snapshot();
    let sync_create = |c: &KanbanCard| {
        if let Some(repo) = &repo {
            gh_sync_card_create(&kanban, repo, &workspace_id, c);
            // C1: the follow-up keeps the card's area, and its label.
            gh_push_area_label_soon(&app, &workspace_id, &c.id);
        }
    };
    let sync_edit = |c: &KanbanCard| {
        if let Some(repo) = &repo {
            gh_sync_card_edit(&kanban, repo, &workspace_id, None, c, true, false);
        }
    };
    let issue = FollowUpIssue { create: &sync_create, edit: &sync_edit };
    let mut follow = match ensure_follow_up_card(
        &kanban,
        &workspace_id,
        &card_id,
        &carried,
        &title,
        &brief,
        Some(&settings_now),
        repo.as_ref().map(|_| &issue),
    ) {
        Ok(made) => made,
        Err(e) => {
            crate::kanban::emit_kanban_changed(&app, &workspace_id);
            return Err(e.into());
        }
    };
    crate::kanban::emit_kanban_changed(&app, &workspace_id);
    let line = crate::review_ledger::follow_up_pr_line(carried.len(), &follow.card_ref);
    // The receipt is written the moment the card has landed, locally and
    // before the go-live step: the new card's brief links what shipped and
    // is marked for Sync, and this card records the follow-up as shipped. A
    // go-live that fails or relaunches Ply cannot lose it; Sync pushes the
    // brief to the issue if the edit below never runs.
    let landed: std::cell::RefCell<Option<String>> = std::cell::RefCell::new(None);
    let on_landed = |shipped_as: &str| {
        // Serialized with Sync: a reconcile holds this lock for its whole
        // pass, so it cannot apply a patch it planned from the old brief
        // over the receipt.
        let lock = crate::github_sync::board_pass_lock(&workspace_id);
        let _pass = lock.lock().unwrap_or_else(|p| p.into_inner());
        let brief = crate::review_ledger::follow_up_brief(&card.title, &carried, Some(shipped_as));
        record_follow_up_landed(&kanban, &workspace_id, &card_id, &follow, &brief, repo.is_some());
        *landed.borrow_mut() = Some(shipped_as.to_string());
    };
    let result = card_ship_blocking_with(
        app.clone(),
        workspace_id.clone(),
        card_id.clone(),
        mode,
        carry_local_commits,
        Some(line),
        pr_draft_request,
        &on_landed,
    );
    if landed.borrow().is_some() {
        follow.shipped = true;
        // Optional: mirror the brief to the issue now; the card stays marked
        // for Sync until the edit is known to have landed.
        if let Some(repo) = &repo {
            push_follow_up_brief(&kanban, repo, &workspace_id, &follow.card_id);
        }
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
    }
    let mut outcome = result?;
    outcome.follow_up = Some(follow);
    Ok(outcome)
}

fn short_sha(sha: &str) -> &str {
    &sha[..sha.len().min(8)]
}

/// Crash recovery: commit the worktree's uncommitted edits, then start
/// Verify on the resulting commit. `start_verify` runs only once the tree is
/// exactly that commit, so what Verify examines is what a later Ship
/// publishes. Returns the commit's SHA.
fn recovery_flush_and_verify(
    worktree: &Path,
    start_verify: impl FnOnce() -> Result<String, String>,
) -> Result<String, String> {
    crate::worktrees::commit_pending_in_worktree(worktree, SHIP_RECOVERY_COMMIT_MSG)?;
    if crate::worktrees::worktree_is_dirty(worktree)? {
        return Err(
            "Ship could not commit the uncommitted edits for Verify — nothing was published".into(),
        );
    }
    let sha = crate::worktrees::head_sha(worktree)?;
    start_verify().map_err(|e| {
        format!(
            "Ship committed the uncommitted edits as {} but could not start Verify on it ({e}). \
             Nothing was published — run Verify, then Ship",
            short_sha(&sha)
        )
    })?;
    Ok(sha)
}

/// What Ship may publish, decided before anything is merged or pushed.
#[derive(Debug, PartialEq)]
enum ShipDecision {
    /// The exact commit that passed the checks. Ship merges or pushes this
    /// SHA — never the branch — and commits nothing afterwards, so edits
    /// arriving after the decision cannot ride along.
    Publish(String),
    /// A card with no Builder holds uncommitted edits Verify has not passed
    /// on: they need the recovery flush + Verify first.
    NeedsRecovery,
    /// Skills hub H3a (§4.2 "Ship's tree gate"): a skill card's clean HEAD
    /// whose changes since its base are only its skill's two copies and its
    /// link record, decided here on this pinned commit. Verify is *Not
    /// needed*; the gate records that against `tree` before publishing.
    PublishSkillOnly { head: String, tree: String },
}

/// Ship never publishes edits nobody verified.
/// - A Builder card publishes its last build snapshot, verified on that
///   snapshot's own content; anything the Builder changed since is refused.
/// - A card with no Builder may carry uncommitted edits (swarms leave their
///   work uncommitted and are verified in place). If Verify passed on
///   exactly that content they are committed and that commit is published;
///   otherwise they need recovery.
/// - A clean HEAD ships only after a pass on its tree, whatever its subject.
fn ship_decision(
    card: &KanbanCard,
    wt: &Path,
    verify_in_flight: bool,
) -> Result<ShipDecision, String> {
    if card.builder.is_some() {
        crate::builder::require_verified_snapshot(card, wt, verify_in_flight)?;
        return Ok(ShipDecision::Publish(crate::builder::publish_rev(card, "HEAD")));
    }
    if crate::worktrees::worktree_is_dirty(wt)? {
        if verify_in_flight {
            return Err("Verify is running on this card's edits — Ship once it finishes".into());
        }
        let content = crate::worktrees::content_tree_sha(wt)?;
        if crate::verify::verify_result_on(&content, &card.verify_history) != Some(true) {
            return Ok(ShipDecision::NeedsRecovery);
        }
        crate::worktrees::commit_pending_in_worktree(wt, REVIEW_CHECKPOINT_MSG)?;
        let head = crate::worktrees::head_sha(wt)?;
        if crate::worktrees::commit_tree_sha(wt, &head)? != content {
            return Err(
                "The card's copy changed while Ship was committing the checked edits, so nothing was published. Ship again."
                    .into(),
            );
        }
        return Ok(ShipDecision::Publish(head));
    }
    // Any clean HEAD — whatever its subject, whoever committed it — ships
    // only after a pass on its own tree, read from one pinned SHA.
    let head = crate::worktrees::head_sha(wt)?;
    let tree = crate::worktrees::commit_tree_sha(wt, &head)?;
    // Skills hub H3a (§13 C1): a skill card whose commit changes nothing but
    // its skill needs no Verify — decided from the commit itself, never from
    // the card's kind alone. Anything else it changed goes through Verify.
    if let Some(skill) = card.skill_card() {
        let base = card.worktree_base.as_ref().map(|base| base.commit.as_str());
        if !verify_in_flight
            && base.is_some_and(|base| crate::skill_card::card_only(wt, base, &head, skill))
        {
            return Ok(ShipDecision::PublishSkillOnly { head, tree });
        }
    }
    crate::verify::require_verified_commit(&head, &tree, verify_in_flight, &card.verify_history)?;
    Ok(ShipDecision::Publish(head))
}

/// Result of Ship's gate: publish exactly this commit, or stop with an
/// outcome (recovery flush committed, Verify started, nothing published).
enum ShipGate {
    Publish(String),
    /// Skills hub H3a: publish this skill-only commit; Verify was *Not
    /// needed* and the go-live step does not run (§14 Q23).
    PublishSkillOnly(String),
    Pending(ShipOutcome),
}

/// `ship_decision`, plus the recovery path: uncommitted edits Verify has not
/// passed on become a recovery commit, Verify starts on it and
/// `verify_pending` comes back with nothing published.
fn ship_tree_gate(
    app: &tauri::AppHandle,
    workspaces: &WorkspaceStore,
    kanban: &KanbanStore,
    card: &KanbanCard,
    wt: &Path,
) -> Result<ShipGate, String> {
    let verify = app.state::<VerifyRegistry>();
    let in_flight = verify.is_inflight(&card.workspace_id, &card.id);
    match ship_decision(card, wt, in_flight)? {
        ShipDecision::Publish(rev) => Ok(ShipGate::Publish(rev)),
        ShipDecision::PublishSkillOnly { head, tree } => {
            // The verified-tree rule holds: the tree Ship publishes has its
            // entry — *Not needed — only skill files changed*.
            if crate::verify::verify_result_on(&tree, &card.verify_history) != Some(true) {
                kanban.with_card(&card.workspace_id, &card.id, |c| {
                    c.verify_history.push(crate::skill_card::not_needed_entry(&tree));
                    c.verify_status = crate::kanban::VerifyStatus::Passed;
                    Ok(())
                })?;
            }
            Ok(ShipGate::PublishSkillOnly(head))
        }
        ShipDecision::NeedsRecovery => {
            let gate = app.state::<crate::card_execution::CardExecutionGate>();
            let agents = app.state::<AgentRegistry>();
            let swarms = app.state::<SwarmRegistry>();
            let sha = recovery_flush_and_verify(wt, || {
                gate.enqueue_verify(
                    app.clone(),
                    &verify,
                    kanban,
                    workspaces,
                    &agents,
                    &swarms,
                    VerifyRequest {
                        workspace_id: card.workspace_id.clone(),
                        card_id: card.id.clone(),
                        post_outcome_issue: false,
                    },
                )
            })?;
            Ok(ShipGate::Pending(ShipOutcome {
                kind: "verify_pending".into(),
                recovery_sha: Some(sha),
                ..Default::default()
            }))
        }
    }
}

/// v1.31.0 (Cycle 1): reject-with-feedback — dispatch a follow-up swarm
/// into the card's existing worktree to address the rejected hunks. The
/// template is adaptive: a coordinator-mode card reuses its own template;
/// a sequential-template card runs the lightweight `review-followup`
/// builtin. Returns the new swarm id.
#[tauri::command]
pub fn card_review_request_changes(
    app: tauri::AppHandle,
    kanban: State<'_, KanbanStore>,
    templates: State<'_, SwarmTemplatesStore>,
    verify: State<'_, VerifyRegistry>,
    card_execution: State<'_, crate::card_execution::CardExecutionGate>,
    workspace_id: String,
    card_id: String,
    rejections: Vec<ReviewRejection>,
) -> Result<String, String> {
    if rejections.is_empty() {
        return Err("no rejected hunks — nothing to send back to the swarm".to_string());
    }
    let card = kanban.get_card(&workspace_id, &card_id)?;
    // G4 (launch D8): a follow-up swarm only on a card that ran one.
    if let Some(why) = review::followup_swarm_refusal(&card) {
        return Err(why.to_string());
    }
    let worktree = card
        .worktree_path
        .clone()
        .ok_or_else(|| "This card has no copy of the repository, so it can't run a follow-up.".to_string())?;
    let worktree_path = PathBuf::from(&worktree);
    if !worktree_path.exists() {
        return Err(format!(
            "The card's copy of the repository is gone ({worktree})."
        ));
    }

    // Adaptive template choice: reuse a coordinator template so a
    // coordinator-origin card stays coordinator-driven; otherwise the
    // lightweight single-builder `review-followup` builtin.
    let followup_template = match card.swarm_template_id.as_deref() {
        Some(orig) => {
            let is_coordinator = templates
                .get(orig)?
                .map(|t| t.coordinator)
                .unwrap_or(false);
            if is_coordinator {
                orig.to_string()
            } else {
                "review-followup".to_string()
            }
        }
        None => "review-followup".to_string(),
    };

    let goal = review::build_followup_prompt(&rejections);
    let decisions: Vec<crate::kanban::ReviewDecision> = rejections
        .iter()
        .map(|r| crate::kanban::ReviewDecision {
            path: r.path.clone(),
            hunk_header: r.hunk_header.clone(),
            status: crate::kanban::ReviewDecisionStatus::Rejected,
            feedback: Some(r.feedback.clone()),
        })
        .collect();
    let swarm = card_execution.run_attempt(
        &verify,
        &kanban,
        &workspace_id,
        &card_id,
        crate::card_execution::AuthorizationKind::ReviewFollowup,
        || {
            crate::swarms::swarm_start(
                &app,
                &workspace_id,
                &followup_template,
                &goal,
                std::collections::HashMap::new(),
                Some(worktree_path),
                crate::swarms::SwarmKind::Card,
            )
        },
        |swarm| {
            kanban.mark_review_followup(
                &workspace_id,
                &card_id,
                &swarm.id,
                decisions,
            )
        },
        |swarm| {
            crate::swarms::abort_unlinked_start(
                &app,
                &swarm.id,
                "card review follow-up link failed",
            );
        },
    )?;
    crate::kanban::emit_kanban_changed(&app, &workspace_id);
    Ok(swarm.id)
}

/// G4 (launch D8): the changes a person asked for on a card, in the words
/// a follow-up swarm got (`review::build_followup_prompt`), for the frontend
/// to send to the card's Builder session when the card never ran a swarm.
#[tauri::command]
pub fn card_review_followup_message(rejections: Vec<ReviewRejection>) -> Result<String, String> {
    if rejections.is_empty() {
        return Err("Nothing was marked as wrong, so there is nothing to send.".to_string());
    }
    Ok(review::build_followup_prompt(&rejections))
}

/// v1.31.0 (Outcome screen): the backend half of the outcome screen — the
/// reviewer leg's verdict + critique (scanned from the linked swarm's run
/// artifacts) and the changed-file count. The FE composes the rest (card
/// goal, swarm status, verify status) from stores it already holds.
///
/// v1.38.0 (Recon-aware Outcome): also returns the recon `summary_md` +
/// `is_recon` + `recon_verdict_negative` flags so the FE can render a
/// markdown report variant for `ux-audit` / `design` swarm outcomes
/// instead of the diff/ship/verify surface.
/// GH #99: a Builder card's branch tip (its worktree HEAD) and the commits
/// on it since the last completed Challenger review. Cheap and read-only:
/// the card polls it while open, so a commit made after a review shows up
/// without any card state changing.
#[derive(Debug, Clone, Default, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ReviewTipFacts {
    pub branch_tip: Option<String>,
    pub commits_since_review: Option<u32>,
}

/// SP-D: the Board and the List read it for every card with an open Builder
/// session; its git reads run off the main thread.
#[tauri::command(async)]
pub fn card_review_tip(
    kanban: State<'_, KanbanStore>,
    workspace_id: String,
    card_id: String,
) -> Result<ReviewTipFacts, String> {
    let card = kanban.get_card(&workspace_id, &card_id)?;
    let Some(wt) = card
        .worktree_path
        .as_deref()
        .map(PathBuf::from)
        .filter(|p| p.is_dir())
    else {
        return Ok(ReviewTipFacts::default());
    };
    let (branch_tip, commits_since_review) = crate::builder::review_tip_facts(&card, &wt);
    Ok(ReviewTipFacts {
        branch_tip,
        commits_since_review,
    })
}

/// 1.169.1 (R2): the commits this card's start holds that GitHub's target
/// doesn't, read now — the card's "Started from <target> on this Mac"
/// line. `None` for a card with no copy, started from GitHub's own target,
/// or whose start GitHub now has. Read-only; no fetch.
#[tauri::command(async)]
pub fn card_local_base_commits(
    workspaces: State<'_, WorkspaceStore>,
    kanban: State<'_, KanbanStore>,
    project_config: State<'_, ProjectConfigStore>,
    workspace_id: String,
    card_id: String,
) -> Result<Option<crate::review::LocalCommits>, String> {
    let card = kanban.get_card(&workspace_id, &card_id)?;
    if card.worktree_path.as_deref().map(PathBuf::from).is_none_or(|p| !p.is_dir()) {
        return Ok(None);
    }
    let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
    // 1.173.0 (B3): the card's area's branch.
    let target = crate::card_area::reading_branch(&project_config, &workspace_id, &card);
    Ok(pr_carries_local_commits(&ws_cwd, &card, &target))
}

// R10 (Challenger): off the UI thread — reading origin may run `ssh -G`.
#[tauri::command(async)]
pub fn card_outcome(
    kanban: State<'_, KanbanStore>,
    swarms: State<'_, SwarmRegistry>,
    agents: State<'_, AgentRegistry>,
    project_config: State<'_, ProjectConfigStore>,
    swarm_templates: State<'_, SwarmTemplatesStore>,
    workspace_id: String,
    card_id: String,
) -> Result<CardOutcome, String> {
    let card = kanban.get_card(&workspace_id, &card_id)?;

    // Read-only: Outcome never commits. Ship decides what is committed and
    // whether it was verified (`ship_tree_gate`); a flush here would turn a
    // Builder's post-Build-done edits into a commit nobody verified.
    let worktree_dir = card
        .worktree_path
        .as_deref()
        .map(PathBuf::from)
        .filter(|p| p.is_dir() && card.branch_name.is_some());
    let origin = worktree_dir.as_deref().map(pr_origin);
    // 1.173.0 (B3): measured from the card's area's branch.
    let card_target = crate::card_area::reading_branch(&project_config, &workspace_id, &card);
    let files_changed = worktree_dir.as_deref().map_or(0, |wt| {
        crate::worktrees::card_changed_file_count(wt, card.worktree_base.as_ref(), &card_target)
    });
    // GH #191: nothing left to ship because it's already in origin/<target>
    // says so, instead of "no changes yet".
    let already_in = match (worktree_dir.as_deref(), card.branch_name.as_deref()) {
        (Some(wt), Some(branch)) if files_changed == 0 => {
            crate::worktrees::card_already_in_origin(
                wt,
                branch,
                card.worktree_base.as_ref().map(|b| b.commit.as_str()),
                &card_target,
            )
        }
        _ => None,
    };
    let (ship_blocked_reason, recovery_sha) = match worktree_dir.as_deref() {
        Some(wt) if card.builder.is_some() => {
            (crate::builder::require_at_last_snapshot(&card, wt).err(), None)
        }
        Some(wt) => (
            None,
            crate::worktrees::head_subject(wt)
                .ok()
                .filter(|s| crate::commit_message::is_ship_recovery(s))
                .and_then(|_| crate::worktrees::head_sha(wt).ok()),
        ),
        None => (None, None),
    };

    // Reviewer verdict — scan the linked swarm's runs for the leg whose
    // artifact carries a `verdict` (last one wins — the most recent pass).
    // v1.38.0: same scan also captures the recon `summary_md` (with a
    // structured-field fallback for pre-v1.38 runs) and the verdict's
    // sign for the negative-verdict warning band.
    let mut reviewer_verdict: Option<String> = None;
    let mut reviewer_critique: Option<String> = None;
    let mut recon_summary_md: Option<String> = None;
    let mut recon_artifact_fallback: Option<serde_json::Value> = None;
    if let Some(swarm_id) = &card.linked_swarm_id {
        if let Some(swarm) = swarms.get(swarm_id) {
            for run_id in &swarm.run_ids {
                if let Ok(run) = agents.get_run(run_id) {
                    if let Some(artifact) = &run.swarm_artifact {
                        if let Some(v) = artifact.get("verdict").and_then(|v| v.as_str()) {
                            reviewer_verdict = Some(v.to_string());
                            reviewer_critique = artifact
                                .get("critique")
                                .and_then(|c| c.as_str())
                                .map(|s| s.to_string());
                        }
                        if let Some(md) = artifact.get("summary_md").and_then(|v| v.as_str()) {
                            recon_summary_md = Some(md.to_string());
                        }
                        // Stash the latest artifact so we can synthesize a
                        // fallback summary if `summary_md` is absent.
                        recon_artifact_fallback = Some(artifact.clone());
                    }
                }
            }
        }
    }

    // v1.108.0 (Builder/Challenger): a card built by a live Builder has no
    // swarm reviewer; its verdict comes from the Challenger's independent
    // review of the latest snapshot.
    let mut reviewer_source: Option<String> = None;
    let mut reviewer_provider: Option<String> = None;
    let mut reviewer_degraded = false;
    if reviewer_verdict.is_none() {
        if let Some(review) = card.builder.as_ref().and_then(|b| b.review.as_ref()) {
            if review.status == "done" {
                reviewer_verdict = review.verdict.clone();
                reviewer_critique = review.excerpt.clone();
                reviewer_source = Some("challenger".into());
                reviewer_provider = Some(review.provider.clone());
                reviewer_degraded = review.degraded;
            }
        }
    } else {
        reviewer_source = Some("swarm".into());
    }

    // Recon detection — resolve the swarm template and check its
    // `output_kind`. Missing template id (legacy card) or unknown
    // template id (template was deleted) → not recon.
    let is_recon = match card.swarm_template_id.as_deref() {
        Some(id) => swarm_templates
            .get(id)
            .ok()
            .flatten()
            .map(|t| matches!(t.output_kind, crate::swarm_templates::OutputKind::Recon))
            .unwrap_or(false),
        None => false,
    };

    // Fallback summary synthesis — for pre-v1.38 recon runs whose agent
    // didn't emit `summary_md`, build a minimal markdown report from the
    // structured artifact fields (verdict / critique / ux_issues etc.)
    // so the Outcome screen is useful before the user reseeds presets.
    if is_recon && recon_summary_md.is_none() {
        if let Some(artifact) = &recon_artifact_fallback {
            recon_summary_md = synthesize_recon_summary_md(artifact);
        }
    }

    let recon_verdict_negative = is_recon
        && reviewer_verdict.as_deref()
            .map(|v| is_negative_verdict(v))
            .unwrap_or(false);

    let verify_configured = project_config
        .get(&workspace_id)
        .and_then(|c| c.verify_pipeline)
        .map_or(false, |p| !p.is_empty());

    Ok(CardOutcome {
        reviewer_verdict,
        reviewer_critique,
        reviewer_source,
        reviewer_provider,
        reviewer_degraded,
        files_changed,
        verify_configured,
        is_recon,
        recon_summary_md,
        recon_verdict_negative,
        ship_blocked_reason,
        recovery_sha,
        already_in,
        // CL-11: the card offers Ship as a PR only where one can be opened
        // (R10: an `origin` on GitHub, or a host it can't tell isn't), and
        // says where the origin is if not.
        has_remote: origin.as_ref().map(PrOrigin::offers_pr),
        origin_unreadable: match &origin {
            Some(PrOrigin::Unreadable(url)) => Some(url.clone()),
            _ => None,
        },
        origin_host: match origin {
            Some(PrOrigin::Elsewhere(host)) => Some(host),
            _ => None,
        },
    })
}

/// Where a pull request would be opened: Ship as a PR pushes to `origin`
/// and asks `gh` for the pull request, so only `origin` counts. Other
/// remotes (`upstream`, …) are never used.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum PrOrigin {
    /// No `origin` (or not a repository): `card_ship` merges here, flagged.
    None,
    /// An `origin` on GitHub (github.com, www.github.com, ssh.github.com, or
    /// an SSH alias whose `ssh -G` hostname is one of them). `repo`: its
    /// `owner/name` (for `gh pr create --repo`); None only for a test
    /// fixture's local origin.
    GitHub { repo: Option<String> },
    /// R10 (Challenger): a host Plyloft can't tell — GitHub Enterprise, an
    /// SSH alias it can't resolve. As before R10: the pull request is
    /// offered and `gh` tries.
    Unknown(String),
    /// An `origin` known not to be GitHub (GitLab, Bitbucket, a local path
    /// as "this computer"): no pull request is offered; Ship as a PR is
    /// refused before any push.
    Elsewhere(String),
    /// An `origin` on GitHub whose path isn't `owner/name`
    /// (`https://github.com/o`) — the URL without credentials. Refused.
    Unreadable(String),
}

impl PrOrigin {
    /// Ship as a PR is offered (and pushes): GitHub, or a host that may be.
    pub(crate) fn offers_pr(&self) -> bool {
        matches!(self, PrOrigin::GitHub { .. } | PrOrigin::Unknown(_))
    }
}

/// A remote URL without its userinfo (`https://user:pa/ss@host/o/r` →
/// `https://host/o/r`): the userinfo ends at the last `@` that a host and a
/// path follow, so a password with an unencoded `/` or `@` is stripped
/// whole. scp-like `git@host:o/r` is left as it is (no secret in it).
fn strip_remote_userinfo(url: &str) -> String {
    let url = url.trim();
    let Some((scheme, rest)) = url.split_once("://") else {
        return url.to_string();
    };
    let head_end = rest.find(['?', '#']).unwrap_or(rest.len());
    if let Some(at) = rest[..head_end].rfind('@') {
        if rest[at + 1..head_end].contains('/') {
            return format!("{scheme}://{}", &rest[at + 1..]);
        }
    }
    // An `@` only in the path (or none): the authority ends at the first `/`.
    let authority_end = rest.find(['/', '?', '#']).unwrap_or(rest.len());
    let (authority, path) = rest.split_at(authority_end);
    let host = authority.rsplit_once('@').map_or(authority, |(_, host)| host);
    format!("{scheme}://{host}{path}")
}

/// The host a remote URL names (scheme or scp-like form), lowercased, its
/// userinfo stripped first ([`strip_remote_userinfo`]).
fn remote_host(url: &str) -> Option<String> {
    let url = strip_remote_userinfo(url);
    let authority = match url.split_once("://") {
        Some((_, rest)) => rest.split(['/', '?', '#']).next()?,
        None => url.split_once(':')?.0,
    };
    let host = authority.rsplit('@').next()?;
    let host = match host.strip_prefix('[') {
        Some(v6) => v6.split(']').next()?,
        None => host.split(':').next()?,
    };
    (!host.is_empty()).then(|| host.to_ascii_lowercase())
}

/// The path after the host (`o/r.git`), for an SSH alias resolved to GitHub.
fn remote_path(url: &str) -> Option<String> {
    let url = strip_remote_userinfo(url);
    match url.split_once("://") {
        Some((_, rest)) => rest.split_once('/').map(|(_, path)| path.to_string()),
        None => url.split_once(':').map(|(_, path)| path.to_string()),
    }
}

/// Hosts known not to be GitHub: refused rather than tried.
fn known_not_github(host: &str) -> bool {
    host == "gitlab.com" || host.ends_with(".gitlab.com") || host == "bitbucket.org"
}

/// Pure: what kind of pull-request origin `url` (as `git remote get-url
/// origin` gives it, insteadOf applied) is. `ssh_hostname` resolves an SSH
/// alias to the host it connects to ([`ssh_config_hostname`] in the app).
fn classify_pr_origin_with(url: &str, ssh_hostname: &dyn Fn(&str) -> Option<String>) -> PrOrigin {
    let url = url.trim();
    if url.is_empty() {
        return PrOrigin::None;
    }
    if crate::review_base::is_local_url(url) {
        // Test fixtures push to local bare origins; there they stand in for
        // GitHub (`review_base`'s rule). Production never opens a pull
        // request on one.
        if crate::review_base::local_origin_trusted() {
            return PrOrigin::GitHub { repo: None };
        }
        return PrOrigin::Elsewhere("this computer".into());
    }
    let clean = strip_remote_userinfo(url);
    let Some(host) = remote_host(&clean) else {
        return PrOrigin::Unknown("another host".into());
    };
    if crate::team::is_github_host(&host) {
        return match crate::team::origin_slug(&clean) {
            Some(slug) => PrOrigin::GitHub { repo: Some(slug) },
            None => PrOrigin::Unreadable(clean),
        };
    }
    if known_not_github(&host) {
        return PrOrigin::Elsewhere(host);
    }
    // An SSH alias (`Host gh-work` in ~/.ssh/config) may connect to GitHub.
    let ssh_form = !clean.contains("://") || clean.to_ascii_lowercase().starts_with("ssh://");
    if ssh_form {
        if let Some(real) = ssh_hostname(&host).map(|h| h.trim().to_ascii_lowercase()) {
            if crate::team::is_github_host(&real) {
                let slug = remote_path(&clean)
                    .and_then(|path| crate::team::origin_slug(&format!("https://github.com/{path}")));
                return match slug {
                    Some(slug) => PrOrigin::GitHub { repo: Some(slug) },
                    None => PrOrigin::Unreadable(clean),
                };
            }
            if known_not_github(&real) {
                return PrOrigin::Elsewhere(real);
            }
        }
    }
    PrOrigin::Unknown(host)
}

/// The host `ssh` connects to for `alias` (`ssh -G <alias>`'s `hostname`).
/// An answer is kept for the app's life; no answer (ssh missing, slow or
/// silent) is asked again after [`SSH_G_RETRY`]. Bounded (3 s), with the
/// cached PATH, in its own process group registered for exit cleanup.
/// Windows: the system OpenSSH (`ssh.exe`) when it is on PATH, else None.
fn ssh_config_hostname(alias: &str) -> Option<String> {
    use std::collections::HashMap;
    use std::sync::{Mutex, OnceLock};
    // Only a plain host name is passed to ssh (never an option).
    if alias.is_empty()
        || alias.starts_with('-')
        || !alias.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_'))
    {
        return None;
    }
    static SEEN: OnceLock<Mutex<HashMap<String, SshGAnswer>>> = OnceLock::new();
    let seen = SEEN.get_or_init(|| Mutex::new(HashMap::new()));
    let now = std::time::Instant::now();
    if let Some(known) = seen.lock().ok().and_then(|m| m.get(alias).cloned()) {
        if let Some(found) = known.still_good(now) {
            return found;
        }
    }
    let mut cmd = crate::platform::new_command("ssh");
    if let Some(env) = crate::shell_env::try_get() {
        cmd.env("PATH", &env.path);
    }
    cmd.args(["-G", alias]).stdin(std::process::Stdio::null());
    let found = crate::worktrees::run_bounded_output(&mut cmd, std::time::Duration::from_secs(3))
        .ok()
        .filter(|out| out.status.success())
        .and_then(|out| ssh_g_hostname(&String::from_utf8_lossy(&out.stdout)));
    if let Ok(mut m) = seen.lock() {
        m.insert(alias.to_string(), SshGAnswer { found: found.clone(), at: now });
    }
    found
}

/// R10 (Challenger): how long "ssh gave no answer" stands before it is
/// asked again (a timeout on a slow moment is not for the app's life).
const SSH_G_RETRY: std::time::Duration = std::time::Duration::from_secs(60);

/// One `ssh -G` answer and when it was read.
#[derive(Debug, Clone)]
struct SshGAnswer {
    found: Option<String>,
    at: std::time::Instant,
}

impl SshGAnswer {
    /// The kept answer, or None when it must be asked again: a hostname
    /// stands; no answer stands for [`SSH_G_RETRY`].
    fn still_good(&self, now: std::time::Instant) -> Option<Option<String>> {
        match &self.found {
            Some(host) => Some(Some(host.clone())),
            None if now.duration_since(self.at) < SSH_G_RETRY => Some(None),
            None => None,
        }
    }
}

/// Pure: the `hostname` line of `ssh -G`'s output.
fn ssh_g_hostname(out: &str) -> Option<String> {
    out.lines()
        .find_map(|l| l.strip_prefix("hostname "))
        .map(|h| h.trim().to_ascii_lowercase())
        .filter(|h| !h.is_empty())
}

/// [`classify_pr_origin_with`] with `ssh -G` as the alias resolver.
fn classify_pr_origin(url: &str) -> PrOrigin {
    classify_pr_origin_with(url, &ssh_config_hostname)
}

/// `repo`'s `origin`, for Ship as a PR (R10).
pub(crate) fn pr_origin(repo: &std::path::Path) -> PrOrigin {
    match crate::git::capture(repo, &["remote", "get-url", "origin"]) {
        Ok(url) => classify_pr_origin(&url),
        Err(_) => PrOrigin::None,
    }
}

/// Whether Ship as a PR is offered from `repo` and pushes: an `origin` on
/// GitHub, or one Plyloft can't tell isn't (R10 Challenger). Without any
/// `origin` `card_ship` merges here, flagged (CL-11: the card says so up
/// front); one known elsewhere is refused ([`pr_origin_refusal`]).
fn origin_offers_pr(repo: &std::path::Path) -> bool {
    pr_origin(repo).offers_pr()
}

/// R10: what the card says where Ship as a PR would be, for an origin
/// elsewhere (the same words as `OutcomeScreen`'s `originElsewhereWords`).
fn origin_elsewhere_words(host: &str) -> String {
    format!("Pull requests need a project on GitHub; this project is on {host}.")
}

/// R10 (Challenger): an origin on GitHub whose address isn't a repository's
/// (the same words as `OutcomeScreen`'s `originUnreadableWords`).
fn origin_unreadable_words(url: &str) -> String {
    format!("This project's GitHub address isn't a repository Plyloft can read: {url}.")
}

/// The card's words for an origin that can't take a pull request, or None.
pub(crate) fn origin_refused_words(origin: &PrOrigin) -> Option<String> {
    match origin {
        PrOrigin::Elsewhere(host) => Some(origin_elsewhere_words(host)),
        PrOrigin::Unreadable(url) => Some(origin_unreadable_words(url)),
        PrOrigin::None | PrOrigin::GitHub { .. } | PrOrigin::Unknown(_) => None,
    }
}

/// G1 (1.170.0): what a ship asks GitHub for once its pull request is open.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ShipAutoMerge {
    /// Ship as a PR: the workspace's remembered "Merge when checks pass".
    Workspace,
    /// Ship it on GitHub: merge when the checks pass, whatever that choice.
    On,
    /// Ship ▾ › Open the pull request only: never.
    Off,
}

/// G1: the press a ship came from, as the land or pull request it runs.
/// `ship_it` follows the workspace's "How Ship it ships" (`ship_via`): on a
/// project whose `origin` can take a pull request ([`PrOrigin::offers_pr`]),
/// a pull request that merges when its checks pass, unless the workspace is
/// set to ship on this Mac; a land here otherwise — never a refusal, so
/// a project not on GitHub ships as it always did. `pr_only` (Open the pull
/// request only) is a pull request without auto-merge. `pr` (Ship as a PR)
/// and `merge_live` (Only on this Mac) are as they were.
pub(crate) fn resolve_ship_press(mode: &str, ship_via: Option<&str>, offers_pr: bool) -> (String, ShipAutoMerge) {
    match mode {
        "ship_it" if offers_pr && ship_via != Some("local") => ("pr".into(), ShipAutoMerge::On),
        "ship_it" => ("merge_live".into(), ShipAutoMerge::Workspace),
        "pr_only" => ("pr".into(), ShipAutoMerge::Off),
        other => (other.to_string(), ShipAutoMerge::Workspace),
    }
}

/// [`resolve_ship_press`] for a workspace's card copy `wt`. `origin` is read
/// only for Ship it.
fn ship_press_for(workspaces: &WorkspaceStore, workspace_id: &str, wt: &Path, mode: &str) -> (String, ShipAutoMerge) {
    if mode != "ship_it" {
        return resolve_ship_press(mode, None, false);
    }
    let via = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .and_then(|w| w.ship_via);
    resolve_ship_press(mode, via.as_deref(), origin_offers_pr(wt))
}

/// G1: whether a ship that opened `pr` asks GitHub for auto-merge. 1.170.0
/// G2: on every plan, Free included.
fn ship_wants_auto_merge(auto: ShipAutoMerge, workspaces: &WorkspaceStore, workspace_id: &str) -> bool {
    match auto {
        ShipAutoMerge::Workspace => auto_merge_wanted(workspaces, workspace_id),
        ShipAutoMerge::On => true,
        ShipAutoMerge::Off => false,
    }
}

/// G1 Challenger: what a ship asks GitHub for, once the review record is
/// known. A ship with the last commit not reviewed, or over a request for
/// changes nobody resolved (Ship anyway, Ship as a PR anyway —
/// `unreviewed`, `ship_review_record`'s "not fixed" line included), or with
/// its findings in a follow-up card (`follow_up`) opens its pull request
/// without auto-merge, whatever the press, the workspace or the plan.
/// Owner, 2026-10-15: a human's decision is an approval — findings the
/// person dismissed ("Not a real issue") and a Builder's pushback the
/// person accepted (`review_override_line`) still merge by themselves.
/// Owner, 2026-10-27 (1.171.0 C3): a review skipped with "Check without the
/// Reviewer" is not a decision on findings — `unreviewed`
/// carries its line, so it never merges by itself.
pub(crate) fn ship_auto_merge_guarded(auto: ShipAutoMerge, unreviewed: Option<&str>, follow_up: bool) -> ShipAutoMerge {
    if unreviewed.is_some() || follow_up {
        ShipAutoMerge::Off
    } else {
        auto
    }
}

/// G1 Challenger (8): Ship it's refusal of an `origin` on GitHub whose
/// address isn't a repository's (`PrOrigin::Unreadable`) — it used to land
/// here. The way on is Ship ▾ › Only on this Mac (the card page reads
/// these words, `shipNeedsGitHub`). None for any other press, origin, or a
/// workspace set to ship on this Mac.
fn ship_it_unreadable_refusal(origin: &PrOrigin, ship_via: Option<&str>) -> Option<String> {
    match origin {
        PrOrigin::Unreadable(url) if ship_via != Some("local") => Some(format!(
            "{} {SHIP_IT_UNREADABLE_TAIL}",
            origin_unreadable_words(url)
        )),
        _ => None,
    }
}

/// G1 Challenger (8): the end of [`ship_it_unreadable_refusal`]'s words.
pub(crate) const SHIP_IT_UNREADABLE_TAIL: &str =
    concat!("Nothing was pushed. To merge the card here instead, use Only on ", crate::this_machine!(), ".");

/// [`ship_it_unreadable_refusal`] for a workspace's card copy `wt`.
fn ship_it_origin_refusal(workspaces: &WorkspaceStore, workspace_id: &str, wt: &Path, mode: &str) -> Option<String> {
    if mode != "ship_it" {
        return None;
    }
    let via = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .and_then(|w| w.ship_via);
    ship_it_unreadable_refusal(&pr_origin(wt), via.as_deref())
}

/// G1 Challenger (7): the host `gh auth token --hostname` is asked about
/// for an `origin` Plyloft can't tell is GitHub (GitHub Enterprise): the
/// URL's own host for an `https://` address, the host `ssh` connects to
/// for an SSH one (`ssh_hostname`) — only a plain host name (a dot, and
/// letters, digits, `.`, `-`), never an alias or anything gh could read as
/// an option. None: the pull request's own calls answer for the sign-in.
fn plain_gh_host(url: &str, ssh_hostname: &dyn Fn(&str) -> Option<String>) -> Option<String> {
    let clean = strip_remote_userinfo(url);
    let host = remote_host(&clean)?;
    let ssh_form = !clean.contains("://") || clean.to_ascii_lowercase().starts_with("ssh://");
    let host = if ssh_form { ssh_hostname(&host)?.trim().to_ascii_lowercase() } else { host };
    let plain = host.contains('.')
        && !host.starts_with(['-', '.'])
        && !host.ends_with('.')
        && host.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-'));
    plain.then_some(host)
}

/// G1: a pull request refused before anything is gated or pushed because
/// the GitHub CLI isn't there. The card page reads this start
/// (`shipNeedsGitHub`) and offers Install the GitHub command and Only on this
/// computer; the doctor's own words follow it.
pub(crate) const SHIP_NEEDS_GH_WORDS: &str =
    "A pull request needs the GitHub command, and it isn't installed on this computer, so nothing was pushed.";

/// G1: …or because the GitHub CLI has no sign-in for this project (Sign in
/// to GitHub, and Only on this Mac).
pub(crate) const SHIP_NEEDS_SIGN_IN_WORDS: &str =
    "A pull request needs a GitHub sign-in on this computer, and there is none for this project, so nothing was pushed.";

/// G1: what `gh auth token --hostname github.com` (a local read: gh's
/// config and keychain, no network) answered, as a refusal or none. Signed
/// in (also through a chosen account's token) → none. Refused → the sign-in
/// words, gh's own line after them (it never holds a token: a refusal has
/// none to print). A gh too old to know the command, a timeout or a gh that
/// didn't run → none: the pull request's own calls answer then (R11). The
/// workspace's chosen account that can't be used (its scope's words) → the
/// sign-in words with them.
pub(crate) fn ship_sign_in_refusal(answer: Result<(bool, &str), &str>) -> Option<String> {
    match answer {
        Ok((true, _)) => None,
        Ok((false, said)) => {
            let lower = said.to_ascii_lowercase();
            if lower.contains("unknown command") || lower.contains("unknown flag") {
                return None;
            }
            let said = said.trim();
            Some(if said.is_empty() {
                SHIP_NEEDS_SIGN_IN_WORDS.to_string()
            } else {
                format!("{SHIP_NEEDS_SIGN_IN_WORDS}\n{said}")
            })
        }
        Err(e) if crate::github::is_gh_timeout(e) || e.starts_with("couldn't ") => None,
        Err(e) => Some(format!("{SHIP_NEEDS_SIGN_IN_WORDS}\n{e}")),
    }
}

/// G1 (owner, 2026-10-26): a pull request on GitHub needs the GitHub CLI and
/// a sign-in for the workspace's account — checked before anything is gated
/// or pushed, never answered by landing here instead. Only for a `pr` press
/// whose `origin` can take one. G1 Challenger (7): on an unknown host
/// (GitHub Enterprise) the sign-in is asked of that host when it is a plain
/// host name ([`plain_gh_host`]); otherwise gh's own calls answer for it.
pub(crate) fn pr_github_preflight(workspaces: &WorkspaceStore, workspace_id: &str, wt: &Path, mode: &str) -> Result<(), String> {
    if mode != "pr" {
        return Ok(());
    }
    let origin = pr_origin(wt);
    if !origin.offers_pr() {
        return Ok(());
    }
    let gh = crate::doctor::require("gh").map_err(|why| format!("{SHIP_NEEDS_GH_WORDS}\n{why}"))?;
    let host = match origin {
        PrOrigin::GitHub { .. } => "github.com".to_string(),
        _ => {
            let url = crate::git::capture(wt, &["remote", "get-url", "origin"]).unwrap_or_default();
            match plain_gh_host(&url, &ssh_config_hostname) {
                Some(host) => host,
                None => return Ok(()),
            }
        }
    };
    let _github = crate::github_account::enter_for_workspace(workspaces, workspace_id);
    let ran = ship_gh(&gh, wt, &["auth", "token", "--hostname", &host]);
    let answer = match &ran {
        // The token on stdout is never read; only whether there was one.
        Ok(out) => Ok((out.status.success(), String::from_utf8_lossy(&out.stderr).into_owned())),
        Err(e) => Err(e.as_str()),
    };
    match ship_sign_in_refusal(answer.as_ref().map(|(ok, said)| (*ok, said.as_str())).map_err(|e| *e)) {
        Some(why) => Err(why),
        None => Ok(()),
    }
}

/// R10: Ship as a PR from a repository whose `origin` isn't on GitHub stops
/// before anything is gated or pushed (it used to push the branch, then
/// `gh pr create` failed and left it there on every retry). Ship it still
/// merges here — G1 Challenger (8): except from a GitHub address that isn't
/// a repository's, where Ship it stops too and Only on this Mac is the
/// way on ([`ship_it_unreadable_refusal`]).
fn pr_origin_refusal(wt: &std::path::Path, mode: &str) -> Option<String> {
    if mode != "pr" {
        return None;
    }
    let origin = pr_origin(wt);
    let way = match origin {
        PrOrigin::Unreadable(_) => SHIP_IT_UNREADABLE_TAIL,
        _ => "Nothing was pushed. Ship it merges the card here.",
    };
    origin_refused_words(&origin).map(|words| format!("{words} {way}"))
}

/// GH #204: every `gh` the card-ship PR flow runs, bounded like
/// `shared_config::Gh`'s PR calls ([`crate::shared_config::GH_TIMEOUT`]) and
/// killed with its process group on timeout or app exit.
fn ship_gh(gh: &str, wt: &std::path::Path, args: &[&str]) -> Result<std::process::Output, String> {
    crate::github::gh_output(gh, Some(wt), args, crate::shared_config::GH_TIMEOUT)
}

/// R12 (Challenger): [`ship_gh`] with `body` on gh's stdin (`--body-file -`).
fn ship_gh_with_body(gh: &str, wt: &std::path::Path, args: &[&str], body: &str) -> Result<std::process::Output, String> {
    crate::github::gh_output_with_stdin(gh, Some(wt), args, crate::shared_config::GH_TIMEOUT, body)
}

/// R12: the repository's pull-request template among `paths` (paths in the
/// published commit, files only), in GitHub's documented places: a single
/// `pull_request_template` (`.md`, `.txt` or no extension, any case) in
/// `.github/`, the root or `docs/` (that order first), else the one
/// template of a `PULL_REQUEST_TEMPLATE/` folder there — only `.md`, `.txt`
/// or extension-less files count; a dotfile (`.gitkeep`) or a README is not
/// a template. Several templates → none, as GitHub uses none by default.
fn pick_pr_template(paths: &[String]) -> Option<String> {
    const DIRS: [&str; 3] = [".github", "", "docs"];
    let split = |p: &str| -> (String, String) {
        match p.rsplit_once('/') {
            Some((dir, name)) => (dir.to_string(), name.to_string()),
            None => (String::new(), p.to_string()),
        }
    };
    // `name` without a template extension (`.md`, `.txt`, none), or None.
    let stem = |name: &str| -> Option<String> {
        let lower = name.to_ascii_lowercase();
        if lower.starts_with('.') {
            return None;
        }
        match lower.rsplit_once('.') {
            Some((stem, "md" | "txt")) => Some(stem.to_string()),
            Some(_) => None,
            None => Some(lower),
        }
    };
    for dir in DIRS {
        if let Some(p) = paths.iter().find(|p| {
            let (d, name) = split(p);
            d == dir && stem(&name).as_deref() == Some("pull_request_template")
        }) {
            return Some(p.clone());
        }
    }
    let in_folders: Vec<&String> = paths
        .iter()
        .filter(|p| {
            let (d, name) = split(p);
            let (parent, folder) = split(&d);
            DIRS.contains(&parent.as_str())
                && folder.eq_ignore_ascii_case("pull_request_template")
                && stem(&name).is_some_and(|s| s != "readme")
        })
        .collect();
    match in_folders.as_slice() {
        [only] => Some((*only).clone()),
        _ => None,
    }
}

/// R12: the template `publish` carries (read from the commit, never the
/// project folder), or None — no template, several, an empty one, or git
/// unreadable. A UTF-8 byte-order mark is not part of it.
pub(crate) fn pr_template_at(wt: &std::path::Path, publish: &str) -> Option<String> {
    let capture = |args: &[&str]| crate::pinned_read::git_capture(wt, args).unwrap_or_default();
    // The root's files, and every file under the folders a template may be
    // in (`ls-tree -r` lists files only; the root's own listing names
    // folders too, which are never a template).
    let mut paths = Vec::new();
    let mut folders = Vec::new();
    for line in capture(&["ls-tree", publish]).lines() {
        let Some((meta, path)) = line.split_once('\t') else { continue };
        match meta.split_whitespace().nth(1) {
            Some("blob") => paths.push(path.to_string()),
            Some("tree") if path == ".github" || path == "docs" || path.eq_ignore_ascii_case("pull_request_template") => {
                folders.push(path.to_string())
            }
            _ => {}
        }
    }
    if !folders.is_empty() {
        let mut args = vec!["ls-tree", "-r", "--name-only", publish, "--"];
        args.extend(folders.iter().map(String::as_str));
        paths.extend(capture(&args).lines().map(str::to_string));
    }
    let path = pick_pr_template(&paths)?;
    let text = crate::pinned_read::git_capture(wt, &["show", &format!("{publish}:{path}")]).ok()?;
    let text = text.trim_start_matches('\u{feff}').trim();
    (!text.is_empty()).then(|| text.to_string())
}

/// R12 (Challenger): a body longer than this (characters) leaves the
/// template out — GitHub refuses a body over 65,536.
const PR_BODY_MAX_CHARS: usize = 60_000;

/// R12: the repository's template, then Plyloft's own body under
/// "From Plyloft"; no template → Plyloft's body unchanged. A template that
/// would make the body too long for GitHub is left out (and logged).
pub(crate) fn pr_body_with_template(template: Option<&str>, body: &str) -> String {
    match template.map(str::trim).filter(|t| !t.is_empty()) {
        Some(template) => {
            let with = format!("{template}\n\n## From Plyloft\n\n{body}");
            if with.chars().count() > PR_BODY_MAX_CHARS {
                log::warn!(
                    "card_ship: the repository's pull-request template left out — the body would be {} characters",
                    with.chars().count()
                );
                body.to_string()
            } else {
                with
            }
        }
        None => body.to_string(),
    }
}

/// SL-3: with the workspace's "Merge when checks pass" on, ask GitHub to
/// merge the PR the ship just opened (or linked) once its checks pass. The
/// ship has succeeded either way; a refusal is recorded on the card.
/// 1.170.0 G2: on every plan.
///
/// G1–G3 Challenger (1, 3): `review_hold` — the guard held auto-merge off
/// for a commit nobody reviewed (Some(whether the press wanted it)). A pull
/// request that already existed (`linked`) and merges by itself on GitHub
/// has that turned off; a press that wanted it is recorded, and Plyloft
/// turns it on once the commit is reviewed (`pr_merge::resume_held`).
#[allow(clippy::too_many_arguments)]
fn auto_merge_after_ship(
    workspaces: &WorkspaceStore,
    kanban: &KanbanStore,
    workspace_id: &str,
    card_id: &str,
    auto: ShipAutoMerge,
    review_hold: Option<bool>,
    linked: bool,
    gh: &str,
    wt: &std::path::Path,
    pr_url: &str,
    pushed_head: &str,
) {
    let gh_answer = |args: &[&str]| ship_gh(gh, wt, args).map(|out| crate::pr_merge::GhAnswer::from_output(&out));
    if let Some(wanted) = review_hold {
        // GitHub's own word on the pull request that existed; else what the
        // card last read of it.
        let auto_on = linked
            && crate::pr_merge::auto_merge_on_from(&gh_answer(&crate::pr_merge::auto_merge_on_args(pr_url)))
                .unwrap_or_else(|| {
                    kanban
                        .get_card(workspace_id, card_id)
                        .ok()
                        .and_then(|c| c.pr)
                        .is_some_and(|p| p.auto_merge)
                });
        crate::pr_merge::hold_for_review(kanban, workspace_id, card_id, pr_url, auto_on, wanted, gh_answer);
        return;
    }
    if !ship_wants_auto_merge(auto, workspaces, workspace_id) {
        return;
    }
    // G3: the repository's merge method, and only while GitHub's head is
    // the commit this ship pushed.
    crate::pr_merge::turn_on_after_ship(
        kanban,
        workspace_id,
        card_id,
        pr_url,
        pushed_head,
        |reread| crate::merge_method::methods_for_pr(workspaces, workspace_id, pr_url, reread, gh_answer),
        |url| crate::pr_merge::checks_required(url, None, &gh_answer),
        gh_answer,
    );
}

/// Whether a ship asks GitHub for auto-merge — the workspace's "Merge when
/// checks pass". 1.170.0 G2: on every plan (Launch D7 made it Pro until then).
pub(crate) fn auto_merge_wanted(workspaces: &WorkspaceStore, workspace_id: &str) -> bool {
    workspaces
        .snapshot()
        .workspaces
        .iter()
        .any(|w| w.id == workspace_id && w.merge_when_checks_pass)
}

/// v1.108.0 (E4): best-effort `gh pr comment` with the Challenger's verdict
/// so whoever reviews the PR sees what the other vendor already found.
/// Never fails the ship (agent-collab invariant #5).
fn post_challenger_verdict_comment(gh: &str, wt: &std::path::Path, pr_url: &str, card: &KanbanCard) {
    let Some(review) = card.builder.as_ref().and_then(|b| b.review.as_ref()) else {
        return;
    };
    if review.status != "done" {
        return;
    }
    let body = crate::builder::verdict_comment_body(review, &[wt]);
    // 1.176.3: once per body — an identical comment there is not posted again.
    crate::verdict_comment::post_once(pr_url, &body, |args| ship_gh(gh, wt, args));
}

/// GH #99 (review 1): bring an existing PR's "Last commit not reviewed"
/// line up to date with what was just pushed. Best effort: a failure is
/// logged, the ship stands.
fn refresh_unreviewed_pr_line(gh: &str, wt: &std::path::Path, pr_url: &str, line: Option<&str>) {
    refresh_pr_body(gh, wt, pr_url, |body| crate::builder::pr_body_with_unreviewed(body, line));
}

/// Rewrite an existing PR's body with `update`; nothing when it is
/// unchanged. Best-effort, as the rest of the PR bookkeeping.
fn refresh_pr_body(gh: &str, wt: &std::path::Path, pr_url: &str, update: impl FnOnce(&str) -> String) {
    let view = match ship_gh(gh, wt, &["pr", "view", pr_url, "--json", "body", "--jq", ".body"]) {
        Ok(out) if out.status.success() => out,
        Ok(out) => {
            log::warn!(
                "ship: reading the PR body failed: {}",
                String::from_utf8_lossy(&out.stderr).trim()
            );
            return;
        }
        Err(e) => {
            log::warn!("ship: reading the PR body failed: {e}");
            return;
        }
    };
    let body = String::from_utf8_lossy(&view.stdout).trim_end().to_string();
    let updated = update(&body);
    if updated == body {
        return;
    }
    // G4 Challenger 4: the body on stdin, never an argument (Windows caps a
    // command line at 32k characters).
    let args = crate::pr_draft::pr_body_edit_args(pr_url);
    let args: Vec<&str> = args.iter().map(String::as_str).collect();
    match ship_gh_with_body(gh, wt, &args, &updated) {
        Ok(out) if out.status.success() => {}
        Ok(out) => log::warn!(
            "ship: updating the PR body failed: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        ),
        Err(e) => log::warn!("ship: updating the PR body failed: {e}"),
    }
}

/// v1.38.0: maps a recon verdict string to negative/non-negative. Negative
/// covers "reject" plus a few likely future variants. Empty/unknown strings
/// are treated as non-negative — silence is not a flag.
fn is_negative_verdict(v: &str) -> bool {
    let t = v.trim().to_ascii_lowercase();
    matches!(
        t.as_str(),
        "reject" | "rejected" | "no" | "no-go" | "abort" | "block" | "blocked"
    )
}

/// v1.38.0: synthesize a minimal markdown report from a pre-v1.38 recon
/// artifact that doesn't carry `summary_md`. Covers both shapes:
/// - ux-reviewer: `{ verdict, critique, ux_issues, ux_strengths }`
/// - architect:   `{ decision, rationale, affected_components, open_questions }`
///
/// Returns `None` when the artifact has none of the expected fields (in
/// which case the Outcome screen falls back to its empty-state copy).
fn synthesize_recon_summary_md(artifact: &serde_json::Value) -> Option<String> {
    let str_field = |k: &str| {
        artifact
            .get(k)
            .and_then(|v| v.as_str())
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
    };
    let list_field = |k: &str| -> Vec<String> {
        artifact
            .get(k)
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|x| x.as_str().map(|s| s.trim().to_string()))
                    .filter(|s| !s.is_empty())
                    .collect()
            })
            .unwrap_or_default()
    };

    let mut out = String::new();
    // ux-reviewer shape
    if let Some(critique) = str_field("critique") {
        out.push_str(&format!("## Critique\n\n{critique}\n"));
    }
    let issues = list_field("ux_issues");
    if !issues.is_empty() {
        out.push_str("\n## UX issues\n\n");
        for i in &issues {
            out.push_str(&format!("- {i}\n"));
        }
    }
    let strengths = list_field("ux_strengths");
    if !strengths.is_empty() {
        out.push_str("\n## UX strengths\n\n");
        for s in &strengths {
            out.push_str(&format!("- {s}\n"));
        }
    }
    // architect shape
    if let Some(decision) = str_field("decision") {
        out.push_str(&format!("## Decision\n\n{decision}\n"));
    }
    if let Some(rationale) = str_field("rationale") {
        out.push_str(&format!("\n## Rationale\n\n{rationale}\n"));
    }
    let affected = list_field("affected_components");
    if !affected.is_empty() {
        out.push_str("\n## Affected components\n\n");
        for a in &affected {
            out.push_str(&format!("- {a}\n"));
        }
    }
    let opens = list_field("open_questions");
    if !opens.is_empty() {
        out.push_str("\n## Open questions\n\n");
        for q in &opens {
            out.push_str(&format!("- {q}\n"));
        }
    }

    let trimmed = out.trim();
    if trimmed.is_empty() {
        None
    } else {
        let mut prefixed = String::from(
            "> _Synthesized from structured artifact fields — this audit \
             pre-dates v1.38.0's `summary_md` prompt. Rerun for a richer \
             report._\n\n",
        );
        prefixed.push_str(trimmed);
        Some(prefixed)
    }
}

/// v1.39.0 (Recon-fork cycle, Increment 2): is the card's swarm
/// template a recon-shape one (`ux-audit`, `design`)? Resolves the
/// template id from `SwarmTemplatesStore` and inspects its
/// `output_kind`. Missing template id (legacy card) or unknown template
/// id (template was deleted) → `false`.
fn is_recon_card(
    card: &KanbanCard,
    swarm_templates: &SwarmTemplatesStore,
) -> bool {
    match card.swarm_template_id.as_deref() {
        Some(id) => swarm_templates
            .get(id)
            .ok()
            .flatten()
            .map(|t| matches!(t.output_kind, crate::swarm_templates::OutputKind::Recon))
            .unwrap_or(false),
        None => false,
    }
}

/// v1.39.0: scan a recon card's latest swarm run artifacts for
/// `summary_md`, with the same "latest wins" semantics as the verdict
/// scan in `card_outcome`. Falls back to the structured-field synthesizer
/// (`synthesize_recon_summary_md`) for pre-v1.38 artifacts. Returns
/// `None` when the card has no linked swarm OR no run artifact yields
/// any usable summary text.
fn resolve_recon_summary_md(
    card: &KanbanCard,
    swarms: &SwarmRegistry,
    agents: &AgentRegistry,
) -> Option<String> {
    let swarm_id = card.linked_swarm_id.as_deref()?;
    let swarm = swarms.get(swarm_id)?;
    let mut summary_md: Option<String> = None;
    let mut fallback_artifact: Option<serde_json::Value> = None;
    for run_id in &swarm.run_ids {
        if let Ok(run) = agents.get_run(run_id) {
            if let Some(artifact) = &run.swarm_artifact {
                if let Some(md) = artifact.get("summary_md").and_then(|v| v.as_str()) {
                    summary_md = Some(md.to_string());
                }
                fallback_artifact = Some(artifact.clone());
            }
        }
    }
    summary_md.or_else(|| {
        fallback_artifact
            .as_ref()
            .and_then(synthesize_recon_summary_md)
    })
}

/// v1.39.0: derive the forked card's title from the parent audit's
/// title. Truncates parent at 60 characters (with an ellipsis when
/// cut) and prefixes with "Implement: ". If the parent already starts
/// with "Implement:" (case-insensitive), use the parent title verbatim
/// — no double-prefix.
fn derive_forked_title(parent_title: &str) -> String {
    let trimmed = parent_title.trim();
    if trimmed.to_ascii_lowercase().starts_with("implement:") {
        return trimmed.to_string();
    }
    let char_count = trimmed.chars().count();
    let truncated = if char_count > 60 {
        let mut s: String = trimmed.chars().take(60).collect();
        s.push('…');
        s
    } else {
        trimmed.to_string()
    };
    format!("Implement: {truncated}")
}

/// v1.39.0: a short human-readable card id for the provenance line in a
/// forked card's knowledge. 1.175.0 (R5): the branch's own short id
/// (`worktrees::branch_short_id`), so an issue card reads `issue12` here
/// too, not `ghissue1`, which #1, #12 and #150 shared.
fn short_card_id(card_id: &str) -> String {
    crate::worktrees::branch_short_id(card_id)
}

/// v1.39.0: build the forked card's `knowledge` field — a provenance
/// header on top of the parent audit's `summary_md` (or its synthesis
/// fallback). When `summary_md` itself starts with the synthesis
/// prefix (`> _Synthesized from structured artifact fields …_`), the
/// two prefixes stack: the derivation line at the very top, then the
/// synthesis disclaimer inside the body. Both are intentional — they
/// convey different facts.
fn build_forked_knowledge(short_id: &str, date: &str, summary_md: &str) -> String {
    format!(
        "> Derived from audit card {short_id} on {date}\n\n{summary_md}"
    )
}

/// v1.39.0 (Recon-fork cycle, Increment 2): the partial-success return
/// shape for `kanban_card_fork_to_implementation`. The card is always
/// persisted before intake is attempted, so the create step and the
/// optional intake start are NOT transactional. When `run_intake: true`
/// is requested and intake fails to start, the card persists and the
/// FE surfaces an additional toast pointing the user to the new card's
/// detail panel for a manual retry.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CardForkResult {
    pub card: KanbanCard,
    /// True when `run_intake: true` was requested AND the intake PTY
    /// started successfully. False when intake wasn't requested OR it
    /// failed to start.
    pub intake_started: bool,
    /// Populated only when intake was requested AND it failed. The FE
    /// surfaces this in a follow-up toast.
    pub intake_error: Option<String>,
    /// v1.39.2: the intake PTY id, populated when `intake_started: true`.
    /// The FE writes this into `useIntake.ptyByCard[cardId]` so the
    /// `IntakeConversation` component mounts and the user sees the live
    /// REPL surface. Without this, the FE would render the
    /// "no PTY is attached in this session" warning (the v1.39.1
    /// Tier-4 walk found this — backend correctly marks intake_status
    /// Active and the PTY runs, but the FE's `useIntake.ptyByCard`
    /// only gets populated by `useIntake.start()` in the manual flow,
    /// not by the fork command).
    pub intake_pty_id: Option<String>,
}

/// v1.39.0 (Recon-fork cycle, Increment 2): one-click create an
/// implementation card from a completed recon audit. The new card lands
/// in the workspace's Todo column with the audit's `summary_md` (or
/// synthesized fallback) preloaded as its `knowledge`, ready to build with
/// the Builder (G4: it no longer carries a swarm template).
///
/// Worktree creation is deferred to the Todo→InProgress transition (the
/// existing path) so the implementation card branches fresh from `main`,
/// not from the audit's branch.
///
/// `run_intake` toggles between "fork and start an intake conversation
/// immediately" (true — sharpen the audit's plan before dispatch) and
/// "fork and leave it ready to dispatch as-is" (false). Intake failure
/// is non-fatal: the card persists and the failure is surfaced via the
/// returned `CardForkResult`.
#[tauri::command]
pub fn kanban_card_fork_to_implementation(
    app: tauri::AppHandle,
    kanban: State<'_, KanbanStore>,
    settings: State<'_, SettingsStore>,
    swarms: State<'_, SwarmRegistry>,
    agents: State<'_, AgentRegistry>,
    swarm_templates: State<'_, SwarmTemplatesStore>,
    intake_store: State<'_, IntakeStore>,
    intake_registry: State<'_, IntakeRegistry>,
    pty_registry: State<'_, PtyRegistry>,
    drain_coord: State<'_, DrainCoordinator>,
    workspace_id: String,
    parent_card_id: String,
    card_id: String,
    suggested_swarm_template_id: Option<String>,
    run_intake: bool,
    workspace_cwd: String,
) -> Result<CardForkResult, String> {
    let parent = kanban.get_card(&workspace_id, &parent_card_id)?;

    // ── Reject paths (distinct error strings for FE-friendly toasts) ──
    if parent.archived {
        return Err("Unarchive the audit before forking.".to_string());
    }
    if !is_recon_card(&parent, &swarm_templates) {
        return Err(
            "This card isn't a recon audit — only ux-audit / design cards can fork."
                .to_string(),
        );
    }
    if parent.linked_swarm_id.is_none() {
        return Err("This audit hasn't been dispatched yet.".to_string());
    }
    let summary_md = resolve_recon_summary_md(&parent, &swarms, &agents)
        .ok_or_else(|| "No audit deliverable to fork from.".to_string())?;

    // ── Prefill payload ──
    let title = derive_forked_title(&parent.title);
    let short = short_card_id(&parent_card_id);
    let date = chrono::Utc::now().format("%Y-%m-%d").to_string();
    let knowledge = build_forked_knowledge(&short, &date, &summary_md);
    // G4 (launch D8): swarms are retired, so the implementation card gets
    // no swarm template — it is built by the Builder like any other card.
    // An older frontend may still send a suggestion; it is ignored.
    let _ = suggested_swarm_template_id;
    let swarm_template_id = None;

    let mut card = KanbanCard::from_audit(
        card_id,
        workspace_id.clone(),
        title,
        knowledge,
        parent_card_id.clone(),
        swarm_template_id,
        KanbanColumnId::Todo,
    );
    // v1.49.0 (Team Mode Phase 0): the fork is a user-driven action;
    // stamp provenance so the forked card surfaces the actor.
    let email = settings.snapshot().identity.user_email;
    card.author = email.clone();
    card.last_edited_by = email;
    // 1.173.0 (B3): the implementation card stays in its recon card's area.
    card.area = crate::card_area::inherited_area(&parent);

    // Persist BEFORE attempting intake — intake failure must not undo
    // the card creation. See plan Increment 2 § "On intake failure".
    let created = kanban.create_card(&workspace_id, card)?;
    crate::kanban::emit_kanban_changed(&app, &workspace_id);

    // ── Optional intake start ──
    let mut intake_started = false;
    let mut intake_error: Option<String> = None;
    let mut intake_pty_id: Option<String> = None;
    let mut card_after_intake = created.clone();
    if run_intake {
        if let Err(e) = drain::guard_dispatch(&drain_coord, "intake") {
            intake_error = Some(e);
        } else {
            match intake::start_intake(
                app.clone(),
                &kanban,
                &intake_store,
                &intake_registry,
                &pty_registry,
                &swarm_templates,
                &workspace_id,
                &created.id,
                &workspace_cwd,
            ) {
                Ok(pty_id) => {
                    intake_started = true;
                    intake_pty_id = Some(pty_id);
                    // v1.39.1: flip the persisted card's intake_status to
                    // Active so the FE renders the INTAKE: ACTIVE pill +
                    // surfaces the conclude / cancel controls. The manual
                    // intake flow (CardDetailPanel) does this FE-side
                    // before calling intake_start; the fork+intake path
                    // bypasses the FE so the backend has to mirror the
                    // flip. Without this, the PTY is alive in
                    // IntakeRegistry but the persisted card looks idle —
                    // the UI bug surfaced by the v1.39.0 Tier-4 walk.
                    match kanban.patch_card(
                        &workspace_id,
                        &created.id,
                        CardPatch {
                            intake_status: Some(IntakeStatus::Active),
                            ..Default::default()
                        },
                        // Internal bookkeeping — don't stamp last_edited_by.
                        None,
                    ) {
                        Ok(patched) => {
                            card_after_intake = patched;
                            crate::kanban::emit_kanban_changed(&app, &workspace_id);
                        }
                        Err(e) => {
                            // Best-effort: log and continue. The PTY is
                            // already alive — the user can recover from a
                            // stale FE by reloading the workspace. We
                            // don't unwind the intake-started signal
                            // because intake genuinely did start.
                            log::warn!(
                                "kanban_card_fork_to_implementation: \
                                 patch intake_status=Active failed for \
                                 card {card_id}: {e}",
                                card_id = created.id,
                            );
                        }
                    }
                }
                Err(e) => {
                    intake_error = Some(e);
                }
            }
        }
    }

    Ok(CardForkResult {
        card: card_after_intake,
        intake_started,
        intake_error,
        intake_pty_id,
    })
}

/// v1.10.x Cycle A: archive a Complete-column card. Best-effort prunes
/// the card's worktree to `<root>/.trash/<id>-<ts>/` (if any),
/// then flips `archived: true` and clears `worktree_path` / `branch_name`.
/// Worktree pruning failures are logged and swallowed — the archive flag
/// always lands so the user's intent is honored.
#[tauri::command]
pub async fn kanban_card_archive(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    auto: Option<bool>,
) -> Result<KanbanCard, String> {
    // GH #222 review 4: on a worker, under CARD_START_LOCK — the record check
    // and the worktree prune are one step, and a Ship holds this lock from its
    // checks to its tag, so an archive never trashes a worktree mid-merge.
    tauri::async_runtime::spawn_blocking(move || {
        let archived = {
            let _start = CARD_START_LOCK.lock().unwrap_or_else(|p| p.into_inner());
            kanban_card_archive_locked(
                &app.state::<KanbanStore>(),
                &app.state::<WorkspaceStore>(),
                &app.state::<ProjectConfigStore>(),
                &workspace_id,
                &card_id,
                auto.unwrap_or(false),
            )?
        };
        // 1.173.0 (C2, Challenger 6): an archived card is built nowhere —
        // this computer's claim marker comes off its issue (after the lock:
        // it is a GitHub round trip). Best-effort.
        let workspaces = app.state::<WorkspaceStore>();
        if let Some(repo) = workspace_github_target(&workspaces, &workspace_id) {
            if team_gate(&app.state::<crate::license::LicenseStore>()).is_ok() {
                let _github = crate::github_account::enter_for_workspace(&workspaces, &workspace_id);
                let store = app.state::<KanbanStore>();
                crate::device_claim::release_card(&store, &repo, &workspace_id, &archived);
                // 1.175.0 (D2): archived by hand, the member left it.
                if !auto.unwrap_or(false) {
                    crate::leave_issue::leave(&store, &repo, &workspace_id, &card_id);
                }
                return store.get_card(&workspace_id, &card_id);
            }
        }
        Ok(archived)
    })
    .await
    .map_err(|e| format!("card archive worker failed: {e}"))?
}

/// UX-5.8: bring an archived card back to the Board (`kanban::card_restorable`).
/// QoL 1.168 S1-3: every archived card. Its brief, plan and history never
/// left it. One archived by hand without shipping also gets its copy back
/// from the Trash while the copy is there, on its branch, edits included
/// (`worktrees::restore_card_copy_from_trash`); otherwise its branch stays
/// recorded and its next Start build checks it out again
/// (`branch_cleanup::restart_candidates`). A shipped card's copy was put
/// away by its ship and stays so. Under CARD_START_LOCK, on a worker: it
/// runs git.
#[tauri::command]
pub async fn kanban_card_restore(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<KanbanCard, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let restored = {
            let _start = CARD_START_LOCK.lock().unwrap_or_else(|p| p.into_inner());
            restore_card_locked(&app.state::<KanbanStore>(), &app.state::<WorkspaceStore>(), &workspace_id, &card_id)?
        };
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        Ok(restored)
    })
    .await
    .map_err(|e| format!("card restore worker failed: {e}"))?
}

/// `kanban_card_restore`'s work; the caller holds CARD_START_LOCK.
///
/// In order: the card comes off the archive; a copy the archive couldn't
/// move (a program held it open, `kept_copy`) is the card's copy again —
/// first, so `kept_copy::retry` never trashes it later; else its copy comes
/// back from the Trash while it is there. The card returns to the column it
/// was archived from, whatever other cards are at work.
fn restore_card_locked(
    store: &KanbanStore,
    workspaces: &WorkspaceStore,
    workspace_id: &str,
    card_id: &str,
) -> Result<KanbanCard, String> {
    let before = store.get_card(workspace_id, card_id)?;
    let mut restored = store.restore_card(workspace_id, card_id)?;
    let ws = workspaces.snapshot().workspaces.into_iter().find(|w| w.id == workspace_id);
    let cwd = ws.as_ref().map(|w| PathBuf::from(&w.cwd));
    if let Some(cwd) = cwd.as_deref() {
        if let Some(kept) = crate::kept_copy::validated_path(cwd, &before).filter(|p| p.is_dir()) {
            // The folder the archive left in place: the card's own again.
            let branch = crate::git::capture(&kept, &["rev-parse", "--abbrev-ref", "HEAD"])
                .ok()
                .map(|b| b.trim().to_string())
                .filter(|b| !b.is_empty() && b != "HEAD")
                .or_else(|| before.branch_cleanup.as_ref().map(|r| r.branch.clone()));
            let path = kept.to_string_lossy().to_string();
            store.with_card(workspace_id, card_id, |c| {
                c.worktree_path = Some(path.clone());
                c.branch_name = branch.clone();
                c.kept_copy = None;
                Ok(())
            })?;
            restored = store.get_card(workspace_id, card_id)?;
        } else if let Some((entry, branch)) = archived_copy_to_restore(&before) {
            match crate::worktrees::restore_card_copy_from_trash(cwd, card_id, &entry, &branch) {
                Ok(path) => {
                    let path = path.to_string_lossy().to_string();
                    store.with_card(workspace_id, card_id, |c| {
                        c.worktree_path = Some(path.clone());
                        c.branch_name = Some(branch.clone());
                        Ok(())
                    })?;
                    restored = store.get_card(workspace_id, card_id)?;
                }
                Err(e) => log::info!(
                    "kanban_card_restore: {card_id}: its copy stays in the Trash ({e}); its branch is kept for Start build"
                ),
            }
        }
    }
    Ok(restored)
}

/// QoL 1.168 S1-3: the Trash copy and branch an archived card can get back —
/// only a card archived without shipping (its cleanup record's reason is
/// the archive) whose copy went to the Trash.
fn archived_copy_to_restore(card: &KanbanCard) -> Option<(PathBuf, String)> {
    if !card.archived || matches!(card.ship_status, crate::kanban::ShipStatus::Shipped) {
        return None;
    }
    let rec = card.branch_cleanup.as_ref()?;
    if rec.reason != crate::branch_cleanup::CleanupReason::Archived
        || matches!(
            rec.outcome,
            Some(crate::branch_cleanup::CleanupOutcome::Deleted)
                | Some(crate::branch_cleanup::CleanupOutcome::Gone)
        )
    {
        return None;
    }
    let entry = PathBuf::from(rec.trash_entry.as_deref()?);
    Some((entry, rec.branch.clone()))
}

/// `kanban_card_archive`'s work; the caller holds CARD_START_LOCK.
/// SL-4: an archive refused while the card's setup runs — the delete sheet's
/// words for the same busy folder.
const SETUP_BUSY_ARCHIVE: &str =
    "The card's setup is running in this card's folder. Wait for it to finish, then archive the card.";

fn kanban_card_archive_locked(
    store: &KanbanStore,
    workspaces: &WorkspaceStore,
    project_config: &ProjectConfigStore,
    workspace_id: &str,
    card_id: &str,
    auto: bool,
) -> Result<KanbanCard, String> {
    let (workspace_id, card_id) = (workspace_id.to_string(), card_id.to_string());
    let card = store.get_card(&workspace_id, &card_id)?;
    // UX-5.8: the auto-archive only ever takes a card with nothing to prune;
    // `archive_card` checks the rest again under the cache lock.
    if auto && !crate::kanban::auto_archive_eligible(&card, crate::kanban::now_ms()) {
        return Err(crate::kanban::AUTO_ARCHIVE_NOT_ELIGIBLE.to_string());
    }
    // GH #222 review 3: never a card of a recorded, unpublished release.
    if let Some(refusal) =
        ship::card_removal_refusal(&project_config, &store, &workspace_id, &card_id, &card.title)
    {
        return Err(refusal);
    }
    // SL-4: nothing prunes the folder under a setup still running in it.
    if crate::worktree_setup::is_in_flight(&workspace_id, &card_id) {
        return Err(SETUP_BUSY_ARCHIVE.to_string());
    }
    // SL-6: two live builds are never archived from under their sessions.
    if crate::build_both::is_undecided(&card) {
        return Err(crate::build_both::UNDECIDED_REFUSAL.to_string());
    }
    let ws_cwd = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .map(|w| PathBuf::from(w.cwd));
    // N18: the card's branch, at its tip now, for the Inbox to ask about
    // once its trash entry expires.
    let mut branch_record = ws_cwd
        .as_deref()
        .and_then(|cwd| crate::branch_cleanup::archive_record(&card, cwd, crate::kanban::now_ms()));
    if card.worktree_path.is_some() {
        if let Some(cwd) = ws_cwd {
            let cache_paths = project_config.cache_paths(&workspace_id);
            let path = crate::worktrees::card_worktree_path(&cwd, &card_id, card.worktree_path.as_deref());
            // Try it (TI-2): never blocks the archive; it stops first.
            crate::try_session::stop_card_try_sessions(&workspace_id, &card_id, None, crate::try_session::TryStopReason::Archive);
            // Windows walk 2026-10-20: a copy a program still holds is kept
            // and recorded (`kept_copy`), and tried again later.
            match crate::kept_copy::prune_or_keep(store, &workspace_id, &card_id, &cwd, &path, &cache_paths) {
                Ok(entry) => {
                    if let (Some(rec), Some(entry)) = (branch_record.as_mut(), entry) {
                        rec.trash_entry = Some(entry.to_string_lossy().to_string());
                    }
                }
                Err(e) => log::warn!(
                    "kanban_card_archive: worktree prune failed for card {card_id}: {e}"
                ),
            }
            // SL-6: the other build of a card still built by both.
            crate::build_both::prune_leftover_variant(&cwd, &card, &cache_paths);
            crate::verify_logs::card_worktree_removed(&workspace_id, &card_id);
        }
    }
    let archived = store.archive_card(&workspace_id, &card_id, auto)?;
    store.record_branch_cleanup(&workspace_id, &card_id, branch_record);
    store.get_card(&workspace_id, &card_id).or(Ok(archived))
}

/// N14 walk F8 (launch D4): put a card In progress (or waiting to ship) back
/// in To do, from its ⋯. One step under CARD_START_LOCK: its sessions stop,
/// it is written To do with nothing running, and its branch and worktree
/// stay for the next Start build (`put_back`). Its pull request, if it has
/// one, is never touched — an open one refuses. On a GitHub Issues board the
/// move follows the team gate of any column move and pushes its label.
#[tauri::command]
pub async fn kanban_card_put_back(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<KanbanCard, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let workspaces = app.state::<WorkspaceStore>();
        let store = app.state::<KanbanStore>();
        team_gate_github_card_write(
            &workspaces,
            &app.state::<crate::license::LicenseStore>(),
            &workspace_id,
            true,
        )?;
        let github_repo = workspace_github_target(&workspaces, &workspace_id);
        let updated = {
            let _start = CARD_START_LOCK.lock().unwrap_or_else(|p| p.into_inner());
            let ws_cwd = resolve_ws_cwd(&workspaces, &workspace_id)?;
            let cache_paths = app.state::<ProjectConfigStore>().cache_paths(&workspace_id);
            let busy = |card: &KanbanCard| put_back_busy(&app, &workspace_id, card);
            let stop_intake = || {
                let registry = app.state::<IntakeRegistry>();
                // Ids repeat across workspaces (`gh-issue-<n>`): only this one's.
                if registry.get(&card_id).filter(|s| s.workspace_id == workspace_id).is_none() {
                    return Ok(false);
                }
                cancel_intake_recorded(
                    &app.state::<IntakeStore>(),
                    &registry,
                    &app.state::<PtyRegistry>(),
                    &store,
                    &workspace_id,
                    &card_id,
                    false,
                )
                .map(|()| true)
            };
            let live = crate::put_back::Live {
                builders: &app.state::<crate::builder::BuilderRegistry>(),
                pty: &app.state::<PtyRegistry>(),
                busy: &busy,
                stop_intake: &stop_intake,
            };
            let by = app.state::<SettingsStore>().snapshot().identity.user_email;
            crate::put_back::put_back_locked(
                &store,
                &ws_cwd,
                &cache_paths,
                &live,
                github_repo.is_some(),
                &workspace_id,
                &card_id,
                by.as_deref(),
            )?
        };
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        // GH #66: other Macs read the column from the issue's labels.
        if let Some(repo) = github_repo {
            let _github = crate::github_account::enter_for_app(&app, &workspace_id);
            gh_sync_card_edit(&store, &repo, &workspace_id, None, &updated, false, true);
            // 1.175.0 (D2): the member left it — their name comes off the issue.
            crate::leave_issue::leave(&store, &repo, &workspace_id, &card_id);
            crate::kanban::emit_kanban_changed(&app, &workspace_id);
            return store.get_card(&workspace_id, &card_id);
        }
        Ok(updated)
    })
    .await
    .map_err(|e| format!("put back worker failed: {e}"))?
}

/// N14 F8: work on the card that Put back in To do does not stop, in words
/// that say what to do. Read under CARD_START_LOCK with the card as it is.
fn put_back_busy<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    workspace_id: &str,
    card: &KanbanCard,
) -> Option<String> {
    const THEN: &str = "then move the card back to Ready to start.";
    if let Some(busy) = card_worktree_busy(app, workspace_id, card) {
        let words = match busy.kind {
            CardBusyKind::Verify => Some(format!("The checks are running on this card. Wait for them to finish, {THEN}")),
            CardBusyKind::Run => Some(format!("An agent run is working on this card. Stop it first, {THEN}")),
            CardBusyKind::Setup => Some(format!("The card's setup is running in its folder. Wait for it to finish, {THEN}")),
            // The worktree stays when a card is put back: a terminal in it
            // loses nothing.
            CardBusyKind::Terminal => None,
        };
        if words.is_some() {
            return words;
        }
    }
    let reviewing = app
        .try_state::<crate::reviewer::ReviewerRegistry>()
        .is_some_and(|r| r.slots().is_reviewing(workspace_id, &card.id));
    if reviewing {
        return Some(format!("The Reviewer is reviewing this card. Wait for the review to finish, {THEN}"));
    }
    let swarm = card.linked_swarm_id.as_deref().is_some_and(|id| {
        app.try_state::<SwarmRegistry>()
            .is_some_and(|r| r.is_card_swarm_live_or_resumable(workspace_id, id))
    });
    if swarm {
        return Some(format!("A swarm is working on this card. Stop it first, {THEN}"));
    }
    None
}

// ── Card attachments (v1.10.0) ────────────────────────

/// v1.10.0: server-side cap on a single attachment's size. Enforced in
/// both the bytes path and the path-copy path so a hand-rolled FE can't
/// bypass it.
const ATTACHMENT_MAX_BYTES: u64 = 5 * 1024 * 1024;

/// Resolve `<app_config>/attachments`. Sits next to `kanban/workspaces/`
/// (NOT under `app_cache/dropped`, which `cache_retention::prune_old`
/// reaps after 90 days) so files persist as long as the card does.
fn attachments_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    let cfg = app
        .path()
        .app_config_dir()
        .map_err(|e| format!("app_config_dir: {e}"))?;
    Ok(cfg.join("attachments"))
}

/// Per-card subdir. Created on demand by the IPC commands; recursively
/// removed by `kanban_attachment_gc_card` when the card is deleted.
fn card_attachments_dir(
    app: &tauri::AppHandle,
    workspace_id: &str,
    card_id: &str,
) -> Result<PathBuf, String> {
    let config = app.path().app_config_dir().map_err(|e| format!("app_config_dir: {e}"))?;
    crate::kanban::card_attachments_dir(&config, workspace_id, card_id)
}

fn now_millis_i64() -> i64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0)
}

/// Extension-based MIME sniff. Intentionally tiny — image thumbnails are
/// the only consumer right now, so non-image extensions return None and
/// the FE renders a generic document icon. Avoids pulling in an extra
/// MIME crate.
fn sniff_mime(name: &str) -> Option<String> {
    let lower = name.to_ascii_lowercase();
    let ext = lower.rsplit('.').next().unwrap_or("");
    match ext {
        "png" => Some("image/png".into()),
        "jpg" | "jpeg" => Some("image/jpeg".into()),
        "gif" => Some("image/gif".into()),
        "webp" => Some("image/webp".into()),
        "heic" => Some("image/heic".into()),
        _ => None,
    }
}

fn format_mb(bytes: u64) -> String {
    format!("{:.1}", bytes as f64 / (1024.0 * 1024.0))
}

/// Materialize an in-memory blob to disk and append it to the card's
/// attachments vec. Used by the FE's drag-drop + paste paths where the
/// WebView `File` object only exposes `.arrayBuffer()` / `.name`.
///
/// D3 (1.172.2): a raw request ([`DroppedRequest`]) — the body is the file's
/// bytes, the workspace, card and name are headers. Off the main thread.
#[tauri::command(async)]
pub fn kanban_attachment_add_from_bytes(
    app: tauri::AppHandle,
    store: State<'_, KanbanStore>,
    request: tauri::ipc::Request<'_>,
) -> Result<CardAttachment, String> {
    let drop = DroppedRequest::new(request.headers(), request.body())?;
    let workspace_id = drop.header(crate::chat::HEADER_WORKSPACE)?;
    let card_id = drop.header(crate::chat::HEADER_CARD)?;
    let name = drop.name()?;
    let bytes = drop.bytes;
    let size = bytes.len() as u64;
    if size > ATTACHMENT_MAX_BYTES {
        return Err(format!(
            "Attachment exceeds 5 MB cap (file is {} MB)",
            format_mb(size)
        ));
    }
    let dir = card_attachments_dir(&app, &workspace_id, &card_id)?;
    std::fs::create_dir_all(&dir).map_err(|e| format!("mkdir: {e}"))?;

    let safe = sanitize_dropped_name(&name);
    let id = uuid::Uuid::new_v4().to_string();
    let filename = format!("{id}-{safe}");
    let target = dir.join(&filename);

    // Tempfile + rename for crash-safe materialization. Cheap on the same
    // filesystem and gives us "either fully present or absent" semantics.
    let tmp = target.with_extension("tmp");
    std::fs::write(&tmp, bytes).map_err(|e| format!("write tmp: {e}"))?;
    crate::platform::rename(&tmp, &target).map_err(|e| format!("rename: {e}"))?;
    crate::platform::mark_from_internet(&target);

    let mime_type = sniff_mime(&name);
    let attachment = CardAttachment {
        id: id.clone(),
        display_name: name.clone(),
        stored_path: target.to_string_lossy().to_string(),
        size_bytes: size,
        mime_type,
        added_at: now_millis_i64(),
    };

    if let Err(e) =
        store.push_attachment(&workspace_id, &card_id, attachment.clone())
    {
        // Card mutation failed (e.g. card deleted between dispatch and
        // arrival). Remove the orphaned bytes so disk doesn't accumulate.
        let _ = std::fs::remove_file(&target);
        return Err(e);
    }
    Ok(attachment)
}

/// Copy an existing absolute path into the attachments dir under a fresh
/// uuid. Used by the file-picker path where the FE already has a real
/// filesystem path back from `@tauri-apps/plugin-dialog`'s `open`.
#[tauri::command]
pub fn kanban_attachment_add_from_path(
    app: tauri::AppHandle,
    store: State<'_, KanbanStore>,
    workspace_id: String,
    card_id: String,
    source_path: String,
) -> Result<CardAttachment, String> {
    let src = Path::new(&source_path);
    let meta = std::fs::metadata(src)
        .map_err(|e| format!("stat source: {e}"))?;
    if !meta.is_file() {
        return Err("Source is not a regular file".into());
    }
    let size = meta.len();
    if size > ATTACHMENT_MAX_BYTES {
        return Err(format!(
            "Attachment exceeds 5 MB cap (file is {} MB)",
            format_mb(size)
        ));
    }
    let display = src
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("attachment")
        .to_string();
    let dir = card_attachments_dir(&app, &workspace_id, &card_id)?;
    std::fs::create_dir_all(&dir).map_err(|e| format!("mkdir: {e}"))?;

    let safe = sanitize_dropped_name(&display);
    let id = uuid::Uuid::new_v4().to_string();
    let filename = format!("{id}-{safe}");
    let target = dir.join(&filename);
    std::fs::copy(src, &target).map_err(|e| format!("copy: {e}"))?;

    let mime_type = sniff_mime(&display);
    let attachment = CardAttachment {
        id: id.clone(),
        display_name: display,
        stored_path: target.to_string_lossy().to_string(),
        size_bytes: size,
        mime_type,
        added_at: now_millis_i64(),
    };

    if let Err(e) =
        store.push_attachment(&workspace_id, &card_id, attachment.clone())
    {
        let _ = std::fs::remove_file(&target);
        return Err(e);
    }
    Ok(attachment)
}

/// Detach + delete an attachment. Removes the metadata entry from the
/// card first; on success, best-effort deletes the file from disk.
/// Logged-but-ignored fs errors keep the FE row from reappearing.
#[tauri::command]
pub fn kanban_attachment_remove(
    app: tauri::AppHandle,
    store: State<'_, KanbanStore>,
    workspace_id: String,
    card_id: String,
    attachment_id: String,
) -> Result<(), String> {
    let removed =
        store.remove_attachment(&workspace_id, &card_id, &attachment_id)?;
    if let Some(att) = removed {
        let root = match attachments_root(&app) {
            Ok(r) => r,
            Err(e) => {
                log::warn!("attachments_root resolution failed: {e}");
                return Ok(());
            }
        };
        // Path-injection guard: only delete files actually under the
        // attachments root. Defends against a poisoned `stored_path` on
        // disk (e.g. someone hand-edited the kanban JSON).
        let stored = Path::new(&att.stored_path);
        if !stored.starts_with(&root) {
            log::warn!(
                "kanban_attachment_remove: refusing to delete out-of-root path: {}",
                att.stored_path
            );
            return Ok(());
        }
        if let Err(e) = std::fs::remove_file(stored) {
            log::warn!(
                "kanban_attachment_remove: fs delete of {} failed: {}",
                att.stored_path,
                e
            );
        }
    }
    Ok(())
}

/// Show an attachment in Finder. Path-injection-guarded — refuses any
/// path that's not under the attachments root.
#[tauri::command(async)]
pub fn kanban_attachment_reveal(
    app: tauri::AppHandle,
    stored_path: String,
) -> Result<(), String> {
    let root = attachments_root(&app)?;
    let p = attachment_target(&root, &stored_path)?;
    crate::platform::reveal_path(&p).map_err(|e| format!("open -R failed: {e}"))?;
    Ok(())
}

/// The attachment `stored_path` names, if it really is one: under the
/// attachments root with no `..` to climb out, there, and still inside the
/// root once links are resolved.
fn attachment_target(root: &Path, stored_path: &str) -> Result<PathBuf, String> {
    const OUTSIDE: &str = "path is not under the attachments dir";
    let p = Path::new(stored_path);
    if p.components()
        .any(|c| matches!(c, std::path::Component::ParentDir))
    {
        return Err(OUTSIDE.into());
    }
    if !p.starts_with(root) {
        return Err(OUTSIDE.into());
    }
    if !p.exists() {
        return Err("attachment file is missing on disk".into());
    }
    let real = crate::platform::canonicalize(p).map_err(|e| format!("resolve attachment: {e}"))?;
    let real_root =
        crate::platform::canonicalize(root).map_err(|e| format!("resolve attachments dir: {e}"))?;
    if !crate::platform::is_within(&real, &real_root) {
        return Err(OUTSIDE.into());
    }
    Ok(p.to_path_buf())
}

#[cfg(test)]
mod attachment_path_tests {
    use super::attachment_target;

    #[test]
    fn only_a_real_attachment_under_the_root_is_handed_out() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().join("attachments");
        let card = root.join("ws").join("card");
        std::fs::create_dir_all(&card).unwrap();
        let file = card.join("a-shot.png");
        std::fs::write(&file, b"png").unwrap();
        std::fs::write(tmp.path().join("secret"), b"no").unwrap();

        let ok = attachment_target(&root, &file.to_string_lossy()).unwrap();
        assert_eq!(ok, file);
        let climbing = card.join("..").join("..").join("..").join("secret");
        assert!(attachment_target(&root, &climbing.to_string_lossy()).is_err());
        let elsewhere = tmp.path().join("secret");
        assert!(attachment_target(&root, &elsewhere.to_string_lossy()).is_err());
        let missing = card.join("gone.png");
        assert_eq!(
            attachment_target(&root, &missing.to_string_lossy()).unwrap_err(),
            "attachment file is missing on disk"
        );
    }

    #[cfg(unix)]
    #[test]
    fn a_link_out_of_the_root_is_refused() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().join("attachments");
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(tmp.path().join("secret"), b"no").unwrap();
        let link = root.join("link");
        std::os::unix::fs::symlink(tmp.path().join("secret"), &link).unwrap();
        assert!(attachment_target(&root, &link.to_string_lossy()).is_err());
    }
}

/// Open an attachment in the user's default app for that file type
/// (Preview.app for images, etc.). Path-injection-guarded.
#[tauri::command(async)]
pub fn kanban_attachment_open(
    app: tauri::AppHandle,
    stored_path: String,
) -> Result<(), String> {
    let root = attachments_root(&app)?;
    let p = attachment_target(&root, &stored_path)?;
    crate::platform::open_path(&p).map_err(|e| format!("open failed: {e}"))?;
    Ok(())
}

/// GC the per-card attachments dir when the card is deleted. Attachment
/// bytes live outside the kanban JSON, so `kanban_card_delete` (v1.33.0)
/// doesn't reach them — the FE makes this call alongside the delete.
/// Best-effort: a missing dir is success.
#[tauri::command]
pub fn kanban_attachment_gc_card(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<(), String> {
    let dir = card_attachments_dir(&app, &workspace_id, &card_id)?;
    if !dir.exists() {
        return Ok(());
    }
    let root = attachments_root(&app)?;
    if !dir.starts_with(&root) {
        // Should be impossible by construction, but defend anyway.
        return Err("computed card dir is not under attachments root".into());
    }
    if let Err(e) = std::fs::remove_dir_all(&dir) {
        log::warn!(
            "kanban_attachment_gc_card: remove_dir_all of {} failed: {}",
            dir.display(),
            e
        );
    }
    Ok(())
}

/// v1.28.0 (Cycle I-2): per-card swarm cascade GC. Sibling to
/// `kanban_attachment_gc_card`. The FE drives card deletion and passes the
/// union of `card.linkedBrainstormId` + `card.linkedSwarmId` (both are swarm
/// IDs; the field split is a kanban-side role distinction). The backend
/// refuses to delete swarms that are still running, are Adhoc, or that
/// remain linked from another card in the same workspace. Returns three
/// disjoint id buckets so the FE can surface the actionable case (still
/// running → user needs to abort first).
#[tauri::command]
pub fn kanban_swarm_gc_card(
    swarms: State<'_, SwarmRegistry>,
    kanban: State<'_, KanbanStore>,
    workspace_id: String,
    card_id: String,
    swarm_ids: Vec<String>,
) -> Result<GcCardResult, String> {
    // Gather every swarm id still referenced by another card in this
    // workspace (linkedBrainstormId + linkedSwarmId on any non-deleted
    // card). Archived / Legacy cards count toward this set — archive ≠
    // delete; their linked swarms must survive.
    // R2: a board that isn't the whole picture, or can't be read, keeps them all.
    let board = kanban.load_whole(&workspace_id);
    let mut still_referenced: std::collections::HashSet<String> =
        if board.is_err() { swarm_ids.iter().cloned().collect() } else { Default::default() };
    if let Ok(cards) = board {
        for card in cards {
            if card.id == card_id {
                // The just-deleted card — its linkage shouldn't keep its own
                // swarms alive. Skip it explicitly in case the FE called this
                // before the kanban save landed.
                continue;
            }
            if let Some(id) = card.linked_brainstorm_id {
                still_referenced.insert(id);
            }
            if let Some(id) = card.linked_swarm_id {
                still_referenced.insert(id);
            }
        }
    }
    Ok(swarms.gc_swarms_for_deleted_card(&swarm_ids, &still_referenced))
}

