/// 1.174.0 (DR2, D1(b)): **Release Site…** — one area's release with zero
/// or more cards not on its target yet (`ship::release_area`). On a worker,
/// as `ship_batch`. It takes any number of ticked cards, on every plan.
#[tauri::command]
pub async fn release_area(
    app: tauri::AppHandle,
    request: ship::ReleaseAreaRequest,
) -> Result<ShipResult, crate::worktrees::ShipError> {
    // G2 walk (Mac): a Stop pressed before the worker starts finds the press.
    let press = ship::PressStop::begin(&request.workspace_id);
    tauri::async_runtime::spawn_blocking(move || {
        let _press = press;
        let workspace_id = request.workspace_id.clone();
        let card_ids = request.card_ids.clone();
        let result = ship::release_area(
            &app,
            request,
            &app.state::<WorkspaceStore>(),
            &app.state::<KanbanStore>(),
            &app.state::<ShipRegistry>(),
            &app.state::<ProjectConfigStore>(),
        )?;
        close_landed_skill_card_issues(&app, &workspace_id, &card_ids);
        Ok(result)
    })
    .await
    .map_err(|e| format!("release worker failed: {e}"))?
}

