/// GH #62: show a verify step's full log in Finder. The log of a card's
/// last run only: a newer run replaces it and removing the card's worktree
/// removes it. Falls back to the run's directory when the step wrote none.
#[tauri::command(async)]
pub fn verify_reveal_log(
    workspace_id: String,
    card_id: String,
    verify_run_id: String,
    step: String,
) -> Result<(), String> {
    let log = crate::verify_logs::step_log_path(&workspace_id, &card_id, &verify_run_id, &step)?;
    let target = if log.is_file() {
        log
    } else {
        match log.parent() {
            Some(run_dir) if run_dir.is_dir() => run_dir.to_path_buf(),
            _ => {
                return Err(
                    "The full log is gone: a newer check run replaced it, or the card's copy was removed."
                        .into(),
                )
            }
        }
    };
    crate::platform::reveal_path(&target).map_err(|e| format!("open -R failed: {e}"))?;
    Ok(())
}

