/// v1.12.1: deterministic filesystem scan that proposes a
/// `ProjectConfig` for a workspace. Used by the FE settings panel's
/// "Detect" / "Re-detect" button on first onboarding and any time
/// the user wants to refresh the inferred config (e.g. they added
/// a `scripts/install-local.sh` after the initial detection ran).
///
/// Pure read-only — does NOT write to the store. The FE shows the
/// proposal, lets the user edit, then calls `project_config_set`
/// with the final shape.
#[tauri::command(async)]
pub fn project_config_detect(
    workspaces: State<'_, WorkspaceStore>,
    workspace_id: String,
) -> Result<ProjectConfigProposal, String> {
    let cwd = workspaces
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| w.id == workspace_id)
        .map(|w| PathBuf::from(w.cwd))
        .ok_or_else(|| format!("workspace '{workspace_id}' not found"))?;
    Ok(project_config::detect_from_filesystem(&cwd))
}

/// v1.12.1: persist a per-workspace `ProjectConfig`. Used by the FE
/// settings panel after the user reviews + edits the detected
/// proposal. Atomic via the store's tempfile-rename pattern.
#[tauri::command]
pub async fn project_config_set(
    app: AppHandle,
    workspace_id: String,
    config: ProjectConfig,
) -> Result<(), String> {
    // GH #79: the project config is the definition's project part.
    tauri::async_runtime::spawn_blocking(move || {
        // GH #111 F29: a whole config (Detect, the proposal editor) keeps the
        // workspace's review settings; `project_config_set_review` owns them.
        crate::workspace_definition::edit_shared(&app, &workspace_id, || {
            app.state::<ProjectConfigStore>().set_keeping_review(&workspace_id, config)
        })
    })
    .await
    .map_err(|e| format!("project config worker failed: {e}"))?
}

