// ── Memory (v1.35.0) ──────────────────────────────────
//
// Per-workspace + opt-in global persistent learnings. Increment 1
// implements CRUD only; dispatch-time injection lands in v1.36.0,
// post-ship suggester in v1.37.0. Scope/workspaceId pair must satisfy:
// scope=workspace → workspaceId required; scope=global → workspaceId
// must be omitted/null.

/// Payload accepted by `memory_create`. The store assigns id, slug, and
/// timestamps; the caller supplies everything else.
#[derive(serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct MemoryCreateInput {
    pub title: String,
    pub body: String,
    pub scope: MemoryScope,
    #[serde(default)]
    pub workspace_id: Option<String>,
    #[serde(default)]
    pub tags: Vec<String>,
    #[serde(default)]
    pub linked_cards: Vec<String>,
    #[serde(default)]
    pub source: MemorySource,
    /// v1.68.0 (Knowledge merge): note (default) or prompt + payload.
    #[serde(default)]
    pub entry_type: crate::memory::KnowledgeType,
    #[serde(default)]
    pub system_prompt: Option<String>,
    #[serde(default)]
    pub prompt_template: Option<String>,
}

#[tauri::command]
pub fn memory_list(
    store: State<'_, MemoryStore>,
    scope: MemoryScope,
    workspace_id: Option<String>,
) -> Result<Vec<Memory>, String> {
    store.list(scope, workspace_id.as_deref())
}

