pub fn memory_get(
    store: State<'_, MemoryStore>,
    scope: MemoryScope,
    workspace_id: Option<String>,
    id: String,
) -> Result<Option<Memory>, String> {
    store.get(scope, workspace_id.as_deref(), &id)
}

#[tauri::command]
pub fn memory_create(
    store: State<'_, MemoryStore>,
    input: MemoryCreateInput,
) -> Result<Memory, String> {
    let new = NewMemory {
        title: input.title,
        body: input.body,
        scope: input.scope,
        workspace_id: input.workspace_id,
        tags: input.tags,
        linked_cards: input.linked_cards,
        source: input.source,
        entry_type: input.entry_type,
        system_prompt: input.system_prompt,
        prompt_template: input.prompt_template,
        evidence: None,
    };
    store.create(new)
}

// ── Project Knowledge scope (v1.72.0 — step 5b-2) ──────────────────
//
// v1.115.0 relabels this layer **Project** (it is shared inside one
// repository). The command names changed with the label because they reach
// the UI; `memory.rs` paths did not, so no entry moved and nothing migrated.
// "Team" now means the cross-project team library, below.

/// List the repo's committed Project-scope Knowledge entries
/// (`<cwd>/.atelier/library/knowledge/`). Missing dir ⇒ `[]`.
#[tauri::command(async)]
pub fn knowledge_list_project(
    store: State<'_, MemoryStore>,
    project_cwd: String,
) -> Result<Vec<Memory>, String> {
    store.list_shared(Path::new(&project_cwd))
}

/// GH #82: the workspace whose checkout is `project_cwd`.
fn workspace_for_cwd<R: tauri::Runtime>(app: &AppHandle<R>, project_cwd: &str) -> Option<String> {
    let wanted = crate::platform::canonicalize(project_cwd).unwrap_or_else(|_| PathBuf::from(project_cwd));
    app.try_state::<WorkspaceStore>()?
        .snapshot()
        .workspaces
        .into_iter()
        .find(|w| crate::platform::canonicalize(&w.cwd).unwrap_or_else(|_| PathBuf::from(&w.cwd)) == wanted)
        .map(|w| w.id)
}

/// GH #82: a note as the channel commits it.
fn knowledge_change(entry: &Memory) -> Result<crate::shared_library_sync::LibraryChange, String> {
    let text = crate::memory::encode_memory_entry(entry)?;
    let kind = crate::shared_library_sync::ItemKind::Knowledge;
    Ok(crate::shared_library_sync::LibraryChange::new(
        kind,
        &entry.slug,
        &entry.title,
        Some(vec![crate::shared_library_sync::LibraryFile::new(
            kind.repo_path(&entry.slug),
            text.as_bytes(),
            false,
        )]),
    ))
}

/// GH #82: refuse a different note already on the branch under `slug`.
fn refuse_slug_collision(mirror: &Path, slug: &str, text: &str) -> Result<(), String> {
    let dir = ply_memory::shared_knowledge_dir(mirror);
    // GH #206: a branch copy that cannot be inspected is not "no clash".
    if !ply_memory::slug_exists_case_insensitive(&dir, slug)
        .map_err(|e| format!("inspect shared knowledge: {e}"))?
    {
        return Ok(());
    }
    let same = std::fs::read(dir.join(format!("{slug}.md")))
        .map(|bytes| bytes == text.as_bytes())
        .unwrap_or(false);
    if same {
        Ok(())
    } else {
        Err(crate::memory::slug_collision_message())
    }
}

/// Move a personal entry into the repo's Project layer.
///
/// GH #82: in a shared workspace the note is published to the integration
/// branch through the channel instead of written into the checkout.
#[tauri::command]
pub async fn knowledge_promote_project<R: tauri::Runtime>(
    app: AppHandle<R>,
    project_cwd: String,
    id: String,
    workspace_id: Option<String>,
) -> Result<Memory, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let store = app.state::<MemoryStore>();
        let scope = if workspace_id.is_some() {
            MemoryScope::Workspace
        } else {
            MemoryScope::Global
        };
        if let Some(shared_ws) = workspace_for_cwd(&app, &project_cwd) {
            let (mut entry, text) = store.shared_publish_plan(scope, workspace_id.as_deref(), &id)?;
            let queued = crate::workspace_definition::app_library_change(&app, &shared_ws, |mirror| {
                refuse_slug_collision(mirror, &entry.slug, &text)?;
                let mut change = knowledge_change(&entry)?;
                // The personal note stays until the change is on the branch
                // (a refresh removes it then), so a pull request closed
                // without merging loses nothing.
                change.personal_source = Some(crate::shared_library_sync::PersonalSource {
                    workspace_id: workspace_id.clone(),
                    id: entry.id.clone(),
                    updated_at: entry.updated_at.clone(),
                });
                Ok((Some(change), ()))
            })?;
            if queued.is_some() {
                entry.shared = true;
                entry.layer = crate::memory::KnowledgeLayer::Project;
                return Ok(entry);
            }
        }
        match workspace_id.as_deref() {
            Some(workspace_id) => store.promote_scope_to_shared(
                MemoryScope::Workspace,
                Some(workspace_id),
                &id,
                Path::new(&project_cwd),
            ),
            None => store.promote_to_shared(&id, Path::new(&project_cwd)),
        }
    })
    .await
    .map_err(|e| format!("join knowledge promote project: {e}"))?
}

/// Move a Project entry back into the personal Global layer.
///
/// GH #82: in a shared workspace the removal is published through the channel.
#[tauri::command]
pub async fn knowledge_demote_project<R: tauri::Runtime>(
    app: AppHandle<R>,
    project_cwd: String,
    id: String,
) -> Result<Memory, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let store = app.state::<MemoryStore>();
        if let Some(shared_ws) = workspace_for_cwd(&app, &project_cwd) {
            let queued = crate::workspace_definition::app_library_change(&app, &shared_ws, |mirror| {
                let entry = ply_memory::read_shared(mirror)?
                    .into_iter()
                    .find(|m| m.id == id)
                    .ok_or_else(|| format!("knowledge entry not found in shared: {id}"))?;
                // The personal copy first: if it can't be saved, no removal
                // is queued. (A failure after it leaves a visible duplicate,
                // never a lost note.)
                let personal = store.adopt_shared_entry(&entry, false)?;
                let mut change = knowledge_change(&entry)?;
                change.files = None;
                Ok((Some(change), personal))
            })?;
            if let Some(personal) = queued {
                return Ok(personal);
            }
        }
        store.demote_to_personal(&id, Path::new(&project_cwd))
    })
    .await
    .map_err(|e| format!("join knowledge demote project: {e}"))?
}

/// A Shared · Project note as the editor sends it.
#[derive(serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ProjectNoteInput {
    /// Absent for a new note.
    #[serde(default)]
    pub id: Option<String>,
    pub title: String,
    pub body: String,
    #[serde(default)]
    pub tags: Vec<String>,
}

/// GH #82: whether this workspace's Shared · Project notes and project skills
/// go through the channel, and whether this Mac may write them.
#[tauri::command]
pub async fn knowledge_project_state(
    app: AppHandle,
    workspace_id: String,
) -> Result<crate::workspace_definition::LibraryState, String> {
    tauri::async_runtime::spawn_blocking(move || {
        crate::workspace_definition::app_library_state(&app, &workspace_id)
    })
    .await
    .map_err(|e| format!("join knowledge project state: {e}"))?
}

/// GH #82: create or edit a Shared · Project note. A shared workspace
/// publishes it to the integration branch (`knowledge: <title>`); any other
/// writes it into the checkout's `.atelier/library/knowledge/`.
#[tauri::command]
pub async fn knowledge_project_save(
    app: AppHandle,
    workspace_id: String,
    input: ProjectNoteInput,
) -> Result<Memory, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let title = input.title.trim().to_string();
        if title.is_empty() {
            return Err("Title is required".to_string());
        }
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        let now = chrono::Utc::now().to_rfc3339();
        // `name_new`: choose a new note's name here (the channel's mirror).
        // The checkout's new note is named as it is created, below.
        let build = |root: &Path, name_new: bool| -> Result<Memory, String> {
            let dir = ply_memory::shared_knowledge_dir(root);
            // An empty id is a new note, as the editor's blank draft sends it.
            match input.id.as_deref().filter(|id| !id.is_empty()) {
                Some(id) => {
                    let mut entry = ply_memory::read_shared(root)?
                        .into_iter()
                        .find(|m| m.id == id)
                        .ok_or_else(|| format!("knowledge entry not found in shared: {id}"))?;
                    entry.title = title.clone();
                    entry.body = input.body.clone();
                    entry.tags = input.tags.clone();
                    entry.updated_at = now.clone();
                    Ok(entry)
                }
                None => Ok(Memory {
                    id: uuid::Uuid::new_v4().to_string(),
                    // GH #206: an uninspectable directory fails the save.
                    slug: if name_new {
                        ply_memory::next_available_slug(&dir, &title)
                            .map_err(|e| format!("inspect shared knowledge: {e}"))?
                    } else {
                        String::new()
                    },
                    title: title.clone(),
                    scope: MemoryScope::Global,
                    workspace_id: None,
                    tags: input.tags.clone(),
                    linked_cards: Vec::new(),
                    source: MemorySource::Manual,
                    entry_type: Default::default(),
                    system_prompt: None,
                    prompt_template: None,
                    shared: true,
                    layer: crate::memory::KnowledgeLayer::Project,
                    evidence: None,
                    body: input.body.clone(),
                    created_at: now.clone(),
                    updated_at: now.clone(),
                }),
            }
        };
        let queued = crate::workspace_definition::app_library_change(&app, &workspace_id, |mirror| {
            let entry = build(mirror, true)?;
            Ok((Some(knowledge_change(&entry)?), entry))
        })?;
        if let Some(entry) = queued {
            return Ok(entry);
        }
        // Not shared: the checkout, as before GH #82.
        let mut entry = build(&cwd, false)?;
        let text = crate::memory::encode_memory_entry(&entry)?;
        let dir = ply_memory::shared_knowledge_dir(&cwd);
        if input.id.as_deref().is_some_and(|id| !id.is_empty()) {
            // An edit keeps its file.
            let path = dir.join(format!("{}.md", entry.slug));
            crate::atomic::write_atomic_text(&path, &text)?;
        } else {
            // GH #206: a new note is created, never written over another.
            entry.slug = crate::memory::publish_new_note(&dir, &entry.title, &text)?;
        }
        Ok(entry)
    })
    .await
    .map_err(|e| format!("join knowledge project save: {e}"))?
}

/// GH #82: delete a Shared · Project note — published as a removal in a
/// shared workspace, removed from the checkout otherwise.
#[tauri::command]
pub async fn knowledge_project_delete(
    app: AppHandle,
    workspace_id: String,
    id: String,
) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        let find = |root: &Path| -> Result<Memory, String> {
            ply_memory::read_shared(root)?
                .into_iter()
                .find(|m| m.id == id)
                .ok_or_else(|| format!("knowledge entry not found in shared: {id}"))
        };
        let queued = crate::workspace_definition::app_library_change(&app, &workspace_id, |mirror| {
            let mut change = knowledge_change(&find(mirror)?)?;
            change.files = None;
            Ok((Some(change), ()))
        })?;
        if queued.is_some() {
            return Ok(());
        }
        let entry = find(&cwd)?;
        crate::memory::remove_project_entry(&cwd, &entry.slug)
    })
    .await
    .map_err(|e| format!("join knowledge project delete: {e}"))?
}

/// GH #82: publish the checkout's `.claude/skills/<skill>` to the integration
/// branch (`skill: <name>`), so every Mac's Claude loads it.
///
/// Owner, 2026-10-19 (R15): a publish that brings a new or changed script, or
/// a file that is not text, onto the branch is refused — with
/// `SCRIPTS_WAIT_MARKER` — unless `scripts_ok` names what the scripts sheet
/// (`project_skill_publish_review`) showed. Checked here, where the change is
/// queued, so no window can publish a script without it.
#[tauri::command]
pub async fn project_skill_publish(
    app: AppHandle,
    workspace_id: String,
    skill: String,
    scripts_ok: Option<Vec<String>>,
) -> Result<crate::shared_library_sync::SkillPublish, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        crate::shared_library_sync::check_name(&skill)?;
        let library = skill_publish_paths(&app, &workspace_id, &cwd);
        let queued = crate::workspace_definition::app_library_change_now(&app, &workspace_id, |_| {
            let git = crate::shared_config::Plumbing { cwd: cwd.clone() };
            let crate::shared_library_sync::CheckoutPublish { files, paths, bases, follows, left, tip } =
                crate::shared_library_sync::checkout_publish(&git, &library, &cwd, &skill)?;
            crate::skill_scripts::publish::answer(
                &git,
                tip.as_deref(),
                &crate::shared_library_sync::branch_name(&library),
                &skill,
                &files,
                &paths,
                scripts_ok.as_deref(),
            )?;
            Ok((
                Some(crate::shared_library_sync::LibraryChange {
                    paths,
                    bases,
                    checkout_copy: true,
                    checkout_head: git.head(),
                    follow_left: left,
                    ..crate::shared_library_sync::LibraryChange::new(
                        crate::shared_library_sync::ItemKind::Skill,
                        &skill,
                        &skill,
                        Some(files),
                    )
                }),
                crate::shared_library_sync::SkillPublish { follows, ..Default::default() },
            ))
        })?;
        // Owner, 2026-10-19: the push runs now, so the toast can say what it
        // did — published, or queued (offline, retried on the next Sync).
        let (mut done, report) = queued.ok_or_else(|| {
            "This repository has no shared workspace definition, so its skills travel with cards."
                .to_string()
        })?;
        done.outcome = crate::shared_library_sync::skill_publish_outcome(
            report.as_ref().and_then(|r| r.library.as_ref()),
            &skill,
        );
        Ok(done)
    })
    .await
    .map_err(|e| format!("join project skill publish: {e}"))?
}

fn skill_publish_paths(app: &AppHandle, workspace_id: &str, cwd: &Path) -> crate::shared_library_sync::Paths {
    crate::shared_library_sync::Paths {
        workspace_dir: app
            .state::<crate::project_config::ProjectConfigStore>()
            .workspace_dir(workspace_id),
        cwd: cwd.to_path_buf(),
    }
}

/// Owner, 2026-10-19 (R15): the scripts sheet before `Publish to <branch>` /
/// `Update on <branch>` — every file the publish would write onto the shared
/// workspace's branch, scripts first, when it brings a new or changed script
/// or a file that is not text. `None`: nothing to ask, publish as before (and
/// for a workspace with no shared definition yet, whose publish says so).
/// Read-only.
#[tauri::command]
pub async fn project_skill_publish_review(
    app: AppHandle,
    workspace_id: String,
    skill: String,
) -> Result<Option<crate::skill_scripts::ScriptsReview>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        crate::shared_library_sync::check_name(&skill)?;
        let library = skill_publish_paths(&app, &workspace_id, &cwd);
        if crate::shared_library_sync::load_manifest(&library).is_none() {
            return Ok(None);
        }
        let started = std::time::Instant::now();
        let git = crate::shared_config::Plumbing { cwd: cwd.clone() };
        let publish = crate::shared_library_sync::checkout_publish(&git, &library, &cwd, &skill)?;
        let review =
            crate::skill_scripts::publish::review(&git, publish.tip.as_deref(), &skill, &publish.files, &publish.paths);
        // Publish-sheet walk: a press that seemed to do nothing leaves a line.
        log::info!(
            "skills hub: publish review of {skill}: {} in {} ms",
            match &review {
                Ok(Some(_)) => "the sheet",
                Ok(None) => "nothing to ask",
                Err(_) => "refused",
            },
            started.elapsed().as_millis()
        );
        review
    })
    .await
    .map_err(|e| format!("join project skill publish review: {e}"))?
}

/// GH #82: remove a project skill from the integration branch. The checkout
/// is untouched.
#[tauri::command]
pub async fn project_skill_unpublish(
    app: AppHandle,
    workspace_id: String,
    skill: String,
    // Group B §2 review 1: the skill's id the row showed (`MirrorSkill.id`), so
    // the removal's base is the version on screen. `None` from an older window:
    // the mirror's at the press, as before.
    shown: Option<String>,
) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        crate::shared_library_sync::check_name(&skill)?;
        // 1.169.0 (C4): published after the Undo window, not at once.
        let queued = crate::workspace_definition::app_library_change_after(&app, &workspace_id, SKILL_REMOVAL_UNDO, |_| {
            Ok((
                Some(crate::shared_library_sync::LibraryChange {
                    bases: shown
                        .as_deref()
                        .map(|id| crate::shared_library_sync::skill_bases_from_id(&skill, Some(id)))
                        .unwrap_or_default(),
                    // GH #105: the skill is one item in two roots, so removing it
                    // takes both copies. Claiming the Claude root alone left the
                    // Codex copy on the branch, and Codex went on loading it.
                    paths: crate::shared_library_sync::ItemKind::Skill.repo_paths(&skill),
                    // C4 (Challenger): never published inside the Undo window,
                    // whichever drain comes first.
                    not_before: crate::shared_config::now_millis() + SKILL_REMOVAL_UNDO.as_millis() as i64,
                    ..crate::shared_library_sync::LibraryChange::new(
                        crate::shared_library_sync::ItemKind::Skill,
                        &skill,
                        &skill,
                        None,
                    )
                }),
                (),
            ))
        })?;
        queued.ok_or_else(|| {
            "This repository has no shared workspace definition, so its skills travel with cards."
                .to_string()
        })
    })
    .await
    .map_err(|e| format!("join project skill unpublish: {e}"))?
}

/// 1.169.0 (C4): how long a skill's removal waits, queued, before it is
/// published — its toast's Undo (`project_skill_unpublish_undo`).
pub const SKILL_REMOVAL_UNDO: std::time::Duration = std::time::Duration::from_secs(10);

/// 1.169.0 (C4): `Undo` on `Removing <skill> from <branch>`: take the queued
/// removal back while it waits, saying what it found
/// (`shared_library_sync::RemovalWithdrawal`), or that this project has no
/// shared library any more (`noLibrary`).
#[tauri::command]
pub async fn project_skill_unpublish_undo(app: AppHandle, workspace_id: String, skill: String) -> Result<String, String> {
    tauri::async_runtime::spawn_blocking(move || {
        crate::shared_library_sync::check_name(&skill)?;
        use crate::shared_library_sync::RemovalWithdrawal as W;
        let found = crate::workspace_definition::withdraw_library_removal(
            &app,
            &workspace_id,
            crate::shared_library_sync::ItemKind::Skill,
            &skill,
        )?;
        Ok(match found {
            None => "noLibrary",
            Some(W::Withdrawn) => "withdrawn",
            Some(W::Restored) => "restored",
            Some(W::NotQueued) => "notQueued",
            Some(W::Replaced) => "replaced",
        }
        .to_string())
    })
    .await
    .map_err(|e| format!("join project skill unpublish undo: {e}"))?
}

/// GH #105: `Make available to both` / `Make all available to both` — create
/// the missing copy of each skill on the integration branch, through the shared
/// channel, in **one commit** for the whole action.
///
/// The copy is made on the branch, out of the copy that is already there (the
/// mirror is the branch's tip with this Mac's queued changes over it): it is the
/// shared skill that reaches teammates, and nothing in the member's checkout is
/// read or written. A skill that cannot be carried over is skipped with its
/// reason and the rest still travel — [`crate::skill_reach`] holds those rules,
/// and they are the copy rules this app already had.
///
/// Not team-gated: this writes the repository's own integration branch, exactly
/// as `project_skill_publish` does, and never the team library. The read-only
/// refusal is `app_library_change`'s, so a collaborator without write access is
/// stopped before anything is queued.
#[tauri::command]
pub async fn project_skills_available_to_both(
    app: AppHandle,
    workspace_id: String,
    skills: Vec<String>,
) -> Result<crate::skill_reach::ReachOutcome, String> {
    tauri::async_runtime::spawn_blocking(move || {
        if skills.is_empty() {
            return Err("No skill was named to make available to both.".to_string());
        }
        let state = crate::workspace_definition::app_library_state(&app, &workspace_id)?;
        let branch = state
            .branch
            .clone()
            .unwrap_or_else(|| "the integration branch".to_string());
        // What the mirror leaves out and says so: a root whose copy holds a
        // symlink is not in the build, and without this it would read as a
        // missing copy (review 1, MAJOR).
        let hidden = crate::skill_reach::hidden_copies(&state.skipped);
        let queued =
            crate::workspace_definition::app_library_change(&app, &workspace_id, |mirror| {
                let plan = crate::skill_reach::plan_both(mirror, &skills, &branch, &hidden);
                let outcome = crate::skill_reach::ReachOutcome {
                    queued: plan.copies.iter().map(|copy| copy.name.clone()).collect(),
                    skipped: plan.skipped.clone(),
                    already: plan.already.clone(),
                    branch: state.branch.clone(),
                };
                let (title, message) = crate::skill_reach::both_words(&plan.copies);
                let change = match plan.copies.as_slice() {
                    [] => None,
                    [one] => Some(crate::skill_reach::one_change(one, title, message)),
                    many => Some(crate::skill_reach::group_change(many, title, message)?),
                };
                Ok((change, outcome))
            })?;
        queued.ok_or_else(|| {
            "This repository has no shared workspace definition, so its skills travel with cards."
                .to_string()
        })
    })
    .await
    .map_err(|e| format!("join project skills available to both: {e}"))?
}

/// GH #105: `Align` — the two copies of a skill on the integration branch
/// disagree, and the member chose which one wins. One commit, through the same
/// channel; the loser's copy is replaced by the winner's, file for file.
#[tauri::command]
pub async fn project_skill_align(
    app: AppHandle,
    workspace_id: String,
    skill: String,
    winner: String,
    // Group B §2 review 1: the id the Compare/Align dialog showed.
    shown: Option<String>,
) -> Result<crate::skill_reach::ReachOutcome, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let winner = crate::skill_reach::Side::parse(&winner)?;
        let state = crate::workspace_definition::app_library_state(&app, &workspace_id)?;
        let branch = state
            .branch
            .clone()
            .unwrap_or_else(|| "the integration branch".to_string());
        let queued =
            crate::workspace_definition::app_library_change(&app, &workspace_id, |mirror| {
                let copy = crate::skill_reach::plan_align(mirror, &skill, winner, &branch)?;
                let (title, message) = crate::skill_reach::align_words(&copy);
                let mut change = crate::skill_reach::one_change(&copy, title, message);
                if let Some(id) = shown.as_deref() {
                    change.bases = crate::shared_library_sync::skill_bases_from_id(&skill, Some(id));
                }
                Ok((
                    Some(change),
                    crate::skill_reach::ReachOutcome {
                        queued: vec![skill.clone()],
                        skipped: Vec::new(),
                        already: Vec::new(),
                        branch: state.branch.clone(),
                    },
                ))
            })?;
        queued.ok_or_else(|| {
            "This repository has no shared workspace definition, so its skills travel with cards."
                .to_string()
        })
    })
    .await
    .map_err(|e| format!("join project skill align: {e}"))?
}

// ── Improvement proposals (GH #104, ADR 0005; BOARDS.md §4 state C) ──
//
// The Challenger's one suggested change after a card that met friction. The
// pass itself is `proposals::after_last_review`, on the Challenger's own
// thread; the three below are what the interface asks of it, and the fourth is
// the one fact only the window can count.

/// GH #104: this workspace's improvement proposal, or `null`.
///
/// Read by all three surfaces — the block on the target's Library page, the
/// Inbox item and the card's Ship step — through `proposals::current`, which is
/// also where the staleness rules are applied: a proposal older than 30 days or
/// whose target changed under it is dropped here, once, so the three can never
/// disagree about whether there is one.
#[tauri::command]
pub async fn improvement_proposal_state(
    app: AppHandle,
    workspace_id: String,
) -> Result<Option<crate::proposals::ProposalView>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        let workspace_dir = app
            .state::<crate::project_config::ProjectConfigStore>()
            .workspace_dir(&workspace_id);
        // A read-only collaborator reads the proposal and is offered no
        // `Approve and publish`: the channel would refuse the write, and a
        // button that cannot work is not offered (PATTERNS.md §3). SP-5: a
        // workspace with no shared definition approves too, as a commit on the
        // project's integration branch — `Approve and commit to <branch>` when
        // the repository has no remote to publish to.
        let library = crate::workspace_definition::app_library_state(&app, &workspace_id).ok();
        let target_branch = app
            .state::<crate::project_config::ProjectConfigStore>()
            .get(&workspace_id)
            .map(|config| config.target_branch);
        let has_origin = crate::shared_config::Plumbing { cwd: cwd.clone() }.has_origin();
        let (can_approve, commit_to) = crate::proposals::approve_offer(
            library.as_ref().is_some_and(|state| state.shared),
            library.as_ref().is_some_and(|state| state.read_only),
            target_branch.as_deref(),
            has_origin,
        );
        let found = crate::proposals::current(
            &workspace_dir,
            &cwd,
            can_approve,
            crate::shared_config::now_millis(),
        );
        // GH #104 review 1 (MINOR): a read that dropped a stale proposal has
        // just made the other two surfaces wrong, so they are told.
        if found.dropped {
            announce_proposal_change(&app, &workspace_id);
        }
        // SP-5 review: a local commit is made from the branch's copy, so one
        // the Challenger did not read is never offered — the block says why.
        let approve_blocked = match (&commit_to, found.view.as_ref()) {
            (Some(branch), Some(view)) if view.can_approve => crate::proposals::load(&workspace_dir)
                .proposal
                .and_then(|stored| {
                    crate::proposals::local_commit_blocker(
                        &crate::shared_config::Plumbing { cwd: cwd.clone() },
                        &stored,
                        branch,
                    )
                }),
            _ => None,
        };
        let can_approve = found.view.as_ref().is_some_and(|view| view.can_approve)
            && approve_blocked.is_none();
        // SP-5 walk: before the press, what Approve does to the skill's other
        // CLI's copy — read from where the change is made from: the mirror on
        // the shared channel, else the (last fetched) integration branch.
        let copies_note = if can_approve {
            proposal_copies_hint(&app, &workspace_id, &workspace_dir, &cwd, library.as_ref(), target_branch.as_deref(), has_origin)
        } else {
            None
        };
        Ok(found.view.map(|view| crate::proposals::ProposalView {
            can_approve,
            commit_to,
            approve_blocked,
            copies_note,
            ..view
        }))
    })
    .await
    .map_err(|e| format!("join improvement proposal state: {e}"))?
}

/// SP-5 walk: [`crate::proposals::copies_hint`] for the workspace's proposal.
fn proposal_copies_hint(
    app: &AppHandle,
    workspace_id: &str,
    workspace_dir: &Path,
    cwd: &Path,
    library: Option<&crate::workspace_definition::LibraryState>,
    target_branch: Option<&str>,
    has_origin: bool,
) -> Option<String> {
    let stored = crate::proposals::load(workspace_dir).proposal?;
    if !matches!(stored.target, crate::proposals::ProposalTarget::Skill { .. }) {
        return None;
    }
    let git_bin = crate::doctor::require("git").ok()?;
    // Advisory: read without the workspace lock, and cached per (proposal,
    // source build or tip), so the block's refresh never waits behind a fetch,
    // push or drain and never recomputes the same answer.
    if library.is_some_and(|state| state.shared) {
        let mirror = crate::workspace_definition::app_library_mirror(app, workspace_id)?;
        let key = mirror.to_string_lossy().into_owned();
        return cached_copies_hint(workspace_id, stored.created_at, key, || {
            crate::proposals::copies_hint(&git_bin, &stored, cwd, &mirror)
        });
    }
    let branch = target_branch?;
    let rev = if has_origin {
        format!("refs/remotes/origin/{branch}")
    } else {
        format!("refs/heads/{branch}")
    };
    let git = crate::shared_config::Plumbing { cwd: cwd.to_path_buf() };
    let tip = git.rev_parse_commit(&rev)?;
    cached_copies_hint(workspace_id, stored.created_at, tip.clone(), || {
        crate::proposals::copies_hint_at(&git_bin, &git, &tip, &stored, cwd)
    })
}

/// One remembered hint per workspace, keyed by the proposal and the source
/// it was read from.
fn cached_copies_hint(
    workspace_id: &str,
    created_at: i64,
    source: String,
    compute: impl FnOnce() -> Option<String>,
) -> Option<String> {
    type Entry = (i64, String, Option<String>);
    static CACHE: std::sync::LazyLock<std::sync::Mutex<std::collections::HashMap<String, Entry>>> =
        std::sync::LazyLock::new(Default::default);
    if let Some((at, from, hint)) = CACHE.lock().unwrap_or_else(|p| p.into_inner()).get(workspace_id) {
        if *at == created_at && *from == source {
            return hint.clone();
        }
    }
    let hint = compute();
    CACHE
        .lock()
        .unwrap_or_else(|p| p.into_inner())
        .insert(workspace_id.to_string(), (created_at, source, hint.clone()));
    hint
}

/// GH #104: the proposal changed — written, dropped, dismissed or published —
/// so every surface that shows one re-reads it. The one emitter outside the
/// pass itself (`proposals::after_last_review` emits its own).
fn announce_proposal_change(app: &AppHandle, workspace_id: &str) {
    use tauri::Emitter;
    let _ = app.emit(crate::proposals::PROPOSAL_CHANGED_EVENT, workspace_id);
}

/// The card whose last improvement-proposal pass stopped at Claude's trust
/// question, or `null`: that card shows the trust step where its proposal
/// would appear. A file read; nothing runs.
#[tauri::command]
pub async fn improvement_proposal_trust_stopped(
    app: AppHandle,
    workspace_id: String,
) -> Result<Option<String>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let workspace_dir = app
            .state::<crate::project_config::ProjectConfigStore>()
            .workspace_dir(&workspace_id);
        Ok(crate::proposals::trust_stopped_card(&workspace_dir))
    })
    .await
    .map_err(|e| format!("join improvement proposal trust read: {e}"))?
}

/// GH #104: `Dismiss` — forget it. The card is still remembered, so the
/// Challenger is not asked about the same card again.
#[tauri::command]
pub async fn improvement_proposal_dismiss(
    app: AppHandle,
    workspace_id: String,
) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        let workspace_dir = app
            .state::<crate::project_config::ProjectConfigStore>()
            .workspace_dir(&workspace_id);
        crate::proposals::dismiss(&workspace_dir)?;
        announce_proposal_change(&app, &workspace_id);
        Ok(())
    })
    .await
    .map_err(|e| format!("join improvement proposal dismiss: {e}"))?
}

/// GH #104: `Approve and publish` — the change goes onto the integration
/// branch through the shared channel's **existing** paths.
///
/// A skill travels as the `Update on <branch>` action's own change: the
/// integration branch's copy of the skill under the one root the proposal
/// names, with the diffed file patched, claiming only that root so the other
/// CLI's copy on the branch is left as it is. Only a skill the branch has never
/// carried is taken from the checkout, and only from a clean directory. An
/// instruction file travels GH #101's never-override path, so one that moved on
/// the branch opens a pull request or is reported blocked and is never written
/// over. Nothing here writes the checkout: the change is queued and drained,
/// and the checkout receives it with the normal Sync, exactly as
/// `library_instructions_set_up` does it.
///
/// The proposal is forgotten in the same call: it has been answered.
///
/// SP-5: a workspace with **no** shared definition approves too
/// (`proposals::approve_unshared`, ADR 0003's 2026-10-01 amendment): a commit
/// on the project's integration branch, pushed only when there is a remote,
/// never over a newer change. That path answers with its own words for the
/// toast; the shared channel's path answers `None` and the page says its own.
#[tauri::command]
pub async fn improvement_proposal_approve(
    app: AppHandle,
    workspace_id: String,
) -> Result<Option<crate::proposals::Approved>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let (_, cwd) = workspace_checkout(&app, &workspace_id)?;
        let workspace_dir = app
            .state::<crate::project_config::ProjectConfigStore>()
            .workspace_dir(&workspace_id);
        // GH #104 review 1 (MINOR): through `current`, so the staleness rules
        // hold here too — a window left open past the thirtieth day could
        // otherwise publish a proposal the pages had already stopped showing.
        let found = crate::proposals::current(
            &workspace_dir,
            &cwd,
            true,
            crate::shared_config::now_millis(),
        );
        if found.dropped {
            announce_proposal_change(&app, &workspace_id);
        }
        if found.view.is_none() {
            return Err("There is no suggested skill change to publish.".to_string());
        }
        let proposal = crate::proposals::load(&workspace_dir)
            .proposal
            .ok_or_else(|| "There is no suggested skill change to publish.".to_string())?;
        // `app_library_change` holds the workspace lock, refuses a read-only
        // collaborator in words and hands the mirror in — so the bases the
        // never-override rule compares are read under the same lock the publish
        // runs under, not from a window that may be a minute stale.
        // SP-5 walk: a skill's other CLI's copy that was the same file takes
        // the change too; one that already differed is left, and said.
        let queued =
            crate::workspace_definition::app_library_change(&app, &workspace_id, |mirror| {
                let git = crate::doctor::require("git")?;
                let approval = crate::proposals::approve_change_full(&git, &proposal, &cwd, mirror)?;
                let note = crate::proposals::copies_note(
                    &proposal,
                    approval.copies,
                    crate::proposals::Tense::Queued,
                );
                Ok((Some(approval.change), note))
            })?;
        let approved = match queued {
            Some(None) => None,
            Some(Some(note)) => {
                let branch = crate::workspace_definition::app_library_state(&app, &workspace_id)
                    .ok()
                    .and_then(|state| state.branch)
                    .unwrap_or_else(|| "the integration branch".to_string());
                Some(crate::proposals::Approved {
                    title: format!("Publishing the change to {branch}"),
                    body: format!(
                        "Everyone who opens this repo gets it after their next refresh. Your checkout is untouched. {note}"
                    ),
                })
            }
            None => Some(approve_unshared_proposal(&app, &workspace_id, &proposal)?),
        };
        crate::proposals::dismiss(&workspace_dir)?;
        announce_proposal_change(&app, &workspace_id);
        Ok(approved)
    })
    .await
    .map_err(|e| format!("join improvement proposal approve: {e}"))?
}

/// SP-5: [`improvement_proposal_approve`] for a workspace with no shared
/// definition. Under the workspace lock (lock order: workspace lock →
/// `integration_lock` → the fast-forward lock, never `CARD_START_LOCK`); the
/// definition is read again under it, so a definition adopted meanwhile is
/// refused rather than committed around.
fn approve_unshared_proposal(
    app: &AppHandle,
    workspace_id: &str,
    proposal: &crate::proposals::StoredProposal,
) -> Result<crate::proposals::Approved, String> {
    let branch = app
        .state::<crate::project_config::ProjectConfigStore>()
        .get(workspace_id)
        .map(|config| config.target_branch)
        .filter(|branch| !branch.trim().is_empty())
        .ok_or_else(|| {
            "This workspace has no integration branch yet, so there is nowhere to commit the change. \
Choose one in Setup."
                .to_string()
        })?;
    let git = crate::doctor::require("git")?;
    let gh = crate::doctor::require("gh").ok().map(crate::shared_config::Gh::new);
    crate::workspace_definition::with_workspace_lock(app, workspace_id, |stores, repo| {
        if crate::workspace_definition::library_target(stores, repo, workspace_id).is_some() {
            return Err(
                "This repository now has a shared workspace definition. Approve again to publish through it."
                    .to_string(),
            );
        }
        crate::proposals::approve_unshared(
            &git,
            gh.as_ref(),
            proposal,
            &repo.cwd,
            &branch,
            crate::shared_config::now_millis() / 1000,
        )
    })
}

/// GH #104: the human typed a correction into the Builder session after its
/// first answer — one of the three conditions the friction rule reads.
///
/// The window counts it because the window is where the human's keystrokes
/// are: the Builder is the vendor's own TUI in a PTY, and Ply keeps no
/// transcript of it (`builder::BuilderSession::capture` is the **output** side,
/// in memory, for xterm replay). `BuilderSession`'s `onData` is the hand and
/// nothing else — Ply's own injections reach `pty_write` directly — and
/// `lib/proposals.ts::countsAsCorrection` is the rule it applies.
#[tauri::command]
pub fn builder_note_correction(
    kanban: State<'_, crate::kanban::KanbanStore>,
    workspace_id: String,
    card_id: String,
    // GH #104 walk (B3): the words of the correction, as the window read them
    // (`lib/proposals.ts::correctionPayload`). Optional, so an older window's
    // call still counts; kept bounded on the card (`remember_correction`).
    text: Option<String>,
) -> Result<u32, String> {
    // SL-6: a build of a card built by both has no Builder record of its
    // own yet; the friction rule counts the picked one's session from then.
    if crate::build_both::parse_lane_key(&card_id).is_some() {
        return Ok(0);
    }
    let mut counted = 0;
    kanban.with_card(&workspace_id, &card_id, |card| {
        if let Some(builder) = card.builder.as_mut() {
            builder.user_corrections = builder.user_corrections.saturating_add(1);
            counted = builder.user_corrections;
            if let Some(text) = text.as_deref() {
                builder.remember_correction(text);
            }
        }
        Ok(())
    })?;
    Ok(counted)
}

/// Copy a Project entry into a fresh personal Global entry.
#[tauri::command]
pub fn knowledge_fork_project(
    license: State<'_, crate::license::LicenseStore>,
    store: State<'_, MemoryStore>,
    project_cwd: String,
    id: String,
) -> Result<Memory, String> {
    team_gate(&license)?;
    store.fork_to_personal(&id, Path::new(&project_cwd))
}

// ── Team Knowledge scope (v1.115.0 — team sharing rung 2) ───────────
//
// Shared *everywhere*, not just inside one repo: the team library in the
// team repo, cloned at `<app-support>/team/<slug>/library/knowledge/`. Every
// write goes through `team::publish_library_change` — pull, write, commit,
// push — so a member never has to know there is a repository behind it.
// These three commands shell out to git over the network, so they run on the
// blocking pool exactly as the rung-1 team commands do.

/// Where the Team scope lives on this Mac, and why it might not.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TeamKnowledgeView {
    /// A key naming a team repo is present.
    pub configured: bool,
    /// The team repo is cloned on this Mac.
    pub has_clone: bool,
    /// Why the list is empty for a reason other than "no entries yet".
    pub reason: Option<String>,
    /// Writing into the team library is a paid team feature; reading is not.
    pub can_share: bool,
    pub entries: Vec<Memory>,
}

/// The clone directory of the team this Mac is in, or the reason there is
/// none. `Ok(None)` is not an error — most machines have no team.
fn team_knowledge_target(app: &AppHandle) -> Result<Option<(String, PathBuf)>, String> {
    let Some(slug) = current_team_repo(app) else {
        return Ok(None);
    };
    let team = app.state::<crate::team::TeamStore>();
    Ok(Some((slug.clone(), team.clone_dir(&slug))))
}

/// Read the Team scope. No gate and no network: reading the team library is
/// free, and the clone is pulled by Settings → Team and before every write.
#[tauri::command]
pub async fn knowledge_list_team(app: AppHandle) -> Result<TeamKnowledgeView, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_knowledge_view(
            &app.state::<crate::license::LicenseStore>(),
            &app.state::<SettingsStore>(),
            &app.state::<crate::team::TeamStore>(),
            &app.state::<MemoryStore>(),
        )
    })
    .await
    .map_err(|error| format!("join knowledge list team: {error}"))?
}

/// [`knowledge_list_team`] over the stores themselves.
pub(crate) fn team_knowledge_view(
    license: &crate::license::LicenseStore,
    settings: &SettingsStore,
    team: &crate::team::TeamStore,
    memory: &MemoryStore,
) -> Result<TeamKnowledgeView, String> {
    let can_share = license.team_allowed();
    let Some(clone_dir) = team_repo_of(settings).map(|slug| team.clone_dir(&slug))
    else {
        return Ok(TeamKnowledgeView {
            configured: false,
            has_clone: false,
            reason: Some(no_team_message()),
            can_share,
            entries: Vec::new(),
        });
    };
    if !clone_dir.join(".git").exists() {
        return Ok(TeamKnowledgeView {
            configured: true,
            has_clone: false,
            reason: Some(
                format!("The team repo is not cloned on {THIS_MACHINE} yet. Open Settings › Team › Members and library and refresh."),
            ),
            can_share,
            entries: Vec::new(),
        });
    }
    let entries = memory.list_team(&clone_dir)?;
    Ok(TeamKnowledgeView {
        configured: true,
        has_clone: true,
        reason: None,
        can_share,
        entries,
    })
}

/// Where a Share/Promote into the team library takes the entry from.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum TeamPromoteSource {
    /// Personal, one project.
    Workspace,
    /// Personal, everywhere.
    Global,
    /// Shared inside one repository — the Promote direction.
    Project,
}

/// The result of a Share/Promote into the team library.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TeamPromoteOutcome {
    /// The entry as it now sits in the team library.
    pub entry: Memory,
    /// Set when Ply deliberately did *not* remove the source, and why. The
    /// panel says this out loud rather than reporting a plain success.
    pub note: Option<String>,
}

/// Share or promote one entry into the team library: pull, write, commit,
/// push, then remove it from the layer it came from. The source file is
/// removed only after the push, so a conflict never loses the entry.
#[tauri::command]
pub async fn knowledge_promote_team(
    app: AppHandle,
    source: TeamPromoteSource,
    id: String,
    workspace_id: Option<String>,
    project_cwd: Option<String>,
) -> Result<TeamPromoteOutcome, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let (slug, _) = team_knowledge_target(&app)?.ok_or_else(no_team_message)?;
        // N14 review (Q1): the team library's pull and push run as the team's account.
        let _account = team_account_scope(&app);
        let store = app.state::<MemoryStore>();
        let team = app.state::<crate::team::TeamStore>();

        // Read the entry and the exact Markdown that will be committed.
        // `Ok(None)` means the source is gone, which only the re-read below
        // can encounter — the first read must find it.
        let read_source = |store: &MemoryStore| -> Result<Option<(Memory, String)>, String> {
            match source {
                TeamPromoteSource::Workspace => {
                    let workspace_id = workspace_id.as_deref().ok_or_else(|| {
                        "workspaceId is required for a Workspace entry".to_string()
                    })?;
                    Ok(store
                        .shared_publish_plan(MemoryScope::Workspace, Some(workspace_id), &id)
                        .ok())
                }
                TeamPromoteSource::Global => {
                    Ok(store.shared_publish_plan(MemoryScope::Global, None, &id).ok())
                }
                TeamPromoteSource::Project => {
                    let cwd = project_cwd
                        .as_deref()
                        .ok_or_else(|| "projectCwd is required for a Project entry".to_string())?;
                    let Some(entry) = store
                        .list_shared(Path::new(cwd))?
                        .into_iter()
                        .find(|m| m.id == id)
                    else {
                        return Ok(None);
                    };
                    let text = crate::memory::encode_memory_entry(&entry)?;
                    Ok(Some((entry, text)))
                }
            }
        };
        let (mut entry, text) = read_source(&store)?
            .ok_or_else(|| format!("knowledge entry not found: {id}"))?;

        // GH #82: a Project note in a shared workspace leaves the integration
        // branch through the channel, which a read-only collaborator can't
        // write — refused before anything reaches the team library.
        let shared_project_ws = match (source, project_cwd.as_deref()) {
            (TeamPromoteSource::Project, Some(cwd)) => workspace_for_cwd(&app, cwd),
            _ => None,
        };
        if let Some(shared_ws) = shared_project_ws.as_deref() {
            let state = crate::workspace_definition::app_library_state(&app, shared_ws)?;
            if state.shared && state.read_only {
                return Err(crate::workspace_definition::library_read_only_error(
                    state.repository.as_deref(),
                ));
            }
        }
        // The note's bytes as the Project layer holds them now: what the
        // removal below compares against (re-encoding would differ for a
        // note written by hand).
        let original_bytes = project_cwd.as_deref().and_then(|cwd| {
            let root = store.project_layer_root(Path::new(cwd));
            std::fs::read(ply_memory::shared_knowledge_dir(&root).join(format!("{}.md", entry.slug)))
                .ok()
        });

        let relative =
            crate::team::library_relative_path(&format!("knowledge/{}.md", entry.slug))?;
        let message = format!("knowledge: share \"{}\" with the team", entry.title);
        // The slug-collision refusal runs inside `apply`, i.e. after the
        // pull: it must be decided against what teammates have published,
        // never against a stale clone.
        team.publish(&slug, &relative, &message, |path| {
            let dir = path
                .parent()
                .ok_or_else(|| "team library path has no parent".to_string())?;
            std::fs::create_dir_all(dir).map_err(|e| format!("create {}: {e}", dir.display()))?;
            crate::memory::publish_shared_entry(dir, &entry.slug, &text)
        })?;

        // Published. The push was a network round trip, so re-read the
        // source before removing it: an edit saved meanwhile would be
        // deleted by id while the team library held only the older text.
        // Keeping the newer entry and saying so beats a silent lost write.
        let note = match read_source(&store)? {
            // Someone removed it while we published; nothing left to do.
            None => None,
            Some((_, current)) if current == text => {
                match source {
                    TeamPromoteSource::Workspace => {
                        store.delete(MemoryScope::Workspace, workspace_id.as_deref(), &id)?
                    }
                    TeamPromoteSource::Global => store.delete(MemoryScope::Global, None, &id)?,
                    TeamPromoteSource::Project => {
                        let cwd = project_cwd.as_deref().expect("checked above");
                        // GH #82: a shared workspace's Project note leaves
                        // the integration branch through the channel. The
                        // note is compared again under the workspace lock,
                        // against the mirror the removal would apply to: a
                        // refresh or edit since the check above keeps it.
                        let queued = match shared_project_ws.as_deref() {
                            Some(shared_ws) => crate::workspace_definition::app_library_change(
                                &app,
                                shared_ws,
                                |mirror| {
                                    match original_bytes.as_deref() {
                                        Some(original) => {
                                            crate::shared_library_sync::removal_if_unchanged(
                                                mirror,
                                                &entry.slug,
                                                &entry.title,
                                                original,
                                            )
                                        }
                                        None => Ok((None, false)),
                                    }
                                },
                            ),
                            None => Ok(None),
                        };
                        match queued {
                            Ok(Some(true)) => {}
                            Ok(Some(false)) => {
                                entry.shared = true;
                                entry.layer = crate::memory::KnowledgeLayer::Team;
                                return Ok(TeamPromoteOutcome {
                                    note: Some(changed_while_pushing(&entry.title)),
                                    entry,
                                });
                            }
                            Ok(None) => {
                                crate::memory::remove_project_entry(Path::new(cwd), &entry.slug)?
                            }
                            // Published to the team, but the Project copy
                            // couldn't be removed (write access went away
                            // meanwhile): say both halves.
                            Err(error) => {
                                entry.shared = true;
                                entry.layer = crate::memory::KnowledgeLayer::Team;
                                return Ok(TeamPromoteOutcome {
                                    note: Some(format!(
                                        "\"{}\" is in the team library, but its Project copy stays: {error}",
                                        entry.title
                                    )),
                                    entry,
                                });
                            }
                        }
                    }
                }
                None
            }
            Some(_) => Some(changed_while_pushing(&entry.title)),
        };
        entry.shared = true;
        entry.layer = crate::memory::KnowledgeLayer::Team;
        Ok(TeamPromoteOutcome { entry, note })
    })
    .await
    .map_err(|error| format!("join knowledge promote team: {error}"))?
}

fn changed_while_pushing(title: &str) -> String {
    format!(
        "\"{title}\" changed while Plyloft was pushing, so the team library has the \
         earlier version and your edited copy was kept where it was. \
         Share it again to publish the newer text."
    )
}

/// Move a Team entry back into the personal Global layer.
///
/// Two orderings carry this, and both were review findings:
///
/// 1. **Everything happens after the pull.** The entry is read, copied and
///    removed inside the mutation `publish_library_change` runs once the
///    clone is up to date, so a teammate's newer text is what comes back to
///    the personal layer — reading it beforehand copied the stale version
///    and then deleted the fresh one.
/// 2. **The copy is written before the removal.** The removal reaches
///    GitHub, so a personal write failing after it would take the lesson
///    off every layer a member can see. Writing first makes the worst case
///    a duplicate — visible and deletable — and a publish that is *provably*
///    rolled back deletes that duplicate itself.
#[tauri::command]
pub async fn knowledge_demote_team(app: AppHandle, id: String) -> Result<Memory, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let (slug, clone_dir) = team_knowledge_target(&app)?.ok_or_else(no_team_message)?;
        // N14 review (Q1): the team library's pull and push run as the team's account.
        let _account = team_account_scope(&app);
        let store = app.state::<MemoryStore>();
        let team = app.state::<crate::team::TeamStore>();

        // Refresh first so the path below is derived from a clone that is
        // already current. Advisory: `publish` pulls again, and that pull
        // is the one that decides a conflict.
        if let Err(error) = team.sync(&slug) {
            log::warn!("knowledge: could not refresh the team clone before a demote ({error})");
        }
        // Only to name the file; the content is read again after the pull.
        let existing = store.team_entry(&clone_dir, &id)?;
        let relative =
            crate::team::library_relative_path(&format!("knowledge/{}.md", existing.slug))?;
        let message = format!(
            "knowledge: move \"{}\" out of the team library",
            existing.title
        );

        let adopted: std::cell::RefCell<Option<Memory>> = std::cell::RefCell::new(None);
        let published = team.publish(&slug, &relative, &message, |path| {
            // Post-pull: this is the team's current text.
            let entry = store.team_entry(&clone_dir, &id).map_err(|_| {
                format!(
                    "\"{}\" is no longer in the team library — a teammate moved it.",
                    existing.title
                )
            })?;
            // The path was derived before the pull. A slug that changed
            // under us would have this delete the wrong file.
            if entry.slug != existing.slug {
                return Err(format!(
                    "\"{}\" was renamed in the team library while Plyloft was working. \
                     Try again.",
                    existing.title
                ));
            }
            // Secure the copy before the removal, still inside the window
            // the rollback covers: if this fails, nothing is deleted.
            *adopted.borrow_mut() = Some(store.adopt_shared_entry(&entry, false)?);
            std::fs::remove_file(path)
                .map_err(|error| format!("remove team knowledge: {error}"))?;
            Ok(())
        });

        let adopted = adopted.into_inner();
        // Undo the copy only when the library is *provably* untouched. A
        // rollback that itself failed reports `Abandoned`, and deleting the
        // copy on the strength of that is how a lesson disappears from
        // every layer at once.
        if crate::team::library_is_provably_unchanged(&published) {
            let detail = published
                .err()
                .map(|error| error.message())
                .unwrap_or_else(|| "the team library write did not complete".to_string());
            let Some(adopted) = adopted else {
                return Err(detail);
            };
            return match store.delete(MemoryScope::Global, None, &adopted.id) {
                Ok(()) => Err(detail),
                Err(cleanup) => Err(format!(
                    "{detail} A personal copy of \"{}\" was left in Global Knowledge and can be \
                     deleted from there. ({cleanup})",
                    adopted.title
                )),
            };
        }

        let adopted = adopted.ok_or_else(|| {
            "the team library write reported no entry — check Settings › Team › Members and library.".to_string()
        })?;
        match published {
            Ok(_) => Ok(adopted),
            // A push that may have landed, a refused one over an earlier
            // commit, or an abandoned rollback: either way the copy stands and
            // the trouble still needs saying.
            Err(error) => Err(error.message()),
        }
    })
    .await
    .map_err(|error| format!("join knowledge demote team: {error}"))?
}

/// Copy a Team entry into a fresh personal Global entry. The team library is
/// untouched, so this writes nothing to the team repo and pushes nothing.
#[tauri::command]
pub async fn knowledge_fork_team(app: AppHandle, id: String) -> Result<Memory, String> {
    tauri::async_runtime::spawn_blocking(move || {
        team_gate(&app.state::<crate::license::LicenseStore>())?;
        let (_, clone_dir) = team_knowledge_target(&app)?.ok_or_else(no_team_message)?;
        let store = app.state::<MemoryStore>();
        let entry = store.team_entry(&clone_dir, &id)?;
        store.adopt_shared_entry(&entry, true)
    })
    .await
    .map_err(|error| format!("join knowledge fork team: {error}"))?
}

