// GH #171: `swarm_templates_create` / `_update` / `_delete` went with
// Settings › Swarm templates, their only caller.

// v1.52.0 lifecycle actions for swarm templates. Builtins reject
// promote/demote (they're universal and don't live in any overlay).

/// v1.53.0 (Team Mode Phase 2.4): pre-dispatch check that surfaces
/// every role in a swarm template that the current workspace hasn't
/// bound to an agent. The FE calls this before swarm_start when the
/// chosen template is `scope: "shared"` — if the returned list is
/// non-empty, it shows the role-binding modal instead of dispatching.
/// Resolves suggested bindings from `<project_cwd>/.atelier/agents/`
/// when supplied. Returns empty when every role is bound (the
/// happy path — FE proceeds with dispatch).
#[tauri::command]
pub fn swarm_template_unbound_roles(
    swarm_templates: State<'_, SwarmTemplatesStore>,
    bindings: State<'_, RoleBindingsStore>,
    agents: State<'_, AgentRegistry>,
    template_id: String,
    workspace_id: String,
    project_cwd: Option<String>,
) -> Result<Vec<UnboundRole>, String> {
    crate::swarm_templates::ensure_startable_template_id(&template_id)?;
    let cwd_path = project_cwd.as_deref().map(Path::new);
    // Resolve the template from builtins/personal first, then fall
    // back to the shared overlay (matches the v1.52.0 fork resolver).
    let template = match swarm_templates.get(&template_id)? {
        Some(t) => t,
        None => {
            let with_shared = swarm_templates.list_all_with_shared(cwd_path)?;
            with_shared
                .into_iter()
                .find(|t| t.id == template_id)
                .ok_or_else(|| format!("swarm template not found: {template_id}"))?
        }
    };
    unbound_roles_for_template(
        &template,
        &workspace_id,
        &bindings,
        &agents,
        cwd_path,
    )
}

