/// SL-6: why nothing may be set aside now — a Verify or a setup still works
/// in one of the two worktrees.
fn build_both_busy(workspace_id: &str, card_id: &str, verify: &VerifyRegistry) -> Option<String> {
    for lane in [crate::build_both::LANE_A, crate::build_both::LANE_B] {
        if verify.is_inflight(workspace_id, &crate::build_both::lane_key(card_id, lane)) {
            return Some(format!(
                "{}'s checks are still running; wait for them to finish.",
                crate::builder::vendor_display(crate::build_both::lane_vendor(lane))
            ));
        }
    }
    let b_setup = crate::worktree_setup::is_in_flight(
        workspace_id,
        &crate::build_both::lane_key(card_id, crate::build_both::LANE_B),
    );
    (crate::worktree_setup::is_in_flight(workspace_id, card_id) || b_setup)
        .then(|| "A setup is still running for this card; wait for it to finish.".to_string())
}

/// SL-6: the owner picks one build. Under CARD_START_LOCK: the other
/// build's session ends, its worktree (anything uncommitted committed on its
/// branch first) goes to the 7-day trash with its branch kept, and the
/// picked build becomes the card's worktree, branch and Builder — its live
/// session re-keyed to the card. The normal loop follows: Build done, then
/// Verify and the full Challenger review, then Ship.
#[tauri::command]
pub async fn build_both_pick(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
    lane: String,
) -> Result<KanbanCard, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _start = CARD_START_LOCK.lock().unwrap_or_else(|p| p.into_inner());
        let kanban = app.state::<KanbanStore>();
        let verify = app.state::<VerifyRegistry>();
        let ws_cwd = resolve_ws_cwd(&app.state::<WorkspaceStore>(), &workspace_id)?;
        let cache_paths = app.state::<ProjectConfigStore>().cache_paths(&workspace_id);
        let by = app.state::<SettingsStore>().snapshot().identity.user_email;
        let updated = crate::build_both::pick_locked(
            &kanban,
            &app.state::<crate::builder::BuilderRegistry>(),
            &app.state::<PtyRegistry>(),
            &|key| verify.is_inflight(&workspace_id, key),
            &ws_cwd,
            &cache_paths,
            &workspace_id,
            &card_id,
            &lane,
            by.as_deref(),
        );
        for l in [crate::build_both::LANE_A, crate::build_both::LANE_B] {
            crate::verify_logs::card_worktree_removed(&workspace_id, &crate::build_both::lane_key(&card_id, l));
        }
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        updated
    })
    .await
    .map_err(|e| format!("Build with both worker failed: {e}"))?
}

/// SL-6: stop building with both. Both sessions end; the card keeps
/// Claude's worktree (its own) with no Builder, so Start build works as on
/// any card; Codex's worktree goes to the trash, its branch kept.
#[tauri::command]
pub async fn build_both_stop(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<KanbanCard, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let _start = CARD_START_LOCK.lock().unwrap_or_else(|p| p.into_inner());
        let kanban = app.state::<KanbanStore>();
        let card = kanban.get_card(&workspace_id, &card_id)?;
        let bb = card
            .build_both
            .as_ref()
            .filter(|bb| bb.undecided())
            .ok_or("This card isn't being built by both.")?;
        if let Some(why) = build_both_busy(&workspace_id, &card_id, &app.state::<VerifyRegistry>()) {
            return Err(why);
        }
        let b = bb.lane(crate::build_both::LANE_B).cloned().unwrap_or_default();
        crate::build_both::end_lane_sessions(
            &app.state::<crate::builder::BuilderRegistry>(),
            &app.state::<PtyRegistry>(),
            &card_id,
        );
        let ws_cwd = resolve_ws_cwd(&app.state::<WorkspaceStore>(), &workspace_id)?;
        let cache_paths = app.state::<ProjectConfigStore>().cache_paths(&workspace_id);
        let dir = crate::build_both::variant_dir(&card_id);
        // N16: the lane's own record of its folder, never a lookup by name.
        let path = crate::worktrees::recorded_worktree_path(&ws_cwd, &dir, Some(&b.worktree_path));
        if path.is_dir() {
            let _ = crate::worktrees::commit_pending_in_worktree(
                &path,
                &crate::commit_message::set_aside_subject("Codex", &card.title),
            );
        }
        // Try it (TI-2): the set-aside build's preview stops with it.
        crate::try_session::stop_card_try_sessions(
            &workspace_id,
            &card_id,
            Some(crate::build_both::LANE_B),
            crate::try_session::TryStopReason::Discard,
        );
        let archived = crate::build_both::archived_lane(&b, crate::worktrees::prune_worktree_at(&ws_cwd, &path, &cache_paths));
        let by = app.state::<SettingsStore>().snapshot().identity.user_email;
        let at = crate::worktree_setup::now_millis();
        let mut updated = None;
        kanban.with_card(&workspace_id, &card_id, |c| {
            crate::build_both::apply_stop(c, by.as_deref(), at, archived.clone())?;
            updated = Some(c.clone());
            Ok(())
        })?;
        for l in [crate::build_both::LANE_A, crate::build_both::LANE_B] {
            crate::verify_logs::card_worktree_removed(&workspace_id, &crate::build_both::lane_key(&card_id, l));
        }
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        updated.ok_or_else(|| "the stop did not capture the card".to_string())
    })
    .await
    .map_err(|e| format!("Build with both worker failed: {e}"))?
}

/// D13: resume a lost Builder session in the same worktree.
#[tauri::command]
pub async fn builder_resume(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) -> Result<crate::builder::BuilderStartResult, String> {
    // GH #116: a resume spawns into the card's worktree, so it is a card
    // lifecycle event like Start build and the delete — all three behind
    // `CARD_START_LOCK`. Without it a resume could read a card, spawn,
    // and register its session after a concurrent delete had removed the
    // row and ended the sessions, leaving a live Builder with no card in
    // a folder on its way out. On a worker, as the lock holder may be
    // fetching.
    tauri::async_runtime::spawn_blocking(move || {
        let result = {
            let _start = CARD_START_LOCK.lock().unwrap_or_else(|p| p.into_inner());
            // Under the lock, as `builder_start_blocking` checks it: a
            // drain can begin while this waits behind a start that is
            // fetching, and a resume admitted after that would spawn
            // into a drain already under way.
            drain::guard_dispatch(&app.state::<DrainCoordinator>(), "builder")?;
            resume_admission(&app.state::<KanbanStore>(), &workspace_id, &card_id)?;
            let workspace_cwd = app
                .state::<WorkspaceStore>()
                .snapshot()
                .workspaces
                .into_iter()
                .find(|w| w.id == workspace_id)
                .map(|w| w.cwd)
                .ok_or_else(|| format!("workspace '{workspace_id}' not found"))?;
            // UX P-C (Challenger): the guide as saved now decides whether a
            // guided session resumes in its mode.
            // QoL 7.4: and the tour, for the tour card's session.
            let onboarding = app.state::<SettingsStore>().snapshot().onboarding.clone();
            crate::builder::resume(
                app.clone(),
                &app.state::<crate::builder::BuilderRegistry>(),
                &app.state::<PtyRegistry>(),
                &app.state::<KanbanStore>(),
                &workspace_id,
                &workspace_cwd,
                &card_id,
                onboarding.first_card.as_ref(),
                onboarding.tutorial.as_ref(),
            )?
        };
        push_in_progress_label_in_background(app, workspace_id, card_id);
        Ok(result)
    })
    .await
    .map_err(|e| format!("Builder resume worker failed: {e}"))?
}

/// What `builder_resume` asks before it spawns, under `CARD_START_LOCK`:
/// not in To do, and a pull request card's Builder allowed and started
/// before.
pub(crate) fn resume_admission(kanban: &KanbanStore, workspace_id: &str, card_id: &str) -> Result<(), String> {
    let card = kanban.get_card(workspace_id, card_id).ok();
    // N14 F8: a card put back in To do goes on through Start build, which
    // moves it.
    if card.as_ref().is_some_and(|c| c.column_id == crate::kanban::KanbanColumnId::Todo) {
        return Err(RESUME_IN_TODO.to_string());
    }
    // Challenger on a pull request: only the member's own, open one.
    if let Some(why) = card
        .as_ref()
        .and_then(|c| crate::pr_review::builder_refusal(c).or_else(|| crate::pr_review::resume_refusal(c)))
    {
        return Err(why);
    }
    Ok(())
}

/// N14 F8: Resume on a card in To do (put back) — refused; Start build
/// continues it.
pub(crate) const RESUME_IN_TODO: &str =
    "This card is back at Ready to start. Start build picks it up again with the work so far.";

/// GH #66: Resume re-asserts `status:in-progress` on the backing issue, so a
/// card started before Start build pushed its label (or whose push failed
/// without a Sync since) shows In Progress on the other Macs. Off the main
/// thread: this command is synchronous and `gh` takes a second. Skipped on a
/// local board, an unlicensed one (read-only) or a card not In Progress.
fn push_in_progress_label_in_background(
    app: tauri::AppHandle,
    workspace_id: String,
    card_id: String,
) {
    std::thread::spawn(move || {
        let store = app.state::<KanbanStore>();
        let Some(repo) = workspace_github_target(&app.state::<WorkspaceStore>(), &workspace_id)
        else {
            return;
        };
        if !app.state::<crate::license::LicenseStore>().team_allowed() {
            return;
        }
        let Ok(card) = store.get_card(&workspace_id, &card_id) else {
            return;
        };
        if card.column_id != crate::kanban::KanbanColumnId::InProgress || card.sync_pending {
            // A pending card is pushed whole by the next Sync.
            return;
        }
        // OB-7b: on this thread, the workspace's GitHub account.
        let _github = crate::github_account::enter_for_app(&app, &workspace_id);
        gh_sync_card_edit(&store, &repo, &workspace_id, None, &card, false, true);
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
    });
}

/// D6/E1: "Build done" — snapshot commit + run finished. The frontend
/// starts Verify right after a new snapshot; an unchanged tree reports
/// "no new snapshot" instead of recording the same SHA again.
#[tauri::command(async)]
pub fn builder_done(
    app: tauri::AppHandle,
    kanban: State<'_, KanbanStore>,
    settings: State<'_, SettingsStore>,
    workspace_id: String,
    card_id: String,
    skip_review: Option<bool>,
    self_check: Option<crate::kanban::SelfCheckRecord>,
) -> Result<crate::builder::BuildDone, String> {
    let by = settings.snapshot().identity.user_email;
    crate::builder::done(
        app,
        &kanban,
        &workspace_id,
        &card_id,
        skip_review.unwrap_or(false),
        by.as_deref(),
        self_check,
    )
}

/// ADR 0006 (third card): the self-check message Build done sends the
/// Builder first, or null when none runs (the repository's switch is off,
/// or nothing changed since the last snapshot).
///
/// Async (review): deciding the tests sentence runs `git ls-files` and
/// `git grep` in the worktree, which must not block the main thread.
#[tauri::command]
pub async fn builder_self_check_message(
    app: AppHandle,
    workspace_id: String,
    card_id: String,
    token: String,
) -> Result<Option<String>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let card = app.state::<KanbanStore>().get_card(&workspace_id, &card_id)?;
        let review = app.state::<ProjectConfigStore>().review(&workspace_id);
        let message = crate::builder::self_check_message(&card, &review, &token)?;
        // 1.171.0 C2: a self-check runs — the card keeps when it was asked
        // for, so a quit during it is said after the relaunch. A record
        // that can't be written costs only that note; the check still runs.
        if message.is_some() {
            let at = crate::builder::now_millis();
            match crate::builder::mark_self_check_started(&app.state::<KanbanStore>(), &workspace_id, &card_id, at) {
                Ok(()) => crate::kanban::emit_kanban_changed(&app, &workspace_id),
                Err(e) => eprintln!("[builder] self-check start not recorded on {card_id}: {e}"),
            }
        }
        Ok(message)
    })
    .await
    .map_err(|e| format!("join builder self-check message: {e}"))?
}

/// ADR 0006 (third card): the workspace's review settings, with or without
/// a project config.
#[tauri::command]
pub fn project_review_get(
    project_configs: State<'_, ProjectConfigStore>,
    workspace_id: String,
) -> crate::project_config::ReviewSettings {
    project_configs.review(&workspace_id)
}

/// ADR 0006 (third card): the repository's review settings — `Self-check
/// before review` and its own checklist classes — changed in place under
/// the shared definition's lock. `base_checklist` is the list the editor
/// started from: a list that changed since is refused, never overwritten.
/// The classes are held to their limits; a list over them is refused with
/// the reason.
#[tauri::command]
pub async fn project_config_set_review(
    app: AppHandle,
    workspace_id: String,
    self_check: Option<bool>,
    review_checklist: Option<Vec<crate::project_config::ReviewChecklistClass>>,
    base_checklist: Option<Vec<crate::project_config::ReviewChecklistClass>>,
) -> Result<crate::project_config::ReviewSettings, String> {
    tauri::async_runtime::spawn_blocking(move || {
        crate::workspace_definition::edit_shared(&app, &workspace_id, || {
            let store = app.state::<ProjectConfigStore>();
            crate::project_config::set_review(
                &store,
                &workspace_id,
                self_check,
                review_checklist,
                base_checklist,
            )
        })
    })
    .await
    .map_err(|e| format!("project config worker failed: {e}"))?
}

/// Findings filter: `Findings that block approval` for this workspace —
/// "p1", "p1-p2" (the default) or "all". It applies from the next review
/// that settles. This Mac's own: it does not travel in the shared
/// definition, but takes the same lock as the review settings that do.
#[tauri::command]
pub async fn project_config_set_blocking_findings(
    app: AppHandle,
    workspace_id: String,
    threshold: crate::project_config::BlockingThreshold,
) -> Result<crate::project_config::ReviewSettings, String> {
    tauri::async_runtime::spawn_blocking(move || {
        crate::workspace_definition::edit_shared(&app, &workspace_id, || {
            let store = app.state::<ProjectConfigStore>();
            crate::project_config::set_blocking_findings(&store, &workspace_id, threshold)
        })
    })
    .await
    .map_err(|e| format!("project config worker failed: {e}"))?
}

/// Findings filter: "Not a real issue" — the member dismisses an open
/// finding of the card's ledger, with an optional one-line reason. It stays
/// on the card as dismissed, never blocks again, and the next review is told
/// so. A request for changes on the current snapshot that rested only on
/// findings that no longer block reads as an approval from now on.
#[tauri::command]
pub fn review_finding_dismiss(
    app: tauri::AppHandle,
    kanban: State<'_, KanbanStore>,
    settings: State<'_, SettingsStore>,
    reviewers: State<'_, crate::reviewer::ReviewerRegistry>,
    workspace_id: String,
    card_id: String,
    finding_id: String,
    reason: Option<String>,
) -> Result<(), String> {
    let by = settings.snapshot().identity.user_email;
    let at = crate::kanban::now_ms();
    // The card first, from the ledger as the dismissal leaves it; then the
    // ledger. A ledger that cannot be written puts the card back, so the
    // two never disagree.
    let mut ledger = reviewers
        .ledger(&workspace_id, &card_id)
        .ok_or_else(|| "This card has no findings from the Reviewer to dismiss.".to_string())?;
    crate::review_ledger::dismiss(&mut ledger, &finding_id, reason.as_deref(), by.as_deref(), at)?;
    let mut approved = false;
    let mut before: Option<KanbanCard> = None;
    kanban.with_card_saved(&workspace_id, &card_id, |c| {
        before = Some(c.clone());
        approved = crate::builder::apply_dismissal(c, &ledger, finding_id.trim(), at);
        Ok(())
    })?;
    if let Err(e) = reviewers.dismiss_finding(&workspace_id, &card_id, &finding_id, reason.as_deref(), by.as_deref(), at) {
        if let Some(before) = before {
            let _ = kanban.with_card_saved(&workspace_id, &card_id, |c| {
                *c = before;
                Ok(())
            });
        }
        crate::kanban::emit_kanban_changed(&app, &workspace_id);
        return Err(e);
    }
    crate::kanban::emit_kanban_changed(&app, &workspace_id);
    if approved {
        // GH #104: the member's decision settles the card, as an accepted
        // pushback does, so the improvement proposal's pass may run now.
        crate::proposals::after_human_decision(&app, &workspace_id, &card_id);
        // G1–G3 Challenger (3): a human's decision is an approval.
        crate::pr_merge::kick_resume_held(&app, &workspace_id, &card_id);
    }
    Ok(())
}

/// The human accepts the Builder's pushback on a changes-requested
