// ── Swarm (v1.0) ─────────────────────────────────

#[tauri::command]
pub fn swarm_start(
    app: tauri::AppHandle,
    drain_coord: State<'_, DrainCoordinator>,
    verify: State<'_, VerifyRegistry>,
    kanban: State<'_, KanbanStore>,
    card_execution: State<'_, crate::card_execution::CardExecutionGate>,
    workspace_id: String,
    template_id: String,
    goal: String,
    role_bindings: std::collections::HashMap<String, String>,
    cwd_override: Option<String>,
    kind: Option<String>,
    card_id: Option<String>,
) -> Result<Swarm, String> {
    drain::guard_dispatch(&drain_coord, "swarm")?;
    let cwd = cwd_override.map(PathBuf::from);
    // v1.22.0: optional `kind` controls how the swarm record is tagged
    // (`adhoc` | `card` | `brainstorm`). Defaults to `adhoc` so any
    // older frontend (or direct IPC caller) still works.
    let kind = match kind.as_deref() {
        Some("card") => SwarmKind::Card,
        Some("brainstorm") => SwarmKind::Brainstorm,
        Some("adhoc") | None => SwarmKind::Adhoc,
        Some(other) => return Err(format!("unknown swarm kind '{other}'")),
    };
    // G4 (launch D8): no new swarm starts. A card that already ran one may
    // start it again; resume (`swarm_resume`) and the queue pump are
    // separate paths and unaffected.
    let refusal_card = card_id
        .as_deref()
        .and_then(|id| kanban.get_card(&workspace_id, id).ok());
    if let Some(why) =
        crate::kanban::swarm_start_refusal(kind == SwarmKind::Card, refusal_card.as_ref())
    {
        return Err(why.to_string());
    }
    let start = || {
        swarms::swarm_start(
            &app,
            &workspace_id,
            &template_id,
            &goal,
            role_bindings,
            cwd,
            kind,
        )
    };
    if kind == SwarmKind::Card {
        let card_id = card_id
            .as_deref()
            .ok_or_else(|| "card_id is required for a card swarm".to_string())?;
        // SL-6: no swarm on a card Claude and Codex are both building.
        if kanban.get_card(&workspace_id, card_id).is_ok_and(|c| crate::build_both::is_undecided(&c)) {
            return Err(crate::build_both::UNDECIDED_REFUSAL.to_string());
        }
        card_execution.run_attempt(
            &verify,
            &kanban,
            &workspace_id,
            card_id,
            crate::card_execution::AuthorizationKind::CardSwarm,
            start,
            |swarm| {
                kanban
                    .set_run_state(
                        &workspace_id,
                        card_id,
                        RunStatePatch {
                            linked_run_id: Some(None),
                            linked_swarm_id: Some(Some(swarm.id.clone())),
                            last_run_status: Some(Some(crate::kanban::LastRunStatus::Running)),
                        },
                    )
                    .map(|_| ())?;
                crate::kanban::emit_kanban_changed(&app, &workspace_id);
                Ok(())
            },
            |swarm| {
                crate::swarms::abort_unlinked_start(
                    &app,
                    &swarm.id,
                    "card swarm link failed",
                );
            },
        )
    } else {
        start()
    }
}

#[tauri::command]
pub fn swarm_get(registry: State<'_, SwarmRegistry>, swarm_id: String) -> Option<Swarm> {
    registry.get(&swarm_id)
}

#[tauri::command]
pub fn swarm_list(
    registry: State<'_, SwarmRegistry>,
    workspace_id: Option<String>,
) -> Vec<Swarm> {
    match workspace_id {
        Some(ws) => registry.list_by_workspace(&ws),
        None => registry.list(),
    }
}

#[tauri::command]
pub fn swarm_abort(
    app: tauri::AppHandle,
    registry: State<'_, SwarmRegistry>,
    agent_registry: State<'_, AgentRegistry>,
    pty_registry: State<'_, PtyRegistry>,
    swarm_id: String,
) -> Result<(), String> {
    // Kill the in-flight run (most recent in run_ids) before flipping the
    // swarm to Aborted, mirroring SWARM_DESIGN §11.2.
    let aborted = registry.get(&swarm_id);
    if let Some(swarm) = &aborted {
        if let Some(latest) = swarm.run_ids.last() {
            let _ = agent_registry.kill_run(latest, &pty_registry);
        }
    }
    registry.abort(&swarm_id, "user aborted")?;
    if let Some(queue) = app.try_state::<crate::writer_queue::WriterQueue>() {
        queue.cancel_prefix(&format!("swarm:{swarm_id}:"));
    }
    // v1.30.0 (parallel swarms): aborting a card swarm frees a slot —
    // pump the queue so the next queued card in that workspace auto-starts.
    if let Some(swarm) = aborted {
        if swarm.kind == SwarmKind::Card {
            crate::kanban::pump_card_queue(&app, &swarm.workspace_id);
        }
    }
    Ok(())
}

/// v1.30.0 (parallel swarms): current card-swarm slot usage for a
/// workspace. The frontend reads this before dispatching a card-driven
/// swarm so over-cap cards stay queued instead of showing a failed
/// dispatch. Running + Suspended both count toward the cap.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CardSlotStatus {
    pub running_card_swarms: usize,
    pub suspended_card_swarms: usize,
    pub cap: usize,
}

#[tauri::command]
pub fn swarm_card_slot_status(
    registry: State<'_, SwarmRegistry>,
    workspace_id: String,
) -> CardSlotStatus {
    CardSlotStatus {
        running_card_swarms: registry.active_card_count(&workspace_id),
        suspended_card_swarms: registry.suspended_card_count(&workspace_id),
        cap: registry.card_swarm_cap(),
    }
}

