/// v1.5.0 (S1): per-instance abort. User clicks the abort button on a
/// single fan-out leg in the lanes view. Kills the leg's PTY (if it has
/// one) and marks the RoleInstance Failed; the FSM sees "all instances
/// terminal" sooner and advances to PendingCoordinator(tick+1), letting
/// the coordinator re-plan around the killed leg.
#[tauri::command]
pub fn swarm_instance_abort(
    registry: State<'_, SwarmRegistry>,
    agent_registry: State<'_, AgentRegistry>,
    pty_registry: State<'_, PtyRegistry>,
    swarm_id: String,
    instance_id: String,
) -> Result<(), String> {
    let run_id = registry.abort_instance(&swarm_id, &instance_id)?;
    if let Some(rid) = run_id {
        let _ = agent_registry.kill_run(&rid, &pty_registry);
    }
    Ok(())
}

