    /// GH #209: a double press, or a second window, runs two `Ship with
    /// follow-up` calls on one card at once. The per-card guard and the
    /// re-read under it leave exactly one follow-up card and one issue
    /// create, and both calls return that card.
    #[test]
    fn two_concurrent_ship_with_follow_up_calls_make_one_card_and_one_issue() {
        use crate::kanban::{KanbanColumnId, KanbanStore};
        use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
        let tmp = tempfile::tempdir().unwrap();
        let store = KanbanStore::new(tmp.path().join("state")).unwrap();
        let card: crate::kanban::KanbanCard = serde_json::from_str(
            r#"{"id":"c1","workspaceId":"ws","title":"t","columnId":"in_progress","createdAt":0,"updatedAt":0,"area":"site",
                "builder":{"vendor":"claude","snapshots":[{"n":4,"sha":"s4","at":0}]}}"#,
        )
        .unwrap();
        store.create_card("ws", card).unwrap();
        let finding = crate::review_ledger::LedgerFinding { id: "F1".into(), severity: Some("P2".into()), ..Default::default() };
        let creates = AtomicUsize::new(0);
        let next_issue = AtomicU64::new(300);
        let barrier = std::sync::Barrier::new(2);
        let results: Vec<crate::kanban::FollowUpCard> = std::thread::scope(|scope| {
            let handles: Vec<_> = (0..2)
                .map(|_| {
                    scope.spawn(|| {
                        // The stub `issue create`: slow, like `gh`, so an
                        // unguarded second call would overlap it.
                        let create = |c: &crate::kanban::KanbanCard| {
                            creates.fetch_add(1, Ordering::SeqCst);
                            std::thread::sleep(std::time::Duration::from_millis(50));
                            let n = next_issue.fetch_add(1, Ordering::SeqCst);
                            store.set_github_sync("ws", &c.id, Some(Some(n)), Some(false), None).unwrap();
                        };
                        let edit = |_: &crate::kanban::KanbanCard| {};
                        let issue = super::FollowUpIssue { create: &create, edit: &edit };
                        barrier.wait();
                        super::ensure_follow_up_card(
                            &store, "ws", "c1", &[&finding], "Follow-up: t", "brief", None, Some(&issue),
                        )
                        .unwrap()
                    })
                })
                .collect();
            handles.into_iter().map(|h| h.join().unwrap()).collect()
        });
        let board = store.load("ws").unwrap();
        let follow_ups: Vec<_> = board.iter().filter(|c| c.id != "c1").collect();
        assert_eq!(follow_ups.len(), 1, "exactly one follow-up card: {follow_ups:?}");
        assert_eq!(follow_ups[0].column_id, KanbanColumnId::Todo);
        assert_eq!(creates.load(Ordering::SeqCst), 1, "exactly one issue create");
        // 1.173.0 (B3 Challenger 1): it stays in the shipped card's area.
        assert_eq!(follow_ups[0].area.as_deref(), Some("site"));
        assert_eq!(results[0].card_id, follow_ups[0].id);
        assert_eq!(results[1].card_id, follow_ups[0].id, "the second call returns the same follow-up");
        assert_eq!(results[0].card_ref, "#300");
        assert_eq!(results[1].card_ref, "#300");
        let recorded = store.get_card("ws", "c1").unwrap().builder.unwrap().follow_up.unwrap();
        assert_eq!(recorded.card_id, follow_ups[0].id);
        assert_eq!(recorded.card_ref, "#300");
        // N19: the link is recorded both ways, once, even after two calls.
        assert_eq!(follow_ups[0].follows_up.as_ref().unwrap().card_id, "c1");
        let by = store.get_card("ws", "c1").unwrap().followed_up_by;
        assert_eq!(by.iter().map(|l| l.card_id.as_str()).collect::<Vec<_>>(), vec![follow_ups[0].id.as_str()]);
    }

    /// GH #209 review 1: a second `Ship with follow-up` that arrives while the
    /// first is landing must not write its stale view (`shipped: false`, the
    /// pre-ship brief) over the first call's receipt. Call B arrives while A
    /// is between making the follow-up card and its `on_landed` receipt. With
    /// the per-card claim B is refused outright; were it let through, B
    /// would sit in the issue edit while A writes the receipt, then record
    /// its stale follow-up over it.
    #[test]
    fn a_second_ship_with_follow_up_cannot_undo_the_first_ones_receipt() {
        use crate::kanban::KanbanStore;
        use std::sync::mpsc;
        let tmp = tempfile::tempdir().unwrap();
        let store = KanbanStore::new(tmp.path().join("state")).unwrap();
        let card: crate::kanban::KanbanCard = serde_json::from_str(
            r#"{"id":"c9","workspaceId":"ws","title":"t","columnId":"in_progress","createdAt":0,"updatedAt":0,
                "builder":{"vendor":"claude","snapshots":[{"n":4,"sha":"s4","at":0}]}}"#,
        )
        .unwrap();
        store.create_card("ws", card).unwrap();
        let finding = crate::review_ledger::LedgerFinding { id: "F1".into(), severity: Some("P2".into()), ..Default::default() };
        let create = |c: &crate::kanban::KanbanCard| {
            store.set_github_sync("ws", &c.id, Some(Some(400)), Some(false), None).unwrap();
        };
        let (go_b, b_go) = mpsc::channel::<()>();
        let (b_says, a_hears) = mpsc::channel::<&'static str>();
        let (resume_b, b_resumes) = mpsc::channel::<()>();
        let b_result = std::thread::scope(|scope| {
            let (store_b, finding_b, create_b) = (&store, &finding, &create);
            let b = scope.spawn(move || {
                let (store, finding, create) = (store_b, finding_b, create_b);
                b_go.recv().unwrap();
                let _claim = match super::FollowUpShipClaim::take("ws", "c9") {
                    Ok(claim) => claim,
                    Err(e) => {
                        b_says.send("refused").unwrap();
                        return Err(e);
                    }
                };
                // Let through: the reused card's issue is edited, and A lands
                // meanwhile.
                let edit = |_: &crate::kanban::KanbanCard| {
                    b_says.send("in edit").unwrap();
                    b_resumes.recv().unwrap();
                };
                let issue = super::FollowUpIssue { create, edit: &edit };
                super::ensure_follow_up_card(store, "ws", "c9", &[finding], "Follow-up: t", "brief B", None, Some(&issue))
            });
            // Call A: claim, make the card, then (the ship running) B arrives.
            let claim_a = super::FollowUpShipClaim::take("ws", "c9").unwrap();
            let never = |_: &crate::kanban::KanbanCard| {};
            let issue = super::FollowUpIssue { create: &create, edit: &never };
            let follow = super::ensure_follow_up_card(&store, "ws", "c9", &[&finding], "Follow-up: t", "brief A", None, Some(&issue)).unwrap();
            go_b.send(()).unwrap();
            let heard = a_hears.recv().unwrap();
            // A lands: `on_landed`'s receipt.
            super::record_follow_up_landed(&store, "ws", "c9", &follow, "RECEIPT", true);
            if heard == "in edit" {
                resume_b.send(()).unwrap();
            }
            let result = b.join().unwrap();
            drop(claim_a);
            result
        });
        let recorded = store.get_card("ws", "c9").unwrap().builder.unwrap().follow_up.unwrap();
        assert!(recorded.shipped, "the first call's receipt stands: {recorded:?}");
        let follow_card = store.get_card("ws", &recorded.card_id).unwrap();
        assert_eq!(follow_card.notes.as_deref(), Some("RECEIPT"));
        assert!(follow_card.sync_pending);
        assert_eq!(b_result.unwrap_err(), super::FOLLOW_UP_SHIP_IN_FLIGHT, "the second call is refused");
        // The claim is released with the first call: a later attempt runs.
        assert!(super::FollowUpShipClaim::take("ws", "c9").is_ok());
    }

    /// GH #209 review 1: the claim is the command's first statement, so it
    /// covers the follow-up card, the ship and the receipt.
    #[test]
    fn ship_with_follow_up_takes_its_claim_before_anything_else() {
        let src = include_str!("commands.rs");
        let body = src
            .split_once("fn card_ship_with_follow_up_blocking(")
            .unwrap()
            .1
            .split_once(") -> Result<ShipOutcome, crate::worktrees::ShipError> {")
            .unwrap()
            .1;
        let first = body
            .lines()
            .map(str::trim)
            .find(|l| !l.is_empty() && !l.starts_with("//"))
            .unwrap();
        assert_eq!(first, "let _claim = FollowUpShipClaim::take(&workspace_id, &card_id)?;");
        let claim = body.find("FollowUpShipClaim::take").unwrap();
        assert!(claim < body.find("ensure_follow_up_card(").unwrap());
        assert!(claim < body.find("record_follow_up_landed(").unwrap());
    }
