    #[test]
    fn target_dirty_preflight_distinguishes_observed_clean_from_unavailable() {
        let repo = tempfile::tempdir().unwrap();
        let git = crate::doctor::resolved_path_if_initialized("git")
            .unwrap_or_else(|| if cfg!(windows) { "git" } else { "/usr/bin/git" }.to_string());
        let run = |args: &[&str]| {
            let output = crate::platform::new_command(&git)
                .args(args)
                .current_dir(repo.path())
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "{}",
                String::from_utf8_lossy(&output.stderr)
            );
        };
        run(&["init", "-q"]);
        let clean =
            super::capture_target_dirty_state_with_git(&git, repo.path()).unwrap();
        assert_eq!(clean.total_count, 0);
        assert!(clean.paths.is_empty());
        assert!(!clean.truncated);

        let non_repo = tempfile::tempdir().unwrap();
        assert!(
            super::capture_target_dirty_state_with_git(&git, non_repo.path()).is_err()
        );
    }

    #[test]
    fn target_dirty_mutation_recheck_returns_same_typed_payload() {
        let repo = tempfile::tempdir().unwrap();
        let git = crate::doctor::resolved_path_if_initialized("git")
            .unwrap_or_else(|| if cfg!(windows) { "git" } else { "/usr/bin/git" }.to_string());
        let run = |args: &[&str]| {
            let output = crate::platform::new_command(&git)
                .args(args)
                .current_dir(repo.path())
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "{}",
                String::from_utf8_lossy(&output.stderr)
            );
        };
        run(&["init", "-q"]);
        run(&["config", "user.email", "t@ply.test"]);
        run(&["config", "user.name", "ply-test"]);
        std::fs::write(repo.path().join("dirty.txt"), "clean\n").unwrap();
        run(&["add", "dirty.txt"]);
        run(&["commit", "-q", "-m", "tracked"]);
        // GH #190: an untracked file alone is not what the guard protects.
        std::fs::write(repo.path().join("untracked.txt"), "mine\n").unwrap();
        let untracked_only =
            super::capture_target_dirty_state_with_git(&git, repo.path()).unwrap();
        assert_eq!(untracked_only.total_count, 0, "{untracked_only:?}");
        assert!(super::require_clean_target_state(untracked_only).is_ok());
        // A tracked edit is.
        std::fs::write(repo.path().join("dirty.txt"), "dirty\n").unwrap();

        let advisory =
            super::capture_target_dirty_state_with_git(&git, repo.path()).unwrap();
        assert_eq!(advisory.paths, vec!["dirty.txt".to_string()]);
        let error = super::require_clean_target_state(advisory.clone()).unwrap_err();
        assert_eq!(
            crate::review::decode_target_dirty_error(&error),
            Some(advisory)
        );
    }

