    // v1.20.5: SHELL_INTEGRATION_BASH must use PS0 (fires once per typed
    // interactive command) instead of `trap '...' DEBUG` (fires on every
    // simple command, floods PTY during conda init / sourced eval chains —
    // caused the v1.20.4 shell-tile startup hang). The whole body must be
    // gated on $ATELIER_SHELL_INTEGRATION so the snippet is silent outside
    // Atelier PTYs (also resolves the Codex shell_snapshot OSC 133 error).
    #[test]
    fn shell_integration_bash_uses_ps0_and_env_gate() {
        let snippet = super::SHELL_INTEGRATION_BASH;
        assert!(
            snippet.contains("ATELIER_SHELL_INTEGRATION"),
            "bash snippet must gate on $ATELIER_SHELL_INTEGRATION"
        );
        assert!(
            snippet.contains("PS0="),
            "bash snippet must use PS0 for the C marker"
        );
        assert!(
            !snippet.contains("trap '__atelier_emit_c' DEBUG"),
            "bash snippet must NOT use the DEBUG trap (flood footgun)"
        );
    }

    /// Command blocks in PowerShell: the snippet prints the four marks the
    /// tile's OSC 133 handler reads, each BEL-terminated with ESC written as
    /// `[char]27` (Windows PowerShell 5.1 has no "`e"), through
    /// `[Console]::Write`, and only inside a Plyloft tile.
    #[test]
    fn shell_integration_powershell_prints_the_four_marks() {
        let snippet = super::shell_integration_script("powershell".into()).unwrap();
        assert_eq!(snippet, super::SHELL_INTEGRATION_POWERSHELL);
        for mark in [
            r#"[Console]::Write("$esc]133;A$bel")"#,
            r#""$text$esc]133;B$bel""#,
            r#"[Console]::Write("$([char]27)]133;C$([char]7)")"#,
            r#"[Console]::Write("$esc]133;D;$code$bel")"#,
        ] {
            assert!(snippet.contains(mark), "missing {mark}");
        }
        assert!(snippet.contains("$esc = [char]27") && snippet.contains("$bel = [char]7"));
        assert!(!snippet.contains("`e"), "5.1 has no `e escape");
        assert!(snippet.contains("if ((Test-Path Env:\\ATELIER_SHELL_INTEGRATION)"), "gated on the tile's own marker");
        // C on the accepted line, D only after a C, $? handed back.
        assert!(snippet.contains("function global:PSConsoleHostReadLine"));
        assert!(snippet.contains("$ok = $global:?"));
        assert!(snippet.contains("Write-Error 'failed' -ErrorAction Ignore"));
        assert!(snippet.contains("if ($global:__PlyloftCommandRan)"));
        // A Rust raw string keeps it ASCII: Windows PowerShell 5.1 reads a
        // BOM-less profile as the ANSI code page.
        assert!(snippet.is_ascii(), "the PowerShell snippet stays ASCII");
        assert!(super::shell_integration_script("fish".into()).is_err());
    }

    /// Challenger: the PowerShell snippet's own instructions never empty an
    /// existing profile (`New-Item -Force` on a file that is there replaces
    /// it with an empty one), the `$?` hand-back sits right before the call
    /// to the user's prompt, and PSReadLine is wrapped again from the prompt
    /// (a PSReadLine imported after the snippet) without wrapping itself.
    #[test]
    fn shell_integration_powershell_keeps_the_profile_and_the_prompt_state() {
        let snippet = super::SHELL_INTEGRATION_POWERSHELL;
        assert!(!snippet.contains("New-Item -Force $PROFILE"), "would empty an existing profile");
        assert!(snippet.contains("if (-not (Test-Path $PROFILE)) { New-Item -ItemType File -Path $PROFILE -Force }"));
        assert!(snippet.contains("run this\n# once in Windows PowerShell: Set-ExecutionPolicy -Scope CurrentUser RemoteSigned"));
        assert!(snippet.contains("Test-Path variable:global:__PlyloftShellIntegration"));
        // Write-Error is the last statement before the user's prompt runs.
        let lines: Vec<&str> = snippet.lines().map(str::trim).collect();
        let call = lines.iter().position(|l| *l == "$text = & $original").expect("the call");
        assert_eq!(lines[call - 1], "if (-not $ok) { Write-Error 'failed' -ErrorAction Ignore }");
        // The hook: at load and on every prompt, skipping its own wrapper.
        assert!(snippet.contains("function global:__PlyloftHookReadLine"));
        assert_eq!(snippet.matches("\n  __PlyloftHookReadLine\n").count(), 1, "once at load");
        assert_eq!(snippet.matches("\n    __PlyloftHookReadLine\n").count(), 1, "once per prompt");
        assert!(snippet.contains("if ($current.ToString().Contains('__PlyloftOriginalReadLine')) { return }"));
        let wrapper = snippet.split("function global:PSConsoleHostReadLine").nth(1).unwrap();
        assert!(wrapper.contains("& $global:__PlyloftOriginalReadLine"), "the marker the hook looks for");
    }

