/// QoL 1.168 S1-3: a card archived without shipping comes back whole —
/// its copy out of the Trash with the edits not yet committed, on its branch.
#[cfg(test)]
mod card_restore_tests {
    use crate::kanban::{KanbanCard, KanbanColumnId, KanbanStore};
    use crate::project_config::ProjectConfigStore;
    use crate::workspace::WorkspaceStore;

    fn git(dir: &std::path::Path, args: &[&str]) {
        let ok = crate::platform::git_command()
            .args(args)
            .current_dir(dir)
            .status()
            .is_ok_and(|s| s.success());
        assert!(ok, "git {args:?}");
    }

    fn fixture() -> (tempfile::TempDir, std::path::PathBuf, WorkspaceStore, KanbanStore, String) {
        let tmp = tempfile::tempdir().unwrap();
        let config = tmp.path().join("config");
        let repo = tmp.path().join("repo");
        std::fs::create_dir_all(&repo).unwrap();
        git(&repo, &["init", "-q", "-b", "main"]);
        git(&repo, &["-c", "user.email=t@t", "-c", "user.name=t", "commit", "-q", "--allow-empty", "-m", "init"]);
        let workspaces = WorkspaceStore::new(config.clone()).unwrap();
        let ws = workspaces.create("Repo".into(), repo.to_string_lossy().into_owned()).unwrap().id;
        let store = KanbanStore::new(config).unwrap();
        (tmp, repo, workspaces, store, ws)
    }

    /// Review (HIGH): a copy the archive couldn't move (a program held it,
    /// `kept_copy`) is the card's copy again on Restore — so the later retry
    /// never trashes it with its edits.
    #[test]
    fn a_kept_copy_is_the_restored_cards_copy_again() {
        let (_tmp, repo, workspaces, store, ws) = fixture();
        let made = crate::worktrees::ensure_for_card(&repo, "c1", "Held open", "main").unwrap();
        std::fs::write(made.worktree_path.join("edit.txt"), "not committed\n").unwrap();
        let mut card = KanbanCard::new("c1".into(), ws.clone(), "Held open".into(), None, KanbanColumnId::InProgress);
        card.archived = true;
        card.kept_copy = Some(crate::kept_copy::KeptCopy {
            path: made.worktree_path.to_string_lossy().into_owned(),
            reason: "os error 32".into(),
            at: 1,
            head: None,
        });
        store.create_card(&ws, card).unwrap();
        let back = super::restore_card_locked(&store, &workspaces, &ws, "c1").unwrap();
        assert!(!back.archived);
        assert!(back.kept_copy.is_none());
        assert_eq!(back.worktree_path.as_deref(), Some(made.worktree_path.to_string_lossy().as_ref()));
        assert_eq!(back.branch_name.as_deref(), Some(made.branch_name.as_str()));
        let cwd = repo.clone();
        assert_eq!(crate::kept_copy::retry(&store, &ws, "c1", &cwd, &[]), crate::kept_copy::Retry::Nothing);
        assert!(made.worktree_path.join("edit.txt").is_file(), "the edit is still there");
    }

    /// On every plan a restored card comes back to the column it was
    /// archived from, while another card is at work too.
    #[test]
    fn a_restore_comes_back_where_it_was_while_another_card_is_at_work() {
        let (_tmp, _repo, workspaces, store, ws) = fixture();
        store
            .create_card(&ws, KanbanCard::new("busy".into(), ws.clone(), "Busy".into(), None, KanbanColumnId::InProgress))
            .unwrap();
        let mut away = KanbanCard::new("away".into(), ws.clone(), "Away".into(), None, KanbanColumnId::InProgress);
        away.archived = true;
        store.create_card(&ws, away).unwrap();
        let back = super::restore_card_locked(&store, &workspaces, &ws, "away").unwrap();
        assert!(!back.archived);
        assert_eq!(back.column_id, KanbanColumnId::InProgress, "not sent back to Ready to start");
    }

    #[test]
    fn an_unshipped_archived_card_comes_back_with_its_copy() {
        let tmp = tempfile::tempdir().unwrap();
        let config = tmp.path().join("config");
        let repo = tmp.path().join("repo");
        std::fs::create_dir_all(&repo).unwrap();
        git(&repo, &["init", "-q", "-b", "main"]);
        git(&repo, &["-c", "user.email=t@t", "-c", "user.name=t", "commit", "-q", "--allow-empty", "-m", "init"]);
        let workspaces = WorkspaceStore::new(config.clone()).unwrap();
        let ws = workspaces.create("Repo".into(), repo.to_string_lossy().into_owned()).unwrap().id;
        let store = KanbanStore::new(config.clone()).unwrap();
        let project_config = ProjectConfigStore::new(config.clone()).unwrap();
        let made = crate::worktrees::ensure_for_card(&repo, "c1", "Keep me", "main").unwrap();
        let mut card = KanbanCard::new("c1".into(), ws.clone(), "Keep me".into(), None, KanbanColumnId::InProgress);
        card.notes = Some("the brief".into());
        card.worktree_path = Some(made.worktree_path.to_string_lossy().into_owned());
        card.branch_name = Some(made.branch_name.clone());
        store.create_card(&ws, card).unwrap();
        std::fs::write(made.worktree_path.join("half.txt"), "half done\n").unwrap();

        super::kanban_card_archive_locked(&store, &workspaces, &project_config, &ws, "c1", false).unwrap();
        let archived = store.get_card(&ws, "c1").unwrap();
        assert!(archived.archived);
        assert!(!made.worktree_path.exists(), "the copy went to the Trash");
        assert!(crate::kanban::card_restorable(&archived));

        let back = super::restore_card_locked(&store, &workspaces, &ws, "c1").unwrap();
        assert!(!back.archived);
        assert_eq!(back.notes.as_deref(), Some("the brief"));
        assert_eq!(back.branch_name.as_deref(), Some(made.branch_name.as_str()));
        let wt = std::path::PathBuf::from(back.worktree_path.clone().expect("its copy is back"));
        assert_eq!(std::fs::read_to_string(wt.join("half.txt")).unwrap(), "half done\n");
        let head = crate::git::capture(&wt, &["rev-parse", "--abbrev-ref", "HEAD"]).unwrap();
        assert_eq!(head.trim(), made.branch_name);
    }
}

/// 1.173.0 A3: *Make it a card* — a card on the copy's folder and branch
/// through the cards' own advance.
#[cfg(test)]
mod copy_make_card_tests {
    use crate::kanban::{KanbanCard, KanbanColumnId, KanbanStore};
    use crate::license::{LicenseStore, PlanCase};
    use crate::project_config::ProjectConfigStore;
    use crate::workspace::WorkspaceStore;
    use std::path::{Path, PathBuf};

    fn git(dir: &Path, args: &[&str]) -> String {
        let out = crate::platform::git_command().args(args).current_dir(dir).output().unwrap();
        assert!(out.status.success(), "git {args:?}: {}", String::from_utf8_lossy(&out.stderr));
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    struct Fixture {
        _tmp: tempfile::TempDir,
        store: KanbanStore,
        workspaces: WorkspaceStore,
        project_config: ProjectConfigStore,
        ws: String,
        cwd: PathBuf,
    }

    fn fixture() -> Fixture {
        let tmp = tempfile::tempdir().unwrap();
        let seed = tmp.path().join("seed");
        std::fs::create_dir(&seed).unwrap();
        git(&seed, &["init", "-q", "-b", "main"]);
        for (k, v) in [("user.email", "t@t"), ("user.name", "t"), ("commit.gpgsign", "false")] {
            git(&seed, &["config", k, v]);
        }
        std::fs::write(seed.join("README.md"), "x\n").unwrap();
        git(&seed, &["add", "."]);
        git(&seed, &["commit", "-q", "-m", "init"]);
        let origin = tmp.path().join("origin.git");
        git(tmp.path(), &["clone", "-q", "--bare", seed.to_str().unwrap(), origin.to_str().unwrap()]);
        let cwd = tmp.path().join("ws");
        git(tmp.path(), &["clone", "-q", origin.to_str().unwrap(), cwd.to_str().unwrap()]);
        for (k, v) in [("user.email", "t@t"), ("user.name", "t"), ("commit.gpgsign", "false")] {
            git(&cwd, &["config", k, v]);
        }
        let config = tmp.path().join("config");
        let workspaces = WorkspaceStore::new(config.clone()).unwrap();
        let ws = workspaces.create("Project".into(), cwd.to_string_lossy().into_owned()).unwrap().id;
        Fixture {
            store: KanbanStore::new(config.clone()).unwrap(),
            project_config: ProjectConfigStore::new(config).unwrap(),
            workspaces,
            ws,
            cwd,
            _tmp: tmp,
        }
    }

    fn copy(f: &Fixture, name: &str) -> crate::copies::CopyEntry {
        let dir = f.project_config.workspace_dir(&f.ws);
        let place = crate::copies::Place { registry_dir: &dir, workspace_cwd: &f.cwd };
        crate::copies::create(place, name, "main", Some("claude"), 1, crate::worktrees::resolve_base).unwrap()
    }

    fn make(f: &Fixture, license: &LicenseStore, id: &str) -> Result<super::CopyMadeCard, String> {
        super::make_card_from_copy(
            None::<&tauri::AppHandle<tauri::test::MockRuntime>>,
            &f.store,
            &f.workspaces,
            &f.project_config,
            license,
            &crate::settings::Settings::default(),
            &f.ws,
            id,
            None,
            false,
        )
        .map(|out| {
            assert!(out.pending.is_none(), "the copy's folder is there: nothing to set up");
            assert!(out.mirror_to.is_none(), "a local board makes no issue");
            out.made
        })
    }

    /// Walk fixes (a–c): the card waits in Not started on the copy as it is,
    /// its work saved in a commit that says where it came from, and the card
    /// knows its copy (`from_copy`, `card_copy_changes_of`).
    #[test]
    fn make_it_a_card_makes_a_not_started_card_on_the_copy_as_it_is() {
        let f = fixture();
        let entry = copy(&f, "inbox-empty-state");
        let path = PathBuf::from(&entry.path);
        std::fs::write(path.join("work.txt"), "not committed\n").unwrap();
        let license = LicenseStore::for_plan_test(f._tmp.path().join("lic"), PlanCase::Pro);

        let made = make(&f, &license, &entry.id).unwrap();

        assert!(!made.started, "no session works on it yet");
        assert_eq!(made.note, None);
        let card = &made.card;
        assert_eq!(card.title, "inbox-empty-state");
        assert_eq!(card.column_id, KanbanColumnId::Todo, "Not started, as the Board shows it");
        assert_eq!(card.worktree_path.as_deref(), Some(entry.path.as_str()), "the copy's own folder");
        assert_eq!(card.branch_name.as_deref(), Some(entry.branch.as_str()), "its branch keeps its name");
        assert_eq!(card.worktree_base.as_ref().map(|b| b.commit.as_str()), Some(entry.base_commit.as_str()));
        assert_eq!(card.from_copy.as_ref().map(|c| c.name.as_str()), Some("inbox-empty-state"));
        assert_eq!(card.area, None, "no areas here");
        // C4: no commit of its own, so the copy's name; the brief is empty.
        assert_eq!(card.notes, None, "What you want is the person's to write");
        assert!(card.port_base.is_some(), "the card has its own port block");
        // The work is saved, in a commit that says what happened.
        assert_eq!(git(&path, &["status", "--porcelain"]), "");
        assert_eq!(git(&path, &["log", "-1", "--format=%s"]), "chore: work from the copy inbox-empty-state");
        assert_eq!(git(&path, &["rev-parse", "--abbrev-ref", "HEAD"]), entry.branch);
        assert_eq!(std::fs::read_to_string(path.join("work.txt")).unwrap(), "not committed\n");
        // The card page reads the copy's change.
        let changes = super::card_copy_changes_of(card).unwrap();
        assert_eq!((changes.count, changes.files.clone()), (1, vec!["work.txt".to_string()]));
        // The copy is the card's and has left the Copies list.
        let dir = f.project_config.workspace_dir(&f.ws);
        let place = crate::copies::Place { registry_dir: &dir, workspace_cwd: &f.cwd };
        assert_eq!(crate::copies::load(&dir).copies[0].card_id.as_deref(), Some(card.id.as_str()));
        assert!(crate::copies::list(place, &|_| 0, &|_| false).is_empty());
        // A second press finds it a card's.
        assert_eq!(make(&f, &license, &entry.id).unwrap_err(), crate::copies::IS_A_CARD_REFUSAL);
        // C4: Start build waits for the brief, by every path.
        assert_eq!(f.store.start_refusal(&f.ws, &card.id).unwrap().as_deref(), Some(crate::kanban::COPY_BRIEF_EMPTY));
        f.store
            .with_card(&f.ws, &card.id, |c| {
                c.notes = Some("Finish the empty state".into());
                Ok(())
            })
            .unwrap();
        assert_eq!(f.store.start_refusal(&f.ws, &card.id).unwrap(), None);
        // Start build is the cards' own advance, which reuses the copy as it is.
        let started = super::advance_card_to_in_progress(
            None::<&tauri::AppHandle<tauri::test::MockRuntime>>,
            &f.store,
            &f.workspaces,
            &f.project_config,
            &license,
            &f.ws,
            &card.id,
            Some("main".into()),
        )
        .unwrap();
        assert_eq!(started.column_id, KanbanColumnId::InProgress);
        assert_eq!(started.worktree_path.as_deref(), Some(entry.path.as_str()), "the same folder");
        assert_eq!(started.port_base, card.port_base, "the same ports");
        // Its branch is one a card owns: cleanup and after-merge accept it.
        assert!(crate::worktrees::is_card_owned_branch(&entry.branch));
        assert!(!crate::worktrees::is_card_branch(&entry.branch), "the backlog scan still leaves it alone");
    }

    /// 1.174.0 C4 (P17): the card is called after the copy's own last
    /// commit — not the one Make it a card saves the work in — and its brief
    /// is empty; an explicit title still wins.
    #[test]
    fn the_card_is_called_after_the_copys_last_commit() {
        let f = fixture();
        let entry = copy(&f, "walk-copy-5");
        let path = PathBuf::from(&entry.path);
        for (k, v) in [("user.email", "t@t"), ("user.name", "t"), ("commit.gpgsign", "false")] {
            git(&path, &["config", k, v]);
        }
        std::fs::write(path.join("pricing.html"), "two plans\n").unwrap();
        git(&path, &["add", "."]);
        git(&path, &["commit", "-q", "-m", "Pricing: drop the third plan card"]);
        std::fs::write(path.join("more.txt"), "not committed\n").unwrap();
        assert_eq!(
            crate::copies::last_commit_subject(&path, &entry.base_commit).as_deref(),
            Some("Pricing: drop the third plan card")
        );
        assert_eq!(crate::copies::last_commit_subject(&path, ""), None, "no base: the name");
        let license = LicenseStore::for_plan_test(f._tmp.path().join("lic"), PlanCase::Pro);

        let card = make(&f, &license, &entry.id).unwrap().card;

        assert_eq!(card.title, "Pricing: drop the third plan card");
        assert_eq!(card.notes, None);
        assert_eq!(card.from_copy.as_ref().map(|c| c.name.as_str()), Some("walk-copy-5"), "Activity says where it came from");
        // The work is saved after the subject was read, and is never the title.
        assert_eq!(git(&path, &["log", "-1", "--format=%s"]), "chore: work from the copy walk-copy-5");
        assert_eq!(
            crate::copies::last_commit_subject(&path, &entry.base_commit).as_deref(),
            Some("Pricing: drop the third plan card")
        );

        // A title given by the caller is kept.
        let other = copy(&f, "named");
        let named = super::make_card_from_copy(
            None::<&tauri::AppHandle<tauri::test::MockRuntime>>,
            &f.store,
            &f.workspaces,
            &f.project_config,
            &license,
            &crate::settings::Settings::default(),
            &f.ws,
            &other.id,
            Some("  Chosen  "),
            false,
        )
        .unwrap();
        assert_eq!(named.made.card.title, "Chosen");
    }

    /// C4 round 1: main merged into the copy (`git merge main`, a pull)
    /// never names the card — only the copy's own line of work does — and a
    /// long subject is cut on a character boundary.
    #[test]
    fn the_title_is_the_copys_own_commit_cut_to_its_length() {
        let f = fixture();
        let entry = copy(&f, "merged-copy");
        let path = PathBuf::from(&entry.path);
        std::fs::write(path.join("own.txt"), "mine\n").unwrap();
        git(&path, &["add", "."]);
        git(&path, &["commit", "-q", "-m", "Copy: its own change"]);
        // main moves on later (a newer commit), and the copy merges it in.
        std::fs::write(f.cwd.join("base.txt"), "base\n").unwrap();
        git(&f.cwd, &["add", "."]);
        let out = crate::platform::git_command()
            .args(["commit", "-q", "-m", "Main: moved on"])
            .env("GIT_AUTHOR_DATE", "2099-01-01T00:00:00Z")
            .env("GIT_COMMITTER_DATE", "2099-01-01T00:00:00Z")
            .current_dir(&f.cwd)
            .output()
            .unwrap();
        assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
        git(&path, &["merge", "-q", "--no-ff", "--no-edit", "main"]);
        assert_eq!(
            crate::copies::last_commit_subject(&path, &entry.base_commit).as_deref(),
            Some("Copy: its own change"),
            "main's commit is not the copy's"
        );

        // A 300-character subject (multi-byte) is cut at the title's length.
        let long = "é".repeat(300);
        std::fs::write(path.join("long.txt"), "x\n").unwrap();
        git(&path, &["add", "."]);
        git(&path, &["commit", "-q", "-m", &long]);
        let title = crate::copies::last_commit_subject(&path, &entry.base_commit).unwrap();
        assert_eq!(title.chars().count(), crate::copies::SUBJECT_TITLE_MAX);
        assert!(long.starts_with(&title));
    }

    /// 1.174.0 C4 (G3a walk): deleting a card made from a copy acts on the
    /// copy's folder as on a card's own. The sheet sees the folder and its
    /// work; kept (Auto with work nowhere else), the copy is listed again;
    /// Delete everything takes the folder and its branch, and the copy is
    /// forgotten.
    #[test]
    fn deleting_a_card_made_from_a_copy_treats_the_copy_as_its_folder() {
        let f = fixture();
        let dir = f.project_config.workspace_dir(&f.ws);
        let place = || crate::copies::Place { registry_dir: &dir, workspace_cwd: &f.cwd };
        let license = LicenseStore::for_plan_test(f._tmp.path().join("lic"), PlanCase::Pro);
        let entry = copy(&f, "g3a copy");
        let path = PathBuf::from(&entry.path);
        std::fs::write(path.join("copy.html"), "hi\n").unwrap();
        git(&path, &["add", "."]);
        git(&path, &["commit", "-q", "-m", "Site: add copy.html"]);
        let card = make(&f, &license, &entry.id).unwrap().card;
        assert_eq!(
            crate::worktrees::card_worktree_path(&f.cwd, &card.id, card.worktree_path.as_deref()),
            path,
            "the card's folder is the copy's"
        );
        // The sheet's read: the copy's folder, with work that exists nowhere else.
        let state = super::read_card_worktree(&f.cwd, &card, "main", false, None, &[]);
        assert_eq!(state.path.as_deref().map(PathBuf::from), Some(path.clone()));
        assert_eq!(state.disposition, crate::worktrees::WorktreeDisposition::Ask);
        assert!(state.unpushed_commits >= 1);

        // Delete the card (Auto): its work is kept, and the copy is a copy again.
        f.store.delete_card(&f.ws, &card.id).unwrap();
        let kept = super::finish_card_delete_at(&f.cwd, &f.ws, &card, "main", super::WorktreeChoice::Auto, &[]);
        assert_eq!(kept.kept_path.as_deref().map(PathBuf::from), Some(path.clone()));
        assert!(path.is_dir());
        assert!(crate::copies::after_card_deleted(&dir, &card.id).unwrap());
        let listed = crate::copies::list(place(), &|_| 0, &|_| false);
        assert_eq!(listed.iter().map(|v| v.copy.id.as_str()).collect::<Vec<_>>(), vec![entry.id.as_str()]);
        assert!(listed[0].present && listed[0].saved >= 1, "listed with its saved work, to throw away");

        // Made a card again, then Delete everything: the folder and branch go.
        let again = make(&f, &license, &entry.id).unwrap().card;
        f.store.delete_card(&f.ws, &again.id).unwrap();
        let gone = super::finish_card_delete_at(&f.cwd, &f.ws, &again, "main", super::WorktreeChoice::Everything, &[]);
        assert!(gone.worktree_removed || gone.kept_in_trash.is_some(), "{gone:?}");
        assert!(!path.is_dir(), "the copy's folder is gone");
        assert!(crate::worktrees::branch_tip(&f.cwd, &entry.branch).is_none(), "its branch too");
        assert!(crate::copies::after_card_deleted(&dir, &again.id).unwrap());
        assert!(crate::copies::load(&dir).copies.is_empty(), "the copy is forgotten");
        assert!(crate::copies::list(place(), &|_| 0, &|_| false).is_empty());
    }

    /// B3: the card takes the area whose branch the copy started from.
    #[test]
    fn the_card_takes_the_area_whose_branch_the_copy_started_from() {
        use crate::areas::AreaDef;
        let f = fixture();
        let def = |id: &str, path: &str, branch: &str| AreaDef {
            id: id.into(),
            name: id.into(),
            path: path.into(),
            target_branch: Some(branch.into()),
            ..Default::default()
        };
        let mut cfg = crate::project_config::default_atelier_config();
        cfg.target_branch = "main".into();
        f.project_config.set(&f.ws, cfg).unwrap();
        crate::team_models::share_for_test(&f.project_config, &f.ws, false);
        crate::areas::save(&f.project_config, &f.ws, &[def("app", "/", "staging"), def("site", "site/", "main")]).unwrap();
        assert_eq!(super::area_for_branch(&f.project_config, &f.ws, "main").as_deref(), Some("site"));
        assert_eq!(super::area_for_branch(&f.project_config, &f.ws, "staging").as_deref(), Some("app"));
        assert_eq!(super::area_for_branch(&f.project_config, &f.ws, "other"), None, "none: the card asks");
        let entry = copy(&f, "site-fix");
        let license = LicenseStore::for_plan_test(f._tmp.path().join("lic"), PlanCase::Pro);
        assert_eq!(make(&f, &license, &entry.id).unwrap().card.area.as_deref(), Some("site"));
        // Windows walk: the copy's files all in one area on its start branch
        // take that area; files spread over areas, or an area on another
        // branch, fall back to the branch's.
        let both_main = [def("app", "/", "main"), def("site", "site/", "main")];
        crate::areas::save(&f.project_config, &f.ws, &both_main).unwrap();
        let paths = |p: &[&str]| p.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        assert_eq!(super::area_for_copy(&f.project_config, &f.ws, "main", &paths(&["win.txt"])).as_deref(), Some("app"));
        assert_eq!(super::area_for_copy(&f.project_config, &f.ws, "main", &paths(&["site/a.md"])).as_deref(), Some("site"));
        assert_eq!(super::area_for_copy(&f.project_config, &f.ws, "main", &paths(&["win.txt", "site/a.md"])), None, "spread, two on main: asks");
        crate::areas::save(&f.project_config, &f.ws, &[def("app", "/", "staging"), def("site", "site/", "main")]).unwrap();
        // The walk's setup: App goes to staging, Site to main, the copy
        // started from main, its one file at the root (App's): the card asks.
        assert_eq!(
            super::area_for_copy(&f.project_config, &f.ws, "main", &paths(&["win.txt"])),
            None,
            "the files point at an area on another branch: never the other area"
        );
        assert_eq!(super::area_for_copy(&f.project_config, &f.ws, "main", &paths(&["site/a.md"])).as_deref(), Some("site"));
        assert_eq!(super::area_for_copy(&f.project_config, &f.ws, "main", &paths(&["win.txt", "site/a.md"])).as_deref(), Some("site"), "spread: the one area on main");
        assert_eq!(super::area_for_copy(&f.project_config, &f.ws, "main", &[]).as_deref(), Some("site"), "no files: the one area on main");
        let walk = copy(&f, "walk-root");
        std::fs::write(PathBuf::from(&walk.path).join("win.txt"), "x\n").unwrap();
        assert_eq!(make(&f, &license, &walk.id).unwrap().card.area, None, "the walk's card asks");
        let root_change = copy(&f, "root-change");
        std::fs::write(PathBuf::from(&root_change.path).join("win.txt"), "x\n").unwrap();
        crate::areas::save(&f.project_config, &f.ws, &both_main).unwrap();
        assert_eq!(make(&f, &license, &root_change.id).unwrap().card.area.as_deref(), Some("app"), "the walk's case");
        // Two areas on the same branch: none (the card asks).
        crate::areas::save(&f.project_config, &f.ws, &[def("a", "a/", "main"), def("b", "b/", "main")]).unwrap();
        assert_eq!(super::area_for_branch(&f.project_config, &f.ws, "main"), None);
    }

    /// Challenger 2: the copy's port block goes with it to the card.
    #[test]
    fn the_card_keeps_the_copys_port_block() {
        let f = fixture();
        let entry = copy(&f, "ports");
        let dir = f.project_config.workspace_dir(&f.ws);
        let place = crate::copies::Place { registry_dir: &dir, workspace_cwd: &f.cwd };
        let held: std::collections::HashSet<u16> = [crate::worktree_ports::RANGE_START].into();
        let block = crate::copies::ensure_port_base(place, &entry.id, &held, &|_| true).unwrap().unwrap();
        let license = LicenseStore::for_plan_test(f._tmp.path().join("lic"), PlanCase::Pro);

        let made = make(&f, &license, &entry.id).unwrap();

        assert_eq!(made.card.port_base, Some(block), "the dev server keeps its ports");
        assert!(crate::copies::held_port_bases(dir.parent().unwrap(), None).is_empty(), "never counted twice");
    }

    /// Challenger 4 and 6: a copy stranded by a card that isn't on the board
    /// is made a card again; one being sent to GitHub is refused.
    #[test]
    fn a_stranded_copy_is_made_a_card_and_one_being_sent_waits() {
        let f = fixture();
        let entry = copy(&f, "stranded");
        let dir = f.project_config.workspace_dir(&f.ws);
        let place = crate::copies::Place { registry_dir: &dir, workspace_cwd: &f.cwd };
        crate::copies::give_to_card(place, &entry.id, "card-that-never-was").unwrap();
        let license = LicenseStore::for_plan_test(f._tmp.path().join("lic"), PlanCase::Pro);

        let sending = crate::copies::begin_sending(&f.ws, &entry.id).unwrap();
        assert_eq!(make(&f, &license, &entry.id).unwrap_err(), crate::copies::SENDING_REFUSAL);
        drop(sending);

        let made = make(&f, &license, &entry.id).unwrap();
        assert_eq!(made.card.column_id, KanbanColumnId::Todo);
        assert_eq!(crate::copies::load(&dir).copies[0].card_id.as_deref(), Some(made.card.id.as_str()));
    }

    /// Re-walk: on Free with another card building, Make it a card makes the
    /// card (in Not started), and Start build carries on in the copy while
    /// the other card is still at work.
    #[test]
    fn on_free_make_it_a_card_and_start_build_while_another_card_builds() {
        let f = fixture();
        let entry = copy(&f, "second");
        let mut busy = KanbanCard::new("busy".into(), f.ws.clone(), "Busy card".into(), None, KanbanColumnId::InProgress);
        busy.worktree_path = Some(f.cwd.join("elsewhere").to_string_lossy().into_owned());
        f.store.create_card(&f.ws, busy).unwrap();
        let license = LicenseStore::for_plan_test(f._tmp.path().join("lic"), PlanCase::Free);

        let made = make(&f, &license, &entry.id).unwrap();

        assert_eq!(made.card.column_id, KanbanColumnId::Todo);
        let dir = f.project_config.workspace_dir(&f.ws);
        assert_eq!(crate::copies::load(&dir).copies[0].card_id.as_deref(), Some(made.card.id.as_str()));
        let started = super::advance_card_to_in_progress(
            None::<&tauri::AppHandle<tauri::test::MockRuntime>>,
            &f.store,
            &f.workspaces,
            &f.project_config,
            &license,
            &f.ws,
            &made.card.id,
            Some("main".into()),
        )
        .unwrap();
        assert_eq!(f.store.get_card(&f.ws, "busy").unwrap().column_id, KanbanColumnId::InProgress);
        assert_eq!(started.worktree_path.as_deref(), Some(entry.path.as_str()));
    }
}
